    /// How many notes are still waiting for their first relay. Read once per
    /// build, because the publisher writes the queue from its own thread and the
    /// view must see one answer for the whole frame.
    pub fn outbox_label(self: *const Model, arena: std.mem.Allocator) []const u8 {
        // First, because it is the worst thing this zone can have to say: a note
        // the reader wrote that was never offered to anybody. `g_outbox_overflow`
        // was set for this and read nowhere, so the promise under the banner,
        // that anything you write is kept until a relay takes it, was quietly
        // untrue in the one case it was written for.
        if (self.outbox_overflowed) return "a note could not be queued";
        // A note that gave up is not "posting". Saying so would be the same lie
        // the queue was built to stop telling.
        if (self.outbox_pending == 0 and self.outbox_stuck > 0) {
            if (self.outbox_stuck == 1) return "1 note did not go out";
            return std.fmt.allocPrint(arena, "{d} notes did not go out", .{self.outbox_stuck}) catch "notes did not go out";
        }
        const n = self.outbox_pending;
        if (n == 1) return "posting 1 note…";
        return std.fmt.allocPrint(arena, "posting {d} notes…", .{n}) catch "posting…";
    }
    /// The app version line for the Settings footer.
    pub fn version_line(self: *const Model) []const u8 {
        _ = self;
        return "Plaza " ++ plaza_version;
    }

    /// The feed, iterated by `<for each="note_list">`, newest first.
    pub fn note_list(self: *const Model, arena: std.mem.Allocator) []const Note {
        _ = arena;
        return self.notes[0..self.notes_len];
    }
    pub fn has_notes(self: *const Model) bool {
        return self.notes_len > 0;
    }
    /// No notes yet, show the centered connecting/offline state (the message
    /// itself, `empty_text`, differentiates dialing from a dropped relay).
    pub fn empty(self: *const Model) bool {
        return self.notes_len == 0;
    }
    /// Header status line: how much of the relay pool is live.
    pub fn status(self: *const Model, arena: std.mem.Allocator) []const u8 {
        if (self.live_relays > 0)
            return std.fmt.allocPrint(arena, "Live · {d}/{d} relays", .{ self.live_relays, self.relay_count }) catch "Live";
        if (self.relay_count > 0 and self.offline_relays >= self.relay_count) return "Offline, reconnecting…";
        return "Connecting…";
    }
    pub fn empty_text(self: *const Model) []const u8 {
        // In a place, the pool is not what the reader is waiting on. Its relay
        // is deliberately outside the eight, so "Connecting to the relay pool"
        // under a place header describes a connection that has nothing to do
        // with the empty screen it is explaining, and says "connecting" about a
        // socket that may have failed a minute ago.
        if (places.g_place != null) {
            // What the place calls it, when it says. Only these three lines,
            // and only inside the room: see `Place.empty_line_buf`.
            const p = activePlace();
            return switch (placeLink()) {
                .idle, .connecting => if (p) |m| (if (m.loadingLine().len > 0) m.loadingLine() else "Connecting to this place…") else "Connecting to this place…",
                .unreachable_relay => if (p) |m| (if (m.lostLine().len > 0) m.lostLine() else "Can't reach this place. Retrying…") else "Can't reach this place. Retrying…",
                .connected => if (p) |m| (if (m.emptyLine().len > 0) m.emptyLine() else "Nothing here yet.") else "Nothing here yet.",
                .no_feed => "This place has no feed to read.",
            };
        }
        if (self.relay_count > 0 and self.offline_relays >= self.relay_count) return "Can't reach any relay. Retrying…";
        return "Connecting to the relay pool…";
    }
    /// Status-bar summary.
    pub fn footer(self: *const Model, arena: std.mem.Allocator) []const u8 {
        if (self.notes_len == 0) return "";
        return std.fmt.allocPrint(arena, "{d} notes", .{self.notes_len}) catch "";
    }

    /// The status bar's left text, which doubles as the caught-up footer: there
    /// is no separate spinner, the feed renders from disk before the window
    /// finishes opening.
    pub fn caught_up(self: *const Model, arena: std.mem.Allocator) []const u8 {
        const scope = self.scope_name();
        if (self.notes_len == 0) return scope;
        return std.fmt.allocPrint(arena, "Caught up · {s} · {d} notes", .{ lowerScope(scope), self.notes_len }) catch scope;
    }

    /// The status bar's relay health, drawn after the online dot.
    pub fn relay_health(self: *const Model, arena: std.mem.Allocator) []const u8 {
        return std.fmt.allocPrint(arena, "{d}/{d} relays", .{ self.live_relays, self.relay_count }) catch "relays";
    }

    /// Whether at least one relay is connected (drives the status dot color).
    pub fn relays_online(self: *const Model) bool {
        return self.live_relays > 0;
    }

    /// Whether the reader is browsing without an identity. Reading never
    /// needs one; the gated verbs ask at first intent.
    pub fn is_guest(self: *const Model) bool {
        _ = self;
        return activePubkey() == null;
    }

    /// Whether the guest join strip is showing (guest, and not dismissed).
    pub fn show_guest_strip(self: *const Model) bool {
        return self.is_guest() and !self.guest_strip_dismissed;
    }

    /// What the feed is scoped to. It stops being a hand-picked pack the moment
    /// the reader has a follow list of their own, and the line has to stop
    /// saying so: calling somebody's own follows "hand-picked" by this app is
    /// exactly the kind of small lie that makes a reader distrust the big
    /// statements too.
    pub fn scope_name(self: *const Model) []const u8 {
        _ = self;
        // Inside a place the feed is the place's, so saying "Following" is
        // simply false: those are not the reader's follows. It names the
        // place's own feed instead.
        if (places.g_place) |*m| {
            if (currentPlaceFeed(m)) |f| {
                if (f.name_len > 0) return f.name();
            }
            return "This place";
        }
        return if (homeReadsPack()) "Starter pack" else "Following";
    }

    /// The feed's scope line: how many voices it is scoped to, and whose choice
    /// that was.
    pub fn scope_voices(self: *const Model, arena: std.mem.Allocator) []const u8 {
        _ = self;
        const shown = followSet().len;
        if (homeReadsPack()) {
            return std.fmt.allocPrint(arena, "{d} voices · hand-picked", .{shown}) catch "hand-picked";
        }
        // One number, because the feed reads the whole list. This used to state
        // two ("128 of 300 accounts") back when it read a slice, and that was
        // worth the clutter then: telling somebody who follows five hundred
        // people that they follow 128 is a lie about their own data.
        if (shown == 1) return "1 account · yours";
        return std.fmt.allocPrint(arena, "{d} accounts · yours", .{shown}) catch "yours";
    }

    /// The note with this id, if it is still in the feed or the open thread. A
    /// thread's root and replies are not in the feed window but are still
    /// pressable (like, image, open-as-thread), so they resolve here too.
    pub fn mentionsOff(self: *const Model) []const [32]u8 {
        return self.mentions_off[0..self.mentions_off_len];
    }

    pub fn noteById(self: *const Model, note_id: i64) ?*const Note {
        for (self.notes[0..self.notes_len]) |*note| {
            if (note.id == note_id) return note;
        }
        // A profile's rows live in the same buffer, so they resolve the same way.
        // Without this every press on a profile row (open, like, expand a
        // picture) is a silent no-op, which is worse than an inert control
        // because it looks live.
        if (self.viewing_thread != 0 or self.viewing_profile != null) {
            if (self.thread_root.id == note_id) return &self.thread_root;
            for (self.thread_notes[0..self.thread_notes_len]) |*note| {
                if (note.id == note_id) return note;
            }
        }
        return null;
    }

    /// Which level of the thread stack is on screen. Every per-level table is
    /// indexed by this, and it is clamped because the stack saturates at
    /// `thread_depth_max` by replacing its top rather than growing.
    pub fn currentLevel(self: *const Model) usize {
        return @min(self.thread_stack_len, thread_depth_max);
    }

    /// The open profile's notes, newest first, read from the local store. The
    /// same shape as the thread's refresh: the store is the app, so the screen
    /// fills from disk before any relay answers and the backfill only widens it.
    /// Whether ANY level is stacked over the feed. Was asked as
    /// `viewing_profile != null or viewing_thread != 0` in four places, which is
    /// a question that has to be updated in four places every time a third kind
    /// of level exists.
    pub fn levelOpen(self: *const Model) bool {
        return self.viewing_profile != null or self.viewing_thread != 0 or
            self.topic_len > 0 or self.viewing_bookmarks;
    }

    /// The bookmarked notes this machine actually holds, newest first.
    ///
    /// A bookmark whose note was never fetched is simply not shown. Drawing a
    /// row for an id with no event behind it would be a list of things the
    /// reader cannot read, and the honest answer is the ones that are here.
    fn refreshBookmarkNotes(self: *Model, now_s: i64) void {
        const store = g_store orelse return;
        var n: usize = 0;
        var i: usize = 0;
        const total = bookmarkCount();
        while (i < total and n < thread_reply_cap) : (i += 1) {
            const id = bookmarkAt(i) orelse continue;
            var se = (store.getEvent(std.heap.page_allocator, id) catch continue) orelse continue;
            defer se.deinit();
            if (se.event.kind != 1) continue;
            self.thread_notes[n] = noteFrom(se.event, now_s);
            n += 1;
        }
        self.thread_notes_len = n;
    }

    pub fn viewingTopic(self: *const Model) ?[]const u8 {
        return if (self.topic_len == 0) null else self.topic_buf[0..self.topic_len];
    }

    /// Everything this reader already holds carrying that `t` tag, newest
    /// first. The store indexes tags, so this is one disk read and it answers
    /// before any relay is asked, which is the whole point of keeping a store.
    fn refreshTopicNotes(self: *Model, now_s: i64) void {
        const topic = self.viewingTopic() orelse return;
        const store = g_store orelse return;
        const values = [_][]const u8{topic};
        var tags: [1]nostr.filter.TagFilter = undefined;
        var result = store.query(std.heap.page_allocator, topicFilter(&values, &tags)) catch return;
        defer result.deinit();
        var n: usize = 0;
        for (result.events) |ev| {
            if (n >= thread_reply_cap) break;
            // A tag is written under by strangers, and a muted one is hidden
            // here the way the feed and a thread hide them. Jumble's note list
            // does the same for its hashtag page
            // (src/components/NoteList/index.tsx:147).
            if (isMuted(ev.pubkey)) continue;
            self.thread_notes[n] = noteFrom(ev, now_s);
            // Queue the author's profile so a name and a face resolve for a
            // stranger, which is most of who writes under a tag.
            wantProfile(ev.pubkey);
            n += 1;
        }
        self.thread_notes_len = n;
    }

    /// Ends the topic's loading line. A topic is done waiting when something is
    /// on screen, when its fetch has asked every relay and come back, or when
    /// it has been long enough that a relay holding its EOSE back is no reason
    /// to keep the reader looking at a spinner. The same three exits a thread
    /// has. Without the last two a tag nobody has used was "looking" for ever.
    fn settleTopicLoading(self: *Model, now_s: i64) void {
        if (self.topic_len == 0 or !self.thread_loading) return;
        const done = g_thread_done_seq.load(.acquire) >= self.thread_seq;
        const timed_out = now_s - self.thread_open_at > thread_loading_grace_s;
        if (self.thread_notes_len > 0 or done or timed_out) self.thread_loading = false;
    }

    fn refreshProfileNotes(self: *Model, now_s: i64) void {
        const pk = self.viewing_profile orelse return;
        const store = g_store orelse return;
        // Comments too. A person who answers in the other vocabulary was
        // simply absent from their own profile, and the page looked like
        // somebody who had stopped writing rather than one this app could not
        // read.
        const kinds = [_]u16{ 1, comment_kind };
        const authors = [_][32]u8{pk};
        const want = @min(self.profile_limit, profile_notes_max);
        self.growLevelNotes(want);
        var result = store.query(std.heap.page_allocator, .{
            .authors = &authors,
            .kinds = &kinds,
            .limit = @intCast(@min(want, self.thread_notes.len)),
        }) catch return;
        defer result.deinit();

        // A note already on the page is carried over rather than parsed again.
        // This runs on the tick whenever the store moved, which is most ticks
        // while any relay is streaming, and a page paged down to its ceiling is
        // fifteen hundred notes: parsing every one each time put that whole cost
        // on the render thread once a second to produce the list already on
        // screen. The feed keeps its cards the same way (`buildReuseIndex`).
        //
        // A name landing changes only the notes that mention somebody, since
        // that label is the one thing baked into the text; those are parsed
        // again and the rest are kept.
        const names_same = feed_state.g_profile_notes_names == g_names_generation;
        feed_state.g_profile_notes_names = g_names_generation;
        const old = self.thread_notes[0..self.thread_notes_len];
        const slots = buildReuseIndex(old);
        const n = @min(result.events.len, self.thread_notes.len);
        // In place, oldest first. The page almost always gains notes, above
        // the ones it holds (newer) or below them (an older page), so a note
        // moves to the same index or a later one, and walking up from the
        // bottom writes each slot after the note that was in it has moved. When
        // one was removed and a note moves the other way, its slot may have
        // been written first; `heldIndex` compares the full id, finds nothing,
        // and the note is parsed.
        var i = n;
        while (i > 0) {
            i -= 1;
            const ev = result.events[i];
            if (heldIndex(slots, old, ev.id)) |at| {
                if (names_same or self.thread_notes[at].mentions.len == 0) {
                    if (at != i) self.thread_notes[i] = self.thread_notes[at];
                    continue;
                }
            }
            self.thread_notes[i] = noteFrom(ev, now_s);
            feed_state.g_profile_parses +%= 1;
        }
        self.thread_notes_len = n;
    }

    /// Moves the level's notes onto a buffer of at least `want`, keeping what is
    /// in them. A profile is the only level that asks for more than a thread's
    /// cap; every other one stays on the buffer it started with.
    ///
    /// Doubling, so paging down a long page is a handful of allocations. The
    /// buffer it leaves is freed, as the feed's is: there is one model and it
    /// moves with the buffer. A `Note` is several kilobytes, so the 200, 400 and
    /// 800 note buffers a page grows through would otherwise stay behind as
    /// megabytes nothing reads. The first buffer is static and stays.
    fn growLevelNotes(self: *Model, want: usize) void {
        if (self.thread_notes.len >= want) return;
        if (feed_state.g_level_notes.len >= want) {
            if (self.thread_notes.ptr != feed_state.g_level_notes.ptr) {
                const held = @min(self.thread_notes_len, self.thread_notes.len);
                @memcpy(feed_state.g_level_notes[0..held], self.thread_notes[0..held]);
            }
            self.thread_notes = feed_state.g_level_notes;
            return;
        }
        var next = @max(feed_state.g_level_notes.len, thread_reply_cap);
        while (next < want) next *|= 2;
        const grown = std.heap.page_allocator.alloc(Note, next) catch return;
        const keep = @min(self.thread_notes_len, self.thread_notes.len);
        @memcpy(grown[0..keep], self.thread_notes[0..keep]);
        for (grown[keep..]) |*note| note.* = .{};
        if (feed_state.g_level_notes.ptr != @as([*]Note, &feed_state.g_level_boot)) std.heap.page_allocator.free(feed_state.g_level_notes);
        feed_state.g_level_notes = grown;
        self.thread_notes = grown;
    }

    /// Which of the profile's two tabs a note belongs to. "Notes" is what they
    /// wrote; "Replies" is what they wrote at somebody. A tab that mixed them
    /// would be a tab that lies about what it holds.
    pub fn profileNotesFor(self: *const Model, out: []usize, pubkey: [32]u8) []const usize {
        var n: usize = 0;
        // Only THIS person's notes. `thread_notes` is one buffer shared with the
        // thread screen, so a stacked level that is not the one being read holds
        // somebody else's rows, and counting those would give the retained list
        // a length that does not match what it draws.
        for (self.thread_notes[0..self.thread_notes_len], 0..) |note, i| {
            if (n >= out.len) break;
            if (!std.mem.eql(u8, &note.pubkey, &pubkey)) continue;
            const is_reply = note.has_reply_parent;
            if ((self.profile_tab == .replies) != is_reply) continue;
            out[n] = i;
            n += 1;
        }
        return out[0..n];
    }

    /// Rebuilds the open thread's replies from the store: every kind:1 that
    /// e-tags the root, oldest first, into the `thread_notes` cache. Local-first,
    /// the same path the feed uses; cheap enough to run each tick so
    /// late-arriving replies appear and relative times stay fresh.
    fn refreshThreadNotes(self: *Model, now_s: i64) void {
        if (self.viewing_thread == 0) return;
        const store = g_store orelse return;
        // The whole subtree, not just the direct children: the closure walk is
        // what keeps a SUB-thread's deep replies visible (they tag the true
        // root and their direct parent, never a mid-thread note).
        var ids: [thread_reply_cap][32]u8 = undefined;
        const id_count = collectThreadIds(store, self.thread_root.event_id, &ids);

        var n: usize = 0;
        for (ids[0..id_count]) |id| {
            if (n >= thread_reply_cap) break;
            var se = (store.getEvent(std.heap.page_allocator, id) catch continue) orelse continue;
            defer se.deinit();
            // A muted person's reply is hidden the same way their note is. The
            // thread's ROOT is not checked: opening a thread is asking to read
            // that note, and answering with an empty screen would be the app
            // refusing a question the reader just asked.
            if (isMuted(se.event.pubkey)) continue;
            self.thread_notes[n] = noteFrom(se.event, now_s);
            // Queue the replier's profile so a name, avatar, and handle resolve
            // for a reply from someone outside the follow set.
            wantProfile(se.event.pubkey);
            n += 1;
        }
        // Whether this thread's own fetch has asked every relay and come back, or
        // given up waiting on one that never sends its EOSE. Until then the
        // replies are still streaming in and belong to one batch.
        const settled = self.threadFetchSettled(now_s);
        stampArrival(arrivalTableFor(self.thread_stack_len, self.thread_root.event_id), self.thread_notes[0..n], settled);
        // In reading order, so seat each reply under the note it answers.
        arrangeThread(self.thread_notes[0..n], self.thread_root.event_id);
        self.thread_notes_len = n;
        self.settleThreadLoading(now_s);
    }

    /// Whether the open thread's own fetch has asked every relay and come back,
    /// or been given up on after `thread_loading_grace_s` for a relay that never
    /// sends its EOSE.
    fn threadFetchSettled(self: *const Model, now_s: i64) bool {
        const done = g_thread_done_seq.load(.acquire) == self.thread_seq;
        const timed_out = now_s - self.thread_open_at > thread_loading_grace_s;
        return done or timed_out;
    }

    /// Stops the loading skeletons once replies are in hand, or once the fetch is
    /// done or timed out, so a note that simply has no replies resolves to
    /// "No replies yet" rather than stalling under skeletons. Runs every tick,
    /// not only when the store moved: a quiet relay and an unchanged store is
    /// exactly the case where the answer is "there is nothing", and nothing
    /// changing is what would otherwise never let the skeletons retire.
    fn settleThreadLoading(self: *Model, now_s: i64) void {
        if (!self.thread_loading) return;
        if (self.thread_notes_len > 0 or self.threadFetchSettled(now_s)) self.thread_loading = false;
    }

    /// The reply count for the thread breadcrumb: the crowd count the feed's
    /// engagement subscription already knows (so it reads right the instant a
    /// thread opens, before the replies are fetched), or the fetched count once
    /// that is higher.
    fn threadReplyCount(self: *const Model) usize {
        const crowd: usize = engagementFor(self.thread_root.id).replies;
        return @max(crowd, self.thread_notes_len);
    }

    /// The span of notes at or near the viewport, which is what gets pictures.
    /// Card heights vary, so this estimates from the average (total content over
    /// note count) and pads generously; being a row or two wide only costs a
    /// prefetch. Before the first scroll event it reports the top of the feed.
    pub fn visibleRange(self: *const Model) RowRange {
        if (self.notes_len == 0) return .{ .first = 0, .last = 0 };
        // The windowed list reports the exact rows it put on screen, so this is
        // no longer an estimate. Before the first build it reports the top.
        const last_row = self.notes_len - 1;
        if (g_visible_last == 0 and g_visible_first == 0) {
            return .{ .first = 0, .last = @min(last_row, max_media_images - 1) };
        }
        return .{ .first = @min(g_visible_first, last_row), .last = @min(g_visible_last, last_row) };
    }

    /// The rows to have READY, which is wider than the rows on screen.
    ///
    /// A face or a picture is fetched only for a row the viewport already holds,
    /// so scrolling meant watching them arrive: the row lands blank, asks the
    /// network, and fills in a moment later, over and over, for as long as you
    /// keep moving. The bytes are what take time, and nothing about fetching them
    /// requires the row to be visible.
    ///
    /// So a band either side of the viewport is warmed into the disk cache
    /// ahead of arriving. Either side on purpose: scrolling back up is as common
    /// as scrolling down, and a cache that only ever looks forward makes the way
    /// back feel broken in a way the way down does not.
    pub fn prefetchRange(self: *const Model) RowRange {
        const w = self.visibleRange();
        if (self.notes_len == 0) return w;
        const last_row = self.notes_len - 1;
        return .{
            .first = w.first -| feed_prefetch_rows,
            .last = @min(last_row, w.last + feed_prefetch_rows),
        };
    }

    /// Reconciles the feed with the store. Updates the connection line every
    /// tick; re-queries and rebuilds the note cards only when the store's event
    /// count changed since the last rebuild; and re-computes relative times for
    /// the notes on screen. `now_s` is the current wall-clock second.
    fn refresh(self: *Model, now_s: i64) void {
        var live: usize = 0;
        var offline: usize = 0;
        // Only slots that hold a relay: a dormant slot's status is whatever it
        // was when its relay was removed, and counting it would report the app
        // offline from a relay the reader deleted.
        for (0..relaySlots()) |i| {
            if (relayAt(i) == null) continue;
            switch (@as(Conn, @enumFromInt(relay_conn.g_relay_status[i].load(.acquire)))) {
                // A quiet relay still holds its socket and nothing has failed,
                // so it counts as live here. Saying otherwise would put the app
                // behind an "offline, reconnecting" banner on a slow night.
                .connected, .quiet => live += 1,
                .offline => offline += 1,
                .connecting => {},
            }
        }
        self.live_relays = live;
        self.offline_relays = offline;
        // Sampled together, so a frame never mixes a fresh numerator with a
        // stale denominator and reads "4/3 relays".
        self.relay_count = relayCount();

        // A relay came up, or the pool changed size: whatever could not be found
        // a moment ago may be findable now, so everything still unresolved goes
        // back in the queue immediately rather than waiting out its backoff. This
        // is the case that produced the report: three tries spent while nothing
        // was connected wrote a note off, and nothing ever asked again.
        if (live != g_last_live_relays or self.relay_count != g_last_relay_count) {
            g_last_live_relays = live;
            g_last_relay_count = self.relay_count;
            requeueMissingQuotes();
        }

        const store = g_store orelse return;

        const count = store.eventCount() catch return;
        // Three ways the view can be behind the store. The count catches
        // anything landing by any route; the other two are the feed's own, and
        // either can be true on a tick where the count has not moved (a
        // deletion cancels an insert, or nothing was stored at all and the
        // reader simply changed who they follow).
        // A place's notes arrive on its own socket and go into the store like
        // anything else, so for a place the reader has never seen this fires on
        // the count alone. For one they HAVE seen it does not: every note is
        // already stored, the ingest is a duplicate, the count does not move,
        // and nothing below ever runs. That is a room that sits on "Connecting"
        // forever while its relay is connected and answering.
        //
        // `rebuildNotes` already treats this counter as a reason to rebuild.
        // The bug was one level up: it never got the chance, because deciding
        // whether to call it at all did not know about places.
        const place_rev = places.g_place_rev.load(.monotonic);
        const stale = count != g_last_count or
            feed_state.g_arrival_pending.load(.acquire) or
            feed_state.g_feed_rebuild_all.load(.acquire) or
            place_rev != feed_state.g_notes_place_rev or
            self.feed_limit != feed_state.g_notes_feed_limit;
        if (stale) {
            g_last_count = count;
            // Profiles first, so a note's mentions resolve to names as it builds.
            refreshProfiles(store);
            rebuildNotes(self, store, now_s);
            // A grown store may hold quoted events the feed references now.
            refreshQuotes(store);
        }
        // Off the store-changed guard, on its own flag: a relay list is rare
        // and the ranking reads every one of them, so it runs when one lands
        // and not once a second because a reaction did. And not on the tick the
        // list lands either, because they land in flurries.
        maybeRankRelaySuggestions(store);
        for (self.notes[0..self.notes_len]) |*note| note.setTime(now_s);
    }

    fn rebuildNotes(self: *Model, store: *nostr.store.Store, now_s: i64) void {
        // Whatever the feed ends up holding, the relays get told about it. On
        // every path out of here, including the two that return early.
        defer publishFeedWatch(self.notes[0..self.notes_len]);
        // Notes and the two repost kinds. `rebuildNotesFromStore` reads one
        // query per kind for the reason given there, so this list costs three
        // cursors per author rather than multiplying into one query the store
        // would refuse to index.
        const kinds = [_]u16{ 1, repost_kind, generic_repost_kind };
        // Scope the feed to the follow set (the starter pack) plus the user's own
        // notes, so it reads as a real follow feed, not a firehose. Filtering
        // here (not just at the subscription) also hides notes an earlier,
        // unscoped run may have left in the store.
        var authors: [max_follows + 1][32]u8 = undefined;
        var authors_len: usize = 0;
        for (followSet()) |pk| {
            if (authors_len >= max_follows) break;
            authors[authors_len] = pk;
            authors_len += 1;
        }
        if (activePubkey()) |pk| {
            authors[authors_len] = pk;
            authors_len += 1;
        }
        // Only as much as the reader has paged into, so the rebuild cost stays
        // flat until they actually ask for more.
        // No ceiling. The reader asked for this many, so the storage grows to
        // hold them and the query asks for exactly that.
        const limit = @min(self.feed_limit, ensureFeedCapacity(self.feed_limit));
        // After a growth the old slice is freed, so re-point before using it.
        self.notes = feed_state.g_feed_notes;

        // Mention labels are baked into content at parse time, so a new display
        // name (the generation) forces one full parse pass to refresh them.
        const reuse_ok = g_names_generation == g_notes_names_generation;
        g_notes_names_generation = g_names_generation;

        // Always, and before deciding anything: whatever is waiting is either
        // spliced now or covered by the full read below, and leaving it in the
        // buffer would splice it a second time on the next tick.
        const arrived = takeFeedArrivals();

        // What the list in hand cannot be brought up to date FROM. Everything
        // else is an addition, and an addition is a merge.
        //
        //   the flag       the author set changed, the reader signed in or out,
        //                  or a deletion landed
        //   lost           more arrived between two ticks than the buffer holds
        //   !reuse_ok      a name moved, so every card's baked text is stale
        //   limit moved    the reader paged down, so notes below the old window
        //                  belong now and no arrival describes them
        // A place's notes arrive on its own socket, not through the ingest
        // buffer the splice path drains, so nothing in `arrived` ever describes
        // them. Its revision counter is what says there is something new, and
        // `refresh` consults the same counter before it gets here.
        const place_rev = places.g_place_rev.load(.monotonic);
        const place_moved = place_rev != feed_state.g_notes_place_rev;
        feed_state.g_notes_place_rev = place_rev;

        const full = feed_state.g_feed_rebuild_all.swap(false, .acq_rel) or
            place_moved or
            arrived.lost or
            !reuse_ok or
            limit != feed_state.g_notes_limit or
            self.feed_limit != feed_state.g_notes_feed_limit;
        feed_state.g_notes_limit = limit;
        feed_state.g_notes_feed_limit = self.feed_limit;

        if (full) {
            // In a place, the feed IS the place. Not your follows with a
            // header on top, which is what a lens would be and is exactly the
            // thing the room decision rejected.
            if (places.g_place != null) {
                self.rebuildNotesFromPlace(store, now_s, limit, reuse_ok);
            } else {
                self.rebuildNotesFromStore(store, now_s, authors[0..authors_len], &kinds, limit, reuse_ok);
            }
            return;
        }
        if (arrived.n == 0) return;
        self.spliceArrivals(store, now_s, authors[0..authors_len], &kinds, limit, arrived.n);
    }

    /// Reads the whole window back from the store: a cursor per followed author
    /// and a linear pick across all of them, per note returned. The expensive
    /// one, and the reason for everything above it.
    /// The same rebuild, reading the ids the place's relay sent rather than a
    /// set of authors. Shares `noteFrom`, the reuse index and the mute filter,
    /// because a note in a place is a note.
    fn rebuildNotesFromPlace(
        self: *Model,
        store: *nostr.store.Store,
        now_s: i64,
        limit: usize,
        reuse_ok: bool,
    ) void {
        var ids: [place_feed_cap][32]u8 = undefined;
        var ids_len: usize = 0;
        {
            lockPlaceIds();
            defer unlockPlaceIds();
            ids_len = places.g_place_ids_len;
            @memcpy(ids[0..ids_len], places.g_place_ids[0..ids_len]);
        }
        if (ids_len == 0) {
            self.notes_len = 0;
            return;
        }

        var result = store.query(std.heap.page_allocator, .{
            .ids = ids[0..ids_len],
            .limit = @intCast(limit),
        }) catch return;
        defer result.deinit();
        feed_state.g_feed_work.full_reads += 1;

        const old = feed_state.g_feed_scratch;
        const old_len = self.notes_len;
        @memcpy(old[0..old_len], self.notes[0..old_len]);
        const slots = if (reuse_ok) buildReuseIndex(old[0..old_len]) else &.{};

        var n: usize = 0;
        for (result.events) |ev| {
            if (n >= limit) break;
            // The reader's own mutes still apply inside a place. So what they
            // see is not exactly what the host published, and that is the right
            // way round: a host cannot un-mute somebody for you.
            if (isMuted(ev.pubkey)) continue;
            self.notes[n] = blk: {
                if (heldIndex(slots, old[0..old_len], ev.id)) |at| break :blk old[at];
                feed_state.g_feed_work.parses += 1;
                break :blk noteFrom(ev, now_s);
            };
            n += 1;
        }
        self.notes_len = n;
    }

    fn rebuildNotesFromStore(
        self: *Model,
        store: *nostr.store.Store,
        now_s: i64,
        authors: []const [32]u8,
        kinds: []const u16,
        limit: usize,
        reuse_ok: bool,
    ) void {
        // ONE QUERY PER KIND, merged here, rather than one query naming them all.
        //
        // The store picks its index on the product of authors and kinds: at or
        // under `max_merge_streams` (4096) it opens a cursor per author-kind
        // pair on `idx_author_kind`; over it, it drops to the plain author index
        // and pays a decode for every event those authors ever wrote. A full
        // follow list is 2049 authors, so one kind fits with room to spare and
        // two do not: 4098 pairs misses the cap by two, and the feed would
        // quietly become a full scan of everything two thousand people have
        // ever posted.
        //
        // Splitting by kind means the product is always authors times one,
        // whatever this list grows to. It is robust by construction rather than
        // correct up to a follow count nobody is watching, and it holds fewer
        // cursors open at once than the single query did. The events of one kind
        // come back newest-first, so merging them is a pick across `kinds.len`
        // cursors, which is the same thing the store does internally with three
        // streams instead of six thousand.
        var results: [feed_kind_cap]nostr.store.QueryResult = undefined;
        var results_len: usize = 0;
        defer for (results[0..results_len]) |*r| r.deinit();
        for (kinds) |kd| {
            if (results_len >= results.len) break;
            const one = [_]u16{kd};
            results[results_len] = store.query(std.heap.page_allocator, .{
                .authors = authors,
                .kinds = &one,
                .limit = @intCast(limit),
                // `return`, not `continue`. A failed read used to abandon the
                // whole rebuild and leave the feed as it was; skipping one kind
                // instead would silently show a feed missing everything of that
                // kind, which looks like an empty day rather than a failure.
                // The defer above frees whatever was opened before this.
            }) catch return;
            results_len += 1;
        }
        feed_state.g_feed_work.full_reads += 1;

        // Where each kind's result has been read up to.
        var cursors = [_]usize{0} ** feed_kind_cap;
        // What this pass has already placed, for the repost dedup below.
        const placed = placedReset(limit);

        // The old cards, so new positions can take them over by id.
        const old = feed_state.g_feed_scratch;
        const old_len = self.notes_len;
        @memcpy(old[0..old_len], self.notes[0..old_len]);
        const slots = if (reuse_ok) buildReuseIndex(old[0..old_len]) else &.{};

        var n: usize = 0;
        while (n < limit) {
            // The newest unread event across the per-kind results. Linear over
            // `kinds.len`, which is three.
            var best: ?usize = null;
            for (results[0..results_len], 0..) |r, i| {
                if (cursors[i] >= r.events.len) continue;
                if (best == null or
                    eventNewer(r.events[cursors[i]], results[best.?].events[cursors[best.?]])) best = i;
            }
            const bi = best orelse break;
            const ev = results[bi].events[cursors[bi]];
            cursors[bi] += 1;

            // A muted author never becomes a card. Filtered here rather than in
            // the query because the store has no idea who this reader muted, and
            // rather than at render time because a hidden row would still hold a
            // slot in a window that pages by count.
            if (isMuted(ev.pubkey)) continue;
            // A repost becomes the note it points at, so what is placed, reused
            // and deduped below is the REPOSTED note and not the wrapper.
            const card = feedCardFrom(store, ev, now_s) orelse continue;
            // One row per reposted note. Two follows passing the same note on is
            // one card, and a repost of something the window already holds does
            // not draw it twice. All four reference clients key this on the
            // reposted note; Amethyst's is `distinctBy { replyTo.last().idHex }`
            // with the comment "only the most recent repost per feed", and
            // reading newest-first is what makes the first one seen the keeper.
            if (placedTake(placed, self.notes[0..n], card.event_id, n)) continue;
            self.notes[n] = blk: {
                if (heldIndex(slots, old[0..old_len], card.event_id)) |at| {
                    var held = old[at];
                    // A held card may have been drawn plain before, or passed on
                    // by somebody else. The wrapper in hand is the newest one
                    // that named it, so the byline comes from this pass.
                    held.reposter = card.reposter;
                    held.has_reposter = card.has_reposter;
                    break :blk held;
                }
                feed_state.g_feed_work.parses += 1;
                break :blk card;
            };
            n += 1;
        }
        self.notes_len = n;
    }

    /// Merges the notes that just landed into the list already on screen.
    ///
    /// The ids come from the ingest threads, so the store is asked for exactly
    /// those and nothing else: a direct read per id, no cursor per follow and no
    /// pick across two thousand streams. Everything already held is carried over
    /// as it is, so no card is re-parsed and no picture is re-fetched.
    fn spliceArrivals(
        self: *Model,
        store: *nostr.store.Store,
        now_s: i64,
        authors: []const [32]u8,
        kinds: []const u16,
        limit: usize,
        arrived: usize,
    ) void {
        var result = store.query(std.heap.page_allocator, .{
            .ids = feed_state.g_arrival_taken[0..arrived],
            .kinds = kinds,
        }) catch {
            // The ids are gone with the buffer, so the only honest recovery is
            // to read the window back next tick.
            invalidateFeed();
            return;
        };
        defer result.deinit();
        feed_state.g_feed_work.splices += 1;
        if (result.events.len == 0) return;

        // Which of them this feed is actually about. The store was asked by id,
        // not by author, on purpose: an author list is checked one name at a
        // time, and asking about a handful of arrivals should not walk two
        // thousand follows per arrival. Only the ones that are NOT already held
        // pay that walk, and those are few.
        const held = buildReuseIndex(self.notes[0..self.notes_len]);
        var keep: usize = 0;
        for (result.events, 0..) |ev, i| {
            if (keep >= feed_state.g_splice_keep.len) break;
            if (ev.kind != 1) continue;
            if (heldIndex(held, self.notes[0..self.notes_len], ev.id) != null) continue;
            if (!authorInSet(authors, ev.pubkey)) continue;
            if (isMuted(ev.pubkey)) continue;
            // The window is full and this is older than everything in it, so it
            // would be dropped by the truncation below. Not worth parsing.
            if (self.notes_len >= limit and self.notes_len > 0 and
                !eventNewerThanNote(ev, self.notes[self.notes_len - 1])) continue;
            feed_state.g_splice_keep[keep] = @intCast(i);
            keep += 1;
        }
        if (keep == 0) return;

        // Two sorted runs into one. `result.events` is newest-first (the store
        // sorts it) and so is the list on screen, so this is one pass with no
        // sort and no search. Through the scratch copy rather than in place: an
        // in-place merge is only safe in one direction, and which direction
        // depends on whether the window is growing or already full.
        const old = feed_state.g_feed_scratch;
        const old_len = self.notes_len;
        @memcpy(old[0..old_len], self.notes[0..old_len]);

        const total = @min(old_len + keep, limit);
        var oi: usize = 0;
        var fi: usize = 0;
        for (0..total) |n| {
            const take_new = blk: {
                if (fi >= keep) break :blk false;
                if (oi >= old_len) break :blk true;
                break :blk eventNewerThanNote(result.events[feed_state.g_splice_keep[fi]], old[oi]);
            };
            if (take_new) {
                self.notes[n] = noteFrom(result.events[feed_state.g_splice_keep[fi]], now_s);
                feed_state.g_feed_work.parses += 1;
                fi += 1;
            } else {
                self.notes[n] = old[oi];
                oi += 1;
            }
        }
        self.notes_len = total;
    }
};

pub fn setIdentityForTest(secret: [32]u8) void {
    var signer = nostr.keys.Signer.init();
    defer signer.deinit();
    const kp = signer.keyPairFromSecretKey(secret) catch return;
    feed_state.g_test_secret = secret;
    adoptHelperIdentity(kp.public_key);
}

/// Clears the active identity again. For tests.
pub fn clearIdentityForTest() void {
    g_home_scope = .following;
    g_identity_npub_len = 0;
    g_signer_kind = .helper;
    feed_state.g_test_secret = null;
    g_helper_has_identity = false;
}

/// Forces the next reconcile to do the full work rather than take the
/// unchanged-store fast path, so a benchmark measures a rebuild.
pub fn invalidateFeedForTest() void {
    invalidateFeed();
}

/// Reconciles profiles and notes against `store` directly, bypassing change
/// detection entirely. For tests that drive the store themselves rather than
/// through `plazaIngest`, which is where an arrival announces itself: without
/// the announcement there is nothing to splice, so this asks for the full read.
///
/// Tests of the change-detection layer itself go through `plazaIngestForTest`
/// and `Model.refresh`, which is what the app runs.
/// Rebuilds the open thread's replies from the store. The real one runs off the
/// tick, which a test has no way to turn.
pub fn refreshThreadNotesForTest(model: *Model, now_s: i64) void {
    model.refreshThreadNotes(now_s);
}

pub fn reconcileForTest(model: *Model, store: *nostr.store.Store, now_s: i64) void {
    invalidateFeed();
    refreshProfiles(store);
    model.rebuildNotes(store, now_s);
}

/// A tick as the app actually takes one, including the gate that decides
/// whether the feed is rebuilt AT ALL.
///
/// `reconcileForTest` goes straight to `rebuildNotes` and invalidates on the
/// way in, so every test using it rebuilds unconditionally. That is the right
/// tool for asking what a rebuild produces, and it is why a place could sit on
/// "Connecting" forever with nothing red: the decision NOT to rebuild is the
/// part it skips.
pub fn refreshForTest(model: *Model, store: *nostr.store.Store, now_s: i64) void {
    setStoreForTest(store);
    model.refresh(now_s);
}

/// One tick, exactly as the app's timer runs it: change detection and all. The
/// entry point for tests of how the feed decides what to do, as opposed to what
/// a rebuild produces.
pub fn tickForTest(model: *Model, now_s: i64) void {
    model.refresh(now_s);
}

/// The open thread's or profile's share of a tick, on its own.
pub fn tickOpenLevelForTest(model: *Model, now_s: i64) void {
    refreshOpenLevel(model, now_s);
}

/// Marks a thread's reply fetch as finished, the way its worker does.
pub fn markThreadFetchDoneForTest(seq: u64) void {
    g_thread_done_seq.store(seq, .release);
}

/// Empties the arrival buffer and asks for a full read next time, so a test
/// starts from a known place rather than from whatever the last one left.
pub fn resetFeedChangeDetectionForTest() void {
    clearFeedArrivals();
    invalidateFeed();
    feed_state.g_notes_limit = 0;
    feed_state.g_notes_feed_limit = 0;
    g_last_count = std.math.maxInt(usize);
}

/// Announces an id as newly arrived without storing anything. For the case the
/// app is not supposed to produce and the splice guards against anyway.
pub fn noteFeedArrivalForTest(id: [32]u8) void {
    noteFeedArrival(id);
}

/// Fills the arrival buffer past its capacity, the way a backfill does.
pub fn overflowFeedArrivalsForTest() void {
    for (0..feed_arrival_cap + 1) |i| {
        var id = [_]u8{0} ** 32;
        std.mem.writeInt(u64, id[0..8], i, .big);
        noteFeedArrival(id);
    }
}

pub fn profileParsesForTest() usize {
    return feed_state.g_profile_parses;
}

/// The refresh the tick runs when the store moved.
pub fn refreshProfileNotesForTest(model: *Model) void {
    model.refreshProfileNotes(nowSeconds());
}

/// Makes room for `n` notes and re-points `model` at the grown buffer. For tests
/// that fill the feed by hand rather than through the store: the app grows on
/// its way through `rebuildNotes`, and writing past the end without that is the
/// out-of-bounds it should be.
/// One more page, the way the reader's scroll asks for it. For tests, so they
/// page down through the real path rather than setting the limit by hand.
pub fn loadOlderForTest(model: *Model) void {
    model.feed_limit += feed_page;
}

pub fn reserveFeedForTest(model: *Model, n: usize) void {
    _ = ensureFeedCapacity(n);
    model.notes = feed_state.g_feed_notes;
}
// The names generation the current cards were parsed under (see
// `g_names_generation`).
var g_notes_names_generation: u64 = 0;

/// Reads kind:0 metadata for the feed's authors from the store and parses each
/// into the profile cache. The store keeps only the newest kind:0 per author, so
/// this always reflects the current metadata.
fn refreshProfiles(store: *nostr.store.Store) void {
    const kinds = [_]u16{0};
    // Bounds-checked at every push. This array used to be sized off the
    // comptime pack with no checks, so the first runtime follow list longer than
    // nine would have written past it: silent stack corruption in a release
    // build, from a feature that has nothing to do with profiles.
    // NOT the follow list. This used to walk every follow, up to 2048 of them,
    // on the feed reconcile path, and ask LMDB for all of their metadata on
    // every rebuild. That is the single reason a bigger profile cache made
    // scrolling slower rather than faster: the query limit was derived from the
    // cache size, so growing the cache grew the query.
    //
    // No reference client does this. Notedeck collects pubkeys from notes that
    // were actually ingested and only on a database MISS, then asks in a
    // debounced batch, with no follow-list pass anywhere. Amethyst has no path
    // at all that requests kind:0 for a whole contact list: each name on screen
    // registers itself. Jumble does walk the follow list, but off the render
    // path entirely, twenty at a time with a one second sleep between batches.
    //
    // What replaces it is already here: a displayed author with no name calls
    // `wantProfile`, so the wanted set IS the on-screen set, which is exactly
    // the input Notedeck uses.
    var authors: [wanted_profiles_cap + 1][32]u8 = undefined;
    var authors_len: usize = 0;
    if (activePubkey()) |pk| {
        if (authors_len < authors.len) {
            authors[authors_len] = pk;
            authors_len += 1;
        }
    }
    // Anyone a note mentioned, so their name resolves once it arrives.
    for (&g_wanted) |*w| {
        if (!w.used) continue;
        if (authors_len >= authors.len) break;
        authors[authors_len] = w.pubkey;
        authors_len += 1;
    }
    if (authors_len == 0) return;
    // The limit is how many records the query can match, which is one kind:0
    // per author. It is not a cache size, and tying it to one was the bug.
    var result = store.query(std.heap.page_allocator, .{ .authors = authors[0..authors_len], .kinds = &kinds, .limit = @intCast(authors_len) }) catch return;
    defer result.deinit();
    for (result.events) |ev| {
        const p = upsertProfile(ev.pubkey) orelse continue;
        // The same event parses to the same fields; skip the JSON work.
        if (std.mem.eql(u8, &p.meta_id, &ev.id)) continue;
        const named_before = p.name_len > 0;
        const name_before = p.name_buf;
        parseMetadataInto(p, ev.content);
        p.meta_id = ev.id;
        if ((p.name_len > 0) != named_before or !std.mem.eql(u8, &p.name_buf, &name_before)) {
            g_names_generation +%= 1;
        }
    }
}

/// Marks `pubkey`'s profile as on screen this pass (creating the slot if new),
/// so the id LRU keeps its avatar and evicts someone off screen instead.
fn markAvatarWanted(pubkey: [32]u8) void {
    if (upsertProfile(pubkey)) |p| p.avatar_clock = g_image_clock;
}

/// Lends the `max_avatar_images` registry ids to the authors on screen right
/// now (the feed's visible window, or the open thread), reclaiming ids from
/// authors who scrolled away. There are far more cached authors than ids, so
/// without this only the first handful ever seen could hold a face and a
/// thread of strangers showed initials for everyone. Runs each tick before
/// `scanAvatarFetches`, which then fetches the faces for whoever just gained an
/// id. `fx` is needed to free a reclaimed id's registered image.
/// Asks for the kind:0 of everybody the reader is about to read.
///
/// The wanted set is the app's queue of "whose name do we still need", and it
/// was populated by exactly two callers: the inbox, and quoted notes. The FEED
/// never registered anybody. That was fine only for as long as `refreshProfiles`
/// walked the whole follow list, and when that walk was removed from the render
/// path the feed lost its only source of names: the comment left behind claimed
/// "a displayed author with no name calls `wantProfile`", which was true of the
/// notifications page it was written for and of nothing else.
///
/// What that looked like: real accounts, with profiles sitting on the relays,
/// drawn as a raw npub and a two-character avatar for the whole session. The
/// dial-time subscription asks for kind:0 alongside the notes, so most authors
/// resolve and the gap looks like an occasional glitch rather than a missing
/// mechanism. Anybody that one bounded backfill did not cover was never asked
/// about again.
///
/// Over the PREFETCH band, not just the visible rows, so a name is being fetched
/// while the row is still below the fold. This is the same window the image
/// warmer uses, and it has to be: `warmAvatar` needs `picture_len`, which comes
/// from the kind:0, so a face cannot be warmed ahead for somebody nobody asked
/// about. One missing registration was starving both.
///
/// Cheap to call every tick: `wantProfile` returns at once for anybody already
/// named, which after the first pass is nearly everybody.
fn wantProfilesAhead(model: *const Model) void {
    if (activePubkey()) |pk| wantProfile(pk);
    // The notifications page registers its own authors as rows are admitted,
    // which catches likers and zappers who are in no other set.
    if (model.notifications_open) return;
    if (model.levelOpen()) {
        const set = &g_level_visible[@min(g_visible_level, g_level_visible.len - 1)];
        for (set.authors[0..set.author_count]) |pk| wantProfile(pk);
        return;
    }
    const w = model.prefetchRange();
    var i = w.first;
    while (i <= w.last and i < model.notes_len) : (i += 1) wantProfile(model.notes[i].pubkey);
}

/// Opens one pass of the image passes: everything they mark as on screen is
/// marked against this tick.
///
/// Its own step, called by the tick rather than hidden inside whichever pass
/// happens to run first. Burying it in the avatar pass would have made the
/// picture pass silently depend on running second, and a later reordering would
/// have shown up as pictures thrashing rather than as anything named.
fn beginImagePass() void {
    g_image_clock += 1;
}

fn assignAvatarSlots(fx: *Effects, model: *const Model) void {

    // Collect the on-screen authors in READING ORDER (the active user, then the
    // thread's root and replies top-down, or the feed's visible window). Order
    // matters: there are far fewer ids than a long thread has authors, so the
    // ids are lent to the top of what is being read, not to an arbitrary cache
    // slot. Bounded to the largest set a single pass can hold.
    var onscreen: [thread_reply_cap + 4][32]u8 = undefined;
    var n: usize = 0;
    const push = struct {
        fn f(list: [][32]u8, len: *usize, pk: [32]u8) void {
            if (len.* < list.len) {
                list[len.*] = pk;
                len.* += 1;
            }
        }
    }.f;
    if (activePubkey()) |pk| push(&onscreen, &n, pk);
    if (model.notifications_open) {
        // The notifications page occludes everything, and its rows are the only
        // faces on screen. Without this branch its authors were never in the
        // set that lends registry slots, so every row drew initials no matter
        // how long the page stayed open: the ids were all out on loan to a feed
        // nobody could see.
        // Only the rows ON SCREEN, which is the same rule the thread branch
        // below spells out and the same mistake it is warning about. Pushing
        // all of them marked every author wanted, and the claim pass never
        // evicts anything wanted this pass, so nine ids were locked by rows the
        // reader could not see and every visible row kept its initials.
        var buf: [inbox_cap]InboxItem = undefined;
        const shown = inboxItems(&buf, !model.notifications_everyone);
        const first = @min(g_inbox_visible.first, shown.len);
        const last = @min(g_inbox_visible.last + 1, shown.len);
        if (last > first) {
            for (shown[first..last]) |item| push(&onscreen, &n, item.author);
        }
    } else if (model.levelOpen()) {
        // A level occludes the feed, so its authors own the ids while it is up,
        // and only the ones ON SCREEN in it. Walking every note in the level
        // instead meant the first nine authors of a long thread took every id
        // and kept it: the claim pass never evicts anything marked wanted this
        // pass, and marking all of them made every id unreclaimable. Everyone
        // below kept initials for as long as the level was open.
        const set = &g_level_visible[@min(g_visible_level, g_level_visible.len - 1)];
        for (set.authors[0..set.author_count]) |pk| push(&onscreen, &n, pk);
    } else {
        const w = model.visibleRange();
        var i = w.first;
        while (i <= w.last and i < model.notes_len) : (i += 1) push(&onscreen, &n, model.notes[i].pubkey);
    }

    // Mark every one wanted FIRST, so the claim pass below never evicts a
    // sibling that is also on screen this pass. Then lend an id to each in order,
    // so the earliest-read authors win the scarce ids.
    for (onscreen[0..n]) |pk| markAvatarWanted(pk);
    for (onscreen[0..n]) |pk| {
        const p = lookupProfile(pk) orelse continue;
        if (p.image_id == 0 and p.picture_len > 0) claimAvatarSlot(fx, p);
    }
}

// ------------------------------------------------- the whole-app image pool
//
// ONE allocator over all `image_registry_slots`, serving avatars, pictures and
// the profile banner alike. The block at the top of this file argues for it;
// this is it. Consumers differ only in what they downscale to, never in a
// reserved share, because a reserved share is capacity that sits idle on the
// screen that needs it: a profile page wants a banner and many faces and no
// feed pictures at all, and a feed of four-picture notes wants the opposite.

/// Who is holding each id. Derived from the consumers on every pass rather than
/// stored beside them: they already record which id they hold, and a second
/// table saying the same thing is a second thing that can be wrong.
const IdOwner = union(enum) {
    free,
    avatar: *Profile,
    banner,
    /// The open place's mark. It has to be an owner like any other: a slot this
    /// app holds but the pool does not know about reads as FREE, so the next
    /// face that arrives is handed the id the Info card is drawing. The reader
    /// sees the community's logo turn into somebody's avatar.
    place_logo,
    media: *MediaSlot,
};

/// One pass over the consumers, rather than a scan per id: the profile cache is
/// thousands of entries and this runs whenever a face or a picture appears.
fn imageIdOwners() [image_registry_slots + 1]IdOwner {
    var owners = [_]IdOwner{.free} ** (image_registry_slots + 1);
    if (g_banner_image_id >= 1 and g_banner_image_id <= image_registry_slots) {
        owners[@intCast(g_banner_image_id)] = .banner;
    }
    if (g_place_logo_id >= 1 and g_place_logo_id <= image_registry_slots) {
        owners[@intCast(g_place_logo_id)] = .place_logo;
    }
    for (&g_profiles) |*p| {
        if (p.used and p.image_id >= 1 and p.image_id <= image_registry_slots) {
            owners[@intCast(p.image_id)] = .{ .avatar = p };
        }
    }
    for (&g_media) |*m| {
        if (m.used and m.image_id >= 1 and m.image_id <= image_registry_slots) {
            owners[@intCast(m.image_id)] = .{ .media = m };
        }
    }
    return owners;
}

/// When a held id was last on screen, or null if it may not be taken at all.
///
/// Two things make an id untouchable, and they are the same two for every kind
/// of consumer: it is on screen THIS pass (taking it would evict something the
/// reader is looking at, and with the marking done first, that means a sibling
/// that has not been served yet), or a fetch is in flight for it (taking it
/// would hand the arriving bytes to whoever holds the id next).
fn imageIdSeen(owner: IdOwner) ?u64 {
    return switch (owner) {
        .free => null,
        .avatar => |p| if (p.avatar_clock == g_image_clock or p.avatar_state == .fetching) null else p.avatar_clock,
        .media => |m| if (m.last_used == g_image_clock or m.state == .fetching) null else m.last_used,
        .banner => if (g_banner_seen == g_image_clock) null else g_banner_seen,
        .place_logo => if (g_place_logo_seen == g_image_clock or g_place_logo_state == .fetching) null else g_place_logo_seen,
    };
}

/// Takes an id back from whoever holds it: the registered pixels go, and the
/// former owner is reset so it reloads (from the disk cache, usually) if the
/// reader comes back to it.
fn releaseImageId(fx: *Effects, owner: IdOwner, id: u64) void {
    _ = fx.unregisterImage(id);
    switch (owner) {
        .free => {},
        .avatar => |p| {
            p.image_id = 0;
            p.avatar_state = .idle;
        },
        .media => |m| {
            m.releaseFrames();
            m.image_id = 0;
            m.state = .idle;
        },
        .banner => {
            g_banner_image_id = 0;
            g_banner_state = .idle;
        },
        .place_logo => {
            g_place_logo_id = 0;
            g_place_logo_state = .idle;
        },
    }
}

const IdPick = struct { id: u64, owner: IdOwner };

/// WHICH id the next image should get: a free one, or the one whose holder has
/// been off screen longest. Null when every id is held by something on screen
/// or mid-fetch, which is the honest answer: the caller shows initials, or a
/// blurhash, for this frame and asks again next pass.
///
/// Separate from taking it because this is the whole rule, and taking it needs
/// the effects channel to drop the old pixels. The decision is what a test can
/// ask about.
fn chooseImageId(owners: *const [image_registry_slots + 1]IdOwner) ?IdPick {
    var id: u64 = 1;
    while (id <= image_registry_slots) : (id += 1) {
        if (owners[@intCast(id)] == .free) return .{ .id = id, .owner = .free };
    }

    var pick: ?IdPick = null;
    var oldest: u64 = std.math.maxInt(u64);
    id = 1;
    while (id <= image_registry_slots) : (id += 1) {
        const owner = owners[@intCast(id)];
        const seen = imageIdSeen(owner) orelse continue;
        if (seen < oldest) {
            oldest = seen;
            pick = .{ .id = id, .owner = owner };
        }
    }
    return pick;
}

/// Takes the id `chooseImageId` picked, dropping whatever was in it.
fn acquireImageId(fx: *Effects) ?u64 {
    const owners = imageIdOwners();
    const pick = chooseImageId(&owners) orelse return null;
    if (pick.owner != .free) releaseImageId(fx, pick.owner, pick.id);
    return pick.id;
}

/// Assigns `p` an id from the shared pool. A no-op when everything is spoken
/// for, and that author keeps initials this frame.
fn claimAvatarSlot(fx: *Effects, p: *Profile) void {
    p.image_id = acquireImageId(fx) orelse return;
}

/// Pulls the bytes for rows NEAR the viewport into the disk cache, without
/// claiming a registry id for any of them.
///
/// The two are separable and were not separated. Fetching was gated on holding
/// one of the nine avatar ids or six picture ids, and those are lent only to rows
/// already on screen, so every row arrived cold: blank, then a request, then a
/// face a moment later. Scroll and it happens again, forever, which is what makes
/// a feed feel like it is dragging even when the frame time is fine.
///
/// Nothing about downloading an image needs a slot. Only DISPLAYING it does. So a
/// band either side of the viewport is fetched and written to `~/.plaza/media`
/// ahead of time, and the local-first path that already exists (`loadCachedImage`
/// on claim, "registered before the first paint") turns that into an instant
/// face when the row does arrive.
fn warmAhead(fx: *Effects, model: *const Model) void {
    if (!prefs.g_media_previews) return;
    // Only the feed. A thread or a profile is a bounded level whose rows are all
    // fetched by the pass that owns it, and widening those would spend bandwidth
    // on rows that do not exist.
    if (model.levelOpen()) return;

    const warm = model.prefetchRange();
    const seen = model.visibleRange();
    // Budgets of their own, under the ceilings the on-screen passes use: warming
    // must never crowd out the row the reader is looking at. Faces are small and
    // there is one per row, so they get the larger share; a picture can be a
    // megabyte, and warming a stack of them for rows nobody reaches is how a
    // prefetch turns into somebody's data bill.
    const face_per_tick = 8;
    const picture_per_tick = 3;
    var faces: usize = 0;
    var pictures: usize = 0;

    var i = warm.first;
    while (i <= warm.last and i < model.notes_len) : (i += 1) {
        // The rows on screen are the other passes' business; they hold slots and
        // are already being fetched properly.
        if (i >= seen.first and i <= seen.last) continue;
        const note = &model.notes[i];
        if (faces < face_per_tick) {
            if (lookupProfile(note.pubkey)) |p| {
                if (warmAvatar(fx, p)) faces += 1;
            }
        }
        if (pictures < picture_per_tick and showsImage(note)) {
            if (warmPicture(fx, note)) pictures += 1;
        }
    }
}

/// Warms one face. Returns whether a fetch actually went out.
fn warmAvatar(fx: *Effects, p: *Profile) bool {
    if (p.warm_state != .idle or p.picture_len == 0) return false;
    // A face that HOLDS a registry id is the on-screen path's business, and
    // warming it would be a second request for the same bytes. Everything else is
    // warmable: a `.failed` fetch from a previous pass is worth one more try from
    // the cache's side, and `.idle` with no id is the ordinary case this exists
    // for. What is NOT warmable is a face already in the cache, which the check
    // below settles.
    if (p.image_id != 0 or p.avatar_state == .loaded) return false;

    var url_buf: [1024]u8 = undefined;
    const url = avatarUrl(&url_buf, p.picture(), p.avatar_direct);
    if (cachedImageExists(url)) {
        p.warm_state = .done;
        return false;
    }
    const index = profileIndexOf(p) orelse return false;
    p.warm_state = .fetching;
    fx.fetch(.{
        .key = avatar_warm_key_base + index,
        .url = url,
        .on_response = Effects.responseMsg(.avatar_warmed),
    });
    return true;
}

/// Warms one picture. Keyed by the note's own id rather than a slot, since the
/// whole point is that it has no slot.
fn warmPicture(fx: *Effects, note: *const Note) bool {
    const raw = note.imageUrl();
    if (raw.len == 0) return false;
    var url_buf: [1024]u8 = undefined;
    const url = feedImageUrl(&url_buf, raw);
    if (warmedAlready(url)) return false;
    if (cachedImageExists(url)) {
        _ = rememberWarmed(url);
        return false;
    }
    // A slot's worth of key space, indexed by the ring position rather than by a
    // media slot, which this deliberately does not hold.
    const index = rememberWarmed(url);
    fx.fetch(.{
        .key = media_warm_key_base + index,
        .url = url,
        .on_response = Effects.responseMsg(.media_warmed),
    });
    return true;
}

/// The URLs warmed recently, so a row hovering just off screen is not re-fetched
/// every tick. A ring rather than a set: it only has to stop a repeat within the
/// few seconds a row spends near the edge, and a cache hit is the backstop for
/// anything it forgets.
const warm_ring_len = 32;
const WarmEntry = struct {
    hash: u64 = 0,
    url_buf: [1024]u8 = [_]u8{0} ** 1024,
    url_len: u16 = 0,

    fn url(self: *const WarmEntry) []const u8 {
        return self.url_buf[0..self.url_len];
    }
};
var g_warm_ring: [warm_ring_len]WarmEntry = [_]WarmEntry{.{}} ** warm_ring_len;
var g_warm_ring_next: u64 = 0;

fn warmedAlready(url: []const u8) bool {
    const h = std.hash.Wyhash.hash(0, url);
    for (&g_warm_ring) |*seen| {
        if (seen.hash == h and seen.url_len != 0) return true;
    }
    return false;
}

/// Records the attempt AND the URL, because the effect response carries a key
/// and a body but not the address it came from, and the cache is keyed by the
/// address.
fn rememberWarmed(url: []const u8) u64 {
    const slot = g_warm_ring_next % warm_ring_len;
    const e = &g_warm_ring[@intCast(slot)];
    e.hash = std.hash.Wyhash.hash(0, url);
    const n = @min(url.len, e.url_buf.len);
    @memcpy(e.url_buf[0..n], url[0..n]);
    e.url_len = @intCast(n);
    g_warm_ring_next +%= 1;
    return slot;
}

/// The index of `p` within the profile table, which is what the avatar fetch
/// keys are built from.
fn profileIndexOf(p: *const Profile) ?u64 {
    for (&g_profiles, 0..) |*q, i| {
        if (q == p) return @intCast(i);
    }
    return null;
}

/// A warmed face's bytes: written to the cache, never registered. The row that
/// eventually shows it claims an id and loads it from disk.
fn handleAvatarWarmed(response: native_sdk.EffectResponse) void {
    if (response.key < avatar_warm_key_base) return;
    const index = response.key - avatar_warm_key_base;
    if (index >= g_profiles.len) return;
    const p = &g_profiles[@intCast(index)];
    if (!p.used) return;
    // A rejection is a busy effect table, not a bad URL: leave it warmable.
    if (response.outcome == .rejected) {
        p.warm_state = .idle;
        return;
    }
    p.warm_state = .done;
    if (response.outcome != .ok or response.status != 200 or response.truncated) return;
    if (response.body.len == 0 or response.body.len > max_image_bytes) return;
    var url_buf: [1024]u8 = undefined;
    const url = avatarUrl(&url_buf, p.picture(), p.avatar_direct);
    storeCachedImage(url, response.body);
}

/// The same for a picture. There is no per-note state to update: the ring already
/// recorded the attempt, and the file is the result.
fn handleMediaWarmed(response: native_sdk.EffectResponse) void {
    if (response.key < media_warm_key_base) return;
    const slot = response.key - media_warm_key_base;
    if (slot >= g_warm_ring.len) return;
    if (response.outcome != .ok or response.status != 200 or response.truncated) return;
    // Warming stays one request, so a picture bigger than one body is not warmed
    // at all: it is fetched in slices when its row reaches the screen, and
    // cached then. The cost is that a big picture arrives a moment late the
    // first time and instantly ever after, which is worth more than holding a
    // prefetch slot open across several round trips for a row nobody has
    // reached yet.
    if (response.body.len == 0 or response.body.len > max_image_bytes) return;
    // The ring is what remembers the address: a response carries a key and a
    // body, and the cache is keyed by the URL. A slot reused by a later warm
    // before this answer arrived writes the newer URL's name, so the hash is
    // checked rather than assumed.
    const e = &g_warm_ring[@intCast(slot)];
    if (e.url_len == 0) return;
    storeCachedImage(e.url(), response.body);
}

/// Fires avatar fetches for cached profiles that have a picture and an image
/// slot but no avatar yet, a few per tick to stay well inside the effect budget.
/// The response lands on `avatar_fetched`.
fn scanAvatarFetches(fx: *Effects) void {
    // A face is something the note points at, like its picture.
    if (!prefs.g_media_previews) return;
    const per_tick = 8;
    var fired: usize = 0;
    for (&g_profiles, 0..) |*p, i| {
        if (!p.used or p.avatar_state != .idle or p.picture_len == 0 or p.image_id == 0) continue;

        var url_buf: [1024]u8 = undefined;
        const url = avatarUrl(&url_buf, p.picture(), p.avatar_direct);
        const n = @min(url.len, p.url_buf.len);
        @memcpy(p.url_buf[0..n], url[0..n]);
        p.url_len = @intCast(n);

        // Local-first: a cached avatar is registered before the first paint, so
        // faces arrive with the feed rather than seconds after it.
        if (loadCachedImage(fx, p.image_id, p.url(), avatar_target_px)) |_| {
            p.avatar_state = .loaded;
            continue;
        }
        if (fired >= per_tick) continue;
        p.avatar_state = .fetching;
        p.down.release();
        fetchSlice(fx, avatar_fetch_key_base + @as(u64, @intCast(i)), p.url(), 0, Effects.responseMsg(.avatar_fetched));
        fired += 1;
    }
}

/// Handles an avatar fetch response: registers the decoded image on success, or
/// retries a slot-starved rejection and gives up (initials) on anything else.
fn handleAvatarFetched(fx: *Effects, response: native_sdk.EffectResponse) void {
    if (response.key < avatar_fetch_key_base) return;
    const slot = response.key - avatar_fetch_key_base;
    if (slot >= g_profiles.len) return;
    const p = &g_profiles[@intCast(slot)];
    if (!p.used) return;

    // A rejection means every effect slot was busy: try again next tick.
    if (response.outcome == .rejected) {
        p.down.release();
        p.avatar_state = .idle;
        return;
    }
    // A slice of a face bigger than one body: take it, and ask for the next
    // unless the host just said there is no next.
    if (response.outcome == .ok and response.status == 206 and !response.truncated and response.body.len > 0) {
        const outcome = p.down.append(response.body) orelse {
            p.down.release();
            p.avatar_state = .failed;
            return;
        };
        if (outcome == .want_more) {
            fetchSlice(fx, response.key, p.url(), p.down.len, Effects.responseMsg(.avatar_fetched));
            return;
        }
        const whole = p.down.bytes() orelse response.body;
        finishAvatar(fx, p, whole);
        p.down.release();
        return;
    }
    // Anything but a clean, whole, OK image body. Which of those is worth asking
    // again is the same question the feed's pictures ask, so it is the same
    // answer: a face used to be given up on for the rest of the session over one
    // 503, one rate limit, or one dropped connection.
    if (response.outcome != .ok or response.status != 200 or response.truncated or response.body.len == 0 or response.body.len > max_image_bytes) {
        p.down.release();
        // The proxy refusing the HOST is a different question from the picture
        // being unusable, so it gets the source itself rather than another go
        // at the same wall. Once per face, and only while the proxy is what was
        // used, so it can never loop. The attempt counter is untouched.
        if (prefs.g_media_direct_fallback and prefs.g_media_proxy_on and !p.avatar_direct and
            proxyRefusedHost(response.outcome, response.status))
        {
            // Written down for the whole host, not just this face: the refusal
            // is a fact about where the picture lives, and every other picture
            // there can skip the round trip that discovers it.
            rememberProxyRefusal(p.picture());
            p.avatar_direct = true;
            p.avatar_state = .idle;
            return;
        }
        p.avatar_state = switch (classifyImageFailure(response.outcome, response.status)) {
            .give_up => .failed,
            .retry => blk: {
                p.avatar_attempts +|= 1;
                break :blk if (p.avatar_attempts >= max_image_attempts) .failed else .idle;
            },
        };
        return;
    }
    p.down.release();
    finishAvatar(fx, p, response.body);
}

/// Decodes a complete face into `p`'s registry id and remembers it.
fn finishAvatar(fx: *Effects, p: *Profile, bytes: []const u8) void {
    // Downscaling if the platform decoder will not take it as-is. Only a
    // genuinely undecodable body falls back to initials now.
    if (decodeAndRegister(fx, p.image_id, bytes, avatar_target_px)) |_| {
        p.avatar_state = .loaded;
        p.avatar_attempts = 0;
        storeCachedImage(p.url(), bytes);
    } else {
        // Undecodable bytes are a fact about the picture, not about the network.
        p.avatar_state = .failed;
    }
}

/// A NIP-05 local part (`^[a-z0-9-_.]+$`, case-insensitive per the spec), so the
/// name drops straight into the query string without escaping.
pub fn validNip05Name(name: []const u8) bool {
    if (name.len == 0 or name.len > 64) return false;
    for (name) |c| {
        if (!(std.ascii.isAlphanumeric(c) or c == '-' or c == '_' or c == '.')) return false;
    }
    return true;
}

/// A plausible host (optionally `host:port`) for the well-known URL. Guards the
/// fetch against a malformed identifier rather than trusting the kind:0 blob.
pub fn validNip05Domain(domain: []const u8) bool {
    if (domain.len == 0 or domain.len > 253) return false;
    if (std.mem.indexOfScalar(u8, domain, '.') == null) return false;
    for (domain) |c| {
        if (!(std.ascii.isAlphanumeric(c) or c == '.' or c == '-' or c == '_' or c == ':')) return false;
    }
    return true;
}

/// Fires NIP-05 well-known lookups for cached profiles that carry an identifier
/// and have not been checked, a few per tick. The response lands on
/// `nip05_verified`; only a match flips the profile to `.verified`, and only
/// then does the identity line draw its check.
fn scanNip05Fetches(fx: *Effects) void {
    // Verifying a NIP-05 means asking a domain a stranger wrote whether it knows
    // this key, from the reader's own address. That is the same disclosure the
    // switch exists to stop, so it stops here too, and unverified names simply
    // show without a check.
    if (!prefs.g_media_previews) return;
    const per_tick = 4;
    var fired: usize = 0;
    for (&g_profiles, 0..) |*p, i| {
        if (!p.used or p.nip05_state != .idle or p.nip05_len == 0) continue;
        const at = std.mem.indexOfScalar(u8, p.nip05(), '@') orelse {
            p.nip05_state = .failed;
            continue;
        };
        const name = p.nip05()[0..at];
        const domain = p.nip05()[at + 1 ..];
        if (!validNip05Name(name) or !validNip05Domain(domain)) {
            p.nip05_state = .failed;
            continue;
        }
        if (fired >= per_tick) continue;
        var url_buf: [320]u8 = undefined;
        const url = std.fmt.bufPrint(&url_buf, "https://{s}/.well-known/nostr.json?name={s}", .{ domain, name }) catch {
            p.nip05_state = .failed;
            continue;
        };
        p.nip05_state = .fetching;
        fx.fetch(.{
            .key = nip05_fetch_key_base + @as(u64, @intCast(i)),
            .url = url,
            .on_response = Effects.responseMsg(.nip05_verified),
        });
        fired += 1;
    }
}

/// True when the well-known JSON maps the identifier's name to `pubkey`. This is
/// the whole trust test: a check is drawn on this and nothing weaker.
// --------------------------------------------------------------- the update
//
// Whoever installed Plaza is otherwise on that build until they happen to visit
// the site, which makes shipping a fix worth less than it should be.
//
// TOLD, not done. Plaza is ad-hoc signed and installed by a script that clears
// quarantine, and it is not going to replace its own bundle while running. A
// line saying a newer version exists, with one press to go and get it, is the
// honest amount of automation for how this app is distributed. The toolkit does
// ship a signed self-updater; it swaps the bundle and relaunches, it is macOS
// only while Plaza also ships Linux, and it wants a signed feed hosted
// somewhere. All three are reasons this does not use it.
//
// The releases API, because that is the same document `scripts/install-macos.sh`
// already reads. One source of truth for what the newest release is, rather than
// a second one to keep in step.

pub fn updateNewsForTest(body: []const u8) void {
    handleUpdateChecked(.{ .key = update_check_key, .outcome = .ok, .status = 200, .body = body, .truncated = false, .dropped_before = 0 });
}

pub fn resetUpdateStateForTest() void {
    updates.g_update_check = true;
    updates.g_update_version_len = 0;
    updates.g_update_url_len = 0;
    updates.g_update_asking = false;
    updates.g_update_dismissed = false;
    updates.g_update_next_at_ms = 0;
}

pub fn nip05Matches(identifier: []const u8, pubkey: [32]u8, body: []const u8) bool {
    const at = std.mem.indexOfScalar(u8, identifier, '@') orelse return false;
    const name = identifier[0..at];
    if (name.len == 0) return false;

    var arena_state = std.heap.ArenaAllocator.init(std.heap.page_allocator);
    defer arena_state.deinit();
    const root = std.json.parseFromSliceLeaky(std.json.Value, arena_state.allocator(), body, .{}) catch return false;
    if (root != .object) return false;
    const names = root.object.get("names") orelse return false;
    if (names != .object) return false;
    const entry = names.object.get(name) orelse return false;
    if (entry != .string) return false;

    const want = std.fmt.bytesToHex(pubkey, .lower);
    return std.ascii.eqlIgnoreCase(entry.string, &want);
}

/// Handles a NIP-05 fetch response: verified only on a well-known name→pubkey
/// match; a busy slot retries next tick; anything else fails closed (no check).
fn handleNip05Fetched(response: native_sdk.EffectResponse) void {
    if (response.key < nip05_fetch_key_base) return;
    const slot = response.key - nip05_fetch_key_base;
    if (slot >= g_profiles.len) return;
    const p = &g_profiles[@intCast(slot)];
    if (!p.used or p.nip05_len == 0) return;

    if (response.outcome == .rejected) {
        p.nip05_state = .idle;
        return;
    }
    if (response.outcome != .ok or response.status != 200 or response.truncated or response.body.len == 0) {
        p.nip05_state = .failed;
        return;
    }
    p.nip05_state = if (nip05Matches(p.nip05(), p.pubkey, response.body)) .verified else .failed;
}

// --------------------------------------------------------------- image decode
//
// The canvas image registry decodes through the platform codec and refuses
// anything over 512x512, with no downscaler of its own. Most real avatars and
// nearly every feed photo are larger than that, so Plaza decodes and resizes
// them itself: the platform decoder is tried first (it knows every format the
// OS does, WebP and HEIC included), and stb takes over when it refuses.

/// Whether the vendored decoder can read `bytes` at all. Test seam: what makes
/// the platform fallback in `decodeAndRegister` load-bearing is precisely which
/// formats stb was NOT built for.
pub fn stbCanDecodeForTest(bytes: []const u8) bool {
    var w: c_int = 0;
    var h: c_int = 0;
    var comp: c_int = 0;
    const px = stbi_load_from_memory(bytes.ptr, @intCast(bytes.len), &w, &h, &comp, 4) orelse return false;
    stbi_image_free(px);
    return true;
}

extern fn stbi_load_from_memory(buffer: [*]const u8, len: c_int, x: *c_int, y: *c_int, channels_in_file: *c_int, desired_channels: c_int) ?[*]u8;
extern fn stbi_load_gif_from_memory(buffer: [*]const u8, len: c_int, delays: *?[*]c_int, x: *c_int, y: *c_int, z: *c_int, comp: ?*c_int, req_comp: c_int) ?[*]u8;
extern fn stbi_image_free(retval_from_stbi_load: ?*anyopaque) void;
extern fn stbir_resize_uint8_linear(input_pixels: [*]const u8, input_w: c_int, input_h: c_int, input_stride_in_bytes: c_int, output_pixels: [*]u8, output_w: c_int, output_h: c_int, output_stride_in_bytes: c_int, pixel_layout: c_int) ?[*]u8;

/// `STBIR_RGBA`: four channels, alpha not premultiplied, which is what both stb
/// hands back and the registry wants.
const stbir_rgba: c_int = 4;

// The image cache: every image Plaza fetches is written to `$HOME/.plaza/media`
// under a hash of the URL it was fetched from (which encodes the requested
// size), and read back before the network is touched. This is what makes
// avatars and pictures local-first like the notes themselves: on every launch
// after the first they are on screen with the feed, not seconds later.

/// The cache file name for `url`: its SHA-256, hex encoded.
fn cacheName(out: *[64]u8, url: []const u8) []const u8 {
    var digest: [32]u8 = undefined;
    std.crypto.hash.sha2.Sha256.hash(url, &digest, .{});
    const hexdigits = "0123456789abcdef";
    for (digest, 0..) |b, i| {
        out[i * 2] = hexdigits[b >> 4];
        out[i * 2 + 1] = hexdigits[b & 0x0f];
    }
    return out[0..];
}

/// Opens (creating if needed) `$HOME/.plaza/media`.
fn mediaCacheDir(io: std.Io, environ: *const std.process.Environ.Map) !std.Io.Dir {
    const home = environ.get("HOME") orelse ".";
    var dir_buf: [512]u8 = undefined;
    const dir_path = try std.fmt.bufPrint(&dir_buf, "{s}/.plaza/media", .{home});
    return std.Io.Dir.cwd().createDirPathOpen(io, dir_path, .{});
}

/// Registers `url`'s image from the on-disk cache, if it is there. Reading a
/// handful of small files is fast enough to do inline, and it is what lets the
/// first painted frame already carry avatars.
fn loadCachedImage(fx: *Effects, id: u64, url: []const u8, max_dim: u32) ?DecodedSize {
    const io = g_io orelse return null;
    const environ = g_environ orelse return null;
    var dir = mediaCacheDir(io, environ) catch return null;
    defer dir.close(io);

    var name_buf: [64]u8 = undefined;
    const name = cacheName(&name_buf, url);
    const gpa = std.heap.page_allocator;
    const bytes = dir.readFileAlloc(io, name, gpa, std.Io.Limit.limited(max_image_download_bytes)) catch return null;
    defer gpa.free(bytes);
    return decodeAndRegister(fx, id, bytes, max_dim);
}

/// Writes a freshly fetched image into the cache. Best-effort: a failure here
/// only costs a re-download next launch.
/// The address a feed picture is fetched from, wherever it is fetched from.
///
/// ONE builder, because the disk cache is keyed by this string and two callers
/// derive it: the row that has a slot, and the warm pass that does not. Ask for
/// a different size, or forget the GIF branch, and the warmed bytes land under a
/// name nothing looks up: the download happens twice and the row still waits. A
/// test could compare two spellings; sharing the function means there are not
/// two to compare.
fn feedImageUrl(buf: []u8, src: []const u8) []const u8 {
    return feedImageUrlDirect(buf, src, false);
}

/// A face's URL, with `direct` skipping the proxy and asking the host itself.
///
/// The proxy refuses some hosts by policy rather than by picture: wsrv.nl
/// answers 400 for a `.pub` domain, which is where Ditto's Blossom server
/// lives, so those faces never arrive at all without this. The picture is
/// still resized by us afterwards, the same as a feed image fetched direct.
fn avatarUrl(buf: []u8, src: []const u8, direct: bool) []const u8 {
    if (direct or proxyRefusesHost(src)) return src;
    return mediaUrl(buf, src, avatar_target_px, .square);
}

/// The same, with `direct` skipping the proxy and asking the host itself.
///
/// The picture is still resized afterwards, by us: `decodeAndRegister` scales
/// anything over the registry's budget. What a direct fetch costs is the bytes
/// on the way in, since the proxy would have shrunk them first.
fn feedImageUrlDirect(buf: []u8, src: []const u8, direct: bool) []const u8 {
    if (direct or proxyRefusesHost(src)) return src;
    return if (isGifUrl(src))
        mediaUrl(buf, src, gif_target_px, .animation)
    else
        mediaUrl(buf, src, media_target_px, .inside);
}

pub fn avatarUrlForTest(buf: []u8, src: []const u8, direct: bool) []const u8 {
    return avatarUrl(buf, src, direct);
}

pub fn feedImageUrlForTest(buf: []u8, src: []const u8) []const u8 {
    return feedImageUrl(buf, src);
}

pub const feed_prefetch_rows_for_test = feed_prefetch_rows;
pub const gif_target_px_for_test = gif_target_px;
pub const media_target_px_for_test = media_target_px;

pub fn mediaUrlForTest(buf: []u8, src: []const u8, px: u32, fit: MediaFit) []const u8 {
    return mediaUrl(buf, src, px, fit);
}

/// The address warming asks for, so a test can hold it against the one the row
/// will look up. They are built in two places and must not drift.
pub fn setVisibleRangeForTest(first: usize, last: usize) void {
    g_visible_first = first;
    g_visible_last = last;
}

/// Whether the disk cache already holds this URL's bytes. Cheaper than loading
/// them: warming only needs to know whether to ask the network, and decoding is
/// the expensive half.
fn cachedImageExists(url: []const u8) bool {
    const io = g_io orelse return false;
    const environ = g_environ orelse return false;
    var dir = mediaCacheDir(io, environ) catch return false;
    defer dir.close(io);
    var name_buf: [64]u8 = undefined;
    const name = cacheName(&name_buf, url);
    var file = dir.openFile(io, name, .{}) catch return false;
    file.close(io);
    return true;
}

fn storeCachedImage(url: []const u8, bytes: []const u8) void {
    const io = g_io orelse return;
    const environ = g_environ orelse return;
    var dir = mediaCacheDir(io, environ) catch return;
    defer dir.close(io);

    var name_buf: [64]u8 = undefined;
    const name = cacheName(&name_buf, url);
    dir.writeFile(io, .{
        .sub_path = name,
        .data = bytes,
        .flags = .{ .permissions = secret_file_permissions },
    }) catch {};
}

/// The pixel size an image ended up registered at, so the view can lay it out
/// at its real aspect instead of stretching it into whatever box it is given.
const DecodedSize = struct { width: usize, height: usize };

/// The largest single dimension worth decoding. Its only real job is to make the
/// area check below safe to compute: squared it is 2^28, nowhere near overflowing
/// a usize, so `w * h` cannot wrap before anybody looks at it.
const image_max_dim = 16384;

/// And the area, which is the number that actually costs memory: four bytes a
/// pixel, so this is a 160 MB decode at the limit. A photograph does not reach
/// it; a file built to make an app allocate does.
const image_max_pixels = 40 * 1024 * 1024;

/// Whether a decoded image's own declared size is one to go on with.
pub fn imageSizeUsable(width: usize, height: usize) bool {
    if (width == 0 or height == 0) return false;
    // Both dimensions FIRST, so the multiply that follows cannot wrap. Checking
    // the area alone would be the check computing the very number it exists to
    // decide is safe.
    if (width > image_max_dim or height > image_max_dim) return false;
    return width * height <= image_max_pixels;
}

/// Decodes `bytes` and registers the pixels under `id`, downscaling so the long
/// edge is at most `max_dim`. Returns the registered size, or null on failure.
fn decodeAndRegister(fx: *Effects, id: u64, bytes: []const u8, max_dim: u32) ?DecodedSize {
    @setRuntimeSafety(true); // Pixel dimensions a stranger's file declares, multiplied into a buffer size.
    // Fast path: let the platform decode and register directly, but only when
    // what it produces is close to what this caller asked for.
    //
    // SDK 0.9.2 taught the platform decoder to downsample (thumbnail-at-index
    // against a pixel budget), so this stopped failing on real photos and
    // started succeeding on nearly all of them. That is the fix I asked for and
    // it is worth taking. The catch is that it fits the REGISTRY BUDGET, not
    // `max_dim`: it hands back roughly 512x512 whatever the caller wanted. For
    // feed media (480) and a banner (512) that is the right answer. For an
    // avatar drawn at 40pt and asked for at 128 it is four times the pixels on
    // each edge, so sixteen times the texture bytes, for every face on screen.
    //
    // So the small consumers TRY the vendored decoder first, which honours
    // `max_dim` exactly. They do not skip the platform: that broke every face in
    // the app. stb is compiled for JPEG, PNG and GIF only, and the image proxy
    // hands back WEBP, which is 327 of the 400 files in my own media cache. A
    // gate that sent avatars straight to stb sent them to a decoder that cannot
    // read the format they arrive in, so they all fell back to initials.
    //
    // Hence: platform first when the size it picks is the size we want, stb in
    // the middle because it honours `max_dim`, and platform LAST as the format
    // fallback. Every image gets a decoder that can read it, and only the ones
    // stb can read pay for the smaller texture.
    if (max_dim >= media_target_px) {
        if (fx.registerImageBytes(id, bytes)) |registered| {
            return .{ .width = registered.width, .height = registered.height };
        } else |_| {}
    }

    var w: c_int = 0;
    var h: c_int = 0;
    var comp: c_int = 0;
    const pixels = stbi_load_from_memory(bytes.ptr, @intCast(bytes.len), &w, &h, &comp, 4) orelse {
        // A format stb was not built for, which in practice means WEBP. The
        // platform decoder reads it, so ask even though it will come back
        // larger than `max_dim`: a face at the wrong size beats no face.
        if (max_dim < media_target_px) {
            if (fx.registerImageBytes(id, bytes)) |registered| {
                return .{ .width = registered.width, .height = registered.height };
            } else |_| {}
        }
        return null;
    };
    defer stbi_image_free(pixels);
    if (w <= 0 or h <= 0) return null;

    const src_w: usize = @intCast(w);
    const src_h: usize = @intCast(h);
    // What the C decoder handed back, checked before anything multiplies it.
    //
    // Every line below turns these two numbers into a buffer size, and they came
    // out of a file somebody linked in a note. stb caps a single dimension at
    // 2^24, which is a product of 2^48 pixels, so "it decoded" is not the same as
    // "this is a size to allocate". The safety check above would catch the
    // overflow itself, but catching it means the app stops; refusing the picture
    // means the app carries on without it, which is the right answer for one
    // oversized image in a feed.
    if (!imageSizeUsable(src_w, src_h)) return null;
    const longest = @max(src_w, src_h);
    if (longest <= max_dim) {
        // The platform refused it for some other reason; the decoded pixels
        // still fit, so register them as they are.
        fx.registerImage(id, src_w, src_h, pixels[0 .. src_w * src_h * 4]) catch return null;
        return .{ .width = src_w, .height = src_h };
    }

    const scale = @as(f64, @floatFromInt(max_dim)) / @as(f64, @floatFromInt(longest));
    const dst_w: usize = @max(1, @as(usize, @intFromFloat(@as(f64, @floatFromInt(src_w)) * scale)));
    const dst_h: usize = @max(1, @as(usize, @intFromFloat(@as(f64, @floatFromInt(src_h)) * scale)));

    const gpa = std.heap.page_allocator;
    const out = gpa.alloc(u8, dst_w * dst_h * 4) catch return null;
    defer gpa.free(out);
    if (stbir_resize_uint8_linear(pixels, w, h, 0, out.ptr, @intCast(dst_w), @intCast(dst_h), 0, stbir_rgba) == null) return null;
    fx.registerImage(id, dst_w, dst_h, out) catch return null;
    return .{ .width = dst_w, .height = dst_h };
}

// ---------------------------------------------------------------- feed media
//
// Feed images take the image ids the avatars do not, through a small LRU keyed
// by note. Only the top of the feed loads for now: that is what the budget
// holds and what is on screen at rest. Windowed visibility (load exactly what
// is in view, evict what leaves) arrives with the virtual list.

const MediaSlot = struct {
    used: bool = false,
    note_id: i64 = 0,
    image_id: u64 = 0,
    state: enum { idle, fetching, loaded, failed } = .idle,
    /// Fetches for this slot's URL that came back unusable for a reason worth
    /// retrying. Reset when the slot is handed to a different note, because
    /// `claimMediaSlot` rebuilds the whole struct.
    attempts: u8 = 0,
    /// Tick counter at the last time this note was still wanted, for eviction.
    last_used: u64 = 0,
    /// The registered pixel size, so the card can lay the picture out at its
    /// own aspect rather than stretching it.
    width: usize = 0,
    height: usize = 0,
    /// The resolved URL this image is fetched from, which is also its cache key.
    url_buf: [1024]u8 = [_]u8{0} ** 1024,
    url_len: u16 = 0,
    /// The host the picture actually lives on, which is NOT the host of
    /// `url_buf` while the proxy is in the way. Kept because a refusal is a
    /// fact about this host and has to be written down under it, and the
    /// response handler has nothing else to learn it from.
    host_buf: [96]u8 = [_]u8{0} ** 96,
    host_len: u8 = 0,
    /// Ask this picture's own host next time, skipping the proxy.
    ///
    /// Set when a proxied fetch came back unusable, so the retry goes to the
    /// source. The public proxy refuses whole TLDs by policy and answers 400 for
    /// hosts that serve the same file directly without complaint, and from here
    /// that is indistinguishable from any other refusal: what is observable is
    /// that the proxy would not produce the picture.
    ///
    /// One flag rather than a counter, because it is one alternative: proxy,
    /// then source, then give up. Reset with the rest of the slot when it is
    /// handed to a different note.
    direct: bool = false,
    /// A picture too big for one response body, assembled out of Range slices.
    down: Download = .{},
    /// Every frame of an animated GIF, decoded once and owned by stb (freed on
    /// eviction). Null for a still picture.
    frames: ?[*]u8 = null,
    frame_count: u16 = 0,
    frame_index: u16 = 0,
    /// Milliseconds this GIF holds each frame, and how much of that has elapsed.
    frame_delay_ms: u32 = 100,
    elapsed_ms: u32 = 0,

    fn url(self: *const MediaSlot) []const u8 {
        return self.url_buf[0..self.url_len];
    }
    fn host(self: *const MediaSlot) []const u8 {
        return self.host_buf[0..self.host_len];
    }
    fn animated(self: *const MediaSlot) bool {
        return self.frames != null and self.frame_count > 1;
    }
    /// Releases the decoded frames, if any. Called before a slot is reused.
    fn releaseFrames(self: *MediaSlot) void {
        if (self.frames) |px| stbi_image_free(px);
        self.frames = null;
        self.frame_count = 0;
        self.frame_index = 0;
    }
};

var g_media = [_]MediaSlot{.{}} ** max_media_images;

// The rows the windowed list last put on screen. Written by the view (which is
// where the runtime resolves the window) and read by the fetch pass in
// `update`, so the image budget follows the reader exactly.
var g_visible_first: usize = 0;
var g_visible_last: usize = 0;

// What shape each note's picture turned out to be, remembered per note id and
// OUTLIVING both the media slot and the note itself. A slot is evicted as soon
// as the note scrolls out of the window; without this the card would forget how
// tall its picture was, shrink, and shift the feed under the reader, then shift
// it back on the way up. Notes whose `imeta` declared a size never need it.
const aspect_memory_cap = 128;
const AspectEntry = struct { note_id: i64 = 0, aspect: f32 = 0 };
var g_aspects = [_]AspectEntry{.{}} ** aspect_memory_cap;
var g_aspect_next: usize = 0;

/// Records the shape of `note_id`'s picture.
fn rememberAspect(note_id: i64, width: usize, height: usize) void {
    if (width == 0 or height == 0) return;
    const aspect = @as(f32, @floatFromInt(height)) / @as(f32, @floatFromInt(width));
    for (&g_aspects) |*entry| {
        if (entry.note_id == note_id) {
            entry.aspect = aspect;
            return;
        }
    }
    g_aspects[g_aspect_next] = .{ .note_id = note_id, .aspect = aspect };
    g_aspect_next = (g_aspect_next + 1) % aspect_memory_cap;
}

/// The remembered shape of `note_id`'s picture, if it has been seen.
fn recalledAspect(note_id: i64) ?f32 {
    for (&g_aspects) |entry| {
        if (entry.note_id == note_id and entry.aspect > 0) return entry.aspect;
    }
    return null;
}

/// Clears the media cache. For tests, which share the process globals.
/// Whether the slot for `note_id` was marked wanted by the most recent pass.
/// This is the thing the claim pass reads to decide what it may evict, so it is
/// the thing a test about "which pictures the level is spending its slots on"
/// has to ask about.
pub fn mediaSlotWantedForTest(note_id: i64) ?bool {
    const m = mediaSlotFor(note_id) orelse return null;
    return m.last_used == g_image_clock;
}

pub fn scanMediaFetchesForTest(fx: *Effects, model: *const Model) void {
    scanMediaFetches(fx, model);
}

pub fn warmAheadForTest(fx: *Effects, model: *const Model) void {
    warmAhead(fx, model);
}

/// Whether warming has asked for this picture address, the way `warmPicture`
/// builds it.
pub fn pictureWarmedForTest(src: []const u8) bool {
    var url_buf: [1024]u8 = undefined;
    return warmedAlready(feedImageUrl(&url_buf, src));
}

pub fn resetWarmForTest() void {
    g_warm_ring = [_]WarmEntry{.{}} ** warm_ring_len;
    g_warm_ring_next = 0;
}

pub fn scanLinkFetchesForTest(fx: *Effects, model: *const Model) void {
    scanLinkFetches(fx, model);
}

/// Whether the page behind `url` has been asked for (or is being).
pub fn linkRequestedForTest(url: []const u8) bool {
    const l = linkFor(url) orelse return false;
    return l.state == .fetching or l.attempts > 0;
}

/// Pretends a build put exactly these notes on screen in the front level.
pub fn recordVisibleNotesForTest(ids: []const i64) void {
    const set = &g_level_visible[0];
    set.reset();
    g_visible_level = 0;
    for (ids) |id| set.pushNote(id);
}

/// How many picture slots are currently held, and by which notes.
pub fn mediaSlotNoteIdsForTest(out: []i64) usize {
    var n: usize = 0;
    for (&g_media) |*m| {
        if (!m.used or n == out.len) continue;
        out[n] = m.note_id;
        n += 1;
    }
    return n;
}

pub fn maxMediaImagesForTest() usize {
    return max_media_images;
}

pub const quote_picture_width_for_test = quote_picture_width;

/// Whether the pool could take this id back right now: held, and neither on
/// screen this pass nor mid-fetch.
pub fn imageIdTakeableForTest(id: u64) bool {
    if (id < 1 or id > image_registry_slots) return false;
    const owners = imageIdOwners();
    return imageIdSeen(owners[@intCast(id)]) != null;
}

pub fn resetMediaForTest() void {
    for (&g_media) |*m| m.down.release();
    g_media = [_]MediaSlot{.{}} ** max_media_images;
    g_image_clock = 0;
}

/// How many slots are holding a half-assembled picture. Zero at rest: a slice
/// buffer belongs to one fetch and dies with it.
pub fn mediaPartialCountForTest() usize {
    var n: usize = 0;
    for (&g_media) |*m| {
        if (m.down.buf != null) n += 1;
    }
    return n;
}

/// The slot holding `note_id`'s image, if any.
/// The media-slot key for one picture of a note.
///
/// Picture ZERO keeps the note's own id, deliberately: every slot already on
/// disk was cached under it, and every path that still speaks in note ids keeps
/// working unchanged. Only the second and later pictures need a key of their
/// own.
///
/// A derived key colliding with some other note's id would show that note's
/// picture here. Note ids are already 63 bits taken from an event id, so this is
/// the same order of unlikely as two notes colliding outright, which the feed
/// has always lived with.
fn mediaKey(note_id: i64, index: usize) i64 {
    if (index == 0) return note_id;
    const mixed = @as(u64, @bitCast(note_id)) ^ (0x9E37_79B9_7F4A_7C15 *% @as(u64, index));
    return @bitCast(mixed & 0x7FFF_FFFF_FFFF_FFFF);
}

pub fn mediaKeyForTest(note_id: i64, index: usize) i64 {
    return mediaKey(note_id, index);
}

fn mediaSlotFor(note_id: i64) ?*MediaSlot {
    for (&g_media) |*m| {
        if (m.used and m.note_id == note_id) return m;
    }
    return null;
}

/// The slot for `note_id`, claiming a free one or evicting the least recently
/// wanted. Never evicts a slot whose note is still on screen (touched this
/// pass), and never one with a fetch in flight: when more pictures are visible
/// than there are slots, the extras hold their reserved space rather than
/// stealing each other's slot back and forth, which decoded images on the UI
/// thread every pass and made a tall window feel heavy.
/// Whether this note's picture was asked for and could not be had.
pub fn mediaFailed(note_id: i64) bool {
    const m = mediaSlotFor(note_id) orelse return false;
    return m.state == .failed;
}

pub fn markMediaFailedForTest(slot: *MediaSlot) void {
    slot.state = .failed;
}

pub fn mediaAttemptsForTest(note_id: i64) ?u8 {
    const m = mediaSlotFor(note_id) orelse return null;
    return m.attempts;
}

/// The host a slot's picture lives on, which `fireMediaAt` normally sets from
/// the note. A test that drives the response handler directly never went
/// through it.
pub fn setMediaSlotHostForTest(note_id: i64, host: []const u8) void {
    const m = mediaSlotFor(note_id) orelse return;
    const n = @min(host.len, m.host_buf.len);
    @memcpy(m.host_buf[0..n], host[0..n]);
    m.host_len = @intCast(n);
}

pub fn mediaIdleForTest(note_id: i64) bool {
    const m = mediaSlotFor(note_id) orelse return false;
    return m.state == .idle;
}

/// Whether this note's picture is now pinned to its own host rather than the
/// proxy, and whether it will be asked for again.
pub fn mediaFallbackStateForTest(note_id: i64) ?struct { idle: bool, direct: bool } {
    const m = mediaSlotFor(note_id) orelse return null;
    return .{ .idle = m.state == .idle, .direct = m.direct };
}

/// Delivers one picture-fetch response for `note_id` the way the runtime would,
/// so a test can drive the failure paths rather than the classifier alone.
/// How many faces are holding a half-assembled picture. Zero at rest.
pub fn avatarPartialCountForTest() usize {
    var n: usize = 0;
    for (&g_profiles) |*p| {
        if (p.used and p.down.buf != null) n += 1;
    }
    return n;
}

/// Feeds one delivered slice to a profile's face, exactly as a 206 does.
pub fn appendAvatarSliceForTest(pubkey: [32]u8, body: []const u8) ?SliceOutcome {
    const p = lookupProfile(pubkey) orelse return null;
    return p.down.append(body);
}

pub fn deliverAvatarResponseForTest(
    fx: *Effects,
    pubkey: [32]u8,
    outcome: native_sdk.EffectFetchOutcome,
    status: u16,
    body: []const u8,
) void {
    const p = lookupProfile(pubkey) orelse return;
    const index = (@intFromPtr(p) - @intFromPtr(&g_profiles[0])) / @sizeOf(Profile);
    handleAvatarFetched(fx, .{
        .key = avatar_fetch_key_base + index,
        .outcome = outcome,
        .status = status,
        .body = body,
    });
}

pub fn maxImageBytesForTest() usize {
    return max_image_bytes;
}

pub fn maxImageDownloadBytesForTest() usize {
    return max_image_download_bytes;
}

pub fn rangeHeaderForTest(buf: []u8, offset: usize) ?[]const u8 {
    return rangeHeader(buf, offset);
}

/// Feeds one delivered slice to a note's slot, exactly as a 206 response does.
pub fn appendMediaSliceForTest(note_id: i64, body: []const u8) ?SliceOutcome {
    const m = mediaSlotFor(note_id) orelse return null;
    return m.down.append(body);
}

/// What a note's slot has assembled so far, or null if it is holding nothing.
pub fn mediaPartialForTest(note_id: i64) ?[]const u8 {
    const m = mediaSlotFor(note_id) orelse return null;
    return m.down.bytes();
}

pub fn deliverMediaResponseForTest(
    fx: *Effects,
    note_id: i64,
    outcome: native_sdk.EffectFetchOutcome,
    status: u16,
    body: []const u8,
) void {
    const m = mediaSlotFor(note_id) orelse return;
    handleMediaFetched(fx, .{
        .key = media_fetch_key_base + mediaSlotIndex(m),
        .outcome = outcome,
        .status = status,
        .body = body,
    });
}

pub fn claimMediaSlotForTest(fx: *Effects, note_id: i64) ?*MediaSlot {
    return claimMediaSlot(fx, note_id);
}

pub fn touchMediaClockForTest() u64 {
    beginImagePass();
    return g_image_clock;
}

pub fn acquireImageIdForTest(fx: *Effects) ?u64 {
    return acquireImageId(fx);
}

/// What the pool thinks holds an id. The bug this guards against is a slot the
/// app holds and the pool calls `free`.
pub fn imageIdOwnerNameForTest(id: u64) []const u8 {
    if (id < 1 or id > image_registry_slots) return "out-of-range";
    const owners = imageIdOwners();
    return @tagName(owners[@intCast(id)]);
}

pub fn placeLogoUntouchableForTest() bool {
    return imageIdSeen(.place_logo) == null;
}

pub fn setPlaceLogoIdForTest(id: u64) void {
    g_place_logo_id = id;
}

pub fn markPlaceLogoSeenForTest() void {
    g_place_logo_seen = g_image_clock;
}

pub fn agePlaceLogoForTest() void {
    g_image_clock +%= 1;
}

/// The id the pool would hand out next, without taking it. Lets a test ask what
/// the rule decides without an effects channel to drop pixels through.
pub fn chooseImageIdForTest() ?u64 {
    const owners = imageIdOwners();
    const pick = chooseImageId(&owners) orelse return null;
    return pick.id;
}

pub fn imageClockForTest() u64 {
    return g_image_clock;
}

pub fn markAvatarWantedForTest(pubkey: [32]u8) void {
    markAvatarWanted(pubkey);
}

pub fn beginImagePassForTest() void {
    beginImagePass();
}

/// The slot's position in `g_media`, which is its identity for everything
/// outside the registry: its fetch key is derived from it, so an arriving
/// response finds the slot that asked even after the registry id it holds has
/// been lent to somebody else.
fn mediaSlotIndex(m: *const MediaSlot) usize {
    return (@intFromPtr(m) - @intFromPtr(&g_media[0])) / @sizeOf(MediaSlot);
}

fn claimMediaSlot(fx: *Effects, note_id: i64) ?*MediaSlot {
    if (mediaSlotFor(note_id)) |m| return m;
    for (&g_media) |*m| {
        if (!m.used) {
            // A slot with no registry id yet. It gets one when there is a
            // picture to put in it, from the same pool as everything else.
            m.* = .{ .used = true, .note_id = note_id };
            return m;
        }
    }
    var victim: ?*MediaSlot = null;
    for (&g_media) |*m| {
        if (m.state == .fetching) continue;
        if (m.last_used == g_image_clock) continue; // still wanted on screen
        if (victim == null or m.last_used < victim.?.last_used) victim = m;
    }
    const v = victim orelse return null;
    const id = v.image_id;
    // Free the registry slot and any decoded frames before reusing the slot.
    if (id != 0) _ = fx.unregisterImage(id);
    v.releaseFrames();
    // Not a second cleanup: every way a fetch can end already drops its slices,
    // and a slot still assembling one is `.fetching`, which is never a victim.
    // This says so out loud, so a terminal path that forgets fails here in a
    // test rather than quietly handing the next note half of somebody else's
    // picture.
    std.debug.assert(v.down.buf == null);
    // The id it was holding comes with it: the picture that was in it has just
    // been unregistered, so the slot is empty and nobody else can be lent it
    // between here and the next registration.
    v.* = .{ .used = true, .note_id = note_id, .image_id = id };
    return v;
}

/// Decodes every frame of an animated GIF into `slot` and registers the first,
/// so the shared animation timer can cycle it. Returns false for a still image
/// (including a single-frame GIF), leaving the normal still path to handle it.
fn loadAnimatedGif(fx: *Effects, slot: *MediaSlot, bytes: []const u8) bool {
    if (bytes.len < 3 or !std.mem.eql(u8, bytes[0..3], "GIF")) return false;

    var delays: ?[*]c_int = null;
    var w: c_int = 0;
    var h: c_int = 0;
    var count: c_int = 0;
    var comp: c_int = 0;
    const pixels = stbi_load_gif_from_memory(bytes.ptr, @intCast(bytes.len), &delays, &w, &h, &count, &comp, 4) orelse return false;
    if (count <= 1 or w <= 0 or h <= 0) {
        stbi_image_free(pixels);
        return false;
    }

    const frame_w: usize = @intCast(w);
    const frame_h: usize = @intCast(h);
    const frame_bytes = frame_w * frame_h * 4;
    const frames: usize = @intCast(count);
    // stb decodes every frame up front, so a long or large GIF is the real
    // memory hazard rather than the per-frame cost. Refuse the extremes and let
    // the caller fall back to a still first frame.
    if (frame_bytes > max_registered_image_bytes or frames > max_gif_frames or frame_bytes * frames > max_gif_total_bytes) {
        stbi_image_free(pixels);
        return false;
    }

    fx.registerImage(slot.image_id, frame_w, frame_h, pixels[0..frame_bytes]) catch {
        stbi_image_free(pixels);
        return false;
    };

    slot.releaseFrames();
    slot.frames = pixels;
    slot.frame_count = @intCast(frames);
    slot.frame_index = 0;
    slot.elapsed_ms = 0;
    // GIF delays are centiseconds x10; anything implausibly fast gets the
    // browsers' customary floor.
    slot.frame_delay_ms = if (delays) |d| (if (d[0] >= 20) @intCast(d[0]) else 100) else 100;
    slot.width = frame_w;
    slot.height = frame_h;
    slot.state = .loaded;
    rememberAspect(slot.note_id, frame_w, frame_h);
    return true;
}

/// Registers a feed picture from the on-disk cache, animating it if it is a GIF.
/// Returns whether the slot is now loaded.
fn loadCachedMedia(fx: *Effects, slot: *MediaSlot, gif: bool) bool {
    const io = g_io orelse return false;
    const environ = g_environ orelse return false;
    var dir = mediaCacheDir(io, environ) catch return false;
    defer dir.close(io);

    var name_buf: [64]u8 = undefined;
    const name = cacheName(&name_buf, slot.url());
    const gpa = std.heap.page_allocator;
    const bytes = dir.readFileAlloc(io, name, gpa, std.Io.Limit.limited(max_image_download_bytes)) catch return false;
    defer gpa.free(bytes);

    if (gif and loadAnimatedGif(fx, slot, bytes)) return true;
    if (decodeAndRegister(fx, slot.image_id, bytes, media_target_px)) |size| {
        slot.state = .loaded;
        slot.width = size.width;
        slot.height = size.height;
        rememberAspect(slot.note_id, size.width, size.height);
        return true;
    }
    return false;
}

/// Advances the animated pictures currently in view, one shared timer for all of
/// them (a timer each would exhaust the 16-slot timer table). Only a couple play
/// at once: the rest hold their first frame until they scroll into that budget.
fn advanceAnimations(fx: *Effects, model: *const Model) void {
    const window = model.visibleRange();
    var playing: usize = 0;
    for (&g_media) |*slot| {
        if (!slot.used or !slot.animated() or slot.state != .loaded) continue;
        // In view? The note has to still be one of the ones on screen.
        var visible = false;
        var index = window.first;
        while (index <= window.last and index < model.notes_len) : (index += 1) {
            if (model.notes[index].id == slot.note_id) {
                visible = true;
                break;
            }
        }
        if (!visible) continue;
        if (playing >= max_playing_gifs) break;
        playing += 1;

        slot.elapsed_ms += animation_interval_ms;
        if (slot.elapsed_ms < slot.frame_delay_ms) continue;
        slot.elapsed_ms = 0;
        slot.frame_index = (slot.frame_index + 1) % slot.frame_count;

        const frames = slot.frames orelse continue;
        const frame_bytes = slot.width * slot.height * 4;
        const offset = @as(usize, slot.frame_index) * frame_bytes;
        // Re-registering the same id swaps the pixels everywhere it is drawn.
        fx.registerImage(slot.image_id, slot.width, slot.height, frames[offset..][0..frame_bytes]) catch {};
    }
}

/// Loads the pictures for the notes around the viewport: the cached ones
/// straight from disk, the rest over the network a few per tick. Notes outside
/// the window keep their slot only until something on screen needs it. While a
/// thread is open the feed under it is hidden, so the budget goes to the thread's
/// pictures instead (the feed's reload from the disk cache when it returns).
fn scanMediaFetches(fx: *Effects, model: *const Model) void {
    const per_tick = 6;
    var fired: usize = 0;
    // No tick of its own: `beginImagePass` advances the one clock every image
    // pass marks against. A second bump here would put every picture a tick
    // ahead of every face, so the allocator would read faces as permanently
    // older and evict them first, forever.

    if (model.levelOpen()) {
        // A level occludes the feed, so the picture budget goes to the level,
        // and only to the rows ON SCREEN in it. Marking every note in the level
        // wanted meant the first six pictures held all six slots and nothing
        // else could ever be lent one: the claim pass refuses to evict anything
        // wanted this pass, and everything was. Every other picture in a long
        // thread stayed an empty box for as long as the thread was open.
        //
        // Mark, then fetch, as the feed does: marking first means the claim pass
        // can only evict what has scrolled away, never a picture needed later in
        // this same pass.
        const set = &g_level_visible[@min(g_visible_level, g_level_visible.len - 1)];
        // Each id resolved once: `noteById` walks the whole feed before the
        // level's own rows, and both loops below need the note.
        var shown: [visible_set_cap]?*const Note = undefined;
        for (set.notes[0..set.note_count], 0..) |id, i| {
            markMediaWanted(id);
            shown[i] = model.noteById(id);
            if (shown[i]) |note| markQuoteMediaWanted(note, levelNoteFolds(model, note));
        }
        for (shown[0..set.note_count]) |maybe| {
            const note = maybe orelse continue;
            fireQuoteMedia(fx, note, levelNoteFolds(model, note), &fired, per_tick);
            fireMedia(fx, note, &fired, per_tick);
        }
        return;
    }

    const window = model.visibleRange();

    // First mark every slot whose note is on screen as wanted, so the claim
    // pass below can only ever evict pictures that have scrolled away. Without
    // this, a viewport showing more pictures than there are slots would evict
    // a slot needed later in this very pass, endlessly.
    var touch = window.first;
    while (touch <= window.last and touch < model.notes_len) : (touch += 1) {
        markMediaWanted(model.notes[touch].id);
        markQuoteMediaWanted(&model.notes[touch], true);
    }

    var index = window.first;
    while (index <= window.last and index < model.notes_len) : (index += 1) {
        fireQuoteMedia(fx, &model.notes[index], true, &fired, per_tick);
        fireMedia(fx, &model.notes[index], &fired, per_tick);
    }
}

/// The media-slot key for the picture a quote card shows: the quoted event's
/// own feed key, picture zero.
///
/// The same key the quoted note's row would use if it were in the feed, on
/// purpose. Where the reader has both on screen they share one slot and one
/// registry id, and the picture is downloaded, decoded and held once.
fn quoteMediaKey(quoted: [32]u8) i64 {
    return mediaKey(feedKeyOf(quoted), 0);
}

/// Whether `note` draws its quote card at all right now. A collapsed long note
/// shows the card only when the fold reaches past it, so a card behind the fold
/// is not on screen and must not cost a fetch or a slot. The row's height
/// estimate asks the same question, so the two agree.
///
/// `collapsible` is what the body builder is told: a thread's focal note is
/// drawn whole whatever its length.
fn quoteCardShown(note: *const Note, collapsible: bool) bool {
    if (note.quote.kind != .event) return false;
    const collapsed = collapsible and noteIsLong(note) and !isExpanded(note.id);
    if (!collapsed) return true;
    const quote_end = @as(usize, note.quote.off) + @as(usize, note.quote.len);
    return quote_end <= collapsedLen(note.content(), note_collapse_chars);
}

/// A quote whose entry is in hand and carries a picture the card may load.
/// Looks without touching the cache's recency: this runs for every row in the
/// window, drawn or not, and must not make the cache think they all were.
fn quotePictureFor(note: *const Note, collapsible: bool) ?*const QuoteEntry {
    if (!quoteCardShown(note, collapsible)) return null;
    for (&g_quotes) |*q| {
        if (!q.used or !std.mem.eql(u8, &q.id, &note.quote.id)) continue;
        // A covered quote (NIP-36) fetches nothing until it is shown.
        if (q.state != .loaded or q.image_url_len == 0 or quoteCovered(q)) return null;
        return q;
    }
    return null;
}

/// Marks the slot a quote card holds as wanted this pass, so the claim pass
/// cannot evict a picture that is still on screen.
fn markQuoteMediaWanted(note: *const Note, collapsible: bool) void {
    const q = quotePictureFor(note, collapsible) orelse return;
    if (mediaSlotFor(quoteMediaKey(q.id))) |m| m.last_used = g_image_clock;
}

/// Loads the picture of the quote card `note` draws, if it draws one.
///
/// Previews off means no fetch and no cache read, with no per-note "load" to
/// ask for: the card names the picture and where it is from, and the press that
/// was always there opens the note, where asking is offered.
fn fireQuoteMedia(fx: *Effects, note: *const Note, collapsible: bool, fired: *usize, per_tick: usize) void {
    if (!prefs.g_media_previews) return;
    const q = quotePictureFor(note, collapsible) orelse return;
    fireMediaSlot(fx, quoteMediaKey(q.id), q.imageUrl(), fired, per_tick);
}

/// Whether a note in the open level folds its body: all of them do except the
/// thread's focal note, which `focalBody` draws whole.
fn levelNoteFolds(model: *const Model, note: *const Note) bool {
    return !(model.viewing_thread != 0 and note.id == model.thread_root.id);
}

/// Marks the picture slot for `note_id` wanted this pass (if it has one), so the
/// claim pass does not evict a picture still on screen.
fn markMediaWanted(note_id: i64) void {
    // Every picture of the note, not just the first: a gallery's later cells are
    // as much on screen as its first, and leaving them unmarked let the claim
    // pass evict one to feed another in the same row.
    var i: usize = 0;
    while (i < max_note_images) : (i += 1) {
        if (mediaSlotFor(mediaKey(note_id, i))) |m| m.last_used = g_image_clock;
    }
}

/// Loads one note's picture: claims a slot, serves it from the disk cache, or
/// fetches it over the network (up to `per_tick` fetches a pass). A note with no
/// picture, or one whose slot is already loading or done, is a no-op.
fn fireMedia(fx: *Effects, note: *const Note, fired: *usize, per_tick: usize) void {
    // Every picture the note carries, in reading order, so the first one is the
    // first to get a slot when there are not enough to go round. The ones that
    // miss out draw their blurhash, which costs no slot at all.
    var i: usize = 0;
    while (i < note.imageCount()) : (i += 1) fireMediaAt(fx, note, i, fired, per_tick);
}

fn fireMediaAt(fx: *Effects, note: *const Note, index: usize, fired: *usize, per_tick: usize) void {
    const link = note.imageAt(index).url();
    if (link.len == 0) return;
    // A covered note's pictures are not asked for. Fetching them and then hiding
    // them would defeat the cover: the host would learn the reader's address
    // either way, and a metered connection pays for bytes nobody sees.
    if (noteCovered(note)) return;
    // With previews off, nothing leaves the machine until the reader asks for
    // this note's pictures. That is the point of the setting: not bandwidth, but
    // that reading a feed should not tell every host in it that you did.
    if (!prefs.g_media_previews and !isMediaAsked(note.id)) return;
    fireMediaSlot(fx, mediaKey(note.id, index), link, fired, per_tick);
}

/// Loads the picture at `link` into the media slot filed under `key`: claims
/// the slot and a registry id, serves it from the disk cache, or fetches it.
///
/// The one body behind both a feed picture and a quote card's, so the two
/// cannot disagree about slots, ids, the cache, the proxy or the retry rules.
/// The callers decide WHETHER to load (previews, being on screen); this decides
/// how.
fn fireMediaSlot(fx: *Effects, key: i64, link: []const u8, fired: *usize, per_tick: usize) void {
    const slot = claimMediaSlot(fx, key) orelse return;
    slot.last_used = g_image_clock;
    if (slot.state != .idle) return;
    // A slot is a place to put a picture; an id is the registry capacity to
    // hold one, and there are fewer of those. Take one now, marked on screen
    // first so this cannot evict a sibling picture in the same note. Nothing
    // free means the reader sees this cell as a blurhash for a frame and the
    // next pass tries again, which is what the shared pool is for: the id it
    // needs is whichever face or picture has been off screen longest, not one
    // reserved for pictures and idle.
    if (slot.image_id == 0) {
        slot.image_id = acquireImageId(fx) orelse return;
    }

    var url_buf: [1024]u8 = undefined;
    const gif = isGifUrl(link);
    const url = feedImageUrlDirect(&url_buf, link, slot.direct);
    const n = @min(url.len, slot.url_buf.len);
    @memcpy(slot.url_buf[0..n], url[0..n]);
    slot.url_len = @intCast(n);
    const host = hostOf(link);
    const hn = @min(host.len, slot.host_buf.len);
    @memcpy(slot.host_buf[0..hn], host[0..hn]);
    slot.host_len = @intCast(hn);

    // Local-first: a picture we already have appears with the note, with no
    // network round-trip at all.
    if (loadCachedMedia(fx, slot, gif)) return;
    if (fired.* >= per_tick) return;
    slot.state = .fetching;
    slot.down.release();
    fetchMediaSlice(fx, slot, 0);
    fired.* += 1;
}

/// Asks `slot`'s host for the `max_image_bytes` of the picture that start at
/// `offset`.
///
/// Every request is a Range request, including the first, so one code path
/// covers a thumbnail and a full-frame photo alike: a picture smaller than one
/// slice comes back whole on the first answer and costs no extra round trip.
/// A host that does not do ranges answers 200 with the whole body instead of
/// 206 with a slice, which is a difference the caller can see, so ignoring the
/// header can never be mistaken for a complete picture.
fn fetchMediaSlice(fx: *Effects, slot: *MediaSlot, offset: usize) void {
    fetchSlice(fx, media_fetch_key_base + mediaSlotIndex(slot), slot.url(), offset, Effects.responseMsg(.media_fetched));
}

/// One slice of one image, whoever wants it.
fn fetchSlice(fx: *Effects, key: u64, url: []const u8, offset: usize, on_response: anytype) void {
    var range_buf: [64]u8 = undefined;
    const range = rangeHeader(&range_buf, offset) orelse return;
    fx.fetch(.{
        .key = key,
        .url = url,
        // `identity` is not politeness, it is what makes the arithmetic true.
        // The HTTP client asks for gzip by default, and a range together with a
        // content encoding means the slice boundaries are in ENCODED bytes
        // while what arrives is decoded ones: "a short slice is the last slice"
        // would then be measuring the wrong thing, and the picture would
        // assemble out of the wrong pieces and still decode. Pictures are
        // already compressed, so asking for none costs nothing.
        .headers = &.{
            .{ .name = "range", .value = range },
            .{ .name = "accept-encoding", .value = "identity" },
        },
        .on_response = on_response,
    });
}

/// The value of a `Range` header asking for the slice that starts at `offset`.
///
/// Inclusive at both ends, which is what the header means: the window is
/// `max_image_bytes` wide, so the last byte asked for is one before the next
/// offset. An off-by-one here would either drop a byte between slices (a
/// corrupt picture that still decodes, which is the worst outcome) or overlap
/// them (a picture longer than the file).
fn rangeHeader(buf: []u8, offset: usize) ?[]const u8 {
    return std.fmt.bufPrint(buf, "bytes={d}-{d}", .{ offset, offset + max_image_bytes - 1 }) catch null;
}

/// A slice that came back SHORT is the last one: the host had nothing more to
/// give from that offset. A full slice means there is probably more, so the
/// caller asks again from the new end.
pub const SliceOutcome = enum { complete, want_more };

/// One picture arriving in Range slices.
///
/// Every image Plaza draws goes through this: a face, a feed picture and a
/// profile banner are the same problem, because a response body carries at most
/// `max_image_bytes` and none of the three is reliably under it. It was written
/// for feed pictures first and the other two were left on one request, which
/// meant a full-size profile picture fetched from its own host drew initials
/// for exactly the same reason a photo drew a blank cell.
const Download = struct {
    buf: ?[]u8 = null,
    len: usize = 0,

    /// Appends one delivered slice. `null` means this picture cannot be
    /// assembled (no memory, or past the ceiling) and the fetch is over.
    fn append(self: *Download, body: []const u8) ?SliceOutcome {
        if (self.buf == null) {
            // The first slice arrives before there is anywhere to put it, and
            // it is the only one that can be the whole picture: a short first
            // slice decodes straight from the response with nothing allocated.
            if (body.len < max_image_bytes) return .complete;
            self.buf = std.heap.page_allocator.alloc(u8, max_image_download_bytes) catch return null;
        }
        const buf = self.buf.?;
        const filled = self.len + body.len;
        // The buffer IS the ceiling, and there is deliberately no second check
        // saying the same thing: a host that answers a full slice every time
        // has to run out of room, and one bound that the append cannot cross is
        // easier to trust than two that can drift apart.
        if (filled > buf.len) return null;
        @memcpy(buf[self.len..filled], body);
        self.len = filled;
        return if (body.len < max_image_bytes) .complete else .want_more;
    }

    /// What has been assembled, or null when nothing was: a picture that fit in
    /// one slice decodes from the response body instead.
    fn bytes(self: *const Download) ?[]const u8 {
        const buf = self.buf orelse return null;
        return buf[0..self.len];
    }

    /// Drops a half-assembled picture. Called wherever a fetch ends, however it
    /// ends: bytes that outlive their fetch are bytes nobody will ever decode.
    fn release(self: *Download) void {
        if (self.buf) |buf| std.heap.page_allocator.free(buf);
        self.buf = null;
        self.len = 0;
    }
};

/// What a fetch that produced no usable image says about trying again.
pub const ImageFailure = enum { retry, give_up };

/// Classifies a picture or avatar fetch that did not produce an image.
///
/// The question is not what the status code was, it is WHAT FAILED. A body that
/// arrived whole, with a 200, and is simply too large for the decoder, or was
/// truncated, or is empty, is a fact about that picture: it will be exactly as
/// large the next time, and every time after that. A timeout, a 5xx or a rate
/// limit is the network or the host having a moment, and those recover.
///
/// Reading only the status conflated the two, in opposite directions on the two
/// paths. The feed asked whether the STATUS was final, and an oversized picture
/// comes back 200, so the slot went back to idle and the same picture was
/// downloaded again on the next tick and again on every scroll event, for as
/// long as the note stayed on screen. The avatar path asked nothing at all, so a
/// single 503 or one dropped connection blanked that face for the rest of the
/// session, on every screen.
pub fn classifyImageFailure(outcome: native_sdk.EffectFetchOutcome, status: u16) ImageFailure {
    // Never reached a host, or the request was cut short on the way.
    if (outcome != .ok) return .retry;
    // The host answered, and the answer was not an image and will not become
    // one: too large to decode, cut off, or empty.
    if (status == 200) return .give_up;
    // The two 4xx that are about timing rather than about the resource.
    if (status == 408 or status == 429) return .retry;
    // Any other 4xx is the host saying no, and it will say no again.
    if (status >= 400 and status < 500) return .give_up;
    // 5xx, and anything unexpected: the host is having a moment.
    return .retry;
}

/// The hosts this proxy has refused, so the refusal outlives one picture.
///
/// A slot is not a place to keep this. The proxy's refusal is a fact about the
/// HOST, and it was being remembered on an evictable media slot: the fallback
/// sets the slot idle, an idle slot is exactly what `claimMediaSlot` evicts,
/// and the flag went with it. Scroll a `.pub` picture off screen and back and
/// it asked the proxy again, was refused again, and was evicted again, so it
/// could loop without ever once reaching the host that would have served it.
///
/// A face never had that problem, because its flag lives on the profile, which
/// is keyed by pubkey and outlives any amount of scrolling. That is the whole
/// of why faces on those hosts came back and pictures did not.
///
/// By host rather than by URL, because that is the granularity the refusal has:
/// wsrv.nl blocks whole TLDs by policy, so one refused picture is enough to
/// know about every other picture on that host, and the rest never spend the
/// wasted round trip at all.
const proxy_refused_hosts_cap = 16;
var g_proxy_refused: [proxy_refused_hosts_cap][96]u8 = undefined;
var g_proxy_refused_len: [proxy_refused_hosts_cap]u8 = [_]u8{0} ** proxy_refused_hosts_cap;
var g_proxy_refused_count: usize = 0;

/// The host part of `url`, empty if it does not look like one.
fn hostOf(url: []const u8) []const u8 {
    const scheme = std.mem.indexOf(u8, url, "://") orelse return "";
    const rest = url[scheme + 3 ..];
    const end = std.mem.indexOfAny(u8, rest, "/?#") orelse rest.len;
    const authority = rest[0..end];
    // Userinfo and a port are not part of what the proxy refused.
    const after_at = if (std.mem.lastIndexOfScalar(u8, authority, '@')) |i| authority[i + 1 ..] else authority;
    if (std.mem.indexOfScalar(u8, after_at, ']') != null) return after_at; // an IPv6 literal, taken whole
    return if (std.mem.indexOfScalar(u8, after_at, ':')) |i| after_at[0..i] else after_at;
}

/// Whether the proxy has already refused this URL's host.
pub fn proxyRefusesHost(url: []const u8) bool {
    const host = hostOf(url);
    if (host.len == 0) return false;
    for (0..g_proxy_refused_count) |i| {
        if (std.ascii.eqlIgnoreCase(g_proxy_refused[i][0..g_proxy_refused_len[i]], host)) return true;
    }
    return false;
}

/// Writes down that the proxy refused this URL's host.
///
/// Full is full: sixteen refused hosts in one session is far past the point
/// where the reader has noticed, and dropping the seventeenth costs one wasted
/// round trip per picture on it rather than anything a reader could see.
fn rememberProxyRefusal(url: []const u8) void {
    rememberHostRefusal(hostOf(url));
}

/// The same, for a caller that already has the host rather than a URL.
fn rememberHostRefusal(host: []const u8) void {
    if (host.len == 0 or host.len > g_proxy_refused[0].len) return;
    for (0..g_proxy_refused_count) |i| {
        if (std.ascii.eqlIgnoreCase(g_proxy_refused[i][0..g_proxy_refused_len[i]], host)) return;
    }
    if (g_proxy_refused_count >= proxy_refused_hosts_cap) return;
    const i = g_proxy_refused_count;
    @memcpy(g_proxy_refused[i][0..host.len], host);
    g_proxy_refused_len[i] = @intCast(host.len);
    g_proxy_refused_count += 1;
}

/// Forgets every refusal. A different proxy gets to answer for itself rather
/// than inheriting the last one's policy, which is the same rule the per-face
/// flag already follows.
pub fn forgetProxyRefusals() void {
    g_proxy_refused_count = 0;
}

pub fn proxyRefusedCountForTest() usize {
    return g_proxy_refused_count;
}

pub fn hostOfForTest(url: []const u8) []const u8 {
    return hostOf(url);
}

/// Whether this answer is the proxy refusing the HOST, rather than telling us
/// something about the picture.
///
/// The three statuses a proxy uses to decline on policy. wsrv.nl answers 400
/// with `{"message":"Domain or TLD blocked by policy"}` for Blossom hosts that
/// serve the same file directly; 403 is the same refusal by another name, and
/// 451 is one made for it by somebody else.
///
/// Deliberately NOT 404, which is the source missing and will be missing
/// directly too, and not a 200 that produced no usable image, which is our own
/// size limit and is only worse without the proxy shrinking it first.
pub fn proxyRefusedHost(outcome: native_sdk.EffectFetchOutcome, status: u16) bool {
    if (outcome != .ok) return false;
    return status == 400 or status == 403 or status == 451;
}

/// How many times a picture or avatar may come back unusable for a reason worth
/// retrying before Plaza stops asking.
///
/// A backstop, not the mechanism. `classifyImageFailure` is what should decide,
/// and this is here so that no future mistake in it can produce an unbounded
/// download loop again: getting that wrong cost 240 KiB a second, per picture,
/// for as long as the reader looked at it.
const max_image_attempts = 4;

/// Handles a feed-image fetch response, mirroring the avatar path.
fn handleMediaFetched(fx: *Effects, response: native_sdk.EffectResponse) void {
    if (response.key < media_fetch_key_base) return;
    const index = response.key - media_fetch_key_base;
    if (index >= g_media.len) return;
    const slot = &g_media[@intCast(index)];
    if (!slot.used) return;

    if (response.outcome == .rejected) {
        slot.down.release();
        slot.state = .idle;
        return;
    }
    // A 206 is a slice of a picture that does not fit in one body. Take it, and
    // ask for the next unless the host just told us there is no next.
    if (response.outcome == .ok and response.status == 206 and !response.truncated and response.body.len > 0) {
        const outcome = slot.down.append(response.body) orelse {
            // Too big to assemble, or no memory to assemble it in. Both are
            // facts about this picture rather than about the network, so this
            // is finished rather than retried.
            slot.down.release();
            slot.state = .failed;
            return;
        };
        if (outcome == .want_more) {
            fetchMediaSlice(fx, slot, slot.down.len);
            return;
        }
        // Whole. The bytes are in the slice buffer unless this was a single
        // short first slice, which never allocated one.
        const whole = slot.down.bytes() orelse response.body;
        finishMedia(fx, slot, whole);
        slot.down.release();
        return;
    }
    if (response.outcome != .ok or response.status != 200 or response.truncated or response.body.len == 0 or response.body.len > max_image_bytes) {
        // Whatever was assembled so far is bytes nobody will decode now.
        slot.down.release();
        // A host that said NO is different from a host that did not answer, and
        // a picture that is simply too big is different again: it will be the
        // same size next time, so asking again is a download with a known
        // answer. Only something that can change goes back to idle.
        // One more try, at the source, before this is a failure at all.
        //
        // Only for the answers that are about the PROXY rather than about the
        // picture. The public one refuses whole TLDs by policy and answers 400
        // for Blossom hosts that hand over the same file without complaint, so
        // those say "not through here" and the host has not been asked yet.
        //
        // Narrow on purpose. A 404 through the proxy is the SOURCE missing,
        // and a body too large to decode is our own limit on the response,
        // which a direct fetch only makes worse because the proxy was the thing
        // shrinking it. Falling back on either is a second download with a known
        // answer, and two tests said so before this comment existed.
        //
        // Once per slot, and only while the proxy is what was used, so it can
        // never loop and never fires for a fetch that was already direct. The
        // attempt counter is untouched: this is a different question, not
        // another go at the same one.
        if (prefs.g_media_direct_fallback and prefs.g_media_proxy_on and !slot.direct and
            proxyRefusedHost(response.outcome, response.status))
        {
            // Under the HOST, because this slot is not a place to keep it: the
            // line below sets the slot idle, an idle slot is exactly what
            // eviction takes, and the flag went with it. A picture scrolled off
            // and back asked the proxy again, was refused again, and was
            // evicted again, so it could loop without ever once reaching the
            // host that would have served it.
            rememberHostRefusal(slot.host());
            slot.direct = true;
            slot.state = .idle;
            return;
        }
        slot.state = switch (classifyImageFailure(response.outcome, response.status)) {
            .give_up => .failed,
            .retry => blk: {
                slot.attempts +|= 1;
                break :blk if (slot.attempts >= max_image_attempts) .failed else .idle;
            },
        };
        return;
    }
    slot.down.release();
    finishMedia(fx, slot, response.body);
}

/// Decodes a complete picture into `slot` and remembers it.
fn finishMedia(fx: *Effects, slot: *MediaSlot, bytes: []const u8) void {
    // Whatever it took to get here, this URL answers, so the count of tries
    // worth making starts again.
    slot.attempts = 0;
    // An animated GIF keeps all its frames; anything else (including a GIF with
    // only one frame) takes the still path.
    if (loadAnimatedGif(fx, slot, bytes)) {
        storeCachedImage(slot.url(), bytes);
        return;
    }
    if (decodeAndRegister(fx, slot.image_id, bytes, media_target_px)) |size| {
        slot.state = .loaded;
        slot.width = size.width;
        slot.height = size.height;
        rememberAspect(slot.note_id, size.width, size.height);
        // Keep it for next launch: the feed should come back with its pictures.
        storeCachedImage(slot.url(), bytes);
    } else {
        slot.state = .failed;
    }
}

/// Lets everything that failed to load try again, after the media proxy changed.
fn retryFailedImages() void {
    for (&g_profiles) |*p| {
        if (p.used and p.avatar_state == .failed) {
            p.avatar_state = .idle;
            p.avatar_attempts = 0;
            // A new proxy gets to answer for itself, so the face goes back
            // through it rather than staying pinned to its own host.
            p.avatar_direct = false;
        }
    }
    for (&g_media) |*m| {
        if (m.used and m.state == .failed) {
            m.state = .idle;
            m.attempts = 0;
        }
    }
}

/// Builds a `Note` view-model from a stored event.
pub fn noteFrom(ev: nostr.event.Event, now_s: i64) Note {
    var note = Note{
        .created_at = ev.created_at,
        .pubkey = ev.pubkey,
        .id = noteIdOf(ev),
        .event_id = ev.id,
        .kind = ev.kind,
    };

    // Avatar initials fallback: the first pubkey byte as two hex digits, stable
    // and distinct per author, shown until an avatar image loads.
    const hexdigits = "0123456789abcdef";
    note.initials_buf = .{ hexdigits[ev.pubkey[0] >> 4], hexdigits[ev.pubkey[0] & 0x0f] };

    setAuthor(&note, ev.pubkey);

    if (clientOf(ev)) |name| {
        const n = @min(name.len, note.client_buf.len);
        @memcpy(note.client_buf[0..n], name[0..n]);
        note.client_len = @intCast(n);
    }

    // The author's own request to have this covered. Read here, with the tags in
    // hand, for the same reason the client name is: the tags are gone by the time
    // anything draws.
    if (contentWarningOf(ev)) |reason| {
        note.warned = true;
        @memcpy(note.warning_buf[0..reason.len], reason);
        note.warning_len = @intCast(reason.len);
    }

    // Image links become pictures, so lift them out of the text and omit them
    // from the rendered content rather than showing bare URLs beside a gallery.
    //
    // The URLs are borrowed from the EVENT while it is still in hand, and the
    // omit list below borrows them again; the note keeps its own copies. A URL
    // too long for the buffer is left in the text, which is the honest fallback:
    // it is still a link the reader can open.
    //
    // Not for an article: its pictures are inside the markdown, to be drawn where
    // the author put them, and lifting the first four out of a long read would
    // hang them under its title as though they were its cover.
    var found: [max_note_images][]const u8 = undefined;
    const found_len = if (kindRender(ev.kind) == .article) 0 else collectImageUrls(ev.content, &found);
    var omit: [max_note_images][]const u8 = undefined;
    var omit_len: usize = 0;
    for (found[0..found_len]) |url| {
        if (url.len > note.images[0].url_buf.len) continue;
        const meta = imetaFor(ev.tags, url);
        // The note gets to overrule its own file names. `collectImageUrls` knows
        // only the extension, so a video a host serves as `thumb.jpg` arrives
        // here looking like a picture; declaring `m video/mp4` is the author
        // saying otherwise, and handing it to the image decoder would spend a
        // registry slot and a download on bytes that will never decode.
        //
        // Only ever to REJECT. A declared `image/` on a URL the extension does
        // not recognise is not taken as permission to fetch it: that decides to
        // download something on a stranger's say-so, and it is a separate
        // question from this one.
        if (classifyMedia(url, meta.mime) != .image) continue;
        note.images[note.images_len].set(url, meta);
        omit[omit_len] = url;
        omit_len += 1;
        note.images_len += 1;
    }

    // What text this note shows, decided by its kind rather than by assuming
    // every event keeps its words in `content`.
    //
    // Only the body is decided here. What a card DRAWS around the body, the
    // chip naming a kind nothing can render, belongs where the card is built,
    // because the body buffer has no way to say "there is nothing to say".
    switch (kindRender(ev.kind)) {
        // Content: `nostr:` mentions rewritten to @name (or a short @npub),
        // copied whole-codepoint so a split multi-byte sequence never reaches
        // the shaper.
        .note, .media => {
            note.content_len = @intCast(renderContentInto(&note.content_buf, ev.content, omit[0..omit_len], &note.mentions));
        },
        // An article's content is markdown, and a card is not where anybody
        // asked to read markdown. The `title` tag is the one line of it that
        // belongs in a row. Without a title there is nothing honest to show,
        // so the card falls to the unsupported chip rather than to the body.
        .article => {
            if (titleOf(ev)) |title| {
                @memcpy(note.content_buf[0..title.len], title);
                note.content_len = @intCast(title.len);
            }
            // The `image` tag is the article's cover, and the one picture the
            // note carries, so the reader draws it through the same path every
            // other picture takes (its slot, its disk cache, its placeholder).
            const meta = article.metaOf(ev);
            if (article.isWebUrl(meta.image) and meta.image.len <= note.images[0].url_buf.len) {
                note.images[0].set(meta.image, imetaFor(ev.tags, meta.image));
                // A cover with no declared shape is held to a wide one, so the
                // head does not reserve a portrait-sized box for a banner.
                if (note.images[0].aspect <= 0) note.images[0].aspect = article.cover_aspect;
                note.images_len = 1;
            }
        },
        // Left empty on purpose. Rendering the content of a kind nothing knows
        // how to draw is exactly the bug: a kind:1063's content is empty by
        // design and an article's was markdown, and both were painted as though
        // they were somebody's words.
        .unsupported => {},
    }

    // The first plain link, for the preview card. Read from the ORIGINAL content:
    // the rendered copy has mentions rewritten and may be capped.
    if (firstLinkUrl(ev.content, note.imageUrl(), ev.tags)) |link| {
        if (link.len <= note.link_url_buf.len) {
            @memcpy(note.link_url_buf[0..link.len], link);
            note.link_url_len = @intCast(link.len);
            // What it points at, decided once here with the note's own `imeta`
            // in hand. The tags are gone by the time anything draws.
            note.link_is_video = classifyMedia(link, imetaFor(ev.tags, link).mime) == .video;
        }
    }

    // The first quoted event (nevent/note), decoded once into a byte span the
    // body splits on, and queued for resolving.
    findQuoteRef(&note);
    if (note.quote.kind == .event) wantQuote(note.quote.id);

    // Which note this one answers, for thread nesting AND for the line the feed
    // draws above a reply. Queued into the same cache a quote uses: a reply
    // parent is the same problem, an event referenced by id that may or may not
    // be on the reader's relays, and it already has the fetching, the backoff
    // and the eviction.
    if (replyParent(ev.kind, ev.tags)) |parent_id| {
        note.reply_parent = parent_id;
        note.has_reply_parent = true;
        wantQuote(parent_id);
    }

    note.setTime(now_s);
    return note;
}

/// NIP-22's comment kind: a reply that is not a kind:1.
///
/// Worth reading even though the raw volume is small. Ditto and Coracle publish
/// every reply as one of these whatever the parent is, and every client that
/// writes them at all writes one when the PARENT is already one, so a single
/// comment converts the whole branch beneath it. A client that cannot read them
/// does not lose an event, it loses a subtree, and it shows silence rather than
/// a gap.
pub const comment_kind: u16 = 1111;

/// NIP-18 reposts. 6 wraps a kind 1; 16 wraps anything else and carries a `k`
/// tag saying what.
pub const repost_kind: u16 = 6;
pub const generic_repost_kind: u16 = 16;

pub fn isRepostKind(kind: u16) bool {
    return kind == repost_kind or kind == generic_repost_kind;
}

/// What a repost points at: the LAST `e` tag.
///
/// The last rather than the first, which is what Amethyst reads
/// (`RepostEvent.boostedEventId()` is `tags.lastNotNullOfOrNull(ETag::parseId)`)
/// and what the dedup key below has to agree with. A repost normally carries
/// exactly one, so the two answers differ only for a malformed event, and
/// differing from the rest of the network about a malformed event is how one
/// client shows a row nobody else does.
pub fn repostTargetId(tags: []const nostr.event.Tag) ?[32]u8 {
    var last: ?[32]u8 = null;
    for (tags) |tag| {
        if (tag.len < 2 or tag[1].len != 64) continue;
        if (!std.mem.eql(u8, tag[0], "e")) continue;
        var id: [32]u8 = undefined;
        _ = std.fmt.hexToBytes(&id, tag[1]) catch continue;
        last = id;
    }
    return last;
}

/// How an event of a given kind gets drawn.
///
/// Nothing branched on kind before this. `noteFrom` built a note out of any
/// event and every surface drew its `content` as a note body, which the feed
/// and the thread got away with because they filter to kind 1 upstream. The
/// quote card and `openEvent` do not filter, so a long-form article arrived as
/// a slab of raw markdown and an event whose content is empty by design arrived
/// as a card with a name, a time and nothing under it.
///
/// ONE function, so a quote card, a thread and `open_event` cannot disagree
/// about the same event. Jumble does exactly this: an allowlist in front of the
/// render chain, and everything outside it gets a card naming the kind and a
/// way to open it somewhere that can draw it
/// (`src/components/NoteContent/index.tsx:52`). Amethyst and Coracle instead
/// fall through to drawing unknown content as a text note, which is the
/// behaviour being fixed here, and they get away with it because their feeds
/// are allow-listed too.
pub const KindRender = enum {
    /// Its content is the thing to read. Kind 1 and NIP-22 comments.
    note,
    /// Its content is markdown nobody asked to read in a card, so the `title`
    /// tag stands in for it there. Opened by id it is read in full, in the
    /// reader `articlePanel` draws.
    article,
    /// The media is the point and the content is a caption, which is already
    /// what `noteFrom` does with any note carrying a picture or a video.
    media,
    /// Plaza cannot draw this. Saying so, with the kind number, beats a blank
    /// card: a reader who knows what it is can open it somewhere that can.
    unsupported,
};

pub fn kindRender(kind: u16) KindRender {
    return switch (kind) {
        1, comment_kind => .note,
        // NIP-23 long form, and its unpublished draft.
        30023, 30024 => .article,
        // NIP-68 picture, and the NIP-71 video kinds.
        20, 21, 22 => .media,
        else => .unsupported,
    };
}

/// An event's `title` tag, clipped the way a client name is.
///
/// Modelled line for line on `clientOf`, including the truncate-rather-than-
/// refuse rule and the control-character check: both read one short tag off a
/// stranger's event and put it in a fixed row.
pub fn titleOf(ev: nostr.event.Event) ?[]const u8 {
    for (ev.tags) |tag| {
        if (tag.len < 2 or !std.mem.eql(u8, tag[0], "title")) continue;
        const title = std.mem.trim(u8, tag[1], " \t\r\n");
        if (title.len == 0) return null;
        for (title) |c| {
            if (c < 0x20 or c == 0x7f) return null;
        }
        return clipToChars(title, article_title_chars, article_title_bytes);
    }
    return null;
}

/// A title is one line in a card, so it is capped like every other such string
/// here rather than allowed to fill the body buffer.
const article_title_chars: usize = 96;
const article_title_bytes: usize = 200;

/// Records the FIRST `nostr:nevent`/`note`/`naddr` reference in `note`'s
/// rendered content as a decoded event id plus the byte span of its raw token,
/// so the body can split around it and draw an embedded quote card. A second
/// reference, an `naddr` that is not an article, or an undecodable token is left
/// as plain text (`.none`).
///
/// An `naddr` has no id, so its card is keyed by the address's stand-in key (see
/// `Address.key`). Jumble embeds all three the same way
/// (src/lib/content-parser.ts:62, src/components/Embedded/EmbeddedNote.tsx:11).
fn findQuoteRef(note: *Note) void {
    @setRuntimeSafety(true); // Byte spans of a token inside the note's own content.
    const text = note.content();
    var scratch: [16 * 1024]u8 = undefined;
    var i: usize = 0;
    while (i < text.len) : (i += 1) {
        // The token starts at a `nostr:` prefix, or a bare `nevent1`/`note1`, but
        // only at a word boundary, so one embedded in a URL (`…/nostr:nevent…`)
        // or a longer token is left alone rather than split into a spurious card.
        var body_start = i;
        if (std.mem.startsWith(u8, text[i..], "nostr:")) {
            if (!refPrecededByBoundary(text, i)) continue;
            body_start = i + "nostr:".len;
        } else if (std.mem.startsWith(u8, text[i..], "nevent1") or std.mem.startsWith(u8, text[i..], "note1") or std.mem.startsWith(u8, text[i..], "naddr1")) {
            if (!refPrecededByBoundary(text, i)) continue;
        } else continue;

        const rest = text[body_start..];
        if (!std.mem.startsWith(u8, rest, "nevent1") and !std.mem.startsWith(u8, rest, "note1") and !std.mem.startsWith(u8, rest, "naddr1")) continue;
        var j: usize = 0;
        while (j < rest.len and isBech32Char(rest[j])) j += 1;
        const token = rest[0..j];

        var fba = std.heap.FixedBufferAllocator.init(&scratch);
        const arena = fba.allocator();
        const id: ?[32]u8 = if (std.mem.startsWith(u8, token, "nevent1")) blk: {
            const ptr = nostr.nip19.decodeNevent(arena, token) catch break :blk null;
            // The relays the address named, recorded here because here is where
            // they were being decoded and dropped. `Note.quote` deliberately
            // does not carry them: it is a field on every note in the feed
            // array, and this is two URLs that belong to one cache entry.
            if (ptr.relays.len > 0) wantQuoteHinted(ptr.id, ptr.relays);
            break :blk ptr.id;
        } else if (std.mem.startsWith(u8, token, "naddr1")) blk: {
            const ptr = nostr.nip19.decodeNaddr(arena, token) catch break :blk null;
            // Only the kinds with a screen. Any other address stays the text it
            // was, as it always has.
            const addr = Address.make(ptr.kind, ptr.pubkey, ptr.identifier) orelse break :blk null;
            break :blk registerAddress(addr, ptr.relays);
        } else (nostr.nip19.decodeNote(arena, token) catch null);

        if (id) |event_id| {
            note.quote = .{ .kind = .event, .id = event_id, .off = @intCast(i), .len = @intCast((body_start - i) + j) };
            return;
        }
    }
}

/// A byte count as a reader reads it: `240 KB`, `1.4 MB`. Decimal units, because
/// that is what the file's own host quotes and what the note author copied.
fn byteSize(arena: std.mem.Allocator, bytes: u32) []const u8 {
    if (bytes < 1000) return std.fmt.allocPrint(arena, "{d} B", .{bytes}) catch "";
    if (bytes < 1_000_000) return std.fmt.allocPrint(arena, "{d} KB", .{bytes / 1000}) catch "";
    const mb = @as(f32, @floatFromInt(bytes)) / 1_000_000.0;
    return std.fmt.allocPrint(arena, "{d:.1} MB", .{mb}) catch "";
}

/// What a note's NIP-92 `imeta` tag says about `url`: its pixel dimensions, its
/// alt text and its blurhash. One walk, because the picture's chrome wants all
/// three and the tag is one place.
pub const Imeta = struct {
    width: u16 = 0,
    height: u16 = 0,
    /// A slice of the EVENT's memory, so it lives as long as the event does. The
    /// caller copies what it wants to keep.
    alt: []const u8 = "",
    blurhash: []const u8 = "",
    /// The file's size in bytes, as the note claims it. The only source there is:
    /// the SDK's fetch response carries no headers, so there is no Content-Length
    /// to read, and with previews off nothing is fetched at all.
    size: u32 = 0,
    /// The `m` field: what the note says this file's type is, lowercase, from
    /// NIP-94 by way of NIP-92. A slice of the EVENT's memory, like `alt`.
    ///
    /// It is what tells a video named `.jpg` from a picture. See `classifyMedia`
    /// for why a type nobody recognises is treated as nothing said.
    mime: []const u8 = "",

    /// Height over width, or 0 when the tag says nothing. Knowing the shape
    /// before the bytes arrive is what lets a row reserve exactly the right
    /// space, so nothing shifts when the picture lands.
    pub fn aspect(self: Imeta) f32 {
        if (self.width == 0 or self.height == 0) return 0;
        return @as(f32, @floatFromInt(self.height)) / @as(f32, @floatFromInt(self.width));
    }
};

pub fn imetaFor(tags: []const nostr.event.Tag, url: []const u8) Imeta {
    @setRuntimeSafety(true); // Reads fields out of a tag the note's author wrote.
    for (tags) |tag| {
        if (tag.len == 0 or !std.mem.eql(u8, tag[0], "imeta")) continue;
        var matches_url = false;
        var found: Imeta = .{};
        for (tag[1..]) |field| {
            if (std.mem.startsWith(u8, field, "url ")) {
                matches_url = std.mem.eql(u8, std.mem.trim(u8, field[4..], " "), url);
            } else if (std.mem.startsWith(u8, field, "dim ")) {
                const dim = std.mem.trim(u8, field[4..], " ");
                const x = std.mem.indexOfScalar(u8, dim, 'x') orelse continue;
                // Written as floats by some clients, so parse wide and narrow.
                const w = std.fmt.parseFloat(f32, dim[0..x]) catch continue;
                const h = std.fmt.parseFloat(f32, dim[x + 1 ..]) catch continue;
                if (w > 0 and h > 0 and w < 65536 and h < 65536) {
                    found.width = @intFromFloat(w);
                    found.height = @intFromFloat(h);
                }
            } else if (std.mem.startsWith(u8, field, "alt ")) {
                found.alt = std.mem.trim(u8, field[4..], " ");
            } else if (std.mem.startsWith(u8, field, "size ")) {
                found.size = std.fmt.parseInt(u32, std.mem.trim(u8, field[5..], " "), 10) catch 0;
            } else if (std.mem.startsWith(u8, field, "blurhash ")) {
                found.blurhash = std.mem.trim(u8, field["blurhash ".len..], " ");
            } else if (std.mem.startsWith(u8, field, "m ")) {
                found.mime = std.mem.trim(u8, field[2..], " ");
            }
        }
        if (matches_url) return found;
    }
    return .{};
}

/// The aspect (height over width) the note's own NIP-92 `imeta` tag declares for
/// `url`, or 0 when it says nothing. An `imeta` tag reads
/// `["imeta", "url https://…", "dim 882x302", …]`; dimensions are sometimes
/// written as floats, so both forms parse.
pub fn imetaAspect(tags: []const nostr.event.Tag, url: []const u8) f32 {
    for (tags) |tag| {
        if (tag.len == 0 or !std.mem.eql(u8, tag[0], "imeta")) continue;
        var matches_url = false;
        var aspect: f32 = 0;
        for (tag[1..]) |field| {
            if (std.mem.startsWith(u8, field, "url ")) {
                matches_url = std.mem.eql(u8, std.mem.trim(u8, field[4..], " "), url);
            } else if (std.mem.startsWith(u8, field, "dim ")) {
                const dim = std.mem.trim(u8, field[4..], " ");
                const x = std.mem.indexOfScalar(u8, dim, 'x') orelse continue;
                const w = std.fmt.parseFloat(f32, dim[0..x]) catch continue;
                const h = std.fmt.parseFloat(f32, dim[x + 1 ..]) catch continue;
                if (w > 0 and h > 0) aspect = h / w;
            }
        }
        if (matches_url and aspect > 0) return aspect;
    }
    return 0;
}

/// What a URL points at, once the note has had its say about it.
pub const MediaKind = enum { image, video, other };

const image_exts = [_][]const u8{ ".jpg", ".jpeg", ".png", ".gif", ".webp", ".avif", ".bmp" };
/// What Amethyst carries, minus the audio half. See `classifyMedia`.
const video_exts = [_][]const u8{ ".mp4", ".webm", ".mov", ".m4v", ".avi", ".mkv", ".mpg", ".mpeg", ".m3u8" };

/// The end of the path: the first `?` or the first `#`, whichever comes first.
///
/// Both, not just the query. `…/clip.mp4#t=30` is a real address that names a
/// start time, and stopping only at `?` reads its extension as `.mp4#t=30` and
/// decides it is not a video.
fn urlPathEnd(url: []const u8) usize {
    return std.mem.indexOfAny(u8, url, "?#") orelse url.len;
}

/// Whether the path ends in one of `exts`.
///
/// The dot has to be a real extension dot: after the last `/`, so a host like
/// `cdn.mp4.example/watch` is not a video, and present at all, so a path that
/// merely ends in the letters is not either.
fn hasExtensionIn(url: []const u8, exts: []const []const u8) bool {
    const path = url[0..urlPathEnd(url)];
    const dot = std.mem.lastIndexOfScalar(u8, path, '.') orelse return false;
    const slash = std.mem.lastIndexOfScalar(u8, path, '/');
    if (slash != null and dot < slash.?) return false;
    for (exts) |ext| {
        if (std.ascii.endsWithIgnoreCase(path, ext)) return true;
    }
    return false;
}

/// What a URL points at, given what the note's `imeta` said its type was.
///
/// Amethyst's rule, which is three tiers rather than two, and the third is the
/// one worth keeping: a mime we RECOGNISE wins over the extension in both
/// directions, a mime we do NOT recognise is treated as no declaration at all
/// and the extension decides, and only then is it neither. Collapsing the first
/// two into `startsWith("video/") or looksLikeVideo(url)` is exactly what their
/// regression test says they replaced, because it made a video named `.jpg`
/// render as a picture.
///
/// `m` comes from NIP-94 by way of NIP-92, which says an `imeta` MAY carry any
/// NIP-94 field and delegates the vocabulary; NIP-94 defines `m` as a lowercase
/// MIME type.
///
/// AUDIO IS NOT VIDEO HERE, and that is a deliberate difference from Amethyst.
/// They fold the two together because they have one player for both. Plaza has
/// neither, so calling an `.mp3` a video would put a video card on a sound file.
/// It stays an ordinary link until there is something true to say about it.
pub fn classifyMedia(url: []const u8, mime: []const u8) MediaKind {
    if (std.ascii.startsWithIgnoreCase(mime, "image/")) return .image;
    if (std.ascii.startsWithIgnoreCase(mime, "video/")) return .video;
    // Anything else declared, including `audio/` and a mime that is nonsense,
    // falls through to the extension rather than vetoing it.
    if (hasExtensionIn(url, &image_exts)) return .image;
    if (hasExtensionIn(url, &video_exts)) return .video;
    return .other;
}

/// Whether a URL names an image file. By extension, which is what Nostr media
/// hosts serve; a link without one is an ordinary link.
pub fn looksLikeImageUrl(url: []const u8) bool {
    return hasExtensionIn(url, &image_exts);
}

/// The first image URL in `content`, or null. Recognised by extension, which is
/// what Nostr media hosts serve; a link without one stays ordinary text.
/// A URL's host, as a reader says it: no scheme, no `www.`, no path. One
/// spelling, because two of them drift and then two places disagree about what
/// the same address is called.
pub fn urlHost(url: []const u8) []const u8 {
    var rest = url;
    inline for ([_][]const u8{ "https://", "http://" }) |scheme| {
        if (std.mem.startsWith(u8, rest, scheme)) rest = rest[scheme.len..];
    }
    if (std.mem.startsWith(u8, rest, "www.")) rest = rest["www.".len..];
    if (std.mem.indexOfScalar(u8, rest, '/')) |slash| rest = rest[0..slash];
    return rest;
}

pub fn firstImageUrl(content: []const u8) ?[]const u8 {
    @setRuntimeSafety(true); // Same walk as firstLinkUrl, matching an extension at the end of a run.
    const exts = [_][]const u8{ ".jpg", ".jpeg", ".png", ".gif", ".webp", ".avif", ".bmp" };
    var i: usize = 0;
    while (i < content.len) : (i += 1) {
        if (content[i] != 'h') continue;
        if (!std.mem.startsWith(u8, content[i..], "http://") and !std.mem.startsWith(u8, content[i..], "https://")) continue;
        // The URL runs to the first whitespace.
        var j = i;
        while (j < content.len and !std.ascii.isWhitespace(content[j])) j += 1;
        const url = content[i..j];
        // Ignore a trailing bare query string when matching the extension.
        const path_end = std.mem.indexOfScalar(u8, url, '?') orelse url.len;
        const path = url[0..path_end];
        for (exts) |ext| {
            if (std.ascii.endsWithIgnoreCase(path, ext)) return url;
        }
        i = j;
    }
    return null;
}

/// Every image URL in `content`, in the order written, up to `out.len`.
///
/// The same walk as `firstImageUrl`, which it now backs: a note carrying three
/// pictures is ordinary, and taking only the first left the other two sitting in
/// the body as raw links beside a gallery that had room for them.
pub fn collectImageUrls(content: []const u8, out: [][]const u8) usize {
    @setRuntimeSafety(true); // Walks a stranger's content and indexes `out` as it goes.
    const exts = [_][]const u8{ ".jpg", ".jpeg", ".png", ".gif", ".webp", ".avif", ".bmp" };
    var found: usize = 0;
    var i: usize = 0;
    while (i < content.len and found < out.len) : (i += 1) {
        if (content[i] != 'h') continue;
        if (!std.mem.startsWith(u8, content[i..], "http://") and !std.mem.startsWith(u8, content[i..], "https://")) continue;
        var j = i;
        while (j < content.len and !std.ascii.isWhitespace(content[j])) j += 1;
        const url = content[i..j];
        const path_end = std.mem.indexOfScalar(u8, url, '?') orelse url.len;
        const path = url[0..path_end];
        for (exts) |ext| {
            if (std.ascii.endsWithIgnoreCase(path, ext)) {
                out[found] = url;
                found += 1;
                break;
            }
        }
        i = j;
    }
    return found;
}

/// Copies note content into `dst`, rewriting NIP-27 `nostr:npub…`/`nostr:nprofile…`
/// mentions into a readable `@name` (from the profile cache) or a short `@npub`,
/// and dropping every URL in `omit` (the ones drawn as pictures) wherever they
/// appear.
/// Plain text is copied one whole codepoint at a time and stops at `dst`'s
/// capacity, so the buffer never ends mid-sequence. Returns the byte length.
pub fn renderContent(dst: []u8, src: []const u8, omit: []const u8) usize {
    const one = [_][]const u8{omit};
    return renderContentInto(dst, src, if (omit.len == 0) &.{} else &one, null);
}

/// The same, recording where each mention's label landed into `mentions` when
/// one is given. A note wants that table so the label can be pressed; a profile's
/// "about" text is rendered the same way and has nowhere to put one.
pub const note_content_cap_for_test = note_content_cap;
pub fn noteContentCapForTest() usize {
    return note_content_cap;
}

pub fn renderContentInto(dst: []u8, src: []const u8, omit: []const []const u8, mentions: ?*MentionList) usize {
    @setRuntimeSafety(true); // Copies a stranger's content into a fixed buffer, offset by offset.
    // Mention decoding needs an allocator for bech32 scratch; a stack buffer
    // covers it without touching the heap for every note parsed. A pathological
    // mention that will not fit simply stays as its raw token.
    var scratch: [16 * 1024]u8 = undefined;
    var fba = std.heap.FixedBufferAllocator.init(&scratch);
    const arena = fba.allocator();

    var out: usize = 0;
    var i: usize = 0;
    while (i < src.len) {
        // Every picture's URL comes out, not just the first. Longest match wins,
        // so one URL that is a prefix of another cannot leave the tail of the
        // longer one stranded in the text.
        var skipped: usize = 0;
        for (omit) |gone| {
            if (gone.len > skipped and std.mem.startsWith(u8, src[i..], gone)) skipped = gone.len;
        }
        if (skipped > 0) {
            i += skipped;
            continue;
        }
        if (parseMentionAt(arena, src, i)) |m| {
            var label_buf: [80]u8 = undefined;
            const label = mentionLabel(m.pubkey, &label_buf);
            // Before the copy, so a label that does not fit is not recorded as
            // one that did: the break below leaves the buffer ending where the
            // last whole thing ended.
            if (out + label.len > dst.len) break;
            if (mentions) |list| list.record(out, label.len, m.pubkey);
            @memcpy(dst[out..][0..label.len], label);
            out += label.len;
            i = m.end;
            continue;
        }
        const seq_len = std.unicode.utf8ByteSequenceLength(src[i]) catch 1;
        const take = @min(seq_len, src.len - i);
        // Emoji pass through as themselves; the invisible codepoints between
        // them do not, because a renderer that paints a block for what it
        // cannot find paints one for a variation selector too.
        //
        // Display only. `dst` is the note's render buffer; the event this came
        // from is signed and is not touched, and nothing composed goes through
        // here.
        const wrote = writeDisplaySeq(dst[out..], src[i..][0..take]) orelse break;
        out += wrote;
        i += take;
    }
    // Lifting a URL out can leave whitespace stranded at either edge.
    const trimmed = std.mem.trim(u8, dst[0..out], " \t\r\n");
    if (trimmed.len != out) {
        if (mentions) |list| list.rebase(@intFromPtr(trimmed.ptr) - @intFromPtr(dst.ptr), trimmed.len);
        std.mem.copyForwards(u8, dst[0..trimmed.len], trimmed);
        return trimmed.len;
    }
    return out;
}

/// Codepoints that are INVISIBLE by definition and must never reach a renderer
/// that draws a block for what it cannot find.
///
/// A variation selector is the one that shows: "\u{2620}\u{FE0F}" is a skull
/// followed by U+FE0F, which asks for the colour presentation and inks nothing
/// at all. The skull is in the emoji face and draws; the selector is in no
/// face, so it came out as a solid rectangle sitting next to it. Joiners, the
/// bidi marks and the skin tone modifiers are the same story: meaningful to
/// text, never ink of their own.
///
/// macOS is unaffected. CoreText reads these as the presentation and joining
/// instructions they are, so dropping them there would turn a colour emoji into
/// a monochrome one and split families into their parts.
fn invisibleForDisplay(cp: u21) bool {
    return switch (cp) {
        0x200B...0x200F => true, // zero-width space, joiners, bidi marks
        0x202A...0x202E => true, // bidi embedding and overrides
        0x2060...0x2064 => true, // word joiner and the invisible operators
        0xFE00...0xFE0F => true, // variation selectors
        0x20E3 => true, // combining enclosing keycap
        0x1F3FB...0x1F3FF => true, // skin tone modifiers
        else => false,
    };
}

/// The ASCII letter or digit a Mathematical Alphanumeric codepoint is a styled
/// copy of, or null for anything outside that block.
///
/// U+1D400 to U+1D7FF is where the "fancy text" generators live: 𝐁𝐨𝐛, 𝕊𝕒𝕥,
/// 𝓐𝓵𝓲, 𝕾𝖊𝖗. Unicode put thirteen complete styled alphabets and five styled
/// digit runs there for MATHEMATICS, where the style carries meaning (a bold R
/// and a double-struck R are different objects), and social display names have
/// used it as a font picker ever since.
///
/// It is 996 codepoints and NOTHING Plaza ships covers one of them, so off
/// macOS a name written this way had no glyph anywhere and the renderer filled
/// a solid rectangle per word. That is the whole of what a reader saw: two
/// blocks where a name should be. This was reported against a real account
/// whose `display_name` is 𝕾𝖊𝖗 𝕾𝖑𝖊𝖊𝖕𝖞, Mathematical Bold Fraktur, ten
/// codepoints, none of them drawable.
///
/// A font would not fix it either, or not cheaply: covering the block properly
/// means carrying thirteen more alphabets for a decorative effect. Folding is
/// the better trade. The characters ARE the Latin letters, styled, so folding
/// gives the reader the name back rather than a substitute, and it costs
/// nothing to download.
///
/// Pure arithmetic over the runs. Each alphabet is 52 codepoints, A to Z then
/// a to z; each digit run is 10. The block has holes where the character
/// already existed in Letterlike Symbols (italic h is U+210E, not U+1D455), and
/// mapping a hole is harmless because an unassigned codepoint cannot appear in
/// real text.
///
/// The Greek runs (U+1D6A8 to U+1D7CB) are deliberately NOT folded. They would
/// need a u21 result and a re-encode, the bundled Noto face already draws base
/// Greek so the payoff is a rarer name still, and this is a bug fix rather than
/// a Unicode project.
fn foldMathAlnum(cp: u21) ?u8 {
    const alphabets = [_]u21{
        0x1D400, // bold
        0x1D434, // italic
        0x1D468, // bold italic
        0x1D49C, // script
        0x1D4D0, // bold script
        0x1D504, // fraktur
        0x1D538, // double-struck
        0x1D56C, // bold fraktur
        0x1D5A0, // sans-serif
        0x1D5D4, // sans-serif bold
        0x1D608, // sans-serif italic
        0x1D63C, // sans-serif bold italic
        0x1D670, // monospace
    };
    for (alphabets) |start| {
        if (cp >= start and cp < start + 52) {
            const offset: u8 = @intCast(cp - start);
            return if (offset < 26) 'A' + offset else 'a' + (offset - 26);
        }
    }
    const digits = [_]u21{ 0x1D7CE, 0x1D7D8, 0x1D7E2, 0x1D7EC, 0x1D7F6 };
    for (digits) |start| {
        if (cp >= start and cp < start + 10) return '0' + @as(u8, @intCast(cp - start));
    }
    return null;
}

/// Writes one UTF-8 sequence into `dst`. Null when it would not fit, zero when
/// the sequence is invisible and is dropped.
///
/// The emoji themselves pass through untouched: the renderer reaches the
/// registered colour face for them (see `theme.emoji_ttf`). Only the invisible
/// codepoints are filtered, because a renderer that draws a block for what it
/// cannot find would draw one for them.
fn writeDisplaySeq(dst: []u8, seq: []const u8) ?usize {
    if (comptime builtin.os.tag != .macos) {
        if (std.unicode.utf8Decode(seq)) |cp| {
            if (invisibleForDisplay(cp)) return 0;
        } else |_| {}
    }
    if (seq.len > dst.len) return null;
    @memcpy(dst[0..seq.len], seq);
    return seq.len;
}

/// Copies text this app DRAWS into a fixed buffer, emoji and all.
///
/// A display name is not note content and never went through
/// `renderContentInto`, so an emoji in somebody's name stayed as a codepoint no
/// face off macOS can draw, and painted as a solid block. "Dr. The Daniel" with
/// a raised hand after it is what this was found on.
///
/// Display buffers ONLY. The profile editor seeds itself from the raw JSON
/// rather than from this cache, so nothing dropped here is ever published back
/// into somebody's profile.
fn copyDisplayText(dst: []u8, src: []const u8) usize {
    var out: usize = 0;
    var i: usize = 0;
    while (i < src.len) {
        const seq_len = std.unicode.utf8ByteSequenceLength(src[i]) catch 1;
        const take = @min(seq_len, src.len - i);
        // Folded here rather than in `writeDisplaySeq`, which note bodies also
        // go through. A fold changes the byte count, and `renderContentInto`
        // records mention offsets into the buffer it is filling, so moving text
        // under them would point every mention at the wrong span. Display names
        // carry no offsets, so they are the safe place for it, and they are
        // where the bug was reported.
        if (comptime builtin.os.tag != .macos) {
            if (std.unicode.utf8Decode(src[i..][0..take])) |cp| {
                if (foldMathAlnum(cp)) |ascii| {
                    if (out >= dst.len) break;
                    dst[out] = ascii;
                    out += 1;
                    i += take;
                    continue;
                }
            } else |_| {}
        }
        const wrote = writeDisplaySeq(dst[out..], src[i..][0..take]) orelse break;
        out += wrote;
        i += take;
    }
    return out;
}

pub fn invisibleForDisplayForTest(cp: u21) bool {
    return invisibleForDisplay(cp);
}

pub fn copyDisplayTextForTest(dst: []u8, src: []const u8) usize {
    return copyDisplayText(dst, src);
}

pub fn foldMathAlnumForTest(cp: u21) ?u8 {
    return foldMathAlnum(cp);
}

/// A parsed `nostr:` mention at `src[i]`: the byte just past its token, and the
/// referenced pubkey. Null when `src[i]` is not the start of one.
fn parseMentionAt(arena: std.mem.Allocator, src: []const u8, i: usize) ?struct { end: usize, pubkey: [32]u8 } {
    @setRuntimeSafety(true); // Walks a bech32 run whose length the note chose.
    const prefix = "nostr:";
    var body_start = i;
    if (std.mem.startsWith(u8, src[i..], prefix)) {
        // The same boundary guard the bare form below has always had. Without
        // it a contrived `https://example.com/nostr:npub1…` parses as a
        // mention, and now that the composer turns mentions into `p` tags that
        // is a notification sent to a real stranger on the strength of a path
        // segment in somebody else's link.
        if (!refPrecededByBoundary(src, i)) return null;
        body_start = i + prefix.len;
    } else {
        // A bare npub/nprofile counts too (plenty of clients write them without
        // the scheme), but only at a word boundary, so one inside a URL or a
        // longer token is left alone.
        const bare = std.mem.startsWith(u8, src[i..], "npub1") or std.mem.startsWith(u8, src[i..], "nprofile1");
        if (!bare) return null;
        if (i > 0 and (isBech32Char(src[i - 1]) or src[i - 1] == '/' or src[i - 1] == ':')) return null;
    }
    const rest = src[body_start..];
    var j: usize = 0;
    while (j < rest.len and isBech32Char(rest[j])) j += 1;
    if (j == 0) return null;
    const token = rest[0..j];
    const end = body_start + j;

    if (std.mem.startsWith(u8, token, "npub1")) {
        const pk = nostr.nip19.decodeNpub(arena, token) catch return null;
        return .{ .end = end, .pubkey = pk };
    }
    if (std.mem.startsWith(u8, token, "nprofile1")) {
        const pp = nostr.nip19.decodeNprofile(arena, token) catch return null;
        // Same as the quote side: decoded here, and thrown away here until now.
        if (pp.relays.len > 0) wantProfileHinted(pp.pubkey, pp.relays);
        return .{ .end = end, .pubkey = pp.pubkey };
    }
    return null;
}

/// Writes `@` + the cached display name (or a short npub) for `pubkey` into
/// `buf`, returning the written slice. `buf` should be at least 80 bytes.
fn mentionLabel(pubkey: [32]u8, buf: []u8) []const u8 {
    @setRuntimeSafety(true); // Writes a display name of somebody else's choosing into a fixed buffer.
    buf[0] = '@';
    if (lookupProfile(pubkey)) |p| {
        if (p.name_len > 0) {
            const n = @min(p.name_len, buf.len - 1);
            @memcpy(buf[1..][0..n], p.name_buf[0..n]);
            return buf[0 .. 1 + n];
        }
    }
    // No name for this one: ask for it, so the next rebuild can show it.
    wantProfile(pubkey);
    const npub = abbreviateNpub(buf[1..], pubkey);
    return buf[0 .. 1 + npub.len];
}

/// Whether `c` is a bech32 data character (lowercase letter or digit), the run
/// that follows a `nostr:` prefix.
fn isBech32Char(c: u8) bool {
    return (c >= 'a' and c <= 'z') or (c >= '0' and c <= '9');
}

/// Whether `c` continues a hashtag word: letters, digits, underscore, or any
/// byte of a multi-byte UTF-8 sequence.
///
/// The `>= 0x80` arm is what makes `#café` and `#日本` whole words rather than
/// wreckage. Every continuation and lead byte of a UTF-8 sequence is >= 0x80 and
/// every ASCII byte is below it, so a run that ends on a byte < 0x80 always ends
/// on a codepoint boundary: the predicate cannot cut a character in half. The
/// ASCII-only version returned "caf" for the first of those and nothing at all
/// for the second, and both of those went out as tags once the composer started
/// emitting them.
///
/// It over-accepts emoji and non-ASCII punctuation as word characters. That is
/// the same trade every client here makes, and it fails toward a slightly long
/// tag rather than a truncated one.
fn isHashtagChar(c: u8) bool {
    return std.ascii.isAlphanumeric(c) or c == '_' or c >= 0x80;
}

/// Whether an event reference (`nostr:nevent1…`/`note1…`/`naddr1…`, or a bare one
/// at a word boundary) begins at `text[i]`, so a run can be accent-styled. Only
/// at a word boundary, so a `nostr:` or bare token embedded in a URL is skipped.
fn isEventRefStart(text: []const u8, i: usize) bool {
    if (!refPrecededByBoundary(text, i)) return false;
    var s = text[i..];
    if (std.mem.startsWith(u8, s, "nostr:")) s = s["nostr:".len..];
    return std.mem.startsWith(u8, s, "nevent1") or std.mem.startsWith(u8, s, "note1") or std.mem.startsWith(u8, s, "naddr1");
}

/// Whether `text[i]` sits at a word boundary for a nostr reference: the start, or
/// after a character that could not be part of a URL or bech32 run. Keeps a
/// `nostr:nevent…`/bare token embedded in a URL from being matched.
fn refPrecededByBoundary(text: []const u8, i: usize) bool {
    if (i == 0) return true;
    const c = text[i - 1];
    return !(std.ascii.isAlphanumeric(c) or c == '/' or c == ':' or c == '.' or c == '-' or c == '_' or c == '@');
}

fn setAuthor(note: *Note, pubkey: [32]u8) void {
    const s = abbreviateNpub(&note.author_buf, pubkey);
    note.author_len = @intCast(s.len);
}

/// Writes an abbreviated npub (`npub1p9x8h…7k2q`), the canonical Nostr
/// identifier, for `pubkey` into `out`, returning the written slice; falls back
/// to a short hex prefix if bech32 encoding fails. The result always lives in
/// `out` (never the scratch buffer), so the caller can hold it safely. `out`
/// should be at least 20 bytes for the abbreviated form. bech32's encoder grows
/// an ArrayList and hands back an owned slice, so on a fixed buffer the
/// intermediate reallocations accumulate well past the ~63-char result; 1 KiB of
/// scratch covers that churn without touching the heap.
fn abbreviateNpub(out: []u8, pubkey: [32]u8) []const u8 {
    var buf: [1024]u8 = undefined;
    var fba = std.heap.FixedBufferAllocator.init(&buf);
    const npub = nostr.nip19.encodeNpub(fba.allocator(), pubkey) catch {
        const hexdigits = "0123456789abcdef";
        var n: usize = 0;
        while (n < 16 and n + 1 < out.len) : (n += 2) {
            out[n] = hexdigits[pubkey[n / 2] >> 4];
            out[n + 1] = hexdigits[pubkey[n / 2] & 0x0f];
        }
        return out[0..n];
    };
    if (npub.len > 18) {
        if (std.fmt.bufPrint(out, "{s}…{s}", .{ npub[0..12], npub[npub.len - 5 ..] })) |s| return s else |_| {}
    }
    const n = @min(npub.len, out.len);
    @memcpy(out[0..n], npub[0..n]);
    return out[0..n];
}

/// The largest prefix of `s` no longer than `max` that ends on a UTF-8
/// codepoint boundary (never mid-sequence).
fn utf8SafeLen(s: []const u8, max: usize) usize {
    if (s.len <= max) return s.len;
    var n = max;
    while (n > 0 and (s[n] & 0xC0) == 0x80) n -= 1;
    return n;
}

// -------------------------------------------------------------------- msg

/// The chrome's anchored menus. These are floating surfaces positioned against
/// their trigger, so each one is drawn as the trigger's sibling inside a stack
/// and rendered only while it is the open one.
pub const ChromeMenu = enum { none, scope, relays, account, outbox, place_feed };

pub const Msg = union(enum) {
    /// Read a different one of the open place's feeds.
    place_feed: u8,
    /// The repeating refresh timer fired: reconcile the feed with the store.
    tick: native_sdk.EffectTimer,
    /// A text edit in the composer, mirrored into the draft buffer.
    draft_edit: canvas.TextInputEvent,
    /// Post the current draft: sign, store locally, and publish to the pool.
    post,
    /// Open the compose sheet (a guest is routed to the join screen instead).
    open_compose,
    /// Dismiss the compose sheet.
    close_compose,
    /// Open the first-intent join sheet (create / bring a key / use a signer).
    open_join,
    /// Dismiss the join sheet; a remembered intent is forgotten with it.
    close_join,
    place_enter,
    place_leave,
    /// The Places icon: the switcher rail out, or folded away.
    toggle_places_rail,
    /// The place's Info card: what this place is, and the way out of it.
    open_place_info,
    close_place_info,
    /// Ask to leave, and back out of asking.
    place_leave_request,
    place_leave_cancel,
    /// Ask to delete a note of my own, then answer. A deletion cannot be taken
    /// back, so the press opens a question rather than publishing one.
    delete_note_request: i64,
    delete_note_confirm,
    delete_note_cancel,
    /// The answer to "start a new list?": yes carries on with the write that
    /// asked, no drops it.
    fresh_list_confirm,
    fresh_list_cancel,
    /// Add or remove a bookmark, and open the list of them.
    toggle_bookmark: i64,
    /// Save it where only this reader can read it. NIP-51's private half, sealed
    /// to their own key by whoever holds it.
    bookmark_privately: i64,
    open_bookmarks,
    /// Open one of the places you have entered, by its index in the list.
    place_open: u8,
    /// Back into the visit Home closed.
    place_resume,
    /// The keyboard's places grammar: out of the room and back into it, and
    /// walking the list either way.
    place_bounce,
    place_step: i8,
    /// The sheet's primary: mint a local identity and replay the intent.
    join_create,
    /// The sheet's import path: open the Notary window (a separate process),
    /// so a pasted key never enters Plaza. The remembered intent survives.
    open_notary_import,
    /// Leave the join screen back to the feed; reading never needs an identity.
    keep_browsing,
    /// The join sheet's "Use your own signer": go to the focused bunker input.
    open_bunker,
    /// Back out of the bunker input to the ladder.
    close_bunker,
    /// Open the field that takes an address, and dismiss it.
    open_address,
    close_address,
    /// A text edit in the address field, mirrored into its buffer.
    address_edit: canvas.TextInputEvent,
    /// Read what is in the address field and go where it points.
    address_submit,
    /// A person pressed in the results under it.
    search_pick: [32]u8,
    /// The well-known document for a NIP-05 address typed into it.
    nip05_found: native_sdk.EffectResponse,
    /// Hide the guest strip for this session.
    dismiss_guest_strip,
    /// Open one of the chrome's anchored menus (or close it, when it is already
    /// the open one, so a trigger toggles).
    toggle_menu: ChromeMenu,
    /// The bell, and what is behind it.
    toggle_notifications,
    close_notifications,
    notifications_tab: u8,
    notifications_read_all,
    /// The one action behind the note menu. `direction` says which way: 0 means
    /// a guest reached for it, 1 follow, 2 unfollow.
    ///
    /// It carries WHO, like every other row in that menu carries the note it was
    /// opened on. Carrying only a direction meant the handler had to find the
    /// person itself, and what it reached for was the open thread's root: so the
    /// row did nothing at all in the feed, where there is no open thread, and
    /// followed the wrong person inside one, since the label beside it was
    /// computed from the note actually clicked.
    follow_author: struct { who: [32]u8, direction: u8 },
    /// Opens a person as a level of their own.
    repost: i64,
    open_person: [32]u8,
    /// Which feed Home reads: 0 the starter pack, 1 the reader's follows.
    choose_home_scope: u8,
    /// Follow or unfollow the person whose profile is open: 1 follow, 2 unfollow.
    follow_person: u8,
    /// 1 mutes the open profile, 2 unmutes.
    mute_person: u8,
    /// Which of a profile's two tabs: 0 notes, 1 replies.
    profile_tab: u8,
    /// Opens the Edit profile sheet, and the three fields in it.
    open_profile_edit,
    close_profile_edit,
    profile_name_edit: canvas.TextInputEvent,
    profile_about_edit: canvas.TextInputEvent,
    profile_picture_edit: canvas.TextInputEvent,
    profile_website_edit: canvas.TextInputEvent,
    profile_banner_edit: canvas.TextInputEvent,
    profile_lud16_edit: canvas.TextInputEvent,
    profile_nip05_edit: canvas.TextInputEvent,
    profile_save,
    profile_retry,
    /// Ask the relays again for the reader's own follow, mute and bookmark
    /// lists, after the first ask went unanswered.
    retry_own_lists,
    /// Walks a relay through what it is for: both, read, write.
    relay_cycle: u8,
    /// The notice's answer for relay slot N: identify to it.
    auth_allow: u8,
    /// The notice's answer for relay slot N: do not.
    auth_deny: u8,
    /// The relay row's badge: ask first, identify, anonymous.
    auth_cycle: u8,
    /// A NIP-42 signature came back from the keyholder.
    helper_auth_signed: native_sdk.EffectResponse,
    /// Drops a relay from the pool.
    relay_remove: u8,
    /// The relay being typed into the add field.
    relay_edit: canvas.TextInputEvent,
    /// Adds what was typed, or the suggestion pressed.
    relay_add,
    relay_suggest: u8,
    /// Replaces the `@word` being typed with a real reference to this key.
    insert_mention: [32]u8,
    /// Close whatever chrome menu is open (Escape, or a press outside it).
    close_menu,
    /// Stop talking to the relays until resumed, or start again.
    toggle_relays_paused,
    /// Jump the feed to its newest note.
    jump_to_newest,
    go_home,
    /// Reveal the next page of a thread's replies.
    show_more_replies,
    /// Show or re-hide the replies from outside the follow graph.
    toggle_outside_replies,
    /// Copy a note's nevent address to the clipboard.
    copy_nevent: i64,
    /// Open a note on the web (njump), for sharing it outside nostr.
    open_web: i64,
    open_place_handler: i64,
    place_logo_fetched: native_sdk.EffectResponse,
    /// A text edit in the name beat's field.
    name_edit: canvas.TextInputEvent,
    /// Publish the chosen name as the account's kind:0 and move on.
    name_save,
    /// Skip the name beat; the account stays nameless for now.
    name_skip,
    /// From the backup nudge: open Settings at the backup card.
    backup_now,
    /// Dismiss the backup nudge for this session.
    backup_later,
    /// Onboarding: create a fresh local identity and enter the feed.
    create_identity,
    /// A text edit in the onboarding sign-in field.
    login_edit: canvas.TextInputEvent,
    /// Onboarding: sign in with the pasted nsec or bunker link and enter the feed.
    login_submit,
    /// Open the Settings screen.
    open_settings,
    /// Return from Settings to the feed.
    close_settings,
    /// Reveal (or hide) the local secret key for backup.
    /// Copy the signed-in npub to the clipboard.
    copy_npub,
    /// Copy the signed-in account's nprofile, which names the relays it
    /// publishes to, to the clipboard.
    copy_nprofile,
    /// Copy the local secret key (nsec) to the clipboard.
    /// Ask to log out: show the confirmation.
    logout_request,
    /// Dismiss the logout confirmation.
    logout_cancel,
    /// Confirm logout: wipe the session (and a local key) and return to onboarding.
    logout_confirm,
    /// The signer daemon exited (logged; the watchdog and respawn are later).
    /// One line of the daemon's stdout. Only one matters: the port it bound.
    /// Notary opened a NIP-51 list's private half.
    private_half: native_sdk.EffectResponse,
    /// Notary's answer to a seal: the ciphertext for a private bookmark write.
    private_seal: native_sdk.EffectResponse,
    helper_line: native_sdk.EffectLine,
    helper_exited: native_sdk.EffectExit,
    notary_exited: native_sdk.EffectExit,
    /// The signer daemon's /pubkey health-check answered.
    helper_pubkey: native_sdk.EffectResponse,
    /// A /setup (create) answered: adopt the new helper identity.
    helper_setup: native_sdk.EffectResponse,
    /// A /sign answered: ingest and publish the signed event.
    helper_signed: native_sdk.EffectResponse,
    /// An avatar fetch finished: register the image or fall back to initials.
    avatar_fetched: native_sdk.EffectResponse,
    avatar_warmed: native_sdk.EffectResponse,
    media_warmed: native_sdk.EffectResponse,
    banner_fetched: native_sdk.EffectResponse,
    /// A media fetch finished: decode, downscale if needed, and register it.
    media_fetched: native_sdk.EffectResponse,
    /// A NIP-05 well-known lookup finished: mark the author verified on a match.
    nip05_verified: native_sdk.EffectResponse,
    /// A page that was asked what it says about itself.
    link_fetched: native_sdk.EffectResponse,
    /// The releases API answered the update check.
    update_checked: native_sdk.EffectResponse,
    /// Go and get the newer version: opens the release page in a browser.
    open_update,
    /// Put the update line away for this session.
    dismiss_update,
    /// Settings: stop asking whether a newer version exists.
    update_check_toggle,
    /// A text edit in the Settings media-proxy field.
    proxy_edit: canvas.TextInputEvent,
    /// Save the media-proxy setting.
    proxy_save,
    /// Flips whether the app reaches out for what notes point at.
    previews_toggle,
    /// Settings: draw notes their authors marked sensitive without covering them.
    sensitive_toggle,
    /// Uncover one note whose author asked for it to be covered (by id).
    uncover_note: i64,
    /// The composer's "add a content warning" switch.
    warn_toggle,
    /// A text edit in the composer's content warning reason.
    warn_edit: canvas.TextInputEvent,
    proxy_toggle,
    post_delay_cycle,
    direct_fallback_toggle,
    /// Index into `hideables`.
    hide_toggle: u8,
    client_tag_toggle,
    /// The feed scrolled: remember where, so images load around the viewport.
    feed_scrolled: canvas.ScrollState,
    /// Where Settings is scrolled, echoed back so a press can move it.
    settings_scrolled: canvas.ScrollState,
    /// A link in a note was pressed: open it in the browser.
    open_url: []const u8,
    /// The animation timer fired: advance any playing GIFs.
    animate: native_sdk.EffectTimer,
    /// The profile-fetch timer: re-ask for wanted metadata, decoupled from the
    /// view refresh (see `profile_timer_key`).
    profiles: native_sdk.EffectTimer,
    /// Expand a note's picture to fill the window.
    expand_image: i64,
    /// Which picture of a gallery to open. A single picture still uses
    /// `expand_image`, which is the same thing with an implied zero.
    expand_image_at: struct { note: i64, index: u8 },
    /// One picture, asked for by the reader while previews are off.
    load_image: i64,
    /// Dismiss the expanded picture.
    close_image,
    /// Copy a note's words to the clipboard (by id).
    copy_note_text: i64,
    quote_note: i64,
    toggle_mention_off: [32]u8,
    /// Put the mention picker away without choosing anybody.
    close_mentions,
    /// Open the Notary window on what it is holding, from Settings.
    open_notary_window,
    /// Toggle a like on a note (by id): publish a kind:7 reaction, or a kind:5
    /// deletion to un-like. A guest press is remembered and routed to the join.
    like: i64,
    /// Open a note's thread (by id): the focused note and its replies.
    open_thread: i64,
    /// Open a quoted event as a thread (by its full 32-byte id).
    open_event: [32]u8,
    /// Leave the thread back to the feed.
    close_thread,
    /// A text edit in the thread's reply composer.
    reply_edit: canvas.TextInputEvent,
    /// Publish the reply composer's text as a reply to the open thread's note.
    reply_submit,
    /// Toggle a long note's body (by id) between the collapsed fold and full.
    toggle_expand: i64,
    /// The reader reached the end of the feed: ask the store for another page.
    load_older,
    /// Choose a picture to upload: 0 for a note, 1 for the avatar, 2 for the
    /// banner. Opens the file dialog; nothing is sent until the card asks.
    upload_pick: u8,
    /// Send the chosen picture.
    upload_go,
    /// Send it again after a failure.
    upload_retry,
    /// Put the upload away, whatever it is doing.
    upload_cancel,
    /// A text edit in the picture's description.
    upload_alt_edit: canvas.TextInputEvent,
    /// A text edit in Settings' add-a-media-server field.
    blossom_edit: canvas.TextInputEvent,
    /// Add what was typed to the media server list.
    blossom_add,
    /// Drop one server from the list, by its row.
    blossom_remove: u8,
    /// The reader reached the end of a person's page: another page of their
    /// notes, from the store and then from the relays.
    profile_older,
    /// A press that landed on a modal's own card rather than on a control in it.
