pub fn stepPlaceForTest(delta: i8) void {
    stepPlace(delta);
}
pub fn activePlaceIndexForTest() ?usize {
    return activePlaceIndex();
}

pub fn restoreOpenPlaceForTest() void {
    restoreOpenPlace();
}

pub fn bootPlaceIndexForTest() ?usize {
    return bootPlaceIndex();
}
pub fn applyActivePlaceLineForTest(value: []const u8) void {
    applyActivePlaceLine(value);
}
pub fn visitingPlaceForTest() ?*const Place {
    return visitingPlace();
}
pub fn resumeVisitForTest() void {
    resumeVisit();
}

pub fn boot(model: *Model, fx: *Effects) void {
    // FIRST, before anything slow. On a cold launch macOS sends the Apple Event
    // moments after the app starts, so a handler installed after the store is
    // opened misses the very link that launched Plaza.
    if (has_url_scheme) plaza_url_scheme_install();
    // How the theme asks which room is open. Installed before the places are
    // loaded, so the very first frame of a restored place is already wearing its
    // colour rather than flashing porcelain for one rebuild.
    installThemeHooks();
    if (g_io) |io| {
        if (g_environ) |environ| {
            loadPlaces(io, environ);
            restoreOpenPlace();
        }
    }
    model.refresh(nowSeconds());
    // What was written but not sent when the app last closed, back in the
    // composer where it was left.
    var draft_buf: [note_content_cap]u8 = undefined;
    var warn_buf: [warning_input_capacity]u8 = undefined;
    const stashed = loadDraft(&draft_buf, &warn_buf);
    applyStashedDraft(model, stashed);
    // What was owed when the app last closed. Read before the first frame, so a
    // note written offline yesterday is visible as owed rather than lost, and
    // offered again as soon as a relay answers. Whose queue that is comes from
    // the session that was just restored; a guest starts with empty slots.
    syncOutboxOwner();
    // Local-first, all the way to the first frame: cached avatars and pictures
    // are registered here, so a returning user gets faces WITH the notes rather
    // than a tick later. Only what is on disk resolves now; the rest is fetched
    // from the first tick onward.
    wantProfilesAhead(model);
    beginImagePass();
    assignAvatarSlots(fx, model);
    scanAvatarFetches(fx);
    scanMediaFetches(fx, model);
    warmAhead(fx, model);
    scanLinkFetches(fx, model);
    scanNip05Fetches(fx);
    fx.startTimer(.{
        .key = refresh_timer_key,
        .interval_ms = refresh_interval_ms,
        .mode = .repeating,
        .on_fire = Effects.timerMsg(.tick),
    });
    // One timer drives every playing GIF; a timer each would exhaust the table.
    fx.startTimer(.{
        .key = animation_timer_key,
        .interval_ms = animation_interval_ms,
        .mode = .repeating,
        .on_fire = Effects.timerMsg(.animate),
    });
    // Bring up the isolated signer; the tick health-checks it until it answers.
    spawnHelper(fx);
    // Background metadata fetching on its own cadence, off the view refresh.
    fx.startTimer(.{
        .key = profile_timer_key,
        .interval_ms = profile_interval_ms,
        .mode = .repeating,
        .on_fire = Effects.timerMsg(.profiles),
    });
}

/// What `plainLineBreaks` wrote, how long the whole input comes to once its
/// breaks are plain (including whatever did not fit in `out`), and whether it
/// had to change anything.
pub const PlainLineBreaks = struct { text: []const u8, full_len: usize, changed: bool };

/// Every line break that macOS draws as one and the toolkit does not lay out as
/// one becomes a plain LF: CR on its own, vertical tab, form feed, NEL (U+0085),
/// and the Unicode line and paragraph separators (U+2028, U+2029). Writes what
/// fits into `out`, never cutting a UTF-8 sequence, and counts the rest.
///
/// The toolkit breaks a line only at LF, so it lays "end.\rNext" out as one
/// word on one row. On macOS the host then draws each of those rows through
/// AppKit, which DOES break there, so the words after the break land a row
/// lower, on top of the next row. That is what made a pasted note look
/// scrambled (#165), reproduced with each of these separators by pasting into
/// the composer.
///
/// CRLF is left as it is. The layout breaks at its LF, so its CR is the last
/// byte of a row and nothing is drawn after it: it has always drawn correctly,
/// and changing it would cost the reader the caret and undo (see
/// `applyPlainEdit`) for nothing.
pub fn plainLineBreaks(in: []const u8, out: []u8) PlainLineBreaks {
    var written: usize = 0;
    var full: usize = 0;
    var changed = false;
    var i: usize = 0;
    while (i < in.len) {
        var take: usize = 1;
        var plain = false;
        switch (in[i]) {
            '\r' => plain = !(i + 1 < in.len and in[i + 1] == '\n'),
            0x0B, 0x0C => plain = true,
            0xC2 => if (i + 1 < in.len and in[i + 1] == 0x85) {
                plain = true;
                take = 2;
            },
            0xE2 => if (i + 2 < in.len and in[i + 1] == 0x80 and (in[i + 2] == 0xA8 or in[i + 2] == 0xA9)) {
                plain = true;
                take = 3;
            },
            else => {},
        }
        // Anything else is copied with the rest of its UTF-8 sequence, so a
        // full `out` never ends halfway through a character.
        if (!plain) take = @min(std.unicode.utf8ByteSequenceLength(in[i]) catch 1, in.len - i);
        const len: usize = if (plain) 1 else take;
        // Written only while everything before it was: the text is always a
        // prefix of the whole.
        if (written == full and written + len <= out.len) {
            if (plain) out[written] = '\n' else @memcpy(out[written..][0..len], in[i..][0..len]);
            written += len;
        }
        changed = changed or plain;
        full += len;
        i += take;
    }
    return .{ .text = out[0..written], .full_len = full, .changed = changed };
}

/// Applies an edit to a multi-line text buffer with its line breaks made plain
/// first (see `plainLineBreaks`). Returns what an insert asked to add, counted
/// after that, so a caller can tell how much a clamp refused.
///
/// The editor keeps its own copy of the text, and it holds far more than this
/// buffer does. Whenever this buffer ends up with different text from what the
/// editor inserted, because a separator was replaced or because the paste was
/// cut to fit, the editor takes this text and puts ITS caret at the end: the
/// toolkit gives an app no way to say where the caret should be. So this
/// buffer's caret goes to the end too, or the next key would land where the
/// reader cannot see it. A cut can also split a CRLF and leave a lone CR at the
/// cut, so the whole text is made plain again then. The editor's undo history
/// for the box starts again from there, which is the price of both.
///
/// An insert refused outright changes nothing here, and the editor keeps its
/// own copy, so nothing is moved.
fn applyPlainEdit(comptime capacity: usize, buffer: *canvas.TextBuffer(capacity), edit: canvas.TextInputEvent) usize {
    switch (edit) {
        .insert_text => |inserted| {
            var scratch: [capacity]u8 = undefined;
            const plain = plainLineBreaks(inserted, &scratch);
            const before_len = buffer.len;
            const before_selection = buffer.selection;
            buffer.apply(.{ .insert_text = plain.text });
            // Anything past `scratch` is more than the whole buffer holds, so
            // it is a clamp even when the buffer took all of `plain.text`.
            const clamped = buffer.truncated or plain.full_len > plain.text.len;
            buffer.truncated = clamped;
            const refused = clamped and buffer.len == before_len and
                std.meta.eql(buffer.selection, before_selection);
            if (!refused and (plain.changed or clamped)) {
                var whole: [capacity]u8 = undefined;
                buffer.set(plainLineBreaks(buffer.text(), &whole).text);
            }
            return plain.full_len;
        },
        else => {
            buffer.apply(edit);
            return 0;
        },
    }
}

/// Puts text into a buffer with its line breaks made plain, for text that
/// arrives other than by typing: a draft restored from disk, which an older
/// Plaza may have saved with a CR in it.
fn setPlain(comptime capacity: usize, buffer: *canvas.TextBuffer(capacity), text: []const u8) void {
    var scratch: [capacity]u8 = undefined;
    buffer.set(plainLineBreaks(text, &scratch).text);
}

/// Keeps the open level current, once a tick: what a backfill has since put in
/// the store, the loading line, and the relative times.
///
/// Every kind of level a fetch fills has to be named here (the bookmark list
/// fires no fetch, so it has nothing to hear). The store-moved guard below skips
/// the read when nothing arrived, which is right, but it means a level that is
/// left out never hears about its own fetch: the topic view was, so what its
/// relays sent was ingested and then never drawn, and its loading line never
/// ended.
fn refreshOpenLevel(model: *Model, now: i64) void {
    const level_count = if (g_store) |st| (st.eventCount() catch g_last_level_count) else g_last_level_count;
    if (level_count != g_last_level_count) {
        g_last_level_count = level_count;
        model.refreshThreadNotes(now);
        // And the open person's notes, for the same reason and with
        // the same consequence if it is missed: without this the
        // backfill this screen fires never appears, and the quiet
        // line saying they have written nothing stays up over a
        // store that has since filled with their notes.
        model.refreshProfileNotes(now);
        model.refreshTopicNotes(now);
    }
    // Relative times were a side effect of the rebuild, so they have
    // to be kept up now that the rebuild is conditional. "2m" going
    // stale is exactly the sort of thing a guard like this breaks
    // quietly.
    for (model.thread_notes[0..model.thread_notes_len]) |*note| note.setTime(now);
    if (model.viewing_profile != null) {
        model.thread_loading = model.thread_notes_len == 0 and
            g_thread_done_seq.load(.acquire) < model.thread_seq;
    } else if (model.viewing_thread != 0) {
        // Every tick, not only when the store moved: a thread nobody answered
        // leaves the store unchanged, and that is exactly when the skeletons
        // have to give way to "No replies yet".
        model.settleThreadLoading(now);
    }
    model.settleTopicLoading(now);
}

/// Forgets the store count the last tick saw, so a test's first tick reads.
pub fn forgetLevelCountForTest() void {
    g_last_level_count = std.math.maxInt(usize);
}

/// One tick of the open level's upkeep, for a test.
pub fn refreshOpenLevelForTest(model: *Model, now: i64) void {
    refreshOpenLevel(model, now);
}

/// Marks the fetch for generation `seq` as finished, the way its worker does
/// when every relay has answered, for a test that has no worker.
pub fn finishLevelFetchForTest(seq: u64) void {
    g_thread_done_seq.store(seq, .release);
}

pub fn update(model: *Model, msg: Msg, fx: *Effects) void {
    switch (msg) {
        .tick => |t| {
            if (t.outcome == .fired) {
                const now = nowSeconds();
                // A `plaza://` link somebody clicked, drained once per tick.
                // Polling rather than an effect because the Apple Event lands
                // on the main thread outside the SDK's event loop entirely,
                // so there is nothing to subscribe to.
                var link_buf: [2048]u8 = undefined;
                if (takePendingLink(&link_buf)) |link| handlePlazaLink(model, fx, link);
                refreshPlaceFetch(model);
                // Beside it, and after it: a place arriving from a link moves
                // the reader into a room, and that is a walk away from a note
                // they asked for a moment earlier.
                refreshEventFetch(model);
                refreshAddressFetch(model);
                searchTick(model, awakeMs());
                flushPlaceIds(now);
                model.refresh(now);
                // Keep the open thread's replies current: late replies appear and
                // relative times stay fresh, the same cadence as the feed.
                //
                // Only when the store actually moved, which is the guard the
                // feed rebuild ten lines up has always had and these two never
                // did. Unconditional, they were a full `store.query`, a
                // `collectThreadIds` closure walk that queries again per level,
                // and a re-parse of every reply into a fresh `Note` — once a
                // second, on the render thread, for as long as a thread or a
                // profile stayed open, almost always to produce exactly the
                // list that was already on screen.
                //
                // The open paths call these directly, so a thread still fills
                // the moment it is opened; this only skips the repeat.
                refreshOpenLevel(model, now);
                // And the bottom of the open person's list, which may be in view
                // with nothing left to scroll that would ask for more.
                loadAtProfileBottom(model);
                // Anything still owed goes back out whenever a relay is up: this
                // is the drain, and it is idempotent, since an entry already in
                // flight is skipped.
                // The Edit profile sheet waits on a real answer before it lets
                // anything be published over a profile it has not read.
                if (model.editing_profile and model.profile_stage == .absent and !model.profile_seeded) {
                    // Absent was what the relays had said by then, not a promise.
                    // A profile that arrives after it is shown rather than left
                    // for a Save to merge blank fields into.
                    const gpa = std.heap.page_allocator;
                    if (ownProfileJson(gpa)) |own| {
                        defer freeOwnProfile(gpa, own);
                        seedProfileFields(model, own.json, true);
                        model.profile_stage = .have;
                        model.profile_confirm_new = false;
                    }
                } else if (model.editing_profile and model.profile_stage == .fetching) {
                    const gpa = std.heap.page_allocator;
                    if (ownProfileJson(gpa)) |own| {
                        defer freeOwnProfile(gpa, own);
                        // A profile arriving a few seconds late must not replace
                        // the sentence the reader is in the middle of typing,
                        // which is what the second argument protects. It used to
                        // be all or nothing: one typed character skipped the
                        // seeding of ALL THREE fields, and the flip to `.have`
                        // below ran anyway, so Save lit up over two empty fields
                        // that had never been read and the merge deleted them.
                        if (!model.profile_seeded) seedProfileFields(model, own.json, true);
                        model.profile_stage = .have;
                    } else if (ownProfileAnswered()) {
                        model.profile_stage = .absent;
                    } else if (now - model.profile_asked_at > own_profile_wait_s) {
                        model.profile_stage = .unread;
                    }
                }
                // A logout's reset that never reached the daemon, re-sent. Left
                // undone, the daemon keeps the key the reader just left and the
                // health-check would sign them back into it.
                // Their published relay list, taken on this thread so no ingest
                // thread ever swaps the pool out from under the others.
                _ = adoptRelayList();
                // Starts the clock on reading the reader's own lists at sign-in
                // rather than the first time a control asks about them.
                if (activePubkey() != null) _ = ownListsRead();
                flushRelayList(fx, now);
                // At most one write a second, and only when something changed.
                if (inboxNeedsSave()) saveInbox();
                // Before anything reads or walks the queue: the slots belong
                // to whoever is signed in now, and a sign-in or a logout since
                // the last tick means they change hands here.
                syncOutboxOwner();
                if (liveRelayCount() > 0) drainOutbox(std.heap.page_allocator);
                sweepOutbox(now);
                // At most one write a second, and only when something changed.
                if (g_draft_dirty) {
                    g_draft_dirty = false;
                    saveDraft(model.draft(), draftWarningOf(model));
                }
                const counts = outboxCounts();
                model.outbox_pending = counts.trying;
                model.outbox_stuck = counts.stuck;
                // The banner is about a note that was dropped, and a note can
                // still be dropped by the paths that reach `ingestAndPublish`
                // without going through the composer. It used to latch for the
                // life of the process: the queue drained, later posts landed,
                // and the status bar went on saying a note could not be queued
                // for the rest of the run. It retires when there is room again,
                // which is the condition it was reporting the absence of.
                if (g_outbox_overflow.load(.monotonic) and outboxHasRoom()) {
                    g_outbox_overflow.store(false, .monotonic);
                }
                model.outbox_overflowed = g_outbox_overflow.load(.monotonic);
                if (g_outbox_rev.load(.monotonic) != g_outbox_saved_rev) {
                    g_outbox_saved_rev = g_outbox_rev.load(.monotonic);
                    saveOutbox();
                }
                // Start any pending image fetches (needs effects, so here, not
                // in refresh). The feed reads loaded images at render time.
                wantProfilesAhead(model);
                beginImagePass();
                assignAvatarSlots(fx, model);
                scanAvatarFetches(fx);
                scanBannerFetch(fx, model);
                scanPlaceLogo(fx, model);
                scanMediaFetches(fx, model);
                warmAhead(fx, model);
                scanLinkFetches(fx, model);
                scanNip05Fetches(fx);
                // A list whose private half Notary has not opened yet. Reading
                // it needs the keyholder now that no secret lives here.
                scanPrivateHalves(fx);
                // Complete a like a guest reached for, now that they have signed
                // in and the feed above has rebuilt.
                drivePendingIntent(model, fx);
                // A held note whose clock has run out. This is the only place a
                // note is signed without a press, and the press it stands in for
                // already happened: the reader asked, and then did not take it
                // back.
                if (postIsDue(g_post_due_s, nowSeconds())) _ = firePost(model, fx, g_held_route);
                if (postIsDue(g_reply_due_s, nowSeconds())) fireReply(model, fx, g_held_route);
                // Retire timed-out or refused signer requests, restoring a lost
                // draft to the composer (this thread owns it).
                if (g_signer_kind == .remote) scanPendingRemote(model, fx);
                driveBunkerConnect(model);
                // The same question for the built-in signer, which had no
                // answer to it at all: a sign that failed simply ended.
                if (g_signer_kind == .helper) scanHelperSign(model);
                // A relay that asked who the reader is, and was told yes: get
                // the answer signed. The reader thread sends it.
                driveRelayAuth(fx);
                // A picture on its way: a token that came back, a send that
                // finished, a signer that never answered.
                driveUpload(model);
                // Health-check the signer daemon until the loopback IPC answers,
                // then fire any queued key setup.
                pollHelper(fx);
                driveHelperSetup(fx);
                // Whether a newer Plaza exists, on its own slow clock. Returns
                // at once when the reader has switched it off.
                maybeCheckForUpdate(fx);
                // A toast lives a few seconds, then the tick retires it.
                if (model.toast_until != 0 and nowSeconds() >= model.toast_until) {
                    model.toast_until = 0;
                    model.toast_len = 0;
                }
            }
        },
        .animate => |t| {
            if (t.outcome == .fired) advanceAnimations(fx, model);
        },
        .profiles => |t| {
            if (t.outcome == .fired) {
                // Quotes still re-arm on a round counter. Profiles no longer
                // need to: each pubkey carries its own last-tried stamp and
                // backs off on its own, so asking every tick costs nothing for
                // the ones that are waiting and retries the rest when due.
                g_profile_round +%= 1;
                g_quote_round +%= 1;
                if (g_quote_round % quote_rearm_rounds == 0) rearmWantedQuotes();
                requestWantedProfiles();
                requestWantedQuotes();
            }
        },
        .private_half => |response| handlePrivateHalf(response),
        .private_seal => |response| handlePrivateSeal(model, fx, response),

        .helper_line => |line| {
            // The daemon says where it landed, and until it does there is
            // nowhere to send anything. Everything else it prints is for a
            // human reading a terminal.
            const text = std.mem.trim(u8, line.line, " \t\r\n");
            if (!std.mem.startsWith(u8, text, helper_port_prefix)) return;
            const rest = std.mem.trim(u8, text[helper_port_prefix.len..], " \t");
            const port = std.fmt.parseInt(u16, rest, 10) catch return;
            if (port == 0) return;
            g_helper_port = port;
            // It came up and said where it is, so the budget for starting it
            // again is whole. Without this, three sign-outs across one long
            // session would spend it and the fourth would be refused.
            g_helper_restarts = 0;
        },

        .helper_exited => |e| {
            if (e.reason != .exited) std.debug.print("plaza: [helper] exited\n", .{});
            // Start it again. Signing out from the key window ends the process
            // deliberately, and a crash ends it accidentally; either way this
            // app used to be left holding a port number for something that was
            // gone, unable to sign anything until it was restarted.
            //
            // The port and the identity go with it. The new one comes up
            // locked, which is the truthful state and the one the reader is
            // then asked to leave.
            g_helper_port = 0;
            g_helper_state.store(@intFromEnum(HelperState.starting), .release);
            if (g_helper_restarts < helper_restart_limit) {
                g_helper_restarts += 1;
                spawnHelper(fx);
            } else {
                g_helper_state.store(@intFromEnum(HelperState.unreachable_), .release);
                setToast(model, "Your keyholder keeps stopping. Reopen the app.");
            }
        },
        .notary_exited => |e| handleNotaryExited(model, e),
        .helper_pubkey => |response| {
            handleHelperPubkey(model, response);
            // A queued setup fires the moment the daemon is reachable.
            driveHelperSetup(fx);
            // And a locked keyholder asks for its passphrase rather than just
            // reporting that it is locked.
            driveUnlockPrompt(fx);
        },
        .helper_setup => |response| handleHelperSetup(model, response),
        .helper_signed => |response| handleHelperSigned(response),
        .avatar_fetched => |response| handleAvatarFetched(fx, response),
        .avatar_warmed => |response| handleAvatarWarmed(response),
        .media_warmed => |response| handleMediaWarmed(response),
        .banner_fetched => |response| handleBannerFetched(fx, response),
        .draft_edit => |edit| {
            // What this edit meant to add, before it is clamped. Only an insert
            // can overflow; every other edit is rejected whole.
            const before = model.draft_buffer.len;
            const wanted = applyPlainEdit(compose_capacity, &model.draft_buffer, edit);
            // The buffer's own words for this flag are "loud seam for paste:
            // check after applying a clipboard insert", and nothing here ever
            // did. A paste past the cap lost the overflow in silence: the
            // counter read "0 left", which says the composer is exactly full,
            // not that a third of what you just pasted is gone.
            if (model.draft_buffer.truncated and wanted > 0) {
                model.draft_dropped = wanted -| (model.draft_buffer.len -| before);
            } else if (wanted > 0) {
                // A later paste that DID fit answers the earlier warning.
                model.draft_dropped = 0;
            }
            // A new query is a new question, so a dismissal only covers the one
            // the reader dismissed. Without this, putting the picker away once
            // would put it away for the rest of the note.
            model.mention_dismissed = false;
            // Marked, not written: the tick flushes it. Saving on CLOSE alone
            // was the wrong half, because the state a writer is in when the
            // machine sleeps or the app is killed is the sheet OPEN.
            g_draft_dirty = true;
            // The user is composing again: retire a stale "signer didn't respond".
            g_remote_sign_notice.store(false, .release);
            g_helper_sign_notice.store(false, .release);
        },
        .post => {
            // Every precondition, before anything is signed or said. A message
            // is reachable from more places than the button that names it: the
            // field's own submit chord, a future menu entry, a key. Publishing
            // is not something to do on a model that was not showing a
            // composer, and a draft restored from disk must never leave the
            // machine without the reader seeing it in one.
            if (!model.composing or model.stage != .ready or model.is_guest()) return;
            if (model.draft_empty()) return;
            // Nothing after this runs unless the note actually went to a
            // signer. It used to run regardless: the composer emptied, the draft
            // file was deleted and the toast said "Posted" for a sign that had
            // been refused before it left the process.
            // Held, not sent. Nothing is signed until the clock runs out, and
            // pressing again takes it back while that is still true.
            if (g_post_due_s != 0) {
                g_post_due_s = 0;
                setToast(model, "Kept here.");
                return;
            }
            if (g_post_delay_s > 0) {
                // The room it is being written in, taken NOW. The pause exists
                // so the reader can change their mind, and they are free to walk
                // somewhere else while it counts.
                g_held_route = routeForOpenPlace();
                g_post_due_s = nowSeconds() + g_post_delay_s;
                return;
            }
            _ = firePost(model, fx, null);
        },
        .open_compose => {
            // The keyboard reaches past the sheet: this is a declared shortcut,
            // so the shell delivers it whatever is on screen, and `appView` draws
            // the sheet ABOVE the composer. Without this the composer arms itself
            // unseen and appears unbidden the moment the sheet is dismissed.
            model.notifications_open = false;
            // The gate is on press, not on sight: a guest reaching for the
            // composer is exactly first intent, so the sheet rises and
            // remembers what was reached for.
            if (model.is_guest()) {
                model.joining = true;
                model.pending = .post;
            } else model.composing = true;
        },
        .open_person => |pk| openPerson(model, pk),
        .follow_person => |direction| {
            if (model.is_guest()) {
                // REMEMBERED, not merely gated. This press used to open the sheet
                // and forget what it was for, so signing in landed the reader on
                // the feed still not following the person they had just asked to
                // follow, with nothing to say why.
                if (model.viewing_profile) |who| model.pending = .{ .follow = who };
                model.joining = true;
                return;
            }
            const who = model.viewing_profile orelse return;
            if (direction == 1 and askFreshFirst(model, .{ .action = .follow, .who = who })) return;
            sayFollowWrite(model, writeFollow(fx, who, direction == 1), direction == 1);
        },
        .mute_person => |direction| {
            // A guest has nothing to mute FROM: there is no list to splice and
            // no key to sign with. Unlike a follow, this is not worth
            // remembering across a sign-in either, since muting is about a feed
            // they do not have yet.
            if (model.is_guest()) {
                model.joining = true;
                return;
            }
            const who = model.viewing_profile orelse return;
            if (direction == 1 and askFreshFirst(model, .{ .action = .mute, .who = who })) return;
            sayMuteWrite(model, writeMute(fx, who, direction == 1), direction == 1);
        },
        .choose_home_scope => |which| {
            model.menu = .none;
            setHomeScope(if (which == 0) .starter_pack else .following);
            // Remembered, or the choice lasts until the next launch and the
            // reader has to make it again every morning.
            saveSettings();
        },
        .profile_tab => |which| {
            model.profile_tab = if (which == 1) .replies else .notes;
            model.profile_autofill = 0;
        },
        .toggle_notifications => {
            model.notifications_open = !model.notifications_open;
            // Opening IS reading: the reader is looking at them. The mark moves
            // to the newest item held, never to the wall clock, so a backfill
            // arriving later with older stamps is not born already read.
            if (model.notifications_open) {
                inboxMarkAllRead();
                markInboxDirty();
            }
        },
        .close_notifications => model.notifications_open = false,
        .notifications_tab => |which| {
            model.notifications_everyone = which == 1;
            // The other tab holds a different set, so page four of this one is
            // not page four of that one.
        },
        .notifications_read_all => {
            inboxMarkAllRead();
            markInboxDirty();
        },
        .follow_author => |press| {
            // A guest reaching for Follow is first intent, the same as reaching
            // for the composer: the sheet rises rather than the press failing.
            // Remembered for whoever the menu was opened on, in the feed as well
            // as in a thread: it used to be kept only inside a thread, and then
            // for the thread's root rather than for the person clicked.
            if (press.direction == 0 or model.is_guest()) {
                model.pending = .{ .follow = press.who };
                model.joining = true;
                return;
            }
            if (press.direction == 1 and askFreshFirst(model, .{ .action = .follow, .who = press.who })) return;
            sayFollowWrite(model, writeFollow(fx, press.who, press.direction == 1), press.direction == 1);
        },
        .open_profile_edit => openProfileEdit(model),
        .close_profile_edit => {
            model.editing_profile = false;
            g_profile_upload_unsaved = false;
            // A picture on its way to the avatar or banner has nowhere to go
            // once the sheet is closed.
            if (g_upload) |job| {
                if (job.target != .note) uploadCancel(model);
            }
        },
        .profile_name_edit => |edit| model.profile_name_buffer.apply(edit),
        .profile_about_edit => |edit| _ = applyPlainEdit(profile_about_capacity, &model.profile_about_buffer, edit),
        .profile_picture_edit => |edit| model.profile_picture_buffer.apply(edit),
        .profile_website_edit => |edit| model.profile_website_buffer.apply(edit),
        .profile_banner_edit => |edit| model.profile_banner_buffer.apply(edit),
        .profile_lud16_edit => |edit| model.profile_lud16_buffer.apply(edit),
        .profile_nip05_edit => |edit| model.profile_nip05_buffer.apply(edit),
        .profile_save => {
            g_profile_upload_unsaved = false;
            saveProfile(model, fx);
        },
        .retry_own_lists => {
            retryOwnListsRead();
            setToast(model, "Asking your relays again.");
        },
        .profile_retry => {
            model.profile_confirm_new = false;
            forgetOwnProfileAnswer();
            model.profile_asked_at = nowSeconds();
            model.profile_stage = .fetching;
            startOwnProfileFetch();
        },
        .auth_allow => |i| authAnswer(i, true),
        .auth_deny => |i| authAnswer(i, false),
        .auth_cycle => |i| authCycle(i),
        .helper_auth_signed => |response| handleHelperAuthSigned(response),
        .upload_pick => |which| {
            const target = std.enums.fromInt(UploadTarget, which) orelse return;
            uploadPick(model, fx, target);
        },
        .upload_go => uploadGo(model, fx),
        .upload_retry => uploadRetry(model, fx),
        .upload_cancel => uploadCancel(model),
        .upload_alt_edit => |edit| model.upload_alt_buffer.apply(edit),
        .blossom_edit => |edit| {
            model.blossom_buffer.apply(edit);
            // Typing answers whatever the field last complained about.
            model.blossom_error = .none;
        },
        .blossom_add => blossomAdd(model, fx),
        .blossom_remove => |i| blossomRemove(model, fx, i),
        .relay_cycle => |i| {
            cycleRelay(i);
            // The ack bits name slots, and this slot's direction just changed.
            relayListEdited();
        },
        .relay_remove => |i| {
            // The last relay stays. With none, nothing is read and nothing is
            // written, and the empty list would be what gets published over the
            // one this account already has. Replacing it is add-then-remove.
            if (!mayRemoveRelay()) {
                model.relay_last = true;
                model.relay_full = false;
                model.relay_error = false;
                return;
            }
            removeRelay(i);
            // They just did what the full-pool message asked for.
            model.relay_full = false;
            model.relay_last = false;
            relayListEdited();
        },
        .relay_edit => |edit| {
            model.relay_buffer.apply(edit);
            // Typing is the reader answering what the field asked. Keeping the
            // old complaint under a field they are fixing makes the app look
            // like it is not watching.
            model.relay_error = false;
            model.relay_full = false;
            model.relay_last = false;
        },
        .relay_add => {
            const typed = std.mem.trim(u8, model.relay_buffer.text(), " \t\r\n");
            // Both flags answer THIS press. A full-pool message left standing
            // after the reader removed a relay would hide the real reason the
            // next add failed.
            model.relay_full = false;
            model.relay_error = false;
            model.relay_last = false;
            if (!isRelayUrl(typed)) {
                model.relay_error = true;
                return;
            }
            if (addRelay(typed, true, true) == null) {
                model.relay_full = true;
                return;
            }
            model.relay_full = false;
            model.relay_buffer.clear();
            relayListEdited();
        },
        .relay_suggest => |i| {
            var buf: [96]u8 = undefined;
            const url = relaySuggestionCopy(i, &buf) orelse return;
            if (addRelay(url, true, true) == null) {
                // A silent press is the app refusing without saying so.
                model.relay_full = true;
                return;
            }
            model.relay_full = false;
            model.relay_last = false;
            forgetRelaySuggestion(i);
            relayListEdited();
        },
        .insert_mention => |pubkey| insertMention(model, pubkey),
        .close_compose => {
            // A held note goes with the sheet. Leaving it armed would publish,
            // seconds later, the note whose composer the reader had just
            // dismissed, and the draft below would be the text of something
            // already on its way out.
            g_post_due_s = 0;
            model.composing = false;
            model.draft_dropped = 0;
            // Closing the sheet stashes what is in it. The words survived a
            // closed sheet already; this is what carries them past a quit.
            saveDraft(model.draft(), draftWarningOf(model));
        },
        .open_join => model.joining = true,
        // Enter: keep this place. That is all it does, and it is private.
        .place_enter => {
            if (places.g_place) |m| {
                if (places.g_places_len < places.g_places.len and placeIndexOf(m.author, m.ident()) == null) {
                    places.g_places[places.g_places_len] = m;
                    places.g_places_len += 1;
                    places.g_place_kept = true;
                    places.g_place_last = places.g_places_len - 1;
                    // In the list now, so it is no longer the visit the rail
                    // holds a seat for.
                    places.g_visited = null;
                    savePlaces();
                    // Entering is the moment the rail has something to show,
                    // so it shows it: the place the reader just kept, now with
                    // a seat of its own. It is off until then, because a column
                    // that can only say it is empty is worse than no column.
                    showPlacesRail();
                    saveSettings();
                }
            }
        },
        // Leave: out of the list, and out of the place. The link still works.
        .place_leave => {
            if (places.g_place) |m| {
                if (placeIndexOf(m.author, m.ident())) |i| {
                    for (i..places.g_places_len - 1) |j| places.g_places[j] = places.g_places[j + 1];
                    places.g_places_len -= 1;
                    savePlaces();
                }
            }
            places.g_place = null;
            places.g_place_feed = 0;
            places.g_place_kept = false;
            places.g_place_info = .closed;
            // The visiting seat is deliberately NOT cleared here, and it took a
            // probe to see why: entering already clears it, and the seat only
            // ever holds a place that is not in the list, so a place being left
            // cannot be the one sitting in it. A second clear for a case that
            // cannot happen is a line no test can ever fail on.
            clearPlaceFeed();
            feed_state.g_feed_rebuild_all.store(true, .release);
            saveSettings();
        },
        .toggle_places_rail => togglePlacesRail(),
        .open_place_info => places.g_place_info = .open,
        .close_place_info => places.g_place_info = .closed,
        .toggle_bookmark => |note_id| {
            const note = model.noteById(note_id) orelse return;
            const adding = !isBookmarked(note.event_id);
            if (adding and askFreshFirst(model, .{ .action = .bookmark, .note_id = note_id })) return;
            sayBookmarkWrite(model, writeBookmark(fx, note.event_id, adding), adding);
        },
        .bookmark_privately => |note_id| {
            const note = model.noteById(note_id) orelse return;
            if (askFreshFirst(model, .{ .action = .bookmark_privately, .note_id = note_id })) return;
            // A seal is a round trip, so nothing is said until it lands: the
            // toast comes from `finishPrivateBookmark`, or from the refusal.
            switch (writePrivateBookmark(fx, note.event_id, true)) {
                .published => {},
                else => |outcome| sayBookmarkWrite(model, outcome, true),
            }
        },
        .open_bookmarks => openBookmarks(model),
        .delete_note_request => |id| model.deleting_note = id,
        .delete_note_cancel => model.deleting_note = null,
        .fresh_list_cancel => model.fresh_ask = null,
        .fresh_list_confirm => {
            const ask = model.fresh_ask orelse return;
            model.fresh_ask = null;
            // Said before anything is written: the question was put while every
            // relay had finished, and the yes is only taken if that still holds,
            // and only for the account it was asked about.
            const still_me = if (activePubkey()) |me| std.mem.eql(u8, &me, &ask.of) else false;
            // The list turned up while the question was open: the write below
            // splices onto it like any other, and no yes is recorded, so nothing
            // is left armed to start one from nothing later.
            const arrived = still_me and listHeld(ask.kind());
            if (!still_me or (!arrived and !confirmStartFresh(ask.kind()))) {
                setToast(model, "Your relays changed meanwhile. Nothing changed.");
                return;
            }
            switch (ask.action) {
                .follow => sayFollowWrite(model, writeFollow(fx, ask.who, true), true),
                .mute => sayMuteWrite(model, writeMute(fx, ask.who, true), true),
                .bookmark => {
                    const note = model.noteById(ask.note_id) orelse return;
                    sayBookmarkWrite(model, writeBookmark(fx, note.event_id, true), true);
                },
                .bookmark_privately => {
                    const note = model.noteById(ask.note_id) orelse return;
                    switch (writePrivateBookmark(fx, note.event_id, true)) {
                        .published => {},
                        else => |outcome| sayBookmarkWrite(model, outcome, true),
                    }
                },
                .add_media_server => sayBlossomAdd(model, writeBlossomServers(fx, ask.server(), null)),
            }
        },
        .delete_note_confirm => {
            const id = model.deleting_note;
            model.deleting_note = null;
            if (id) |note_id| deleteNote(model, fx, note_id);
        },
        .place_leave_request => places.g_place_info = .leaving,
        .place_leave_cancel => places.g_place_info = .open,
        .place_resume => resumeVisit(),
        // No `showPlacesRail` here: the press came FROM the rail, so it is
        // already out, and forcing it would undo a fold the reader just did.
        .place_open => |i| openKeptPlace(i),
        .place_bounce => bouncePlace(),
        .place_step => |delta| stepPlace(delta),
        .close_join => {
            if (bunkerConnecting()) abandonRemoteSigner(.none);
            model.joining = false;
            model.bunker_mode = false;
            // Dismissing the sheet is an answer: they chose not to sign in, so
            // the verb they reached for is dropped rather than lying in wait to
            // fire at some later sign-in they made for another reason.
            model.pending = .none;
        },
        .join_create => {
            model.joining = false;
            // `g_identity_minted_here` is NOT set here. It says the key provably
            // has no history, which is what lets a contact list be published
            // without reading one back first, and at this point there is no key
            // at all: the ceremony can still fail, and the reader can still go
            // and import an account with eight hundred follows instead. It is set
            // when a mint is CONFIRMED, in handleNotaryExited and in
            // handleHelperSetup's create branch.
            beginCreate(model, fx);
        },
        .open_notary_import => {
            // Key material never enters Plaza: the Notary window takes the
            // paste and hands it to the daemon; Plaza signs in when the key
            // appears (handleHelperPubkey). If the window binary is missing,
            // fall back to the in-Plaza field rather than a dead button.
            model.joining = false;
            // Whatever a previous press left behind, this is not a mint. Both
            // flags are the reader's answer to "where does this key come from",
            // and they just answered differently.
            g_ceremony = .none;
            g_ceremony_adopted = false;
            g_identity_minted_here = false;
            // And a sign-out earlier in this run latched adopt-on-appear off.
            //
            // The ceremony happens in the other process and exits 0 for an
            // import, so `handleNotaryExited` classifies it as "not a mint" and
            // signs nobody in: the health check is the ONLY thing that carries
            // the result back. A latch left over swallows the whole import. The
            // key lands in the daemon, the poll refuses it once a second, and the
            // reader sits in guest mode until they quit and reopen.
            //
            // `beginCreate` drops it for the create ceremony with a comment
            // saying it has to do by hand what `queueHelperSetup` would have
            // done. This is the third spawn site and it never got that line, so
            // "Create your identity" after a sign-out worked and "Bring your key"
            // was dead, which is what made it look intermittent: the latch is
            // false at launch, so it only bites on a run where something signed
            // out first. The pubkey latch below it is what still keeps the key
            // that just LEFT from walking back in.
            g_logged_out = false;
            // No fallback to a Plaza field. There is no field in this app that
            // can take a key, so dropping to one would be offering a screen
            // that refuses whatever is typed into it.
            if (!ceremonyCanTakeKey()) setToast(model, "Notary is missing from this install.") else if (!spawnNotaryWindow(fx, .import_key)) setToast(model, "Your keyholder is starting. Try again shortly.");
        },
        .keep_browsing => {
            model.stage = .ready;
            model.pending = .none;
        },
        .open_bunker => {
            model.bunker_mode = true;
            g_ceremony = .none;
            g_ceremony_adopted = false;
            g_identity_minted_here = false;
        },
        .close_bunker => {
            if (bunkerConnecting()) abandonRemoteSigner(.none);
            model.bunker_mode = false;
            model.login_buffer.clear();
            login.g_login_error.store(@intFromEnum(LoginError.none), .release);
        },
        .open_address => {
            // Cmd+L with the field already up leaves it as it is: what is typed
            // in it and what that found. Starting over would empty the list
            // under a term that is still there, and never ask the relays for it.
            if (!model.address_open) {
                model.address_error = .none;
                searchOpen();
            }
            model.address_open = true;
            // The row that opens this lives in the account menu, and a menu
            // left standing under a sheet is a menu the reader has to dismiss
            // twice.
            model.menu = .none;
        },
        .close_address => closeAddress(model),
        .address_edit => |edit| {
            model.address_buffer.apply(edit);
            // Typing IS the answer to the refusal, so the refusal goes now
            // rather than on the next submit. A red line under a field the
            // reader is already fixing is describing a string that is gone.
            model.address_error = .none;
            searchOnEdit(model);
        },
        .address_submit => submitAddress(model, fx),
        .search_pick => |pubkey| searchPick(model, pubkey),
        .nip05_found => |response| handleNip05Found(model, response),
        .dismiss_guest_strip => model.guest_strip_dismissed = true,
        // A trigger toggles its own menu and replaces any other, so the chrome
        // never shows two floating surfaces at once.
        .toggle_menu => |which| model.menu = if (model.menu == which) .none else which,
        // Reading a different feed of the SAME place. Nothing is re-fetched and
        // the place does not change: only the socket moves, and the room's list
        // is rebuilt because the notes in it are about to mean something else.
        .place_feed => |i| {
            model.menu = .none;
            const m = places.g_place orelse return;
            if (i >= m.feeds_len or i == places.g_place_feed) return;
            places.g_place_feed = i;
            startPlaceFeed(&places.g_place.?);
            feed_state.g_feed_rebuild_all.store(true, .release);
        },
        .close_menu => model.menu = .none,
        .toggle_relays_paused => {
            model.relays_paused = !model.relays_paused;
            setRelaysPaused(model.relays_paused);
            model.menu = .none;
        },
        // The feed's own list holds the scroll, and there is no API to set an
        // offset, so "newest" is the reconcile that puts the newest note back at
        // the top: the same thing the tick does, asked for on purpose.
        // There is no API to set a list's scroll offset, so this cannot scroll
        // the feed. What it CAN do is make sure nothing is stale before the
        // reader looks: force the next tick to rebuild from the store.
        .show_more_replies => model.thread_page[model.currentLevel()] += 1,
        .toggle_outside_replies => {
            const level = model.currentLevel();
            model.thread_outside_open[level] = !model.thread_outside_open[level];
        },
        .jump_to_newest => {
            invalidateFeed();
            model.menu = .none;
            // The press rebuilds the feed from what the store holds, which is
            // instant and changes nothing a reader can see when they are already
            // caught up. Without a word that reads as a button that did nothing.
            setToast(model, "Feed refreshed");
        },
        .copy_nevent => |id| {
            const note = model.noteById(id) orelse return;
            var addr_buf: [note_address_cap]u8 = undefined;
            const addr = noteAddress(&addr_buf, note, hint_cap) orelse return;
            writeClipboardText(fx, copy_nevent_key, addr);
            setToast(model, "Address copied");
        },
        // njump renders any nostr event as a web page, which is how a note is
        // shared with someone who is not on nostr yet.
        .place_logo_fetched => |response| handlePlaceLogoFetched(fx, response),
        .open_place_handler => |id| {
            const note = model.noteById(id) orelse return;
            const place = activePlace() orelse return;
            const h = place.handlerFor(1) orelse return;
            // The pattern was checked at parse time and carries exactly one
            // `{e}`. What goes in its place is written here as hex from the id
            // this app already holds, so nothing a stranger typed reaches the
            // address.
            var id_hex: [64]u8 = undefined;
            hexLower(&id_hex, note.event_id);
            const pattern = h.pattern();
            const at = std.mem.indexOf(u8, pattern, "{e}") orelse return;
            var url_buf: [place_handler_url_cap + 64]u8 = undefined;
            const url = std.fmt.bufPrint(&url_buf, "{s}{s}{s}", .{
                pattern[0..at],
                &id_hex,
                pattern[at + 3 ..],
            }) catch return;
            openExternally(fx, url);
        },
        .open_web => |id| {
            const note = model.noteById(id) orelse return;
            var addr_buf: [note_address_cap]u8 = undefined;
            const addr = noteAddress(&addr_buf, note, hint_cap) orelse return;
            // The base is validated at parse time (`isSafeShareUrl`) and the
            // menu row already named the host, so by here the only question
            // left is whether it ends in the separator.
            const base = shareBase();
            var url_buf: [512]u8 = undefined;
            const url = if (std.mem.endsWith(u8, base, "/"))
                std.fmt.bufPrint(&url_buf, "{s}{s}", .{ base, addr }) catch return
            else
                std.fmt.bufPrint(&url_buf, "{s}/{s}", .{ base, addr }) catch return;
            openExternally(fx, url);
        },
        // Quoting is composing with the note already referenced. The composer
        // opens holding a `nostr:nevent…`, which `contentTags` turns into the
        // `q` tag at publish, so the reference in the text and the tag on the
        // event can never disagree: they are derived from the same bytes.
        .quote_note => |id| {
            if (model.is_guest()) {
                model.joining = true;
                model.pending = .post;
                return;
            }
            const note = model.noteById(id) orelse return;
            // One relay, not two: this address is typed into the draft and
            // stays there as text, and the `q` tag derived from it carries one.
            var addr_buf: [note_address_cap]u8 = undefined;
            const addr = noteAddress(&addr_buf, note, 1) orelse return;
            // Appended, not overwritten. Something half-written in the composer
            // is the reader's, and a quote arriving on top of it would be this
            // app deciding their draft was worth less than its own convenience.
            const existing = model.draft_buffer.text();
            var line: [compose_capacity]u8 = undefined;
            const sep: []const u8 = if (existing.len == 0) "" else "\n\n";
            const text = std.fmt.bufPrint(&line, "{s}{s}nostr:{s}", .{ existing, sep, addr }) catch return;
            model.draft_buffer.set(text);
            model.viewing_thread = 0;
            model.composing = true;
        },
        // Switching somebody off, or back on. Keyed on the pubkey rather than a
        // position, because the list is re-derived from the text every frame
        // and an index would point at somebody else the moment the draft is
        // edited above it.
        .toggle_mention_off => |pubkey| {
            for (model.mentions_off[0..model.mentions_off_len], 0..) |off, i| {
                if (!std.mem.eql(u8, &off, &pubkey)) continue;
                model.mentions_off[i] = model.mentions_off[model.mentions_off_len - 1];
                model.mentions_off_len -= 1;
                return;
            }
            if (model.mentions_off_len < model.mentions_off.len) {
                model.mentions_off[model.mentions_off_len] = pubkey;
                model.mentions_off_len += 1;
            }
        },
        .close_mentions => model.mention_dismissed = true,
        .copy_note_text => |id| {
            // The words as the note wrote them, not as the feed renders them:
            // a paste that came back with `@name` where the author typed a
            // `nostr:` reference is not the note, it is a screenshot of one.
            const note = model.noteById(id) orelse return;
            fx.writeClipboard(.{ .key = copy_note_text_key, .text = note.content() });
            setToast(model, "Copied");
        },
        .name_edit => |edit| model.name_buffer.apply(edit),
        .name_save => {
            model.naming = false;
            // Nothing typed means nothing to publish. Writing an empty kind:0
            // would replace whatever profile the key already has with a blank
            // one, which is the replaceable-event footgun in miniature.
            if (model.name_empty()) {
                replayPending(model);
                return;
            }
            publishName(model, fx);
            setToast(model, "Name set");
            replayPending(model);
        },
        .name_skip => {
            model.naming = false;
            // Skipping is a decision not to publish this name, so the text goes
            // with it. Kept, it came back in the sheet the next time the beat
            // armed, on a DIFFERENT key, where Enter alone would publish it: the
            // Done button is deliberately never disabled.
            model.name_buffer.clear();
            replayPending(model);
        },
        .backup_now => {
            model.backup_nudge = false;
            model.backup_nudge_dismissed = true;
            enterSettings(model);
        },
        .backup_later => {
            model.backup_nudge = false;
            model.backup_nudge_dismissed = true;
        },
        .create_identity => beginCreate(model, fx),
        .login_edit => |edit| model.login_buffer.apply(edit),
        .login_submit => {
            login.g_login_error.store(@intFromEnum(LoginError.none), .release);
            const raw = std.mem.trim(u8, model.login_buffer.text(), " \t\r\n");
            switch (classifyLogin(raw)) {
                // A secret key, pasted into a client. Plaza does not take it,
                // and does not take it INTO MEMORY either: the text stays in
                // the field the reader typed it in, and the reader is sent to
                // the app that holds keys.
                //
                // Refusing rather than accepting is the whole shape of this
                // change. A client that accepts an nsec is a client holding the
                // one thing that cannot be replaced if it leaks, and every
                // other app on the machine can read what this one writes down.
                .nsec => {
                    login.g_login_error.store(@intFromEnum(LoginError.key_goes_to_notary), .release);
                    if (!spawnNotaryWindow(fx, .import_key)) setToast(model, "Your keyholder is starting. Try again shortly.");
                },
                // Pair with the external signer from the bunker URL; on success
                // the feed comes up and posts route through it. A bad URL keeps
                // us on onboarding with an error (see `login_status`).
                .bunker => {
                    // One connection at a time: a second press would replace the
                    // pairing the first is still waiting on.
                    if (bunkerConnecting()) return;
                    // Not signed in yet. The sheet stays up saying "Connecting
                    // to your signer…" and `driveBunkerConnect` finishes the
                    // sign-in on the signer's answer, or reports why not.
                    _ = connectRemoteSigner(raw);
                },
                .invalid => login.g_login_error.store(@intFromEnum(LoginError.format), .release),
            }
        },
        .open_settings => enterSettings(model),
        .proxy_edit => |edit| {
            model.proxy_buffer.apply(edit);
            model.proxy_saved = false;
            model.proxy_invalid = false;
        },
        .proxy_save => {
            const typed = std.mem.trim(u8, model.proxy_buffer.text(), " \t\r\n");
            // Empty is a choice (load originals); anything else has to be an
            // address. Kept in the field so it can be fixed rather than retyped.
            if (typed.len != 0 and !isMediaProxyUrl(typed)) {
                model.proxy_invalid = true;
                model.proxy_saved = false;
                return;
            }
            model.proxy_invalid = false;
            setMediaProxy(typed);
            saveSettings();
            model.proxy_saved = true;
            // Retry anything that failed to load under the previous setting.
            retryFailedImages();
        },
        .client_tag_toggle => {
            setClientTag(!clientTag());
            saveSettings();
        },
        .post_delay_cycle => {
            // Off, five, ten, and round. A cycle rather than a field: there are
            // only a few useful answers and none of them is worth a keyboard.
            g_post_delay_s = switch (g_post_delay_s) {
                0 => 5,
                5 => 10,
                else => 0,
            };
            // Turning it off must not strand a note that is already waiting on
            // a clock nothing will read again.
            if (g_post_delay_s == 0) g_post_due_s = 0;
            saveSettings();
        },
        .proxy_toggle => {
            setMediaProxyOn(!mediaProxyOn());
            saveSettings();
            // Every picture's URL is built from this, so what is on screen was
            // fetched under the old answer. Retrying the ones that failed is the
            // point of the switch: turning the proxy off is how somebody fixes a
            // blank picture, and it would be a strange switch that left it blank.
            retryFailedImages();
        },
        .direct_fallback_toggle => {
            setMediaDirectFallback(!mediaDirectFallback());
            saveSettings();
            if (mediaDirectFallback()) retryFailedImages();
        },
        .hide_toggle => |i| {
            if (i < hideables.len) {
                setHidden(@enumFromInt(i), !hiding.g_hidden[i]);
                saveSettings();
            }
        },
        .previews_toggle => {
            setMediaPreviews(!mediaPreviews());
            saveSettings();
            // Turning it back on should fill the feed in without a restart.
            if (mediaPreviews()) {
                retryFailedImages();
                scanAvatarFetches(fx);
                scanMediaFetches(fx, model);
                warmAhead(fx, model);
                scanLinkFetches(fx, model);
            }
        },
        .sensitive_toggle => {
            setShowSensitive(!showSensitive());
            saveSettings();
            // Turning the warnings off uncovers every pending picture at once,
            // so fill the feed in without waiting for the next tick.
            if (showSensitive()) {
                scanMediaFetches(fx, model);
                scanLinkFetches(fx, model);
            }
        },
        .uncover_note => |key| {
            uncoverNote(key);
            // The pictures and the link card were held back, not just hidden:
            // ask for them now rather than on the next tick.
            scanMediaFetches(fx, model);
            scanLinkFetches(fx, model);
        },
        .warn_toggle => {
            model.warn_on = !model.warn_on;
            if (!model.warn_on) model.warn_buffer.clear();
            g_draft_dirty = true;
        },
        .warn_edit => |edit| {
            model.warn_buffer.apply(edit);
            g_draft_dirty = true;
        },
        .media_fetched => |response| handleMediaFetched(fx, response),
        .nip05_verified => |response| handleNip05Fetched(response),
        .link_fetched => |response| handleLinkFetched(response),
        .update_checked => |response| handleUpdateChecked(response),
        .open_update => {
            // The release page: the notes and the downloads are both on it, so
            // "what is in it" and "where do I get it" are one press.
            const url = pendingUpdateUrl();
            if (url.len == 0) return;
            openExternally(fx, url);
            // Put away on the press. Somebody who has gone to look does not
            // need the line still there when they come back.
            updates.g_update_dismissed = true;
        },
        .dismiss_update => updates.g_update_dismissed = true,
        .update_check_toggle => {
            setUpdateCheck(!updateCheckOn());
            saveSettings();
        },
        // A paragraph carries one link handler, so a mention arrives here beside
        // the ordinary links. Its payload is not a URL and never reaches the
        // browser; see `mention_link_tag`.
        .open_url => |url| {
            // Checked before the mention form and before the browser: all three
            // ride one message, and only the sentinel tells them apart.
            if (topicLinkValue(url)) |topic| {
                openTopic(model, topic);
            } else if (mentionLinkPubkey(url)) |pubkey| openPerson(model, pubkey) else openExternally(fx, url);
        },
        .expand_image => |note_id| {
            model.expanded_note = note_id;
            model.expanded_image = 0;
        },
        .expand_image_at => |what| {
            model.expanded_note = what.note;
            model.expanded_image = what.index;
        },
        .load_image => |note_id| {
            askForMedia(note_id);
            scanMediaFetches(fx, model);
        },
        .close_image => model.expanded_note = null,
        .open_notary_window => if (!spawnNotaryWindow(fx, .status)) setToast(model, "Your keyholder is starting. Try again shortly."),
        // Deliberately empty: see `Msg.absorb_press`. The press has already done
        // its work by the time it arrives here, which was to stop somewhere.
        .absorb_press => {},
        .like => |note_id| toggleLike(model, fx, note_id),
        .repost => |note_id| repost(model, fx, note_id),
        .open_thread => |note_id| openThread(model, note_id),
        .open_event => |id| {
            // The sheet closes on the PRESS, before the navigation is attempted,
            // never on arrival. Every route out of here has an early return in
            // front of it (a store miss for a note nobody fetched, an identity
            // check for a person already on screen), and each one returns BEFORE
            // anything that could close the sheet. Closing on arrival therefore
            // left it up in exactly the cases where the reader has least idea why
            // nothing moved.
            leaveNotifications(model);
            openEvent(model, id);
        },
        // A held reply belongs to the thread being left. Leaving it armed would
        // publish it into a conversation the reader had walked away from,
        // seconds later; `parkReplyDraft` stops it and keeps the text.
        .close_thread => closeThread(model),
        .go_home => goHome(model),
        .reply_edit => |edit| _ = applyPlainEdit(compose_capacity, &model.reply_buffer, edit),
        .reply_submit => {
            // The one verb that was gated nowhere: a guest could type a reply and
            // press send, and `publishReply` would reach for a signer that does
            // not exist and return, losing nothing but doing nothing and saying
            // nothing either.
            if (model.is_guest()) {
                if (model.viewing_thread != 0) model.pending = .{ .reply = model.viewing_thread };
                model.joining = true;
                return;
            }
            // The same pause a note gets, for the same reason: a reply is exactly
            // as final, and the setting says notes without meaning only notes.
            if (g_reply_due_s != 0) {
                g_reply_due_s = 0;
                setToast(model, "Kept here.");
                return;
            }
            if (g_post_delay_s > 0) {
                g_held_route = routeForOpenPlace();
                g_reply_due_s = nowSeconds() + g_post_delay_s;
                return;
            }
            fireReply(model, fx, null);
        },
        .toggle_expand => |note_id| toggleExpanded(note_id),
        .settings_scrolled => |scroll| model.settings_scroll_y = scroll.offset_y,
        .feed_scrolled => |scroll| {
            model.feed_scroll = scroll;
            // Load what just came into view without waiting for the next tick:
            // hand avatar ids to the newly-visible authors, then their faces and
            // pictures.
            wantProfilesAhead(model);
            assignAvatarSlots(fx, model);
            scanAvatarFetches(fx);
            scanMediaFetches(fx, model);
            // The band beyond the new viewport, which is the whole point of
            // running this on a scroll rather than only on the tick.
            warmAhead(fx, model);
            scanLinkFetches(fx, model);
        },
        .load_older => {
            // One more page from the store, up to what the feed can hold.
            // No ceiling to stop at. The store answers with what it has, and
            // `notes_len` lands wherever that is; asking for more than exists
            // simply returns the same feed and the reader has reached the end
            // of what this app has been told about.
            const held = model.notes_len;
            model.feed_limit += feed_page;
            invalidateFeed();
            model.refresh(nowSeconds());
            // The store had no more to give, so ask the relays for what came
            // before the oldest note in hand. Store first, network second.
            if (model.notes_len == held and model.notes_len > 0 and !feedEndReached()) {
                fetchOlderNotes(model.notes[model.notes_len - 1].created_at - 1);
            }
        },
        .profile_older => loadOlderProfile(model),
        .close_settings => leaveSettings(model),
        // The bare npub stays an npub. It is the account's identifier and the
        // form every tool that takes a key accepts, so it carries no relays; the
        // form that does is `copy_nprofile`, from the account menu.
        .copy_npub => {
            const pk = activePubkey() orelse return;
            var scratch: [1024]u8 = undefined;
            var fba = std.heap.FixedBufferAllocator.init(&scratch);
            const npub = nostr.nip19.encodeNpub(fba.allocator(), pk) catch return;
            writeClipboardText(fx, copy_npub_key, npub);
            setToast(model, "npub copied");
        },
        .copy_nprofile => {
            const pk = activePubkey() orelse return;
            var addr_buf: [note_address_cap]u8 = undefined;
            const addr = profileAddress(&addr_buf, pk) orelse return;
            writeClipboardText(fx, copy_nprofile_key, addr);
            model.menu = .none;
            setToast(model, "Profile address copied");
        },
        .logout_request => {
            model.logout_pending = true;
            // The question is taller than the button it replaces and sits at the
            // very foot of the page, so it opens below the window's edge. The
            // scroll view clamps this to the end of the content.
            model.settings_scroll_y = settings_scroll_end;
        },
        .logout_cancel => model.logout_pending = false,
        .logout_confirm => performLogout(model, fx),
    }
}

/// Shows a small confirming toast for a few seconds (the tick retires it).
/// Says what a follow press did, when it did not do the obvious thing.
///
/// Silent on success, because the button moving IS the answer and a toast on
/// every press would be noise. Not silent on a refusal: `writeFollow` has four
/// of those, all reachable, and the reader used to get a button that stayed
/// where it was and no reason at all. The most ordinary one is pressing Follow
/// in the first seconds after opening the app, before this account's own list
/// has come back from the relays.
/// Closes the notifications sheet on the way into a level, and remembers whether
/// the sheet is where that level's Back should land.
///
/// Only from the feed. Once a level is open, Back returns to it before anything
/// else, and the flag already says how the reader reached the bottom of the
/// stack: a thread opened from the sheet, then its author, then Back, is that
/// thread again, and Back from there is the sheet. Rewriting the flag on the
/// way to the author used to turn that last Back into the feed.
fn leaveNotifications(model: *Model) void {
    if (!model.levelOpen()) model.notifications_return = model.notifications_open;
    model.notifications_open = false;
}

/// Open somebody's profile, remembering whether the notifications sheet was what
/// we came from so closing it returns there rather than to the feed.
fn openPerson(model: *Model, pubkey: [32]u8) void {
    leaveNotifications(model);
    enterProfile(model, pubkey);
}

fn sayFollowWrite(model: *Model, outcome: FollowWrite, following: bool) void {
    switch (outcome) {
        .published => if (following) setToast(model, "Following"),
        // Nothing changed because nothing needed to. Saying so would be noise.
        .nothing_to_do => {},
        .signer_busy => setToast(model, "Your signer is busy. Try that again in a moment."),
        .no_list_yet => setToast(model, noListToast("follow list")),
        // The guard fired, which means the list this app was about to publish
        // was not the list it meant to. Saying "try again" would be wrong: the
        // right move is to leave it alone until the real list is back.
        .would_shrink => setToast(model, "That would change several names. Nothing sent."),
        .failed => setToast(model, "That did not save, and nothing was published."),
    }
}

/// What a bookmark write did, in the reader's terms.
fn sayBookmarkWrite(model: *Model, outcome: BookmarkWrite, adding: bool) void {
    switch (outcome) {
        .published => setToast(model, if (adding) "Bookmarked" else "Bookmark removed"),
        .nothing_to_do => {},
        .signer_busy => setToast(model, "Your signer is busy. Try that again in a moment."),
        .no_list_yet => setToast(model, noListToast("bookmarks")),
        // Waiting is a delay and says so. Declined has already asked again on
        // this press, so it says where to approve it. Unreadable is a limit, so
        // it does not say "try again": the right move is to leave the list
        // alone, because writing without the half would erase every private
        // bookmark in it. All three stay inside the toast's 48 bytes, so none
        // is cut.
        .private_half_waiting => setToast(model, "Opening your private bookmarks. Try again soon."),
        .private_half_declined => setToast(model, "Signer declined. Asked again, approve it there."),
        .private_half_unreadable => setToast(model, "Cannot open private bookmarks. Nothing was sent."),
        .failed => setToast(model, "That did not save, and nothing was published."),
    }
}

/// What a mute write did, in the reader's terms.
fn sayMuteWrite(model: *Model, outcome: MuteWrite, muting: bool) void {
    switch (outcome) {
        .published => setToast(model, if (muting) "Muted" else "Unmuted"),
        .nothing_to_do => {},
        .signer_busy => setToast(model, "Your signer is busy. Try that again in a moment."),
        .no_list_yet => setToast(model, noListToast("mute list")),
        // Waiting is a delay and says so. Declined has already asked again on
        // this press, so it says where to approve it. Unreadable is the one
        // message about a limit rather than a delay, so it does not say "try again":
        // trying again will do the same thing. The reader's private mutes are
        // safe precisely because nothing was published. All three stay inside
        // the toast's 48 bytes, so none is cut.
        .private_half_waiting => setToast(model, "Opening your private mutes. Try again shortly."),
        .private_half_declined => setToast(model, "Signer declined. Asked again, approve it there."),
        .private_half_unreadable => setToast(model, "Cannot read your private mutes. Nothing changed."),
        .would_shrink => setToast(model, "That would change several names. Nothing sent."),
        .failed => setToast(model, "That did not save, and nothing was published."),
    }
}

pub fn sayMuteWriteForTest(model: *Model, outcome: MuteWrite, muting: bool) void {
    sayMuteWrite(model, outcome, muting);
}

pub fn sayBookmarkWriteForTest(model: *Model, outcome: BookmarkWrite, adding: bool) void {
    sayBookmarkWrite(model, outcome, adding);
}

/// Puts `text` on the clipboard. A test build records it instead, because the
/// effect queue behind `fx` does not exist there and the text is the thing worth
/// checking: what Plaza hands another client.
fn writeClipboardText(fx: *Effects, key: u64, text: []const u8) void {
    if (builtin.is_test) {
        g_last_clipboard_len = copyBounded(&g_last_clipboard, text);
        return;
    }
    fx.writeClipboard(.{ .key = key, .text = text });
}
var g_last_clipboard: [note_address_cap]u8 = undefined;
var g_last_clipboard_len: usize = 0;
pub fn lastClipboardForTest() []const u8 {
    return g_last_clipboard[0..g_last_clipboard_len];
}

/// Holds a write that would start a list from nothing and puts the question to
/// the reader. Returns whether it did, so the caller stops there.
fn askFreshFirst(model: *Model, ask: FreshAsk) bool {
    const me = activePubkey() orelse return false;
    if (!needsFreshConsent(ask.kind())) return false;
    var held = ask;
    held.of = me;
    model.fresh_ask = held;
    return true;
}

/// What a refused list write says, by how far the read of that list got. The
/// refusal is the same every time (nothing was changed); what the reader can do
/// about it is not.
fn noListToast(comptime what: []const u8) []const u8 {
    return noListToastIn(what, ownListsRead());
}

fn noListToastIn(comptime what: []const u8, read: OwnListsRead) []const u8 {
    return switch (read) {
        .reading => "Still reading your " ++ what ++ ". Try again soon.",
        .incomplete => "Can't read your " ++ what ++ ". Nothing changed.",
        .none_found => "No " ++ what ++ " on your relays. Nothing changed.",
    };
}

/// Every sentence `noListToast` can say, for the test that checks each fits.
pub fn noListToastsForTest() [9][]const u8 {
    var out: [9][]const u8 = undefined;
    var n: usize = 0;
    inline for (.{ "follow list", "mute list", "bookmarks" }) |what| {
        for ([_]OwnListsRead{ .reading, .incomplete, .none_found }) |read| {
            out[n] = noListToastIn(what, read);
            n += 1;
        }
    }
    return out;
}

pub const place_looking_toast_for_test = place_looking_toast;

pub fn setToast(model: *Model, text: []const u8) void {
    const n = @min(text.len, model.toast_buf.len);
    @memcpy(model.toast_buf[0..n], text[0..n]);
    model.toast_len = n;
    model.toast_until = nowSeconds() + 3;
}

/// Puts Settings away. Shared by its own Close and by anything opened over it
/// that goes somewhere, because the page it goes to is drawn under Settings.
fn leaveSettings(model: *Model) void {
    model.logout_pending = false;
    model.stage = .ready;
}

/// The one door into Settings. Every field on the screen that edits a live
/// setting is seeded here, because an arm that sets `stage = .settings` on its
/// own leaves those fields EMPTY, and an empty field over a Save button is an
/// invitation to erase the setting it was supposed to show. The backup nudge did
/// exactly that to the media proxy.
fn enterSettings(model: *Model) void {
    model.menu = .none;
    // One sheet at a time: Settings is a sheet now, and the notifications sheet
    // is checked FIRST in the view, so leaving it open would open Settings into
    // a window that never shows it.
    model.notifications_open = false;
    model.proxy_buffer.set(mediaProxy());
    model.proxy_saved = false;
    model.proxy_invalid = false;
    model.settings_scroll_y = 0;
    model.editing_profile = false;
    // The Edit profile sheet closes here too, and a picture on its way to the
    // avatar or banner has nowhere to land once it has: it would finish
    // uploading into a field the next open clears.
    if (g_upload) |job| {
        if (job.target != .note) dropUpload();
    }
    g_profile_upload_unsaved = false;
    model.blossom_error = .none;
    // Whether this account has a media server list is asked of the relays now,
    // so by the time an edit is made the answer is in.
    startBlossomProbe();
    model.stage = .settings;
}

/// What the Edit profile sheet knows about the profile it is editing.
///
/// The distinction that matters is `fetching` versus `absent`. "The store has no
/// kind:0 for me" means either that this account has never had a profile or that
/// nobody has answered yet, and those two look identical from here. Publishing
/// under the second reading REPLACES a real profile with whatever three fields
/// this app models, which is how somebody's lightning address disappears. So the
/// sheet asks every read relay first, and only calls it `absent` once they have
/// all answered.
/// What is waiting on the reader's answer to "start a new list?".
pub const FreshAsk = struct {
    action: Action,
    /// The account the question was put about. A yes is never spent on another.
    of: [32]u8 = [_]u8{0} ** 32,
    /// The person to follow or mute.
    who: [32]u8 = [_]u8{0} ** 32,
    /// The note to bookmark.
    note_id: i64 = 0,
    /// The media server to add, normalized.
    server_buf: [blossom.max_server_len]u8 = undefined,
    server_len: u8 = 0,

    pub const Action = enum { follow, mute, bookmark, bookmark_privately, add_media_server };

    pub fn kind(self: FreshAsk) ListKind {
        return switch (self.action) {
            .follow => .follows,
            .mute => .mutes,
            .bookmark, .bookmark_privately => .bookmarks,
            .add_media_server => .media_servers,
        };
    }

    fn mediaServer(url: []const u8) FreshAsk {
        var ask = FreshAsk{ .action = .add_media_server };
        ask.server_len = @intCast(copyBounded(&ask.server_buf, url));
        return ask;
    }

    fn server(self: *const FreshAsk) []const u8 {
        return self.server_buf[0..self.server_len];
    }
};

pub const ProfileStage = enum { fetching, absent, unread, have, saving, sent, failed };

/// How long the sheet waits for a relay before saying it could not read the
/// profile. `relay.receive()` has no deadline, so a relay that accepts the
/// subscription and then says nothing would otherwise hold the round open for
/// the rest of the session.
const own_profile_wait_s: i64 = 12;

/// Which key in the profile object the sheet's one Name field stands for. NIP-01
/// has `name` (a handle) and `display_name` (a fuller name), and some clients
/// still write the legacy `displayName`. The sheet edits whichever one the
/// reader's profile actually uses.
pub const ProfileNameKey = enum { display_name, display_name_legacy, name };

/// WHO has been asked about, and whether a relay actually answered.
///
/// Two things a bool got wrong. It survived a sign-out, so the round run for one
/// account decided that the NEXT account had no profile, and Save then published
/// an empty object over a real one. And it was set even when every relay was
/// offline, unreachable or write-only, so "nobody answered" and "they answered,
/// you have no profile" were the same state. Both readings end in a wipe, so the
/// answer records the pubkey it is about and is only set when a relay reached
/// the end of its answer.
var g_own_profile_asked_for: ?[32]u8 = null;
/// And the same for the CONTACT list, where getting it wrong is worse: a write
/// made before hearing back replaces everyone this reader follows with a
/// handful of accounts the app chose for them.
var g_own_contacts_asked_for: ?[32]u8 = null;
var g_own_contacts_answered = std.atomic.Value(bool).init(false);

/// Whether a relay has told THIS account who they follow (including telling us
/// they follow nobody).
pub fn ownContactsAnswered() bool {
    const pk = activePubkey() orelse return false;
    lockOwnProfile();
    defer unlockOwnProfile();
    const asked = g_own_contacts_asked_for orelse return false;
    if (!std.mem.eql(u8, &asked, &pk)) return false;
    return g_own_contacts_answered.load(.acquire);
}

fn noteOwnContactsAnswered(pk: [32]u8) void {
    lockOwnProfile();
    defer unlockOwnProfile();
    g_own_contacts_asked_for = pk;
    g_own_contacts_answered.store(true, .release);
}

pub fn noteOwnContactsAnsweredForTest(pk: [32]u8) void {
    noteOwnContactsAnswered(pk);
}

// There was a `g_own_relays_answered` here, set by the first EOSE from any relay
// and read as permission to publish a kind:10002. It is GONE rather than merely
// unused: an inference that wrong, left sitting in the file under a reassuring
// name, is one grep away from becoming a gate again. `canWriteRelayList` is the
// rule now, and the reason is written there.

/// Forgets every conclusion about this account's own records. Called on any
/// identity change, so nothing decided about one account is read as a fact about
/// the next.
fn forgetOwnRecordAnswers() void {
    forgetOwnProfileAnswer();
    lockOwnProfile();
    defer unlockOwnProfile();
    g_own_contacts_asked_for = null;
    g_own_contacts_answered.store(false, .release);
    // And WHICH relays answered. Leaving these set would let the next account
    // inherit the previous one's answers and reach the write gate without any
    // relay having said a word about them.
    g_contacts_answered_by = [_]bool{false} ** max_relays;
    g_own_outbox = .{};
    g_own_lists_since_for = null;
    forgetFresh();
}
var g_own_profile_asking = std.atomic.Value(bool).init(false);
/// Set by the worker when at least one relay ANSWERED (EOSE), paired with the
/// pubkey it asked about. Read on the UI thread through `ownProfileAnswered`.
var g_own_profile_answered = std.atomic.Value(bool).init(false);
var g_own_profile_lock = std.atomic.Value(bool).init(false);

fn lockOwnProfile() void {
    while (g_own_profile_lock.cmpxchgWeak(false, true, .acquire, .monotonic) != null) {}
}
fn unlockOwnProfile() void {
    g_own_profile_lock.store(false, .release);
}

/// Whether a relay has answered about THIS account. Anything else, including a
/// round for a previous account and a round where nothing connected, is not an
/// answer about this one.
fn ownProfileAnswered() bool {
    const pk = activePubkey() orelse return false;
    lockOwnProfile();
    defer unlockOwnProfile();
    const asked = g_own_profile_asked_for orelse return false;
    if (!std.mem.eql(u8, &asked, &pk)) return false;
    return g_own_profile_answered.load(.acquire);
}

/// Forgets what was asked. Called whenever the identity changes, so no
/// conclusion about one account is ever read as a fact about another.
fn forgetOwnProfileAnswer() void {
    lockOwnProfile();
    defer unlockOwnProfile();
    g_own_profile_asked_for = null;
    g_own_profile_answered.store(false, .release);
}

/// A profile as it was published: its content AND its tags. NIP-39 puts identity
/// proofs (a GitHub account, a Mastodon handle) in kind:0's TAGS, so republishing
/// with `&.{}` deletes them exactly as silently as dropping a JSON key would.
pub const OwnProfile = struct {
    json: []u8,
    tags: []const nostr.event.Tag,
    created_at: i64,
    /// The event these came from, so a caller can tell an unchanged record from
    /// a new one without re-parsing it.
    id: [32]u8 = [_]u8{0} ** 32,
};

/// The reader's own newest kind:0, raw. The RAW content is the source of truth,
/// never the `Profile` cache: the cache models four fields and drops everything
/// else, so rebuilding from it would publish a profile with the rest deleted.
///
/// The returned slice is owned by the caller's allocator.
fn ownProfileJson(gpa: std.mem.Allocator) ?OwnProfile {
    return ownRecordJson(gpa, 0);
}

/// The reader's own newest event of `kind`, content and tags. The RAW record is
/// the source of truth for every write this app makes over one of its own
/// lists: the caches model a few fields and drop the rest, so rebuilding from
/// one would publish a record with everything else deleted.
pub fn ownRecordJson(gpa: std.mem.Allocator, kind: u16) ?OwnProfile {
    // Counted so a test can assert the SHAPE of the fix rather than its timing:
    // the property is that building a feed does not read this account's whole
    // contact list once per card, and a stopwatch on a CI runner is a poor way
    // to say that. Comptime, so the shipped binary has no counter.
    if (builtin.is_test) store_glue.g_own_record_reads += 1;
    const store = g_store orelse return null;
    const pk = activePubkey() orelse return null;
    const kinds = [_]u16{kind};
    const authors = [_][32]u8{pk};
    var result = store.query(gpa, .{ .authors = &authors, .kinds = &kinds, .limit = 1 }) catch return null;
    defer result.deinit();
    if (result.events.len == 0) return null;
    // Copied out before `result.deinit()`: the query owns its events through an
    // arena, and the write seam holds what it is given past this frame.
    const copy = gpa.dupe(u8, result.events[0].content) catch return null;
    // Whole or not at all. A partial base is what turns a splice into a delete.
    const tags = dupeTags(gpa, result.events[0].tags) orelse return null;
    return .{ .json = copy, .tags = tags, .created_at = result.events[0].created_at, .id = result.events[0].id };
}

/// This account's newest stored event of `kind`, its tags flattened to one
/// string. For tests that need to see what a publish actually WROTE rather than
/// whether it returned true: a splice that quietly drops half the list still
/// publishes, so the return value proves nothing about what went out.
/// This account's newest stored event of `kind`, its CONTENT. For the one
/// property that tags cannot show: that an encrypted half nobody here reads was
/// carried through a write rather than replaced with nothing.
pub fn ownRecordContentForTest(gpa: std.mem.Allocator, kind: u16) ?[]u8 {
    const own = ownRecordJson(gpa, kind) orelse return null;
    defer freeOwnProfile(gpa, own);
    return gpa.dupe(u8, own.json) catch null;
}

pub fn ownRecordTagsJoinedForTest(gpa: std.mem.Allocator, kind: u16) ?[]u8 {
    const own = ownRecordJson(gpa, kind) orelse return null;
    defer freeOwnProfile(gpa, own);
    var out = std.ArrayList(u8).empty;
    for (own.tags) |tag| {
        for (tag) |field| {
            out.appendSlice(gpa, field) catch return null;
            out.append(gpa, ' ') catch return null;
        }
        out.append(gpa, '\n') catch return null;
    }
    return out.toOwnedSlice(gpa) catch null;
}

/// Frees what `ownProfileJson` handed back.
pub fn freeOwnProfile(gpa: std.mem.Allocator, own: OwnProfile) void {
    gpa.free(own.json);
    for (own.tags) |t| {
        for (t) |field| gpa.free(field);
        gpa.free(t);
    }
    gpa.free(own.tags);
}

/// Opens the sheet, seeded from the reader's own kind:0 if the app has it.
fn openProfileEdit(model: *Model) void {
    // A guest has no key, so there is nothing to read and nothing that could
    // sign an edit. The sheet would sit on "Reading your current profile" for
    // the rest of the session.
    if (model.is_guest()) {
        model.joining = true;
        return;
    }
    model.editing_profile = true;
    g_profile_upload_unsaved = false;
    model.profile_confirm_new = false;
    model.profile_name_buffer.clear();
    model.profile_about_buffer.clear();
    model.profile_picture_buffer.clear();
    model.profile_website_buffer.clear();
    model.profile_banner_buffer.clear();
    model.profile_lud16_buffer.clear();
    model.profile_nip05_buffer.clear();
    const gpa = std.heap.page_allocator;
    if (ownProfileJson(gpa)) |own| {
        // The whole record, not just its content: freeing only `json` left every
        // tag it carried behind on each open of the sheet.
        defer freeOwnProfile(gpa, own);
        // The three buffers were cleared two lines up, so there is nothing typed
        // to preserve here.
        seedProfileFields(model, own.json, false);
        model.profile_stage = .have;
        return;
    }
    // Nothing here yet. Ask before concluding anything.
    model.profile_seeded = false;
    model.profile_asked_at = nowSeconds();
    model.profile_stage = if (ownProfileAnswered()) .absent else .fetching;
    if (model.profile_stage == .fetching) startOwnProfileFetch();
}

/// Fills the sheet's fields from the RAW blob, so what the reader sees is what
/// is about to be rewritten.
///
/// A value too long for its field is NOT shown truncated. A bio that runs past
/// the buffer would otherwise appear cut off, and saving without touching it
/// would write the cut-off version back over the real one: silent data loss from
/// merely opening a sheet. Such a field is left empty and marked, and the merge
/// then leaves that key exactly as it was.
fn seedProfileFields(model: *Model, json: []const u8, keep_typed: bool) void {
    var arena_state = std.heap.ArenaAllocator.init(std.heap.page_allocator);
    defer arena_state.deinit();
    const a = arena_state.allocator();
    const root = std.json.parseFromSliceLeaky(std.json.Value, a, json, .{
        // A real profile out there has repeated keys sometimes, and refusing to
        // parse it would refuse to edit it.
        .duplicate_field_behavior = .use_last,
        .allocate = .alloc_always,
    }) catch return;
    if (root != .object) return;
    const obj = root.object;
    // Which key the name came from, so the edit REWRITES that key. Seeding from
    // `name` and writing `display_name` leaves the value the reader edited
    // exactly where it was, and the rename silently does nothing.
    model.profile_name_key = .display_name;
    var name: ?[]const u8 = null;
    if (stringField(obj, "display_name")) |v| {
        name = v;
    } else if (stringField(obj, "displayName")) |v| {
        name = v;
        model.profile_name_key = .display_name_legacy;
    } else if (stringField(obj, "name")) |v| {
        name = v;
        model.profile_name_key = .name;
    }
    // A field the reader has already typed into keeps their text; every other
    // field is filled from the profile that just arrived.
    //
    // It used to be all or nothing, and the tick flipped the stage to `.have`
    // whether or not the seeding ran. So a reader who typed a display name while
    // the fetch was still out got a savable sheet over two fields that had never
    // been seeded and were still empty, and the merge REMOVES a key whose field
    // is empty: pressing Save deleted their bio and their avatar from a profile
    // the app had by then read correctly. Per field, every field is now either
    // known or deliberately typed, which is the same rule the too-long-to-show
    // fields already followed.
    if (!(keep_typed and model.profile_name_buffer.text().len > 0)) {
        model.profile_name_long = seedField(&model.profile_name_buffer, name);
    }
    if (!(keep_typed and model.profile_about_buffer.text().len > 0)) {
        model.profile_about_long = seedField(&model.profile_about_buffer, stringField(obj, "about"));
    }
    if (!(keep_typed and model.profile_picture_buffer.text().len > 0)) {
        model.profile_picture_long = seedField(&model.profile_picture_buffer, stringField(obj, "picture"));
    }
    if (!(keep_typed and model.profile_website_buffer.text().len > 0)) {
        model.profile_website_long = seedField(&model.profile_website_buffer, stringField(obj, "website"));
    }
    if (!(keep_typed and model.profile_banner_buffer.text().len > 0)) {
        model.profile_banner_long = seedField(&model.profile_banner_buffer, stringField(obj, "banner"));
    }
    if (!(keep_typed and model.profile_lud16_buffer.text().len > 0)) {
        model.profile_lud16_long = seedField(&model.profile_lud16_buffer, stringField(obj, "lud16"));
    }
    if (!(keep_typed and model.profile_nip05_buffer.text().len > 0)) {
        model.profile_nip05_long = seedField(&model.profile_nip05_buffer, stringField(obj, "nip05"));
    }
    model.profile_seeded = true;
}

/// Seeds one field. Returns whether the value was too long to hold, in which
/// case the field is left EMPTY rather than truncated: an empty field the merge
/// leaves alone is honest, a truncated one that gets written back is not.
fn seedField(buffer: anytype, value: ?[]const u8) bool {
    const v = value orelse return false;
    if (v.len > buffer.storage.len) {
        buffer.clear();
        return true;
    }
    buffer.set(v);
    return false;
}

fn stringField(obj: std.json.ObjectMap, key: []const u8) ?[]const u8 {
    const v = obj.get(key) orelse return null;
    return switch (v) {
        .string => |str| if (str.len == 0) null else str,
        else => null,
    };
}

/// Publishes the sheet's fields, MERGED into the reader's existing kind:0.
///
/// kind:0 is replaceable: what is published replaces the whole profile. Real
/// profiles carry `about`, `banner`, `website`, `lud16` (the lightning address
/// that is how somebody gets paid), and whatever else their other clients wrote.
/// This app models three of those, so it edits three keys of the object it read
/// and leaves every other key exactly where it was.
fn saveProfile(model: *Model, fx: *Effects) void {
    if (!model.profile_can_save()) return;
    if (activePubkey() == null) return;
    // A profile not found on any relay, for a key that was not made here: the
    // first press shows what a wrong guess costs, and the second is the reader's
    // answer. Nothing is signed or written by the first.
    if (model.profile_stage == .absent) {
        // The profile landed after the sheet said there was none. Its fields were
        // never shown, so merging the sheet into it would remove every one the
        // reader did not happen to type. Show it first; the next Save merges.
        const gpa = std.heap.page_allocator;
        if (ownProfileJson(gpa)) |own| {
            defer freeOwnProfile(gpa, own);
            seedProfileFields(model, own.json, true);
            model.profile_stage = .have;
            model.profile_confirm_new = false;
            return;
        }
    }
    if (model.profile_stage == .absent and !noHistoryKnown(.profile)) {
        if (!model.profile_confirm_new) {
            model.profile_confirm_new = true;
            return;
        }
        model.profile_confirm_new = false;
        if (!confirmStartFresh(.profile)) return;
    }
    // The sheet reports `.sent` as soon as it has handed the merge over, so a
    // rejected sign would show a saved profile that was never signed. Refusing
    // leaves the sheet exactly as it was, with Save still live.
    if (!signerReady()) return;
    const gpa = std.heap.page_allocator;

    var prev_created_at: i64 = 0;
    var prev_tags: []const nostr.event.Tag = &.{};
    var existing: ?OwnProfile = null;
    if (ownProfileJson(gpa)) |own| {
        existing = own;
        prev_created_at = own.created_at;
        prev_tags = own.tags;
    } else if (model.profile_stage != .absent) {
        // It arrived as `have` and is gone now, or the round never finished.
        // Either way there is nothing safe to merge into.
        model.profile_stage = .fetching;
        startOwnProfileFetch();
        return;
    }
    defer if (existing) |e| freeOwnProfile(gpa, e);

    const merged = mergeProfileJson(gpa, if (existing) |e| e.json else "{}", model) orelse {
        model.profile_stage = .failed;
        return;
    };
    // The cache is seeded from a COPY, and BEFORE the write seam takes the
    // original: `signAndPublish` owns what it is handed and the remote path
    // frees it, so reading `merged` afterwards is a use-after-free.
    if (activePubkey()) |pk| {
        if (upsertProfile(pk)) |prof| parseMetadataInto(prof, merged);
        // A cleared picture has to leave the cache too, or the old avatar keeps
        // being drawn from a slot nothing will overwrite.
        if (trimmedField(model.profile_picture()).len == 0) clearProfilePicture(pk);
    }
    // A replaceable event with a stamp that does not beat the one already stored
    // is DROPPED, by this store and by every relay. A second edit inside one
    // second, or a clock that was ahead when the last client wrote, would make
    // the edit vanish while the app claimed success.
    const created = @max(nowSeconds(), prev_created_at + 1);
    // The TAGS come forward too. NIP-39 identity proofs (a GitHub account, a
    // Mastodon handle) live in kind:0's tags, and republishing with none would
    // delete them as silently as dropping a JSON key.
    const tags = dupeTags(gpa, prev_tags) orelse return;
    // The cache was seeded above so the sheet shows the edit at once. If the
    // signature never comes back, that seeding is what has to be contradicted:
    // "Saved here and sent to your relays" is otherwise the last word on an
    // edit that reached nobody.
    signAndPublish(fx, gpa, created, 0, tags, merged, false, .profile, null);
    // NOT "published": nothing here can know that yet. `signAndPublish` returns
    // no verdict, the remote and helper paths have not even signed, and a kind:0
    // that reaches no relay is not retried. What IS true is that the edit is
    // saved here and is on its way out.
    model.profile_stage = .sent;
}

/// Parses `existing`, replaces the three keys this app models, and serialises the
/// whole object back. Key order survives the round trip, so a profile this app
/// did not change comes back byte-similar rather than reshuffled.
/// The object a kind:0 edit merges into, or null when a record that IS there
/// could not be read.
///
/// Falling back to an empty object on a parse failure is the merge failing
/// open, and this object is the base every field is written into. A profile
/// that did not parse would be republished as nothing but the fields the screen
/// happened to hold, so the reader's lightning address, NIP-05, banner and
/// website would be gone from every relay and from every other client. That is
/// the same shape as writing a contact list over one that was never read, and
/// the answer is the same: a record that cannot be read whole reads as "not
/// read", which every caller already handles.
///
/// Not a hypothetical failure, either. Zig's JSON parser is stricter than the
/// ones the rest of the ecosystem uses: it rejects an unpaired surrogate half
/// in a `\u` escape, and it validates raw UTF-8. Profiles that came through
/// bridges, or were written by clients that never checked, carry both, and
/// those readers would be the ones who lost the most.
///
/// Only a caller saying there is nothing there may start from nothing, which is
/// the literal `{}` passed when no record was found.
/// Whether `s` is empty or a plain http(s) URL.
///
/// Scheme only. Anything past that is the host's business, and a checker that
/// refused an unusual but working URL would be worse than one that let a typo
/// through: the reader can see their own picture not loading, and cannot see
/// why this app declined to save it.
fn looksLikeUrl(s: []const u8) bool {
    if (s.len == 0) return true;
    return std.ascii.startsWithIgnoreCase(s, "https://") or std.ascii.startsWithIgnoreCase(s, "http://");
}

/// Whether `s` is empty or looks like `name@domain.tld`.
///
/// One `@`, something on each side, and a dot in the domain. Both a lightning
/// address and a NIP-05 identifier are the same shape, and both are useless to
/// every other client if that shape is wrong.
fn looksLikeAddress(s: []const u8) bool {
    if (s.len == 0) return true;
    const at = std.mem.indexOfScalar(u8, s, '@') orelse return false;
    if (std.mem.lastIndexOfScalar(u8, s, '@').? != at) return false;
    const local = s[0..at];
    const domain = s[at + 1 ..];
    if (local.len == 0 or domain.len == 0) return false;
    const dot = std.mem.indexOfScalar(u8, domain, '.') orelse return false;
    return dot > 0 and dot + 1 < domain.len;
}

fn profileMergeBase(a: std.mem.Allocator, existing: []const u8) ?std.json.ObjectMap {
    const nothing_to_lose = existing.len == 0 or
        std.mem.eql(u8, std.mem.trim(u8, existing, " \t\r\n"), "{}");
    const root = std.json.parseFromSliceLeaky(std.json.Value, a, existing, .{
        .duplicate_field_behavior = .use_last,
        .allocate = .alloc_always,
    }) catch return if (nothing_to_lose) std.json.ObjectMap.empty else null;
    if (root != .object) return if (nothing_to_lose) std.json.ObjectMap.empty else null;
    return root.object;
}

fn mergeProfileJson(gpa: std.mem.Allocator, existing: []const u8, model: *const Model) ?[]u8 {
    var arena_state = std.heap.ArenaAllocator.init(gpa);
    defer arena_state.deinit();
    const a = arena_state.allocator();

    var obj = profileMergeBase(a, existing) orelse return null;

    // An emptied field REMOVES its key rather than writing "": a profile with
    // `"about": ""` reads to other clients as a bio the reader deliberately
    // blanked, which is a different statement from not having one.
    // A field whose real value did not fit its buffer was never SHOWN, so it is
    // never written: the key keeps exactly what it had.
    if (!model.profile_name_long) {
        // Whichever key the name was read from is the key the edit rewrites.
        // Seeding from `name` and writing `display_name` would leave the value
        // the reader edited untouched, so the rename would silently do nothing.
        const key: []const u8 = switch (model.profile_name_key) {
            .display_name => "display_name",
            .display_name_legacy => "displayName",
            .name => "name",
        };
        setOrRemove(&obj, a, key, trimmedField(model.profile_name())) catch return null;
        // A profile with no handle at all gets one, so clients that read only
        // `name` have something to show. One that has a handle keeps it: a
        // display name is not a handle, and renaming yourself must not rename
        // the @handle everyone mentions you by.
        if (stringField(obj, "name") == null) {
            setOrRemove(&obj, a, "name", trimmedField(model.profile_name())) catch return null;
        }
    }
    if (!model.profile_about_long) {
        setOrRemove(&obj, a, "about", trimmedField(model.profile_about())) catch return null;
    }
    if (!model.profile_picture_long) {
        setOrRemove(&obj, a, "picture", trimmedField(model.profile_picture())) catch return null;
    }
    if (!model.profile_website_long) {
        setOrRemove(&obj, a, "website", trimmedField(model.profile_website())) catch return null;
    }
    if (!model.profile_banner_long) {
        setOrRemove(&obj, a, "banner", trimmedField(model.profile_banner())) catch return null;
    }
    if (!model.profile_lud16_long) {
        setOrRemove(&obj, a, "lud16", trimmedField(model.profile_lud16())) catch return null;
    }
    if (!model.profile_nip05_long) {
        setOrRemove(&obj, a, "nip05", trimmedField(model.profile_nip05())) catch return null;
    }

    // Straight onto the caller's allocator: the write seam holds this for the
    // life of the process, and the arena above dies with this function.
    return std.json.Stringify.valueAlloc(gpa, std.json.Value{ .object = obj }, .{}) catch null;
}

/// Publishes one event the way any press does, so a test can ask what actually
/// went out rather than what a helper built.
pub fn signAndPublishForTest(fx: *Effects, created: i64, kind: u16, tags: []const nostr.event.Tag, content: []const u8) void {
    const gpa = std.heap.page_allocator;
    const owned = gpa.dupe(u8, content) catch return;
    signAndPublish(fx, gpa, created, kind, tags, owned, false, .none, null);
}

pub fn activePubkeyForTest() ?[32]u8 {
    return activePubkey();
}

pub fn forgetOwnProfileAnswerForTest() void {
    forgetOwnProfileAnswer();
}

/// Records an answer the way the worker's `defer` does.
pub fn recordOwnProfileAnswerForTest(pk: [32]u8, answered: bool) void {
    lockOwnProfile();
    g_own_profile_asked_for = pk;
    g_own_profile_answered.store(answered, .release);
    unlockOwnProfile();
}

pub fn ownProfileAnsweredForTest() bool {
    return ownProfileAnswered();
}

pub fn seedProfileFieldsForTest(model: *Model, json: []const u8, keep_typed: bool) void {
    seedProfileFields(model, json, keep_typed);
}

/// The merge, exposed so a test can prove what survives it. This is the whole
/// safety argument of the Edit profile sheet in one function.
pub fn mergeProfileJsonForTest(gpa: std.mem.Allocator, existing: []const u8, model: *const Model) ?[]u8 {
    return mergeProfileJson(gpa, existing, model);
}

/// Drives the name beat's whole write, not just its merge. The tags it forwards
/// are invisible to `mergeNameJsonForTest`, which only sees the content.
pub fn publishNameForTest(model: *Model, fx: *Effects) void {
    publishName(model, fx);
}

pub fn mergeNameJsonForTest(gpa: std.mem.Allocator, existing: []const u8, name: []const u8) ?[]u8 {
    return mergeNameJson(gpa, existing, name);
}

/// A field's text with the whitespace a reader leaves behind taken off.
fn trimmedField(s: []const u8) []const u8 {
    return std.mem.trim(u8, s, " \t\r\n");
}

fn setOrRemove(obj: *std.json.ObjectMap, a: std.mem.Allocator, key: []const u8, value: []const u8) !void {
    if (value.len == 0) {
        _ = obj.orderedRemove(key);
        return;
    }
    try obj.put(a, key, .{ .string = try a.dupe(u8, value) });
}

/// Asks every read relay for our own kind:0, once. Until this has finished, "the
/// store has no profile for me" is not a fact about the account.
fn startOwnProfileFetch() void {
    // BEFORE the busy flag, not after: a return that has already swapped the
    // flag to true latches it, and nothing would ever ask again.
    if (!relayFetchAllowed()) return;
    if (g_own_profile_asking.swap(true, .acq_rel)) return;
    const pk = activePubkey() orelse {
        g_own_profile_asking.store(false, .release);
        return;
    };
    const thread = std.Thread.spawn(.{}, ownProfileWorker, .{pk}) catch {
        g_own_profile_asking.store(false, .release);
        return;
    };
    thread.detach();
}

/// What a relay's message says about the question a socket was opened to ask.
///
/// Three outcomes and not two, because the two ways a question ends are not the
/// same thing. An EOSE is the relay saying it looked and that is all of it.
/// A CLOSED is the relay refusing to look, or ending the subscription, and no
/// EOSE follows it. A loop that waits for "every relay answered" has to stop
/// waiting on a refusal, and must not count it toward what it learned.
const AskVerdict = enum { pending, answered, refused };

fn askVerdict(msg: nostr.message.RelayMessage) AskVerdict {
    return switch (msg) {
        .eose => .answered,
        .closed => .refused,
        else => .pending,
    };
}

pub fn askVerdictForTest(msg: nostr.message.RelayMessage) []const u8 {
    return @tagName(askVerdict(msg));
}

fn ownProfileWorker(pk: [32]u8) void {
    var answered = false;
    defer {
        // ANSWERED, not merely attempted. A round where every relay was offline,
        // write-only, or refused the dial proves nothing about the account, and
        // reading it as "you have no profile" is how a profile gets replaced
        // with an empty one.
        lockOwnProfile();
        g_own_profile_asked_for = pk;
        g_own_profile_answered.store(answered, .release);
        unlockOwnProfile();
        g_own_profile_asking.store(false, .release);
    }
    const gpa = std.heap.page_allocator;
    var threaded = std.Io.Threaded.init(gpa, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var signer = nostr.keys.Signer.init();
    defer signer.deinit();

    const kinds = [_]u16{0};
    const authors = [_][32]u8{pk};
    const filters = [_]nostr.filter.Filter{.{ .authors = &authors, .kinds = &kinds, .limit = 1 }};
    for (0..relaySlots()) |ri| {
        var url_buf: [96]u8 = undefined;
        const entry = relaySnapshot(ri, &url_buf) orelse continue;
        if (!entry.read) continue;
        var relay = nostr.relay.dial(gpa, io, entry.url) catch continue;
        // Declared AFTER deinit so it runs BEFORE it: the keeper must have
        // let go of this pointer before the connection is freed.
        defer relay.deinit();
        const watched = watchOneShot(io, relay, one_shot_budget_ms);
        defer releaseOneShot(watched);
        relay.subscribe("plaza-me", &filters) catch continue;
        var seen: usize = 0;
        while (seen < 32) : (seen += 1) {
            var msg = (relay.receive() catch break) orelse break;
            defer msg.deinit();
            // Only an EOSE is an answer: "that is all I have". A CLOSED ends
            // this relay's part of the question and says nothing about the
            // account. `auth-required:` is the case that matters: the relay
            // declined to look, and reading that as "no kind:0 here" is what
            // lets an empty profile replace a real one.
            switch (askVerdict(msg.value)) {
                .answered => {
                    answered = true;
                    break;
                },
                .refused => break,
                .pending => {},
            }
            switch (msg.value) {
                .event => |e| {
                    const result = plazaIngest(gpa, e.event, .{ .verify_with = signer }) catch continue;
                    // A relay can send ANY event down any subscription, so the
                    // event has to be the thing that was asked for before it can
                    // count as an answer about it. Verified was not enough: a
                    // valid note from a stranger, pushed down "plaza-me", used to
                    // decide that this account had no profile.
                    if (result == .invalid) continue;
                    if (e.event.kind != 0) continue;
                    if (!std.mem.eql(u8, &e.event.pubkey, &pk)) continue;
                    answered = true;
                },
                else => continue,
            }
        }
    }
}

/// Publishes the name beat's text as the account's kind:0 metadata, and seeds
/// the local profile cache so the app shows the name at once.
///
/// The beat runs right after a key is created, when there is nothing to merge
/// into, but it goes through the same merge as the Edit profile sheet anyway:
/// the destructive shape is the one where a name is published as the WHOLE
/// profile, and having exactly one path here means that shape cannot come back
/// the next time somebody reaches for this function.
fn publishName(model: *Model, fx: *Effects) void {
    const raw = trimmedField(model.name_buffer.text());
    if (raw.len == 0) return;
    const gpa = std.heap.page_allocator;

    var prev_created_at: i64 = 0;
    var prev_tags: []const nostr.event.Tag = &.{};
    var existing: ?OwnProfile = null;
    if (ownProfileJson(gpa)) |own| {
        existing = own;
        prev_created_at = own.created_at;
        prev_tags = own.tags;
    }
    defer if (existing) |e| freeOwnProfile(gpa, e);

    // Quotes and backslashes are ESCAPED, not dropped: a name is prose, and the
    // serializer knows how to carry prose. (Dropping them was a fixed 64-byte
    // buffer away from a longer field overflowing it.)
    const json = mergeNameJson(gpa, if (existing) |e| e.json else "{}", raw) orelse return;
    // The TAGS come forward, the same as the sheet's save. The beat only arms on
    // a key this app just minted, which has no kind:0 and therefore no NIP-39
    // proofs to lose, so this is not a bug being fixed: it is the one line that
    // stopped the doc comment above from being true, and the read of the stored
    // profile two lines up says plainly that somebody already expected one.
    const tags = dupeTags(gpa, prev_tags) orelse return;
    signAndPublish(fx, gpa, @max(nowSeconds(), prev_created_at + 1), 0, tags, json, false, .profile, null);
    // Seed the cache: the composer line and the feed show the name at once.
    if (activePubkey()) |pk| {
        if (upsertProfile(pk)) |prof| parseMetadataInto(prof, json);
    }
    model.name_buffer.clear();
}

/// The name beat's one-field merge: the same read-modify-write as the sheet's,
/// with only the name touched.
fn mergeNameJson(gpa: std.mem.Allocator, existing: []const u8, name: []const u8) ?[]u8 {
    var arena_state = std.heap.ArenaAllocator.init(gpa);
    defer arena_state.deinit();
    const a = arena_state.allocator();
    var obj = profileMergeBase(a, existing) orelse return null;
    setOrRemove(&obj, a, "name", name) catch return null;
    setOrRemove(&obj, a, "display_name", name) catch return null;
    return std.json.Stringify.valueAlloc(gpa, std.json.Value{ .object = obj }, .{}) catch null;
}

/// Completes the remembered first intent once an identity exists: the guest
/// reached for the composer, so it opens by itself. The welcome-in moment.
fn replayPending(model: *Model) void {
    if (model.pending == .post) {
        model.pending = .none;
        model.composing = true;
    }
}

/// The replay seam, exercised without disk or relays. For tests.
pub fn replayPendingForTest(model: *Model) void {
    replayPending(model);
}

/// Restores a helper identity from a session pubkey hex. For tests.
pub fn restoreHelperForTest(pubkey_hex: []const u8) bool {
    return restoreHelperIdentity(pubkey_hex);
}

/// Sets what the create ceremony has reported, which is the only thing that
/// tells an appearing key apart from any other. For tests.
pub fn setCeremonyForTest(state: enum { none, running, created }) void {
    g_ceremony = switch (state) {
        .none => .none,
        .running => .running,
        .created => .created,
    };
    g_ceremony_adopted = false;
}

/// Parks the daemon health flag at "unreachable", so a queued setup stays queued
/// instead of reaching for an effects layer a unit test does not have. For tests.
pub fn setHelperUnreachableForTest() void {
    g_helper_state.store(0, .release);
    g_helper_setup = .none;
    g_helper_pending_in_flight = .none;
}

pub fn ceremonyOwesNameForTest() bool {
    return g_ceremony_adopted;
}

pub fn identityMintedForTest() bool {
    return g_identity_minted_here;
}

/// Delivers the ceremony window's exit, which is how Plaza learns what it did.
/// For tests.
pub fn handleNotaryExitedForTest(model: *Model, e: native_sdk.EffectExit) void {
    handleNotaryExited(model, e);
}

/// Delivers a daemon /pubkey answer, which is how a key made or imported in the
/// other process reaches Plaza. For tests.
pub fn handleHelperPubkeyForTest(model: *Model, response: native_sdk.EffectResponse) void {
    handleHelperPubkey(model, response);
}

/// Starts connecting to a bunker the way `connectRemoteSigner` does, without a
/// socket or a thread: the connection state is set, nobody is signed in, and a
/// `connect` request is waiting for its answer. Returns that request's id. For
/// tests.
pub fn beginBunkerConnectForTest(pubkey: [32]u8, id_out: *[24]u8) []const u8 {
    g_remote_pubkey = pubkey;
    g_signer_kind = .remote;
    g_remote_status.store(1, .release);
    g_remote_sign_notice.store(false, .release);
    g_remote_confirming.store(true, .release);
    login.g_login_error.store(@intFromEnum(LoginError.none), .release);
    _ = g_remote_generation.fetchAdd(1, .monotonic);
    const id = "connect-for-test";
    @memcpy(id_out[0..id.len], id);
    _ = registerPending(id, .connect, null, false, .none, 0, no_half_id, .{});
    return id_out[0..id.len];
}

/// Lends the app an io for the one place a test reaches for it (minting the
/// ephemeral client key). For tests.
pub fn setIoForTest(io: ?std.Io) void {
    g_io = io;
}

/// The id of the `connect` request a pasted link left waiting, if any. For
/// tests.
pub fn pendingConnectIdForTest(out: *[24]u8) ?[]const u8 {
    pendingLock();
    defer pendingUnlock();
    for (&g_pending) |*slot| {
        if (slot.active and slot.method == .connect) {
            @memcpy(out[0..slot.id_len], slot.id());
            return out[0..slot.id_len];
        }
    }
    return null;
}

/// What the listener does with a `connect` answer from the signer. For tests.
pub fn answerBunkerConnectForTest(id: []const u8) void {
    _ = takeAnswered(id);
}

/// Whether the pairing secret `needle` is still anywhere in the buffer that
/// held it, or a client key is still held. For tests.
pub fn remoteSecretHeldForTest(needle: []const u8) bool {
    if (g_remote_client_kp != null) return true;
    return std.mem.indexOf(u8, &g_remote_secret_buf, needle) != null;
}

/// Which listener generation is current, so a test can see one was stopped.
/// For tests.
pub fn remoteGenerationForTest() u64 {
    return g_remote_generation.load(.acquire);
}

pub fn connectWentQuietForTest() bool {
    return connectWentQuiet();
}

pub fn driveBunkerConnectForTest(model: *Model) void {
    driveBunkerConnect(model);
}

/// Puts every piece of bunker state back to a guest's. For tests.
pub fn resetBunkerConnectForTest() void {
    abandonRemoteSigner(.none);
    g_remote_confirming.store(false, .release);
}

/// Drives the remote-signer connection state (0 idle, 1 reaching, 2 connected,
/// 3 unreachable) plus a remote identity, so the presentation is testable
/// without a live bunker. For tests.
pub fn setRemoteStateForTest(status: u8, npub_len: usize) void {
    g_signer_kind = if (status == 0) .helper else .remote;
    g_remote_status.store(status, .release);
    g_remote_sign_notice.store(false, .release);
    if (npub_len > 0) {
        const stub = "npub1testsigner";
        const n = @min(stub.len, g_identity_npub_buf.len);
        @memcpy(g_identity_npub_buf[0..n], stub[0..n]);
        g_identity_npub_len = n;
    } else g_identity_npub_len = 0;
}

/// Switches to the feed and brings the store + ingest pool up if they are not
/// already running. Shared by all sign-in paths (create, import, remote signer).
/// A fresh identity means the feed's author filter changed, so force a rebuild
/// on the next tick by invalidating the change guard.
fn enterFeed(model: *Model) void {
    model.stage = .ready;
    invalidateFeed();
    if (g_store == null) {
        if (g_io) |io| if (g_environ) |env| startFeed(io, env);
    }
    // Whoever was signed in before, their follows leave with them. Then this
    // account's own list is read back out of the store, so a local-first app
    // does not forget who you follow every time you open it. Both bump the
    // generation, which is what makes the open sockets re-ask for the records
    // of the account that is actually signed in.
    forgetFollows();
    forgetMutes();
    forgetBookmarks();
    // A picture on its way belongs to whoever asked for it.
    dropUpload();
    forgetBlossom();
    loadFollowsFromStore();
    loadMutesFromStore();
    loadBookmarksFromStore();
    loadBlossomFromStore();
    // And what people sent this account while it was away.
    loadInbox();
}

pub fn initialModel() Model {
    var model = Model{};
    attachFeedStorage(&model);
    return model;
}

// -------------------------------------------------------------- compose & post
//
// Posting is local-first: a composed note is signed, written to the local store
// straight away (so it shows in the feed on the next tick), and published to the
// pool on a detached thread. The feed dedupes by event id, so when a relay later
// echoes our own note back through the ingest subscriptions it collapses onto
// the local copy.

/// Posts the current draft: sign a kind:1 note, store it locally at once, and
/// publish it to the pool in the background. A blank draft or a not-yet-ready
/// identity is a no-op.
/// Signs and publishes what is in the composer, and everything that follows a
/// note actually leaving.
///
/// Its own function because there are two ways in now: the press, when the
/// pause is off, and the clock, when it is on. Leaving this inline under the
/// press meant a held note that finally went would clear no draft, close no
/// sheet and say nothing.
/// The room a held note was written in, captured when the reader pressed Post
/// rather than when the pause runs out. That gap is the whole feature: the
/// reader is free to walk somewhere else while it counts, and the note still
/// belongs where it was written.
var g_held_route: PlaceRoute = .none;

fn firePost(model: *Model, fx: *Effects, route: ?PlaceRoute) bool {
    g_post_due_s = 0;
    // Nothing below runs unless the note actually went to a signer. It used to
    // run regardless: the composer emptied, the draft file was deleted and the
    // toast said "Posted" for a sign that had been refused before it left the
    // process.
    if (!submitPost(model, fx, route)) {
        setToast(model, if (!outboxHasRoom())
            "Still sending your last notes. This one is kept."
        else
            "Notary is busy for a moment. Try again.");
        return false;
    }
    // The slot is emptied the moment its contents go to a signer. Leaving it
    // would restore an already-published note into the next launch's composer,
    // one keystroke from being posted twice.
    saveDraft("", null);
    // Posting closes the sheet; the note is already local and will appear on the
    // next tick.
    model.composing = false;
    setToast(model, if (g_signer_kind == .remote) "Sent to your signer" else "Posted");
    // The first post is the calm moment to suggest a backup, and the backup
    // lives in Notary now: this app has nothing to back up.
    if (g_identity_minted_here and !model.backup_nudge_dismissed)
        model.backup_nudge = true;
    return true;
}

/// How long a note waits in the composer before it is signed, in seconds.
///
/// Zero is off and is not the default. The point of the pause is the one thing
/// nostr cannot give back: once a note is signed and out, a kind:5 is a REQUEST.
/// A relay may ignore it and everyone already holding the event keeps it. So an
/// "undo" that runs after publishing would be a button that cannot do what it
/// says, and this waits on the near side of the signature instead, where taking
/// it back means nothing ever existed.
///
/// The composer stays open and editable while it counts. That is the point
/// rather than a side effect: what this is for is catching the typo you see the
/// instant after you press the button.
///
/// Off by default. Turning it on for everybody would make a note that suddenly
/// does not post read as a fault before it reads as a safeguard, and nobody
/// asked for their existing habit to change. The cost is honest: a pause nobody
/// finds helps nobody, so it sits in Settings where it can be found.
pub var g_post_delay_s: i64 = 0;

/// When the held note is due, or 0 when nothing is held.
var g_post_due_s: i64 = 0;

/// And the same for a reply, on its own clock.
///
/// Separate rather than shared because the two surfaces are independent: the
/// composer is a sheet, a reply belongs to a thread, and one held while the
/// other is armed must not cancel or fire it. `postIsDue` and `postSecondsLeft`
/// take the clock as an argument precisely so both can use them.
var g_reply_due_s: i64 = 0;

pub fn replyHeldForTest() bool {
    return g_reply_due_s != 0;
}

pub fn holdReplyForTest(now_s: i64) void {
    g_reply_due_s = now_s + (if (g_post_delay_s == 0) @as(i64, 5) else g_post_delay_s);
}

pub fn postDelayForTest() i64 {
    return g_post_delay_s;
}

/// Gives the open place one write relay of its own, the way a parsed document
/// would. The routing tests are about WHEN the relay list is read, not about
/// parsing it.
pub fn setPlaceWriteRelayForTest(url: []const u8) void {
    if (places.g_place == null) return;
    const m = &places.g_place.?;
    m.write_relay_lens[0] = @intCast(copyBounded(&m.write_relays[0], url));
    m.write_relays_len = 1;
}

pub fn setPostDelayForTest(seconds: i64) void {
    g_post_delay_s = seconds;
}

pub fn postHeldForTest() bool {
    return g_post_due_s != 0;
}

pub fn holdPostForTest(now_s: i64) void {
    g_post_due_s = now_s + g_post_delay_s;
}

/// Whether a held note is due to be signed now.
///
/// A function of its inputs, so a test can say what it must decide without
/// waiting five seconds for it.
pub fn postIsDue(due_s: i64, now_s: i64) bool {
    if (due_s == 0) return false;
    return now_s >= due_s;
}

/// Seconds still on the clock, for the button. Never negative, and never zero
/// while something is held: a button reading "Undo 0" has already gone.
pub fn postSecondsLeft(due_s: i64, now_s: i64) i64 {
    if (due_s == 0) return 0;
    const left = due_s - now_s;
    return if (left < 1) 1 else left;
}

fn submitPost(model: *Model, fx: *Effects, route: ?PlaceRoute) bool {
    const text = std.mem.trim(u8, model.draft_buffer.text(), " \t\r\n");
    if (text.len == 0) return false;
    // The composer is cleared and the draft file deleted right after this
    // returns, so a sign that never went out has to be reported rather than
    // assumed. The one shape that reaches here is a relay-list flush on the same
    // tick, which the SDK would reject and nothing would notice.
    if (!signerReady()) return false;
    // And a queue with room to track it. Refusing here keeps the note in the
    // composer; refusing after the sign, which is where it used to happen,
    // dropped it with no row, no retry and no way back.
    if (!outboxHasRoom()) return false;
    const gpa = std.heap.page_allocator;

    // A process-lifetime copy of the content: `event.create` references its
    // content slice rather than copying it, and the store write and either the
    // publisher or the NIP-46 round-trip read it after the draft is cleared.
    // Canonicalised BEFORE the copy, so the published content and the imeta tag
    // built from it name the same URL. NIP-92 pairs a tag with a URL in the
    // content, and a tag pointing at a string that is not there is one a reader
    // is entitled to ignore.
    const canonical = canonicalMediaUrls(gpa, text);
    const owned = gpa.dupe(u8, canonical) catch return false;
    // Read off `owned`, not off the draft buffer: that is cleared two lines
    // below, and the tags hold slices of whatever they were built from.
    const base_tags = contentTags(gpa, owned, &.{}, model.mentionsOff());
    // The reader's content warning, when they set one. It travels in the tag set,
    // and the signer's pending slot reads it back out of those same tags, so a
    // sign that never comes back hands the words to the composer together with
    // the warning they were signed under. Control characters become spaces: the
    // reason field is a textarea, and a newline in a tag a reader draws on one
    // line would show them a bare warning.
    var reason_buf: [warning_input_capacity]u8 = undefined;
    const warning: ?[]const u8 = if (model.warn_on) singleLine(&reason_buf, model.warn_buffer.text()) else null;
    // Refused, not published without: a note the author asked to have covered
    // must not go out uncovered because an allocation failed.
    const tags = withContentWarning(gpa, base_tags, warning) orelse {
        gpa.free(owned);
        return false;
    };
    // A composer draft: kind:1 carrying whatever its own text implies,
    // restorable to the composer if a remote signer never answers.
    // `.none` on purpose: this is the one write that IS `restorable`, so the
    // draft it came from is what gets handed back.
    signAndPublish(fx, gpa, nowSeconds(), 1, tags, owned, true, .none, route);
    model.draft_buffer.clear();
    model.draft_dropped = 0;
    model.warn_on = false;
    model.warn_buffer.clear();
    return true;
}

/// `text` trimmed, with each control character (a newline from the textarea, a
/// tab) turned into a space, written into `out`. Interior only: the ends are
/// trimmed first.
fn singleLine(out: []u8, text: []const u8) []const u8 {
    const trimmed = std.mem.trim(u8, text, " \t\r\n");
    const n = @min(trimmed.len, out.len);
    for (trimmed[0..n], 0..) |c, i| out[i] = if (c < 0x20 or c == 0x7f) ' ' else c;
    return std.mem.trim(u8, out[0..n], " ");
}

/// The content warning a composer post was signed with, kept in the pending sign
/// that carries the post (the bunker's slot or the built-in signer's), so the
/// post that comes back is restored with its own warning. One global for this
/// held whichever post was submitted last: with several signs out, a timed-out
/// one came back with another post's warning, or none.
const WarnCarry = struct {
    on: bool = false,
    len: u8 = 0,
    buf: [warning_input_capacity]u8 = [_]u8{0} ** warning_input_capacity,

    /// Reads the warning off the tag set the post is being signed with.
    fn fromTags(tags: []const nostr.event.Tag) WarnCarry {
        for (tags) |tag| {
            if (tag.len < 1 or !std.mem.eql(u8, tag[0], "content-warning")) continue;
            var out = WarnCarry{ .on = true };
            const reason = if (tag.len > 1) tag[1] else "";
            const n = @min(reason.len, out.buf.len);
            @memcpy(out.buf[0..n], reason[0..n]);
            out.len = @intCast(n);
            return out;
        }
        return .{};
    }

    /// Puts the warning back in the composer beside the draft it belonged to.
    fn restoreInto(self: WarnCarry, model: *Model) void {
        if (!self.on) return;
        model.warn_on = true;
        model.warn_buffer.set(self.buf[0..self.len]);
    }
};

/// Appends NIP-36's `content-warning` tag when the reader set one. The reason is
/// copied: the tags outlive the composer's buffer, like the content they sit with.
/// An empty reason is still a tag, because the tag is what covers the note.
/// Returns null when the tag could not be built: the caller refuses the post.
pub fn withContentWarning(gpa: std.mem.Allocator, tags: []const nostr.event.Tag, reason: ?[]const u8) ?[]const nostr.event.Tag {
    const text = reason orelse return tags;
    const owned = gpa.dupe(u8, text) catch return null;
    const tag = gpa.dupe([]const u8, &.{ "content-warning", owned }) catch {
        gpa.free(owned);
        return null;
    };
    const out = gpa.alloc(nostr.event.Tag, tags.len + 1) catch {
        gpa.free(tag);
        gpa.free(owned);
        return null;
    };
    @memcpy(out[0..tags.len], tags);
    out[tags.len] = tag;
    return out;
}

/// Signs `content_owned` as an event of `kind` with `tags`, stamped `created`,
/// through whichever signer is active, then stores and publishes it. Takes
/// ownership of `content_owned` and `tags` (process-lifetime: the local and
/// remote paths reference them after this returns, and the write seam intends
/// them to outlive the detached publish). `restorable` marks a composer draft,
/// so only a lost post is put back in the composer, never a reaction.
pub fn signAndPublish(fx: *Effects, gpa: std.mem.Allocator, created: i64, kind: u16, tags_in: []const nostr.event.Tag, content_owned: []const u8, restorable: bool, undo: PendingUndo, route_in: ?PlaceRoute) void {
    // What to take back if this signature never arrives, taken as an ARGUMENT
    // rather than armed by the caller beforehand.
    //
    // Every write in this app moved the screen before it signed and none of
    // them put it back, and the reason the whole class existed is that arming
    // was a separate step a caller could simply not do. A parameter cannot be
    // forgotten: a new write does not compile until it has said what its undo
    // is, and `.none` is a decision spelled out loud rather than an omission.
    //
    // It also fixes the ordering hazard. Arming after the write dispatched
    // could release a record the response had already consumed.
    armUndo(undo);
    // Here, rather than at each call site, because this is the ONE door every
    // published event goes through: a switch the reader turned on has to hold for
    // the note they write, the note they repost and the note they quote, and a
    // per-caller version of it is a switch that holds for whichever paths someone
    // remembered.
    const tags = withClientTag(gpa, kind, tags_in);
    // The finished tag set, recorded where a test can read it. A parser that is
    // correct and never called is the regression worth guarding against here,
    // and every other seam in this file stops short of the event itself.
    g_last_published_tags = tags;
    // Decided HERE, on the UI thread, at the moment the reader asked, and then
    // carried. Every path past this point runs later and somewhere else: a
    // signer that asks a person, a queue that retries, a detached publish
    // thread. `null` means "whatever room is open right now", which is the
    // answer for every write that is submitted the instant it is pressed; a
    // note held for the undo pause passes the room it was WRITTEN in, because
    // by the time it fires the reader may be standing somewhere else.
    const route = route_in orelse routeForOpenPlace();
    switch (g_signer_kind) {
        .remote => requestRemoteSign(gpa, created, kind, tags, content_owned, restorable, route),
        .helper => requestHelperSign(fx, gpa, created, kind, tags, content_owned, restorable, route),
    }
}

/// Appends NIP-89's `client` tag when the reader has asked for it.
///
/// Only to the kinds that ARE the reader's writing. A reaction, a deletion and a
/// contact list are machinery; stamping those would broadcast the same fact more
/// widely for no reader-visible benefit, which is the opposite of what an opt-in
/// privacy switch is for.
pub fn withClientTag(gpa: std.mem.Allocator, kind: u16, tags: []const nostr.event.Tag) []const nostr.event.Tag {
    if (!prefs.g_client_tag) return tags;
    if (kind != 1 and kind != 6) return tags;
    const tag = gpa.dupe([]const u8, &.{ "client", client_tag_name }) catch return tags;
    const out = gpa.alloc(nostr.event.Tag, tags.len + 1) catch return tags;
    @memcpy(out[0..tags.len], tags);
    out[tags.len] = tag;
    return out;
}

/// The time, and what the note was written with when it says so.
///
/// Returned as SPANS of the paragraph the time already occupies, not as a node of
/// its own. A feed row is priced in widget nodes against a per-view ceiling that
/// refuses the whole screen when crossed, and "a quiet second line of metadata"
/// is precisely the sort of thing that costs ten rows' worth of budget without
/// looking like it costs anything.
///
/// The name is drawn in the meta register and prefixed, so it can never be read
/// as the note's own words. It is somebody else's claim about their software.
fn timeSpans(ui: *AppUi, note: *const Note, scale: f32) []const canvas.TextSpan {
    const name = note.client();
    if (name.len == 0) {
        const one = ui.arena.alloc(canvas.TextSpan, 1) catch return &.{};
        one[0] = .{ .text = note.time(), .scale = scale };
        return one;
    }
    const two = ui.arena.alloc(canvas.TextSpan, 2) catch return &.{};
    two[0] = .{ .text = note.time(), .scale = scale };
    // Same faint register as the time it follows: inherited from the paragraph,
    // so it cannot drift into looking like the note's own words.
    two[1] = .{ .text = ui.fmt(" via {s}", .{name}), .scale = scale };
    return two;
}

/// " · via X" for a line that is already a single string, empty when the note
/// says nothing. The span form above is for the rows that draw the time on its
/// own; the focal note builds one sentence, so it needs the text form.
fn viaSuffix(ui: *AppUi, note: *const Note) []const u8 {
    const name = note.client();
    if (name.len == 0) return "";
    return ui.fmt(" · via {s}", .{name});
}

/// What a note says it was written with, if it says anything.
///
/// Foreign text from a stranger's event, so it is treated as such: a name longer
/// than a label is not a label, and control characters in a meta row are how a
/// row stops looking like a row. An absent or unusable tag draws nothing at all,
/// never "via unknown", because what a note does not say is not a fact about it.
/// In BYTES, which is what the buffer holds, and in CHARACTERS, which is what a
/// reader sees. Both are needed: a byte cap alone is about eight characters of
/// Japanese and twenty-four of English, so it silently refuses a legitimate name
/// in one script and accepts a much wider one in another.
/// 48 so that the CHARACTER cap is the one that binds in every script that
/// matters here: fourteen three-byte characters fit, which is what makes the
/// Japanese case behave like the English one rather than being cut a third
/// shorter for no reason a reader could see.
const client_name_bytes = 48;
const client_name_chars = 14;

pub fn clientOf(ev: nostr.event.Event) ?[]const u8 {
    for (ev.tags) |tag| {
        if (tag.len < 2 or !std.mem.eql(u8, tag[0], "client")) continue;
        const name = std.mem.trim(u8, tag[1], " \t\r\n");
        if (name.len == 0) return null;
        for (name) |c| {
            if (c < 0x20 or c == 0x7f) return null;
        }
        // TRUNCATED, not refused. A name too long for the row is still evidence
        // about the note; refusing it outright threw away the whole fact, and
        // did so unevenly by script.
        return clipToChars(name, client_name_chars, client_name_bytes);
    }
    return null;
}

/// How long a content warning's reason may be, in bytes and in characters. One
/// line in a chip, so it is clipped the way a client name is: both caps, because
/// a byte cap alone is a different width in every script.
const warning_reason_bytes = 96;
const warning_reason_chars = 48;
///
/// The room the reason gets while it is being typed. What a reader sees is clipped
/// to the caps above, so the field does not need to run far past them.
const warning_input_capacity = 120;

/// What an event's NIP-36 `content-warning` tag says, or null when it has none.
///
/// The TAG is the warning, not the sentence in it. `["content-warning"]` and
/// `["content-warning", ""]` are both a request to cover the note and answer an
/// empty reason, and so does a reason holding a control character, which is
/// dropped rather than drawn: refusing to cover a note because its explanation
/// was malformed would invert the author's request. Jumble and Amethyst read the
/// tag the same way (`isNsfwEvent` in `src/lib/event.ts:49`, `TagArray.isSensitive`
/// in `nip36SensitiveContent/TagArrayExt.kt:28`), and Amethyst's
/// `ContentWarningTag.parse` blank-checks the reason (`ContentWarningTag.kt:39`).
pub fn contentWarningOf(ev: nostr.event.Event) ?[]const u8 {
    return contentWarningIn(ev.tags);
}

pub fn contentWarningIn(tags: []const nostr.event.Tag) ?[]const u8 {
    for (tags) |tag| {
        if (tag.len < 1 or !std.mem.eql(u8, tag[0], "content-warning")) continue;
        if (tag.len < 2) return "";
        const reason = std.mem.trim(u8, tag[1], " \t\r\n");
        for (reason) |c| {
            if (c < 0x20 or c == 0x7f) return "";
        }
        return clipToChars(reason, warning_reason_chars, warning_reason_bytes);
    }
    return null;
}

/// The longest prefix of `s` that is at most `max_chars` codepoints and
/// `max_bytes` bytes, cut on a UTF-8 boundary.
///
/// Codepoints rather than bytes because the cap exists to bound WIDTH, and a
/// three-byte character is not three characters wide. Cutting mid-sequence would
/// hand the renderer an invalid string, which is a different bug.
fn clipToChars(s: []const u8, max_chars: usize, max_bytes: usize) []const u8 {
    var i: usize = 0;
    var chars: usize = 0;
    while (i < s.len and chars < max_chars) {
        const len = std.unicode.utf8ByteSequenceLength(s[i]) catch return s[0..i];
        if (i + len > s.len or i + len > max_bytes) break;
        _ = std.unicode.utf8Decode(s[i .. i + len]) catch return s[0..i];
        i += len;
        chars += 1;
    }
    return s[0..i];
}

/// Publishes the reply composer's text as a NIP-10 reply to the open thread's
/// note: a kind:1 e-tagging the root (marked "root") and p-tagging its author,
/// signed and stored local-first so it joins the thread at once. A guest cannot
/// sign, so a reply attempt routes to the join sheet.
/// Sends the held reply, or sends one straight away when the pause is off.
fn fireReply(model: *Model, fx: *Effects, route: ?PlaceRoute) void {
    g_reply_due_s = 0;
    publishReply(model, fx, route);
}

fn publishReply(model: *Model, fx: *Effects, route: ?PlaceRoute) void {
    if (model.viewing_thread == 0) return;
    if (model.is_guest()) {
        model.joining = true;
        return;
    }
    const root = model.noteById(model.viewing_thread) orelse return;
    const text = std.mem.trim(u8, model.reply_buffer.text(), " \t\r\n");
    if (text.len == 0) return;
    const gpa = std.heap.page_allocator;
    const content = gpa.dupe(u8, text) catch return;
    const id_hex = hexAlloc(gpa, root.event_id) orelse return;
    // Where the root can be found, so the next reader of this reply does not have
    // to guess. Empty, not absent, when nothing is known: the marker sits in the
    // slot after it.
    var root_hints: HintList = .{};
    hintsFor(root.event_id, root.pubkey, &root_hints);
    const root_hint = hintOrEmpty(gpa, &root_hints) orelse return;
    const e_tag = gpa.dupe([]const u8, &.{ "e", id_hex, root_hint, "root" }) catch return;
    const p_tag = pTagFor(gpa, root.pubkey) orelse return;

    // Everybody already in the conversation, not only the person being answered.
    // A reply that tags one author is a reply the rest of the thread never hears
    // about, so they answer into a conversation that has moved on without them.
    // Both reference clients do this: Amethyst p-tags every author in the thread
    // plus the parent's own mentions, Jumble the parent author plus the parent's
    // p tags. Plaza does not retain a note's raw tags, so this is the authors,
    // which is the part that carries the conversation.
    var participants: [max_thread_participant_tags][32]u8 = undefined;
    var participants_len: usize = 0;
    const me = activePubkey();
    for (model.thread_notes[0..model.thread_notes_len]) |n| {
        if (participants_len == participants.len) break;
        // Not the root author, who already has a tag, and never yourself.
        if (std.mem.eql(u8, &n.pubkey, &root.pubkey)) continue;
        if (me) |mine| {
            if (std.mem.eql(u8, &mine, &n.pubkey)) continue;
        }
        if (mentionExcluded(model.mentionsOff(), n.pubkey)) continue;
        var dup = false;
        for (participants[0..participants_len]) |seen| {
            if (std.mem.eql(u8, &seen, &n.pubkey)) dup = true;
        }
        if (dup) continue;
        participants[participants_len] = n.pubkey;
        participants_len += 1;
    }

    const thread = gpa.alloc(nostr.event.Tag, 2 + participants_len) catch return;
    thread[0] = e_tag;
    thread[1] = p_tag;
    var filled: usize = 2;
    for (participants[0..participants_len]) |pubkey| {
        thread[filled] = pTagFor(gpa, pubkey) orelse break;
        filled += 1;
    }
    // The threading tags first, then whatever the reply's own text implies. A
    // reply can carry a hashtag, a mention or a picture exactly like a note can,
    // and it used to carry none of them.
    const tags = contentTags(gpa, content, thread[0..filled], model.mentionsOff());
    // Its own copy, because `content` belongs to the write seam from here and a
    // reply is not `restorable`: the composer's restore path holds one draft and
    // hands it to the composer, which is the wrong box for this text.
    const kept: PendingUndo = if (std.heap.page_allocator.dupe(u8, text)) |c| .{ .reply = .{ .text = c, .root = root.event_id } } else |_| .none;
    signAndPublish(fx, gpa, nowSeconds(), 1, tags, content, false, kept, route);
    model.reply_buffer.clear();
}

// ------------------------------------------------------------ picture upload
//
// Putting a picture into a note, an avatar or a banner.
//
// The protocol is Blossom and `blossom.zig` holds it. What lives here is what
// only the app can know: who is signed in, which signer will sign, which draft or
// profile field the address belongs in, and what is on screen while it happens.
//
// The shape of one upload, because it spans three threads and a signer:
//
//   1. The reader presses a button, a file dialog opens, and a file is chosen.
//      Nothing has left the machine.
//   2. A worker reads it, checks what it is, removes location and camera
//      metadata and works out the hash, size and blurhash. The card now says what
//      will be sent and to which servers, and waits for a press on Upload.
//   3. The press asks the signer for a kind:24242 token naming that hash. It goes
//      through exactly the signer every other event goes through, so a Notary or
//      a NIP-46 bunker prompts as it would for a note. The token is never stored
//      and never published: it is a bearer credential for one file.
//   4. A second worker sends the picture, server by server, until one takes it.
//   5. The tick puts the returned address where the picture was asked for.
//
// A job is shared between the UI thread and at most one worker at a time, and it
// is reference counted so that cancelling while a worker is mid-write cannot free
// what the worker is reading. The UI holds one reference; each worker holds one
// while it runs.

/// BUD-03's list of a person's media servers.
pub const blossom_list_kind: u16 = 10063;

const UploadTarget = enum(u8) { note, avatar, banner };

const UploadPhase = enum(u8) {
    /// A worker is reading the file.
    preparing,
    /// Checked and waiting for the reader to say go.
    ready,
    /// The token is with the signer.
    signing,
    /// The token is back; the tick starts the send.
    signed,
    sending,
    /// A server took it; the tick applies the address.
    sent,
    failed,
};

const UploadJob = struct {
    refs: std.atomic.Value(u32) = .init(1),
    phase_raw: std.atomic.Value(u8) = .init(@intFromEnum(UploadPhase.preparing)),
    target: UploadTarget,
    path_buf: [1024]u8 = undefined,
    path_len: u16 = 0,
    prepared: ?blossom.Prepared = null,
    /// Why it failed, or empty. Written before the phase moves to `.failed`.
    message_buf: [200]u8 = undefined,
    message_len: u8 = 0,
    /// The servers this upload will try, fixed when the file is chosen so what
    /// the card named is what is used.
    servers: [blossom.max_servers][blossom.max_server_len]u8 = undefined,
    server_lens: [blossom.max_servers]u8 = [_]u8{0} ** blossom.max_servers,
    server_count: u8 = 0,
    /// Whether those are the reader's own list rather than the defaults.
    from_list: bool = false,
    alt_buf: [200]u8 = undefined,
    alt_len: u8 = 0,
    signing_since_s: i64 = 0,
    /// The `Authorization` header, once the signer has answered.
    authorization: ?[]u8 = null,
    progress: blossom.Progress = .{},
    /// What the send found. Written before the phase moves to `.sent` or
    /// `.failed`.
    outcome: ?blossom.Outcome = null,

    fn phase(self: *const UploadJob) UploadPhase {
        return @enumFromInt(self.phase_raw.load(.acquire));
    }

    fn setPhase(self: *UploadJob, next: UploadPhase) void {
        self.phase_raw.store(@intFromEnum(next), .release);
    }

    fn path(self: *const UploadJob) []const u8 {
        return self.path_buf[0..self.path_len];
    }

    /// The file's name, without the folders it was found in.
    fn fileName(self: *const UploadJob) []const u8 {
        const p = self.path();
        const slash = std.mem.lastIndexOfAny(u8, p, "/\\") orelse return p;
        return p[slash + 1 ..];
    }

    fn message(self: *const UploadJob) []const u8 {
        return self.message_buf[0..self.message_len];
    }

    fn server(self: *const UploadJob, i: usize) []const u8 {
        return self.servers[i][0..self.server_lens[i]];
    }

    fn alt(self: *const UploadJob) []const u8 {
        return self.alt_buf[0..self.alt_len];
    }

    /// Ends the job in a failure the reader can read. Safe from a worker.
    fn fail(self: *UploadJob, text: []const u8) void {
        const n = @min(text.len, self.message_buf.len);
        @memcpy(self.message_buf[0..n], text[0..n]);
        self.message_len = @intCast(n);
        self.setPhase(.failed);
    }
};

/// The job on screen, if any. UI thread only.
var g_upload: ?*UploadJob = null;

/// A profile picture or banner has been filled in by an upload and not saved.
/// The sheet says so, because the field alone does not tell anyone that the
/// picture is not published yet.
var g_profile_upload_unsaved: bool = false;

/// Stands in for the file dialog: tests, and the harness that drives the real
/// app without a person to click through a native panel. Null in a build nobody
/// has set it in, which is every shipped one.
var g_pick_path_override: ?[]const u8 = null;

/// How long a token may be out with the signer before the upload gives up on it.
/// Longer than either signer's own timeout, so this only ever fires for a
/// request that was never sent at all.
const upload_sign_wait_s: i64 = 90;

fn releaseUploadJob(job: *UploadJob) void {
    if (job.refs.fetchSub(1, .acq_rel) != 1) return;
    const gpa = std.heap.page_allocator;
    if (job.prepared) |*prepared| prepared.deinit(gpa);
    if (job.authorization) |header| gpa.free(header);
    gpa.destroy(job);
}

/// Lets go of the job on screen. A worker still running keeps it alive until it
/// is done, and is told to stop.
fn dropUpload() void {
    const job = g_upload orelse return;
    g_upload = null;
    job.progress.cancel.store(true, .release);
    releaseUploadJob(job);
}

/// The job on screen when it is for `target`.
fn uploadJobFor(target: UploadTarget) ?*UploadJob {
    const job = g_upload orelse return null;
    return if (job.target == target) job else null;
}

fn uploadBusy(job: *const UploadJob) bool {
    return switch (job.phase()) {
        .preparing, .signing, .signed, .sending, .sent => true,
        .ready, .failed => false,
    };
}

/// Asks for a file and starts reading it. The dialog is the SDK's own, so the
/// reader sees the native one, and nothing is read or sent until they choose.
fn uploadPick(model: *Model, fx: *Effects, target: UploadTarget) void {
    if (model.is_guest()) return;
    if (g_upload) |job| {
        if (uploadBusy(job)) {
            setToast(model, "A picture is already on its way.");
            return;
        }
        dropUpload();
    }
    var buf: [1024]u8 = undefined;
    const path = pickPicturePath(fx, &buf) orelse return;
    startPrepare(model, target, path);
}

fn pickPicturePath(fx: *Effects, buf: []u8) ?[]const u8 {
    if (g_pick_path_override) |path| {
        const n = @min(path.len, buf.len);
        @memcpy(buf[0..n], path[0..n]);
        return buf[0..n];
    }
    if (builtin.is_test) return null;
    const services = fx.services orelse return null;
    const exts = [_][]const u8{ "png", "jpg", "jpeg", "gif", "webp" };
    const filters = [_]native_sdk.FileFilter{.{ .name = "Pictures", .extensions = &exts }};
    var out: [4096 * 4]u8 = undefined;
    const result = services.showOpenDialog(.{ .title = "Choose a picture", .filters = &filters }, &out) catch return null;
    if (result.count == 0) return null;
    // One path per line; one was asked for.
    const first = std.mem.sliceTo(result.paths, '\n');
    const n = @min(first.len, buf.len);
    @memcpy(buf[0..n], first[0..n]);
    return buf[0..n];
}

fn startPrepare(model: *Model, target: UploadTarget, path: []const u8) void {
    const gpa = std.heap.page_allocator;
    if (path.len == 0 or path.len > 1024) return;
    const job = gpa.create(UploadJob) catch return;
    job.* = .{ .target = target };
    @memcpy(job.path_buf[0..path.len], path);
    job.path_len = @intCast(path.len);
    model.upload_alt_buffer.clear();
    // The servers are named now, before anything is read from disk, so the card
    // that asks for a press has the same answer a later look would.
    const servers = uploadServers();
    job.server_count = @intCast(servers.count);
    job.from_list = servers.own;
    for (0..servers.count) |i| {
        job.server_lens[i] = servers.lens[i];
        @memcpy(job.servers[i][0..servers.lens[i]], servers.at(i));
    }
    g_upload = job;
    job.refs.store(2, .release);
    const thread = std.Thread.spawn(.{}, prepareWorker, .{job}) catch {
        job.refs.store(1, .release);
        job.fail("Plaza could not start reading the file.");
        return;
    };
    thread.detach();
}

fn prepareWorker(job: *UploadJob) void {
    defer releaseUploadJob(job);
    const gpa = std.heap.page_allocator;
    var threaded = std.Io.Threaded.init(gpa, .{});
    defer threaded.deinit();
    const io = threaded.io();
    // Read here, with the process's own access, and not through the SDK's file
    // effect: that one caps a read at 1 MiB, and since 0.9.1 it also refuses any
    // path outside the app's own folders unless the manifest asks for
    // `filesystem`. A picture is neither small nor in those folders, and the
    // reader just chose it.
    const file = std.Io.Dir.cwd().readFileAlloc(io, job.path(), gpa, .limited(blossom.max_picture_bytes + 1)) catch |err| {
        job.fail(switch (err) {
            error.StreamTooLong => "That file is larger than the 32 MB Plaza will upload.",
            error.FileNotFound => "That file is no longer there.",
            error.AccessDenied, error.PermissionDenied => "Plaza is not allowed to read that file.",
            else => "Plaza could not read that file.",
        });
        return;
    };
    const prepared = blossom.prepare(gpa, file) catch |err| {
        job.fail(switch (err) {
            error.TooLarge => "That file is larger than the 32 MB Plaza will upload.",
            error.NotAPicture => "That is not a picture Plaza can upload. It takes PNG, JPEG, GIF and WebP.",
            error.Damaged => "That picture's file looks damaged, so Plaza did not upload it.",
            error.OutOfMemory => "Plaza ran out of memory reading that file.",
        });
        return;
    };
    job.prepared = prepared;
    job.setPhase(.ready);
}

/// The Upload press: asks the signer for a token, which is the first thing that
/// leaves this process, and the first thing a bunker will ask its owner about.
fn uploadGo(model: *Model, fx: *Effects) void {
    const job = g_upload orelse return;
    if (job.phase() != .ready) return;
    if (activePubkey() == null) return;
    const prepared = job.prepared orelse return;
    // Said on the card, which stays up, and not as a toast: the composer draws
    // none, so a toast raised from there would turn up on the feed afterwards.
    job.message_len = 0;
    if (!signerReady() or uploadTokenOutstanding()) {
        const busy = "Your signer is busy with something else. Press Upload again in a moment.";
        @memcpy(job.message_buf[0..busy.len], busy);
        job.message_len = busy.len;
        return;
    }
    if (job.target == .note) {
        const alt = std.mem.trim(u8, model.upload_alt(), " \t\r\n");
        const n = @min(alt.len, job.alt_buf.len);
        @memcpy(job.alt_buf[0..n], alt[0..n]);
        job.alt_len = @intCast(n);
    }
    const gpa = std.heap.page_allocator;
    const created = nowSeconds();
    const tags = blossom.authTags(gpa, &prepared.sha256, prepared.bytes.len, created + blossom.auth_lifetime_s) catch {
        job.fail("Plaza ran out of memory.");
        return;
    };
    const content = gpa.dupe(u8, blossom.auth_content) catch {
        job.fail("Plaza ran out of memory.");
        return;
    };
    job.signing_since_s = created;
    job.setPhase(.signing);
    switch (g_signer_kind) {
        .remote => requestRemoteSignAs(.sign_upload_auth, gpa, created, blossom.auth_kind, tags, content, false, .none),
        .helper => requestHelperSign(fx, gpa, created, blossom.auth_kind, tags, content, false, .none),
    }
}

/// Whether a token asked for earlier, for a picture since put away, is still out
/// with the signer. Its answer, or its failure, lands on whichever upload is
/// signing when it arrives, and is not that upload's, so a new request waits
/// until it has come back. A bunker takes several requests at once, so being
/// ready is not enough to say so.
fn uploadTokenOutstanding() bool {
    if (g_helper_sign.active and g_helper_sign.upload_auth) return true;
    pendingLock();
    defer pendingUnlock();
    if (g_upload_sign_inbox.used) return true;
    for (&g_pending) |*slot| {
        if (slot.active and slot.method == .sign_upload_auth) return true;
    }
    return false;
}

/// Sends the same picture again after a failure, with the same token when there
/// is one, so a signer is not asked twice for the same file. A token near the end
/// of its hour is asked for again rather than sent to be refused.
fn uploadRetry(model: *Model, fx: *Effects) void {
    const job = g_upload orelse return;
    if (job.phase() != .failed or job.prepared == null) return;
    job.message_len = 0;
    job.outcome = null;
    job.progress.sent.store(0, .release);
    job.progress.cancel.store(false, .release);
    if (job.authorization) |header| {
        if (nowSeconds() < job.signing_since_s + blossom.auth_lifetime_s - 120) {
            job.setPhase(.signed);
            return;
        }
        std.heap.page_allocator.free(header);
        job.authorization = null;
    }
    job.setPhase(.ready);
    uploadGo(model, fx);
}

fn uploadCancel(model: *Model) void {
    _ = model;
    dropUpload();
}

/// Whether a token is the one that was asked for: an upload token for this file
/// and nothing else, that runs out within the hour. A signer that returns
/// anything wider has not signed what the reader saw: a second `x` would let a
/// server store a different file under this key, a `t delete` would let it
/// delete one, and a token with no expiry is good for as long as anyone keeps it.
fn tokenNamesFile(tags: []const nostr.event.Tag, sha256_hex: []const u8, now: i64) bool {
    var upload = false;
    var named = false;
    var expires = false;
    for (tags) |tag| {
        if (tag.len < 2) continue;
        if (std.mem.eql(u8, tag[0], "t")) {
            if (!std.mem.eql(u8, tag[1], "upload")) return false;
            upload = true;
        } else if (std.mem.eql(u8, tag[0], "x")) {
            if (!std.mem.eql(u8, tag[1], sha256_hex)) return false;
            named = true;
        } else if (std.mem.eql(u8, tag[0], "expiration")) {
            const at = std.fmt.parseInt(i64, tag[1], 10) catch return false;
            // Plaza asked for an hour from the moment it asked. A minute of
            // slack, and no more.
            if (at <= now or at > now + blossom.auth_lifetime_s + 60) return false;
            expires = true;
        }
    }
    return upload and named and expires;
}

/// A signed token arriving from the signer. UI thread. It becomes the header the
/// send carries, and goes nowhere else.
fn acceptUploadAuth(gpa: std.mem.Allocator, ev: nostr.event.Event) void {
    const job = g_upload orelse return;
    if (job.phase() != .signing) return;
    const prepared = job.prepared orelse return;
    const me = activePubkey() orelse return;
    if (ev.kind != blossom.auth_kind or !std.mem.eql(u8, &ev.pubkey, &me) or !tokenNamesFile(ev.tags, &prepared.sha256, nowSeconds())) {
        job.fail("Your signer returned something other than the upload request, so nothing was uploaded.");
        return;
    }
    const json = nostr.event.toJson(gpa, ev) catch {
        job.fail("Plaza ran out of memory.");
        return;
    };
    defer gpa.free(json);
    job.authorization = blossom.authorizationHeader(gpa, json) catch {
        job.fail("Plaza ran out of memory.");
        return;
    };
    job.setPhase(.signed);
}

/// The signer would not, or could not.
fn uploadSignFailed() void {
    const job = g_upload orelse return;
    if (job.phase() != .signing) return;
    job.fail("Your signer did not approve the upload, so nothing was uploaded.");
}

/// A token the bunker's listener thread has read, parked for the tick. The same
/// crossing a sealed private half takes, for the same reason: the listener must
/// not touch what the view is reading.
const UploadSignInbox = struct {
    used: bool = false,
    ok: bool = false,
    buf: [4096]u8 = undefined,
    len: u16 = 0,
};
var g_upload_sign_inbox: UploadSignInbox = .{};

/// Listener thread. `event_json` is the signed token, or null when the answer
/// was unusable.
fn parkUploadSign(event_json: ?[]const u8) void {
    pendingLock();
    defer pendingUnlock();
    g_upload_sign_inbox.used = true;
    g_upload_sign_inbox.ok = false;
    if (event_json) |json| {
        if (json.len <= g_upload_sign_inbox.buf.len) {
            @memcpy(g_upload_sign_inbox.buf[0..json.len], json);
            g_upload_sign_inbox.len = @intCast(json.len);
            g_upload_sign_inbox.ok = true;
        }
    }
}

/// UI thread: hands a parked token to the job it was for.
fn drainUploadSignInbox() void {
    var local: [4096]u8 = undefined;
    var len: usize = 0;
    var ok = false;
    {
        pendingLock();
        defer pendingUnlock();
        if (!g_upload_sign_inbox.used) return;
        ok = g_upload_sign_inbox.ok;
        len = g_upload_sign_inbox.len;
        if (ok) @memcpy(local[0..len], g_upload_sign_inbox.buf[0..len]);
        g_upload_sign_inbox = .{};
    }
    if (!ok) {
        uploadSignFailed();
        return;
    }
    const gpa = std.heap.page_allocator;
    var parsed = nostr.event.fromJson(gpa, local[0..len]) catch {
        uploadSignFailed();
        return;
    };
    defer parsed.deinit();
    acceptUploadAuth(gpa, parsed.value);
}

/// Called from the tick.
fn driveUpload(model: *Model) void {
    drainUploadSignInbox();
    const job = g_upload orelse return;
    switch (job.phase()) {
        .signed => startSend(job),
        .sent => finishUpload(model, job),
        .signing => if (nowSeconds() - job.signing_since_s > upload_sign_wait_s) {
            job.fail("Your signer did not answer, so nothing was uploaded.");
        },
        else => {},
    }
}

fn startSend(job: *UploadJob) void {
    const prepared = job.prepared orelse return;
    job.progress.total = prepared.bytes.len;
    job.setPhase(.sending);
    _ = job.refs.fetchAdd(1, .monotonic);
    const thread = std.Thread.spawn(.{}, sendWorker, .{job}) catch {
        _ = job.refs.fetchSub(1, .monotonic);
        job.fail("Plaza could not start the upload.");
        return;
    };
    thread.detach();
}

fn sendWorker(job: *UploadJob) void {
    defer releaseUploadJob(job);
    const gpa = std.heap.page_allocator;
    var threaded = std.Io.Threaded.init(gpa, .{});
    defer threaded.deinit();
    const io = threaded.io();
    const prepared = job.prepared orelse return;
    const header = job.authorization orelse return;
    var servers: [blossom.max_servers][]const u8 = undefined;
    for (0..job.server_count) |i| servers[i] = job.server(i);
    const out = blossom.upload(io, .{
        .servers = servers[0..job.server_count],
        .bytes = prepared.bytes,
        .mime = prepared.format.mime(),
        .ext = prepared.format.ext(),
        .sha256_hex = &prepared.sha256,
        .authorization = header,
    }, &job.progress);
    job.outcome = out;
    switch (out) {
        .ok => job.setPhase(.sent),
        .failed => |why| job.fail(why.text()),
        // The reader has already let go of it.
        .cancelled => {},
    }
}

/// A server took the picture. Puts its address where it was asked for.
fn finishUpload(model: *Model, job: *UploadJob) void {
    const outcome = job.outcome orelse return;
    const ok = switch (outcome) {
        .ok => |o| o,
        else => return,
    };
    const url = ok.descriptor.url();
    switch (job.target) {
        .note => {
            if (!appendPictureToDraft(model, url)) {
                job.fail("It uploaded, but your note has no room left for its address.");
                return;
            }
            rememberUploaded(job, ok.descriptor);
        },
        .avatar, .banner => {
            const buffer = if (job.target == .avatar) &model.profile_picture_buffer else &model.profile_banner_buffer;
            if (url.len > buffer.storage.len) {
                job.fail("It uploaded, but its address is too long for a profile field.");
                return;
            }
            buffer.set(url);
            // The reader has now chosen this value, so the field no longer
            // stands for one that did not fit.
            if (job.target == .avatar) model.profile_picture_long = false else model.profile_banner_long = false;
            g_profile_upload_unsaved = true;
        },
    }
    dropUpload();
}

/// Appends `url` to the draft on a line of its own. False when it will not fit.
fn appendPictureToDraft(model: *Model, url: []const u8) bool {
    const text = model.draft();
    var buf: [compose_capacity]u8 = undefined;
    const lead: []const u8 = if (text.len == 0 or text[text.len - 1] == '\n') "" else "\n";
    const written = std.fmt.bufPrint(&buf, "{s}{s}{s}\n", .{ text, lead, url }) catch return false;
    model.draft_buffer = @TypeOf(model.draft_buffer).init(written);
    g_draft_dirty = true;
    return true;
}

pub fn appendPictureToDraftForTest(model: *Model, url: []const u8) bool {
    return appendPictureToDraft(model, url);
}

// What the uploader knew about a picture it sent, kept so the note that carries
// its address can say so. Only an uploader has the hash, the dimensions and the
// blurhash before anyone has fetched the file.
const UploadedPicture = struct {
    used: bool = false,
    url_buf: [512]u8 = undefined,
    url_len: u16 = 0,
    mime: []const u8 = "",
    sha_buf: [64]u8 = undefined,
    size: usize = 0,
    width: u32 = 0,
    height: u32 = 0,
    blur_buf: [blossom.max_blurhash_len]u8 = undefined,
    blur_len: u8 = 0,
    alt_buf: [200]u8 = undefined,
    alt_len: u8 = 0,

    fn url(self: *const UploadedPicture) []const u8 {
        return self.url_buf[0..self.url_len];
    }
};
var g_uploaded: [8]UploadedPicture = [_]UploadedPicture{.{}} ** 8;
var g_uploaded_next: usize = 0;

fn rememberUploaded(job: *const UploadJob, d: blossom.Descriptor) void {
    const prepared = job.prepared orelse return;
    var entry: UploadedPicture = .{ .used = true, .mime = prepared.format.mime() };
    @memcpy(entry.url_buf[0..d.url().len], d.url());
    entry.url_len = @intCast(d.url().len);
    // What the server says it stored, when it says. If that is not the file that
    // was sent, the size, dimensions and blurhash describe a different file and
    // are left out; the hash is the server's, because that is what the address
    // serves.
    const same = if (d.sha256()) |theirs| std.mem.eql(u8, theirs, &prepared.sha256) else true;
    @memcpy(&entry.sha_buf, d.sha256() orelse &prepared.sha256);
    if (same) {
        entry.size = prepared.bytes.len;
        entry.width = prepared.width;
        entry.height = prepared.height;
        const blur = prepared.blurhashText();
        @memcpy(entry.blur_buf[0..blur.len], blur);
        entry.blur_len = @intCast(blur.len);
    }
    @memcpy(entry.alt_buf[0..job.alt_len], job.alt());
    entry.alt_len = job.alt_len;
    g_uploaded[g_uploaded_next % g_uploaded.len] = entry;
    g_uploaded_next +%= 1;
}

fn uploadedPictureFor(url: []const u8) ?*const UploadedPicture {
    for (&g_uploaded) |*entry| {
        if (entry.used and std.mem.eql(u8, entry.url(), url)) return entry;
    }
    return null;
}

/// The full `imeta` tag for a picture this app uploaded, or null for any other.
fn uploadedImeta(gpa: std.mem.Allocator, url: []const u8) ?[]const []const u8 {
    const entry = uploadedPictureFor(url) orelse return null;
    return blossom.imetaTag(gpa, url, entry.mime, &entry.sha_buf, entry.size, entry.width, entry.height, entry.blur_buf[0..entry.blur_len], entry.alt_buf[0..entry.alt_len]) catch null;
}

/// Records a picture as if it had just been uploaded. For tests.
pub fn rememberUploadedForTest(url: []const u8, mime: []const u8, sha_hex: []const u8, size: usize, width: u32, height: u32, hash: []const u8, alt: []const u8) void {
    var entry: UploadedPicture = .{ .used = true, .mime = mime, .size = size, .width = width, .height = height };
    @memcpy(entry.url_buf[0..url.len], url);
    entry.url_len = @intCast(url.len);
    @memcpy(entry.sha_buf[0..sha_hex.len], sha_hex);
    @memcpy(entry.blur_buf[0..hash.len], hash);
    entry.blur_len = @intCast(hash.len);
    @memcpy(entry.alt_buf[0..alt.len], alt);
    entry.alt_len = @intCast(alt.len);
    g_uploaded[g_uploaded_next % g_uploaded.len] = entry;
    g_uploaded_next +%= 1;
}

pub fn forgetUploadedForTest() void {
    g_uploaded = [_]UploadedPicture{.{}} ** 8;
    g_uploaded_next = 0;
}

// Test seams for the upload: the file dialog stood in for, the phases read, and
// the stages that happen on a thread or in a signer driven by hand.

pub fn setPickPathForTest(path: ?[]const u8) void {
    g_pick_path_override = path;
}

pub fn uploadPickForTest(model: *Model, fx: *Effects, target: u8) void {
    uploadPick(model, fx, std.enums.fromInt(UploadTarget, target) orelse return);
}

pub fn uploadGoForTest(model: *Model, fx: *Effects) void {
    uploadGo(model, fx);
}

pub fn uploadRetryForTest(model: *Model, fx: *Effects) void {
    uploadRetry(model, fx);
}

pub fn uploadCancelForTest(model: *Model) void {
    uploadCancel(model);
}

pub fn driveUploadForTest(model: *Model) void {
    driveUpload(model);
}

pub fn dropUploadForTest() void {
    dropUpload();
}

/// The phase of the job on screen, or "none".
pub fn uploadStateForTest() []const u8 {
    const job = g_upload orelse return "none";
    return @tagName(job.phase());
}

/// Why the job failed, or empty.
pub fn uploadMessageForTest() []const u8 {
    const job = g_upload orelse return "";
    return job.message();
}

/// Moves the job's token back in time, as if it had been signed `seconds` ago.
pub fn ageUploadTokenForTest(seconds: i64) void {
    const job = g_upload orelse return;
    job.signing_since_s -= seconds;
}

pub fn uploadSentBytesForTest() usize {
    const job = g_upload orelse return 0;
    return job.progress.sent.load(.acquire);
}

/// Makes `urls` this account's server list, as if a kind:10063 had been read.
pub fn setBlossomServersForTest(urls: []const []const u8) void {
    const gpa = std.heap.page_allocator;
    const tags = gpa.alloc(nostr.event.Tag, urls.len) catch return;
    for (urls, 0..) |url, i| tags[i] = gpa.dupe([]const u8, &.{ "server", url }) catch return;
    setBlossomServers(tags, 1);
}

pub fn forgetBlossomForTest() void {
    forgetBlossom();
}

pub fn loadBlossomFromStoreForTest() void {
    loadBlossomFromStore();
}

pub fn ingestAndPublishForTest(gpa: std.mem.Allocator, ev: nostr.event.Event) void {
    ingestAndPublish(gpa, ev, null, .none);
}

pub fn clearLastPublishedForTest() void {
    g_last_published = null;
    g_last_published_tags = &.{};
}

pub fn ownRecordCreatedAtForTest(kind: u16) i64 {
    return ownRecordCreatedAt(kind);
}

/// A token as the bunker's listener thread would park it.
pub fn parkUploadSignForTest(event_json: ?[]const u8) void {
    parkUploadSign(event_json);
}

pub fn tokenNamesFileForTest(tags: []const nostr.event.Tag, sha256_hex: []const u8, now: i64) bool {
    return tokenNamesFile(tags, sha256_hex, now);
}

/// The clock a token's expiry is checked against.
pub fn nowSecondsForTest() i64 {
    return nowSeconds();
}

/// Says the probe found nothing on any relay, for the account that is signed in.
pub fn markBlossomProbeCleanForTest(clean: bool) void {
    lockBlossom();
    g_blossom_probe_for = activePubkey();
    unlockBlossom();
    g_blossom_probe_state.store(if (clean) probe_clean else probe_unknown, .release);
}

// ------------------------------------------------------- the reader's servers

/// The media servers uploads go to, with where they came from.
const UploadServers = struct {
    urls: [blossom.max_servers][blossom.max_server_len]u8 = undefined,
    lens: [blossom.max_servers]u8 = [_]u8{0} ** blossom.max_servers,
    count: usize = 0,
    /// The reader's own list, rather than the built-in fallback.
    own: bool = false,

    fn at(self: *const UploadServers, i: usize) []const u8 {
        return self.urls[i][0..self.lens[i]];
    }
};

var g_blossom_lock = std.atomic.Value(bool).init(false);
var g_blossom_owner: ?[32]u8 = null;
var g_blossom_urls: [blossom.max_servers][blossom.max_server_len]u8 = undefined;
var g_blossom_lens: [blossom.max_servers]u8 = [_]u8{0} ** blossom.max_servers;
var g_blossom_count: usize = 0;
/// When the list held here was signed, or 0 when this account has none.
var g_blossom_created_at: i64 = 0;

fn lockBlossom() void {
    while (g_blossom_lock.cmpxchgWeak(false, true, .acquire, .monotonic) != null) std.atomic.spinLoopHint();
}

fn unlockBlossom() void {
    g_blossom_lock.store(false, .release);
}

/// Whether the list held here is the signed-in account's.
fn blossomIsOwned() bool {
    const pk = activePubkey() orelse return false;
    const owner = g_blossom_owner orelse return false;
    return std.mem.eql(u8, &owner, &pk);
}

/// Where a picture goes: the reader's own list when they have published one,
/// else the two built-in servers.
fn uploadServers() UploadServers {
    var out: UploadServers = .{};
    {
        lockBlossom();
        defer unlockBlossom();
        if (blossomIsOwned() and g_blossom_count > 0) {
            out.own = true;
            out.count = g_blossom_count;
            for (0..g_blossom_count) |i| {
                out.lens[i] = g_blossom_lens[i];
                @memcpy(out.urls[i][0..g_blossom_lens[i]], g_blossom_urls[i][0..g_blossom_lens[i]]);
            }
            return out;
        }
    }
    for (blossom.default_servers) |url| {
        var buf: [blossom.max_server_len]u8 = undefined;
        const norm = blossom.normalizeServer(&buf, url) orelse continue;
        out.lens[out.count] = @intCast(norm.len);
        @memcpy(out.urls[out.count][0..norm.len], norm);
        out.count += 1;
    }
    return out;
}

fn setBlossomServers(tags: []const nostr.event.Tag, created_at: i64) void {
    const pk = activePubkey() orelse return;
    var urls: [blossom.max_servers][blossom.max_server_len]u8 = undefined;
    var lens: [blossom.max_servers]u8 = undefined;
    const n = blossom.serversFromTags(tags, &urls, &lens);
    lockBlossom();
    defer unlockBlossom();
    g_blossom_urls = urls;
    g_blossom_lens = lens;
    g_blossom_count = n;
    g_blossom_owner = pk;
    g_blossom_created_at = created_at;
}

fn forgetBlossom() void {
    lockBlossom();
    defer unlockBlossom();
    g_blossom_owner = null;
    g_blossom_count = 0;
    g_blossom_created_at = 0;
}

fn loadBlossomFromStore() void {
    const gpa = std.heap.page_allocator;
    const own = ownRecordJson(gpa, blossom_list_kind) orelse return;
    defer freeOwnProfile(gpa, own);
    setBlossomServers(own.tags, own.created_at);
}

/// A server list arriving from a relay. This reader's own only, and only a newer
/// one than the one held.
pub fn ingestBlossomList(ev: nostr.event.Event) void {
    const me = activePubkey() orelse return;
    if (!std.mem.eql(u8, &me, &ev.pubkey)) return;
    // Under the lock: this runs on whichever relay thread delivered the list,
    // while the UI thread reads the same fields.
    lockBlossom();
    const older = blossomIsOwned() and ev.created_at < g_blossom_created_at;
    unlockBlossom();
    if (older) return;
    loadBlossomFromStore();
}

/// Whether this account's own server list is held here.
fn haveOwnBlossomList() bool {
    lockBlossom();
    defer unlockBlossom();
    return blossomIsOwned() and g_blossom_created_at > 0;
}

// Whether a list that is not here is a list that does not exist. Not a question
// the local store can answer: it holds no row both when there is none and when
// the fetch has not landed. So every relay the reader reads from is asked once,
// and only if ALL of them answer without one is the account treated as having
// none. One that is down, slow or write-only proves nothing about the others.
var g_blossom_probe_state = std.atomic.Value(u8).init(0);
var g_blossom_probe_for: ?[32]u8 = null;
const probe_none: u8 = 0;
const probe_asking: u8 = 1;
const probe_clean: u8 = 2;
const probe_unknown: u8 = 3;

/// Asks the relays whether this account has a server list. Once per account,
/// unless the last round could not tell: a relay that was down a minute ago may
/// be up now, and until it answers the list cannot be edited.
fn startBlossomProbe() void {
    if (!relayFetchAllowed()) return;
    const pk = activePubkey() orelse return;
    {
        lockBlossom();
        defer unlockBlossom();
        if (!blossomProbeWantedUnlocked(pk)) return;
        g_blossom_probe_for = pk;
    }
    g_blossom_probe_state.store(probe_asking, .release);
    const thread = std.Thread.spawn(.{}, blossomProbeWorker, .{pk}) catch {
        g_blossom_probe_state.store(probe_unknown, .release);
        return;
    };
    thread.detach();
}

/// Whether `pk` should be asked about. Called with the blossom lock held.
fn blossomProbeWantedUnlocked(pk: [32]u8) bool {
    const asked = g_blossom_probe_for orelse return true;
    if (!std.mem.eql(u8, &asked, &pk)) return true;
    return g_blossom_probe_state.load(.acquire) == probe_unknown;
}

pub fn blossomProbeWantedForTest() bool {
    const pk = activePubkey() orelse return false;
    lockBlossom();
    defer unlockBlossom();
    return blossomProbeWantedUnlocked(pk);
}

/// Whether one relay's reply to the probe answers it. EOSE does: that relay
/// looked and has sent everything it holds. CLOSED does not: it is the relay
/// declining to look (auth-required, rate-limited, restricted), and a list kept
/// there is exactly as possible as before it said so.
fn probeReplyAnswers(tag: std.meta.Tag(nostr.message.RelayMessage)) bool {
    return tag == .eose;
}

pub fn probeReplyAnswersForTest(tag: std.meta.Tag(nostr.message.RelayMessage)) bool {
    return probeReplyAnswers(tag);
}

fn blossomProbeWorker(pk: [32]u8) void {
    var asked: usize = 0;
    var answered: usize = 0;
    var found = false;
    defer {
        // An answer about one account is not an answer about another.
        lockBlossom();
        const still_current = if (g_blossom_probe_for) |current| std.mem.eql(u8, &current, &pk) else false;
        unlockBlossom();
        if (still_current) {
            g_blossom_probe_state.store(if (asked > 0 and answered == asked and !found) probe_clean else probe_unknown, .release);
        }
    }
    const gpa = std.heap.page_allocator;
    var threaded = std.Io.Threaded.init(gpa, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var signer = nostr.keys.Signer.init();
    defer signer.deinit();

    const kinds = [_]u16{blossom_list_kind};
    const authors = [_][32]u8{pk};
    const filters = [_]nostr.filter.Filter{.{ .authors = &authors, .kinds = &kinds, .limit = 1 }};
    for (0..relaySlots()) |ri| {
        var url_buf: [96]u8 = undefined;
        const entry = relaySnapshot(ri, &url_buf) orelse continue;
        if (!entry.read) continue;
        asked += 1;
        var relay = nostr.relay.dial(gpa, io, entry.url) catch continue;
        defer relay.deinit();
        const watched = watchOneShot(io, relay, one_shot_budget_ms);
        defer releaseOneShot(watched);
        relay.subscribe("plaza-bl", &filters) catch continue;
        var seen: usize = 0;
        while (seen < 32) : (seen += 1) {
            var msg = (relay.receive() catch break) orelse break;
            defer msg.deinit();
            switch (msg.value) {
                .event => |e| {
                    const result = plazaIngest(gpa, e.event, .{ .verify_with = signer }) catch continue;
                    if (result == .invalid) continue;
                    if (e.event.kind != blossom_list_kind) continue;
                    if (!std.mem.eql(u8, &e.event.pubkey, &pk)) continue;
                    found = true;
                },
                .eose, .closed => {
                    if (probeReplyAnswers(std.meta.activeTag(msg.value))) answered += 1;
                    break;
                },
                else => continue,
            }
        }
    }
}

fn blossomProbeAsking() bool {
    return g_blossom_probe_state.load(.acquire) == probe_asking;
}

/// Whether the account's server list may be published. Either it is here, so an
/// edit splices onto it and loses nothing, or the key was made in this app a
/// moment ago, or every relay the reader writes to has finished without one, in
/// which case the first Add asks before it starts a list.
fn canWriteBlossomList() bool {
    if (activePubkey() == null) return false;
    if (haveOwnBlossomList()) return true;
    if (g_identity_minted_here) return true;
    return ownRelaysAllFinished();
}

pub const BlossomWrite = enum {
    published,
    /// Already there, or already gone.
    nothing_to_do,
    /// A signature is already out. One key signs one thing at a time.
    signer_busy,
    /// This account's list has not been read back, so publishing one would
    /// replace whatever is really out there.
    no_list_yet,
    /// The list is as long as Plaza sends to.
    full,
    failed,
};

/// Adds `add` to, or removes `remove` from, this reader's kind:10063. Either is
/// a normalized server address.
///
/// A near-copy of `writeBookmark`'s discipline, applied to a smaller list: the
/// RAW previous record is read, every tag and the content are carried forward
/// whole, only the one server moves, and nothing is written over a record that
/// has not been read.
fn writeBlossomServers(fx: *Effects, add_raw: ?[]const u8, remove_raw: ?[]const u8) BlossomWrite {
    if (!signerReady()) return .signer_busy;
    _ = activePubkey() orelse return .failed;
    const gpa = std.heap.page_allocator;
    // Compared and written in one spelling, whatever the caller was handed.
    var add_buf: [blossom.max_server_len]u8 = undefined;
    var remove_buf: [blossom.max_server_len]u8 = undefined;
    const add: ?[]const u8 = if (add_raw) |raw| (blossom.normalizeServer(&add_buf, raw) orelse return .failed) else null;
    const remove: ?[]const u8 = if (remove_raw) |raw| (blossom.normalizeServer(&remove_buf, raw) orelse return .failed) else null;

    var previous: ?OwnProfile = null;
    if (ownRecordJson(gpa, blossom_list_kind)) |own| previous = own;
    defer if (previous) |prev| freeOwnProfile(gpa, prev);
    // With nothing stored to splice onto, only proof that there is nothing to
    // lose licenses a write. A list held in memory is not that proof: it is a
    // copy of a stored record, and a stored record that has gone is the case
    // where writing from nothing replaces it with one server. Nor is every relay
    // in the pool answering without one: on a cold import the pool is the
    // bootstrap relays, and the list lives on the relays the reader writes to.
    // The proof is the follow list's: the key was made here, or the reader said
    // to start one after every relay they write to had finished without it, and
    // that yes is spent by this write.
    if (previous == null and !g_identity_minted_here and !takeFresh(.media_servers)) return .no_list_yet;

    const base_tags: []const nostr.event.Tag = if (previous) |prev| prev.tags else &.{};
    const base_content: []const u8 = if (previous) |prev| prev.json else "";
    const base_created_at: i64 = if (previous) |prev| prev.created_at else 0;

    var tags = std.ArrayList(nostr.event.Tag).empty;
    var handed_off = false;
    defer if (!handed_off) {
        for (tags.items) |tag| {
            for (tag) |field| gpa.free(field);
            gpa.free(tag);
        }
        tags.deinit(gpa);
    };
    var found = false;
    var dropped = false;
    var usable: usize = 0;
    for (base_tags) |tag| {
        if (tag.len >= 2 and std.mem.eql(u8, tag[0], "server")) {
            var buf: [blossom.max_server_len]u8 = undefined;
            if (blossom.normalizeServer(&buf, tag[1])) |norm| {
                if (add) |a| {
                    if (std.mem.eql(u8, norm, a)) found = true;
                }
                if (remove) |r| {
                    if (std.mem.eql(u8, norm, r)) {
                        dropped = true;
                        continue;
                    }
                }
                usable += 1;
            }
        }
        // Everything else, and any server this app cannot read, goes back out
        // exactly as it came in.
        const copy = gpa.alloc([]const u8, tag.len) catch return .failed;
        for (tag, 0..) |field, i| copy[i] = gpa.dupe(u8, field) catch return .failed;
        tags.append(gpa, copy) catch return .failed;
    }
    if (add) |a| {
        if (found) return .nothing_to_do;
        if (usable >= blossom.max_servers) return .full;
        const copy = gpa.alloc([]const u8, 2) catch return .failed;
        copy[0] = gpa.dupe(u8, "server") catch return .failed;
        copy[1] = gpa.dupe(u8, a) catch return .failed;
        tags.append(gpa, copy) catch return .failed;
    } else if (!dropped) {
        return .nothing_to_do;
    }

    const owned_tags = tags.toOwnedSlice(gpa) catch return .failed;
    handed_off = true;
    const content = gpa.dupe(u8, base_content) catch return .failed;
    const created = @max(@max(nowSeconds(), ownRecordCreatedAt(blossom_list_kind) + 1), base_created_at + 1);
    g_blossom_saving = created;
    signAndPublish(fx, gpa, created, blossom_list_kind, owned_tags, content, false, .none, null);
    return .published;
}

/// The stamp of a server list that has been sent to be signed and has not come
/// back yet, or 0.
var g_blossom_saving: i64 = 0;

pub fn writeBlossomServersForTest(fx: *Effects, add: ?[]const u8, remove: ?[]const u8) BlossomWrite {
    return writeBlossomServers(fx, add, remove);
}

pub fn blossomServersForTest(out: *[blossom.max_servers][]const u8) usize {
    const s = uploadServers();
    for (0..s.count) |i| out[i] = std.heap.page_allocator.dupe(u8, s.at(i)) catch "";
    return s.count;
}

pub fn blossomOwnListForTest() bool {
    return uploadServers().own;
}

fn blossomAdd(model: *Model, fx: *Effects) void {
    const typed = std.mem.trim(u8, model.blossom_buffer.text(), " \t\r\n");
    model.blossom_error = .none;
    var buf: [blossom.max_server_len]u8 = undefined;
    const norm = blossom.normalizeServer(&buf, typed) orelse {
        model.blossom_error = .invalid;
        return;
    };
    // No list held and every write relay finished without one: the reader is
    // asked before a list of one is published over anything Plaza has not seen.
    if (askFreshFirst(model, FreshAsk.mediaServer(norm))) return;
    sayBlossomAdd(model, writeBlossomServers(fx, norm, null));
}

/// What an Add did, under the field.
fn sayBlossomAdd(model: *Model, outcome: BlossomWrite) void {
    switch (outcome) {
        .published => model.blossom_buffer.clear(),
        .nothing_to_do => model.blossom_buffer.clear(),
        .signer_busy => model.blossom_error = .busy,
        .no_list_yet => model.blossom_error = .unread,
        .full => model.blossom_error = .full,
        .failed => model.blossom_error = .failed,
    }
}

fn blossomRemove(model: *Model, fx: *Effects, index: u8) void {
    model.blossom_error = .none;
    const servers = uploadServers();
    // Only the reader's own list has rows to remove; the fallback is not theirs.
    if (!servers.own or index >= servers.count) return;
    switch (writeBlossomServers(fx, null, servers.at(index))) {
        .published, .nothing_to_do => {},
        .signer_busy => model.blossom_error = .busy,
        .no_list_yet => model.blossom_error = .unread,
        .full => model.blossom_error = .full,
        .failed => model.blossom_error = .failed,
    }
}

const BlossomEdit = enum { none, invalid, busy, unread, full, failed };

// -------------------------------------------------------------------- views

/// What sits in the composer, or beside a profile field, for putting a picture
/// in: a button while there is nothing going on, and the card for the job while
/// there is.
fn uploadStrip(ui: *AppUi, model: *const Model, target: UploadTarget) AppUi.Node {
    const p = theme.palette;
    if (uploadJobFor(target)) |job| return uploadCard(ui, model, job);
    const servers = uploadServers();
    return ui.row(.{ .cross = .center, .gap = 0 }, .{
        hgap(ui, 2),
        ui.button(.{ .size = .sm, .variant = .ghost, .on_press = Msg{ .upload_pick = @intFromEnum(target) } }, "Add picture"),
        hgap(ui, 8),
        ui.paragraph(
            .{ .style = .{ .foreground = p.text_dim } },
            &.{.{ .text = ui.fmt("Uploads to {s}", .{blossom.serverLabel(servers.at(0))}), .monospace = true, .scale = mono_meta_scale }},
        ),
    });
}

/// Where the servers are said, in the reader's terms. Named before anything is
/// sent, and the same words whether they chose the servers or the app did.
fn uploadWhere(ui: *AppUi, job: *const UploadJob) []const u8 {
    if (job.server_count == 0) return "No media server is set up.";
    const first = blossom.serverLabel(job.server(0));
    if (job.from_list) {
        if (job.server_count == 1) return ui.fmt("Uploads to {s}, from your server list.", .{first});
        return ui.fmt("Uploads to {s}, from your server list. If it refuses, {s} is next.", .{ first, blossom.serverLabel(job.server(1)) });
    }
    if (job.server_count == 1) return ui.fmt("You have no server list, so this goes to {s}.", .{first});
    return ui.fmt("You have no server list, so this goes to {s}, then {s} if it refuses. Settings has the list.", .{ first, blossom.serverLabel(job.server(1)) });
}

fn uploadCard(ui: *AppUi, model: *const Model, job: *UploadJob) AppUi.Node {
    const p = theme.palette;
    var rows: [9]AppUi.Node = undefined;
    var n: usize = 0;
    const name = job.fileName();
    switch (job.phase()) {
        .preparing => {
            rows[n] = uploadLine(ui, ui.fmt("Reading {s}...", .{name}), p.text_secondary);
            n += 1;
            rows[n] = uploadButtons(ui, null, "", "Cancel");
            n += 1;
        },
        .ready => {
            const prepared = job.prepared.?;
            var detail: []const u8 = byteSize(ui.arena, @intCast(@min(prepared.bytes.len, std.math.maxInt(u32))));
            // A profile sheet is a fixed card with no room to spare, so its
            // version of this is the short one.
            if (prepared.width > 0 and prepared.height > 0 and job.target == .note) detail = ui.fmt("{s}, {d} x {d}", .{ detail, prepared.width, prepared.height });
            rows[n] = uploadLine(ui, ui.fmt("{s}  {s}", .{ name, detail }), p.text_primary);
            n += 1;
            rows[n] = uploadNote(ui, uploadWhere(ui, job), p.text_muted);
            n += 1;
            if (prepared.stripped and job.target == .note) {
                rows[n] = uploadNote(ui, "Location and camera details in the file are removed first.", p.text_faint);
                n += 1;
            }
            if (job.message().len > 0) {
                rows[n] = uploadNote(ui, job.message(), p.status_warning_text);
                n += 1;
            }
            if (job.target == .note) {
                rows[n] = ui.el(.textarea, .{
                    .text = model.upload_alt(),
                    .placeholder = "Describe the picture (optional)",
                    .on_input = AppUi.inputMsg(.upload_alt_edit),
                    .height = 34,
                    .semantics = .{ .label = "Picture description" },
                }, .{});
                n += 1;
            }
            rows[n] = uploadButtons(ui, Msg.upload_go, "Upload", "Cancel");
            n += 1;
        },
        .signing => {
            rows[n] = uploadLine(ui, "Waiting for your signer to approve the upload...", p.text_secondary);
            n += 1;
            rows[n] = uploadButtons(ui, null, "", "Cancel");
            n += 1;
        },
        .signed, .sending, .sent => {
            const total = @max(job.progress.total, 1);
            const sent = @min(job.progress.sent.load(.acquire), total);
            const percent: usize = sent * 100 / total;
            const at: usize = @min(job.progress.server.load(.acquire), @max(job.server_count, 1) - 1);
            rows[n] = uploadLine(ui, ui.fmt("Uploading {s} to {s}", .{ name, blossom.serverLabel(job.server(at)) }), p.text_secondary);
            n += 1;
            rows[n] = uploadBar(ui, percent);
            n += 1;
            rows[n] = uploadButtons(ui, null, "", "Cancel");
            n += 1;
        },
        .failed => {
            rows[n] = uploadNote(ui, if (job.message().len > 0) job.message() else "The upload did not work.", p.status_warning_text);
            n += 1;
            // The file read fine and the failure was the network or a server:
            // the same picture can be sent again without choosing it again.
            const sent_ok = if (job.outcome) |o| o == .ok else false;
            const again: ?Msg = if (job.prepared != null and !sent_ok) Msg.upload_retry else null;
            rows[n] = uploadButtons(ui, again, "Try again", "Dismiss");
            n += 1;
        },
    }
    return ui.el(.card, .{
        .padding = 12,
        .style = .{ .background = p.surface_settings_card, .border = p.border_chip, .radius = settings_card_radius, .stroke_width = 1 },
        .semantics = .{ .label = "Picture upload" },
    }, .{
        ui.column(.{ .gap = 8, .grow = 1 }, .{rows[0..n]}),
    });
}

fn uploadLine(ui: *AppUi, text: []const u8, color: canvas.Color) AppUi.Node {
    return ui.paragraph(.{ .wrap = true, .style = .{ .foreground = color } }, &.{.{ .text = text, .scale = menu_scale }});
}

fn uploadNote(ui: *AppUi, text: []const u8, color: canvas.Color) AppUi.Node {
    return ui.paragraph(.{ .wrap = true, .style = .{ .foreground = color } }, &.{.{ .text = text, .scale = mono_hint_scale }});
}

/// A thin bar and the number beside it.
fn uploadBar(ui: *AppUi, percent: usize) AppUi.Node {
    const p = theme.palette;
    const track: f32 = 240;
    const fill = track * @as(f32, @floatFromInt(@min(percent, 100))) / 100.0;
    return ui.row(.{ .cross = .center, .gap = 0 }, .{
        ui.row(.{ .gap = 0, .width = track, .height = 4 }, .{
            if (fill >= 1)
                ui.el(.panel, .{ .width = fill, .height = 4, .padding = 0.01, .style = .{ .background = p.accent, .radius = 2, .stroke_width = 0 } }, .{})
            else
                ui.spacer(0),
            ui.el(.panel, .{ .width = @max(track - fill, 0.01), .height = 4, .padding = 0.01, .style = .{ .background = p.border_control, .radius = 2, .stroke_width = 0 } }, .{}),
        }),
        hgap(ui, 10),
        ui.paragraph(.{ .style = .{ .foreground = p.text_muted } }, &.{.{ .text = ui.fmt("{d}%", .{percent}), .monospace = true, .scale = mono_meta_scale }}),
    });
}

fn uploadButtons(ui: *AppUi, primary: ?Msg, primary_label: []const u8, cancel_label: []const u8) AppUi.Node {
    return ui.row(.{ .gap = 8, .cross = .center }, .{
        if (primary) |msg|
            ui.button(.{ .size = .sm, .variant = .primary, .on_press = msg }, primary_label)
        else
            ui.spacer(0),
        ui.button(.{ .size = .sm, .variant = .ghost, .on_press = Msg.upload_cancel }, cancel_label),
        ui.spacer(1),
    });
}

/// The label row of a profile field that can take a picture: the name, and on
/// the right the way to upload one. While a job for this field is on screen, the
/// card stands where the text box was.
fn profilePictureField(ui: *AppUi, model: *const Model, label: []const u8, value: []const u8, comptime tag: std.meta.Tag(Msg), target: UploadTarget) AppUi.Node {
    const p = theme.palette;
    if (uploadJobFor(target)) |job| {
        return ui.column(.{ .gap = 0 }, .{
            ui.paragraph(.{ .style = .{ .foreground = p.text_label } }, &.{.{ .text = label, .monospace = true, .scale = mono_meta_scale }}),
            vgap(ui, 5),
            uploadCard(ui, model, job),
        });
    }
    return ui.column(.{ .gap = 0 }, .{
        ui.row(.{ .cross = .center, .gap = 0 }, .{
            ui.paragraph(.{ .style = .{ .foreground = p.text_label } }, &.{.{ .text = label, .monospace = true, .scale = mono_meta_scale }}),
            ui.spacer(1),
            settingsLink(ui, "Upload...", Msg{ .upload_pick = @intFromEnum(target) }),
        }),
        vgap(ui, 5),
        ui.el(.textarea, .{
            .text = value,
            .placeholder = "https://",
            .on_input = AppUi.inputMsg(tag),
            .on_submit = Msg.profile_save,
            .height = 34,
            .semantics = .{ .label = label },
        }, .{}),
    });
}

/// Settings: the servers pictures go to, and how to change them.
fn mediaServersCard(ui: *AppUi, model: *const Model) AppUi.Node {
    const p = theme.palette;
    const servers = uploadServers();
    const rows = ui.arena.alloc(AppUi.Node, servers.count + 4) catch return ui.spacer(0);
    var n: usize = 0;
    rows[n] = ui.paragraph(
        .{ .wrap = true, .style = .{ .foreground = p.text_faint } },
        &.{.{ .text = if (servers.own)
            "A picture goes to the first of these that takes it."
        else
            "You have not published a list, so a picture goes to the first of these that takes it. Adding one publishes your list.", .scale = mono_hint_scale }},
    );
    n += 1;
    rows[n] = vgap(ui, 10);
    n += 1;
    for (0..servers.count) |i| {
        rows[n] = ui.column(.{ .gap = 0 }, .{
            ui.row(.{ .cross = .center, .gap = 0 }, .{
                ui.paragraph(.{ .style = .{ .foreground = p.text_secondary } }, &.{.{ .text = blossom.serverLabel(servers.at(i)), .monospace = true, .scale = mono_row_scale }}),
                ui.spacer(1),
                if (servers.own)
                    ui.el(.list_item, .{
                        .padding = 0.01,
                        .height = 20,
                        .cross = .center,
                        .on_press = Msg{ .blossom_remove = @intCast(i) },
                        .style = .{ .radius = 4 },
                        .semantics = .{ .role = .button, .label = ui.fmt("Remove {s}", .{servers.at(i)}), .focusable = true },
                    }, .{
                        hgap(ui, 4),
                        ui.icon(.{ .width = 11, .height = 11, .style = .{ .foreground = p.text_dim } }, "x"),
                        hgap(ui, 4),
                    })
                else
                    ui.paragraph(.{ .style = .{ .foreground = p.text_dim } }, &.{.{ .text = "built in", .monospace = true, .scale = mono_chip_scale }}),
            }),
            vgap(ui, 9),
        });
        n += 1;
    }
    rows[n] = ui.inputGroup(
        .{ .semantics = .{ .label = "Add a media server" } },
        ui.el(.textarea, .{
            .text = model.blossom_draft(),
            .placeholder = "https://",
            .on_input = AppUi.inputMsg(.blossom_edit),
            .on_submit = Msg.blossom_add,
            .height = 30,
        }, .{}),
        ui.inputGroupActions(.{}, .{
            ui.paragraph(
                .{ .wrap = true, .grow = 1, .style = .{ .foreground = if (model.blossom_error != .none) p.status_warning_text else p.text_dim } },
                &.{.{ .text = model.blossom_status(), .scale = mono_meta_scale }},
            ),
            ui.button(.{ .size = .sm, .on_press = Msg.blossom_add }, "Add"),
        }),
    );
    n += 1;
    return settingsCard(ui, .{rows[0..n]});
}

/// What the line under the add field says.
fn blossomStatusText(error_kind: BlossomEdit) []const u8 {
    return switch (error_kind) {
        .invalid => "A server address starts with https:// and names a host.",
        .busy => "Your signer is busy. Try again in a moment.",
        .unread => "Plaza has not read your server list yet, so it will not replace it.",
        .full => "Plaza sends to up to 4 servers.",
        .failed => "That did not go through.",
        .none => if (blossomProbeAsking() and !haveOwnBlossomList())
            "Reading your server list..."
        else if (g_blossom_saving != 0 and g_blossom_saving > g_blossom_created_at)
            "Saving..."
        else if (activePubkey() != null and !canWriteBlossomList())
            // Said before the press, as the relay list does: an edit that will not
            // be published must not look as though it will.
            "Plaza has not read your server list yet, so it will not replace it."
        else
            "",
    };
}

// ------------------------------------------------------------------------ likes
//
// A like is a NIP-25 kind:7 reaction with content "+", e/p/k-tagging the note.
// It rides the same three sign paths as a post and is local-first and optimistic:
// the heart fills the instant it is pressed (read from `g_my_likes` at render),
// and the reaction publishes in the background. Un-like is a NIP-09 kind:5
// deletion e-tagging our own reaction, since NIP-25 has no un-react. A guest
// press cannot sign, so it is remembered and completed after sign-in.

/// Lowercase-hex-encodes a 32-byte value into a fresh process-lifetime slice.
fn hexAlloc(gpa: std.mem.Allocator, bytes: [32]u8) ?[]const u8 {
    const out = gpa.alloc(u8, 64) catch return null;
    const digits = "0123456789abcdef";
    for (bytes, 0..) |b, i| {
        out[i * 2] = digits[b >> 4];
        out[i * 2 + 1] = digits[b & 0x0f];
    }
    return out;
}

// How many of each derived tag one note may carry. Caps rather than limits: a
// pasted C header emits a topic per `#include`, a pasted thread emits a mention
// per npub, and neither should be allowed to turn one note into a hundred-tag
// event that relays reject wholesale.
const max_topic_tags = 10;
const max_mention_tags = 8;
const max_quote_tags = 4;
const max_imeta_tags = 4;
// A long thread should not turn one reply into a mass notification, and some
// relays cap tag counts outright.
const max_thread_participant_tags = 12;
const max_topic_bytes = 64;

/// Rewrites `github.com/<owner>/<repo>/raw/<rest>` to
/// `raw.githubusercontent.com/<owner>/<repo>/<rest>`, returning `text` unchanged
/// when there is nothing to rewrite (and on OOM).
///
/// The first form is a 302 whose own response is `content-type: text/html`, so a
/// client that checks the type before inlining refuses to draw the picture and
/// the note arrives as a wall of text with a link in it. The second form is the
/// same bytes with `image/jpeg` on the first response.
///
/// Narrow on purpose: one host, one path shape, both ends serving the identical
/// file. This is the only place Plaza edits what somebody typed, and widening it
/// into a general URL cleaner would make that a habit instead of a fix.
fn canonicalMediaUrls(gpa: std.mem.Allocator, text: []const u8) []const u8 {
    const marker = "https://github.com/";
    if (std.mem.indexOf(u8, text, marker) == null) return text;

    var out = std.ArrayList(u8).initCapacity(gpa, text.len) catch return text;
    var i: usize = 0;
    while (i < text.len) {
        if (!std.mem.startsWith(u8, text[i..], marker)) {
            out.append(gpa, text[i]) catch return text;
            i += 1;
            continue;
        }
        var end = i;
        while (end < text.len and !std.ascii.isWhitespace(text[end])) end += 1;
        const url = text[i..end];
        const tail = url[marker.len..];
        // owner/repo/raw/<rest>, and nothing shorter.
        var parts = std.mem.splitScalar(u8, tail, '/');
        const owner = parts.next() orelse "";
        const repo = parts.next() orelse "";
        const raw = parts.next() orelse "";
        const rest = parts.rest();
        if (owner.len > 0 and repo.len > 0 and std.mem.eql(u8, raw, "raw") and rest.len > 0) {
            out.print(gpa, "https://raw.githubusercontent.com/{s}/{s}/{s}", .{ owner, repo, rest }) catch return text;
        } else {
            out.appendSlice(gpa, url) catch return text;
        }
        i = end;
    }
    return out.toOwnedSlice(gpa) catch text;
}

/// The MIME type an image URL's extension implies, or "" when it implies none.
fn imageMimeForUrl(url: []const u8) []const u8 {
    const path_end = std.mem.indexOfScalar(u8, url, '?') orelse url.len;
    const path = url[0..path_end];
    const table = [_]struct { ext: []const u8, mime: []const u8 }{
        .{ .ext = ".jpg", .mime = "image/jpeg" },
        .{ .ext = ".jpeg", .mime = "image/jpeg" },
        .{ .ext = ".png", .mime = "image/png" },
        .{ .ext = ".gif", .mime = "image/gif" },
        .{ .ext = ".webp", .mime = "image/webp" },
        .{ .ext = ".avif", .mime = "image/avif" },
        .{ .ext = ".bmp", .mime = "image/bmp" },
    };
    for (table) |row| {
        if (std.ascii.endsWithIgnoreCase(path, row.ext)) return row.mime;
    }
    return "";
}

/// The tags a note's own text implies: `t` per hashtag, `p` per mention, `q` per
/// quoted event, and `imeta` per image URL.
///
/// Everything here is derived from the text being published, at the moment it is
/// published, never from a list assembled while typing. Deleting a mention has
/// to delete its tag, and a side list built when the mention was picked goes
/// stale the moment the text is edited around it.
///
/// Not folded into `signAndPublish` alongside `withClientTag`, though that is the
/// one door every event passes through. A kind:0's content is a JSON blob whose
/// display name may contain a `#`, and a kind:3's content is machinery; scanning
/// those would put garbage on the network. The single-door pattern is right for a
/// tag that describes the client and wrong for tags derived from prose.
///
/// Process-lifetime, like the other builders here: the local write and the
/// detached publish both read these after this returns. Degrades to fewer tags on
/// OOM rather than refusing to post.
/// Everyone `content` would notify: each mention it names, and the author of
/// each event it quotes. Self-filtered and deduped, in the order they appear.
///
/// The composer's chips and the publish path both call this. Two functions that
/// each derived the set would be two functions that could disagree, and the one
/// promise the chips make is that they name exactly who gets tagged.
fn notifiedBy(content: []const u8, out: *[max_mention_tags][32]u8) usize {
    var n: usize = 0;
    const me = activePubkey();
    var scratch: [16 * 1024]u8 = undefined;
    var i: usize = 0;
    while (i < content.len and n < out.len) {
        // URLs whole, so a token inside one is never read as a reference.
        if (std.mem.startsWith(u8, content[i..], "http://") or std.mem.startsWith(u8, content[i..], "https://")) {
            while (i < content.len and !std.ascii.isWhitespace(content[i])) i += 1;
            continue;
        }
        var found: ?[32]u8 = null;
        var next = i + 1;
        var fba = std.heap.FixedBufferAllocator.init(&scratch);
        const arena = fba.allocator();
        if (parseMentionAt(arena, content, i)) |m| {
            found = m.pubkey;
            next = m.end;
        } else if (refPrecededByBoundary(content, i)) {
            var body_start = i;
            if (std.mem.startsWith(u8, content[i..], "nostr:")) body_start = i + "nostr:".len;
            const rest = content[body_start..];
            if (std.mem.startsWith(u8, rest, "nevent1")) {
                var j: usize = 0;
                while (j < rest.len and isBech32Char(rest[j])) j += 1;
                if (nostr.nip19.decodeNevent(arena, rest[0..j])) |ptr| {
                    // Only an author the pointer itself carries. A note1 has
                    // none, and this list must not name somebody on a guess.
                    if (ptr.author) |author| found = author;
                    next = body_start + j;
                } else |_| {}
            }
        }
        if (found) |pubkey| {
            const is_me = if (me) |mine| std.mem.eql(u8, &mine, &pubkey) else false;
            var dup = false;
            for (out[0..n]) |seen| {
                if (std.mem.eql(u8, &seen, &pubkey)) dup = true;
            }
            if (!is_me and !dup) {
                out[n] = pubkey;
                n += 1;
            }
            i = @max(next, i + 1);
            continue;
        }
        i += 1;
    }
    return n;
}

/// Whether `content` names `who`: as a NIP-27 mention, or as the author of an
/// event it quotes.
///
/// The reading half of what `notifiedBy` does for writing. Same scan, same
/// tokens, one difference: this one is asked about a specific person and so
/// cannot filter the reader out, which is the only thing it is ever asked
/// about.
pub fn contentNames(content: []const u8, who: [32]u8) bool {
    var scratch: [16 * 1024]u8 = undefined;
    var i: usize = 0;
    while (i < content.len) {
        // URLs whole, so a token inside one is never read as a reference.
        if (std.mem.startsWith(u8, content[i..], "http://") or std.mem.startsWith(u8, content[i..], "https://")) {
            while (i < content.len and !std.ascii.isWhitespace(content[i])) i += 1;
            continue;
        }
        var fba = std.heap.FixedBufferAllocator.init(&scratch);
        const arena = fba.allocator();
        if (parseMentionAt(arena, content, i)) |m| {
            if (std.mem.eql(u8, &m.pubkey, &who)) return true;
            i = @max(m.end, i + 1);
            continue;
        }
        if (refPrecededByBoundary(content, i)) {
            var body_start = i;
            if (std.mem.startsWith(u8, content[i..], "nostr:")) body_start = i + "nostr:".len;
            const rest = content[body_start..];
            if (std.mem.startsWith(u8, rest, "nevent1")) {
                var j: usize = 0;
                while (j < rest.len and isBech32Char(rest[j])) j += 1;
                if (nostr.nip19.decodeNevent(arena, rest[0..j])) |ptr| {
                    // Quoting somebody's note is telling them about it, so the
                    // author the pointer carries counts. A `note1` carries none,
                    // and nobody is named on a guess.
                    if (ptr.author) |author| {
                        if (std.mem.eql(u8, &author, &who)) return true;
                    }
                    i = @max(body_start + j, i + 1);
                    continue;
                } else |_| {}
            }
        }
        i += 1;
    }
    return false;
}

pub fn notifiedByForTest(content: []const u8, out: *[max_mention_tags][32]u8) usize {
    return notifiedBy(content, out);
}

/// Whether `pubkey` is in `excluded`, the set the reader has switched off for
/// this draft.
fn mentionExcluded(excluded: []const [32]u8, pubkey: [32]u8) bool {
    for (excluded) |e| {
        if (std.mem.eql(u8, &e, &pubkey)) return true;
    }
    return false;
}

fn contentTags(gpa: std.mem.Allocator, content: []const u8, base: []const nostr.event.Tag, excluded: []const [32]u8) []const nostr.event.Tag {
    var topics: [max_topic_tags][]const u8 = undefined;
    var topics_len: usize = 0;
    var mentions: [max_mention_tags][32]u8 = undefined;
    var mentions_len: usize = 0;
    var quotes: [max_quote_tags]struct { id: [32]u8, author: ?[32]u8, relay: UrlList(1) } = undefined;
    var quotes_len: usize = 0;
    var images: [max_imeta_tags][]const u8 = undefined;
    var images_len: usize = 0;

    const me = activePubkey();
    var scratch: [16 * 1024]u8 = undefined;

    var i: usize = 0;
    scan: while (i < content.len) {
        // A URL is consumed WHOLE, before anything else looks at this byte. That
        // single ordering is what keeps `https://example.com/page#section` from
        // publishing a topic called "section", and it is the guard the reference
        // clients are missing.
        if (std.mem.startsWith(u8, content[i..], "http://") or std.mem.startsWith(u8, content[i..], "https://")) {
            var j = i;
            while (j < content.len and !std.ascii.isWhitespace(content[j])) j += 1;
            const url = content[i..j];
            // A picture this app uploaded is one whatever its address ends in:
            // it knows what it sent.
            if (images_len < images.len and (looksLikeImageUrl(url) or uploadedPictureFor(url) != null)) {
                var dup = false;
                for (images[0..images_len]) |seen| {
                    if (std.mem.eql(u8, seen, url)) dup = true;
                }
                // One tag per distinct URL: NIP-92 pairs a tag with a URL in the
                // content, and the same picture twice is still one picture.
                if (!dup) {
                    images[images_len] = url;
                    images_len += 1;
                }
            }
            i = j;
            continue :scan;
        }

        // A mention, by the same parser the renderer uses, so what is tagged is
        // exactly what is drawn as a name.
        {
            var fba = std.heap.FixedBufferAllocator.init(&scratch);
            if (parseMentionAt(fba.allocator(), content, i)) |m| {
                const is_me = if (me) |mine| std.mem.eql(u8, &mine, &m.pubkey) else false;
                var dup = false;
                for (mentions[0..mentions_len]) |seen| {
                    if (std.mem.eql(u8, &seen, &m.pubkey)) dup = true;
                }
                // Never tag yourself: your own inbox lighting up for your own
                // note is a bug the reader would report as one.
                const off = mentionExcluded(excluded, m.pubkey);
                if (!is_me and !dup and !off and mentions_len < mentions.len) {
                    mentions[mentions_len] = m.pubkey;
                    mentions_len += 1;
                }
                i = m.end;
                continue :scan;
            }
        }

        // A quoted event.
        if (quotes_len < quotes.len) {
            var body_start = i;
            var is_ref = false;
            if (std.mem.startsWith(u8, content[i..], "nostr:")) {
                if (refPrecededByBoundary(content, i)) {
                    body_start = i + "nostr:".len;
                    is_ref = true;
                }
            } else if (std.mem.startsWith(u8, content[i..], "nevent1") or std.mem.startsWith(u8, content[i..], "note1")) {
                is_ref = refPrecededByBoundary(content, i);
            }
            if (is_ref) {
                const rest = content[body_start..];
                if (std.mem.startsWith(u8, rest, "nevent1") or std.mem.startsWith(u8, rest, "note1")) {
                    var j: usize = 0;
                    while (j < rest.len and isBech32Char(rest[j])) j += 1;
                    const token = rest[0..j];
                    var fba = std.heap.FixedBufferAllocator.init(&scratch);
                    const arena = fba.allocator();
                    var id: ?[32]u8 = null;
                    var author: ?[32]u8 = null;
                    // The relay the pointer itself names, first, because whoever
                    // wrote it chose it. Copied here: the decode's arena is the
                    // scratch buffer, reused on the next token.
                    var named: UrlList(1) = .{};
                    if (std.mem.startsWith(u8, token, "nevent1")) {
                        if (nostr.nip19.decodeNevent(arena, token)) |ptr| {
                            id = ptr.id;
                            author = ptr.author;
                            for (ptr.relays) |r| {
                                if (named.add(r)) break;
                            }
                        } else |_| {}
                    } else if (nostr.nip19.decodeNote(arena, token)) |note_id| {
                        id = note_id;
                    } else |_| {}
                    if (id) |event_id| {
                        var dup = false;
                        for (quotes[0..quotes_len]) |seen| {
                            if (std.mem.eql(u8, &seen.id, &event_id)) dup = true;
                        }
                        if (!dup) {
                            // Only the author the pointer itself carries. A
                            // `note1` carries none, and slot 4 is a notification
                            // target, so a guess there tells the wrong person
                            // they were quoted. Absent beats wrong.
                            quotes[quotes_len] = .{ .id = event_id, .author = author, .relay = named };
                            quotes_len += 1;
                        }
                        i = body_start + j;
                        continue :scan;
                    }
                }
            }
        }

        // A hashtag, last, because everything above can begin with a character
        // this would otherwise swallow.
        if (content[i] == '#' and i + 1 < content.len and isHashtagChar(content[i + 1]) and
            (i == 0 or !isHashtagChar(content[i - 1])))
        {
            var j = i + 1;
            while (j < content.len and isHashtagChar(content[j])) j += 1;
            const raw = content[i + 1 .. j];
            if (raw.len <= max_topic_bytes and std.unicode.utf8ValidateSlice(raw) and topics_len < topics.len) {
                // NIP-24 is a MUST on the value being lowercase. ASCII folding
                // only: a full Unicode fold would need a casing table, and the
                // tags this misses are ones no relay filter is asking for.
                const folded = gpa.alloc(u8, raw.len) catch {
                    i = j;
                    continue :scan;
                };
                _ = std.ascii.lowerString(folded, raw);
                var dup = false;
                for (topics[0..topics_len]) |seen| {
                    if (std.mem.eql(u8, seen, folded)) dup = true;
                }
                // Folded first, THEN deduped, so `#Nostr #nostr` is one topic.
                if (dup) {
                    gpa.free(folded);
                } else {
                    topics[topics_len] = folded;
                    topics_len += 1;
                }
            }
            i = j;
            continue :scan;
        }

        i += 1;
    }

    // Every quoted author is also a mention: NIP-10 asks for it, and without it
    // the person you quoted never learns you did.
    for (quotes[0..quotes_len]) |q| {
        const author = q.author orelse continue;
        if (mentions_len >= mentions.len) break;
        const is_me = if (me) |mine| std.mem.eql(u8, &mine, &author) else false;
        if (is_me or mentionExcluded(excluded, author)) continue;
        var dup = false;
        for (mentions[0..mentions_len]) |seen| {
            if (std.mem.eql(u8, &seen, &author)) dup = true;
        }
        if (dup) continue;
        mentions[mentions_len] = author;
        mentions_len += 1;
    }

    const derived = topics_len + mentions_len + quotes_len + images_len;
    if (derived == 0) return base;

    var out = std.ArrayList(nostr.event.Tag).initCapacity(gpa, base.len + derived) catch return base;
    out.appendSliceAssumeCapacity(base);

    for (topics[0..topics_len]) |topic| {
        const tag = gpa.dupe([]const u8, &.{ "t", topic }) catch break;
        out.appendAssumeCapacity(tag);
    }
    for (mentions[0..mentions_len]) |pubkey| {
        const tag = pTagFor(gpa, pubkey) orelse break;
        out.appendAssumeCapacity(tag);
    }
    for (quotes[0..quotes_len]) |q| {
        const id_hex = hexAlloc(gpa, q.id) orelse break;
        // The pointer's own relay, else the best Plaza knows (`hintsFor`), as
        // Jumble's `extractQuoteTags` does with `data.relays?.[0] ?? getEventHint`.
        // Empty when neither exists, because the author sits after it.
        const relay: []const u8 = if (q.relay.count > 0)
            gpa.dupe(u8, q.relay.at(0)) catch break
        else blk: {
            var hints: HintList = .{};
            hintsFor(q.id, q.author, &hints);
            break :blk hintOrEmpty(gpa, &hints) orelse break;
        };
        // Positional, so an author can only be read out of slot 4. With no
        // author the tag stops at the relay, or at the id when there is none,
        // rather than shipping empty slots.
        const tag = if (q.author) |author| blk: {
            const author_hex = hexAlloc(gpa, author) orelse break :blk gpa.dupe([]const u8, &.{ "q", id_hex }) catch break;
            break :blk gpa.dupe([]const u8, &.{ "q", id_hex, relay, author_hex }) catch break;
        } else if (relay.len > 0)
            gpa.dupe([]const u8, &.{ "q", id_hex, relay }) catch break
        else
            gpa.dupe([]const u8, &.{ "q", id_hex }) catch break;
        out.appendAssumeCapacity(tag);
    }
    for (images[0..images_len]) |url| {
        // One this app uploaded: it carries everything the uploader knew, which
        // is more than a reader fetching it would learn.
        if (uploadedImeta(gpa, url)) |full| {
            out.appendAssumeCapacity(full);
            continue;
        }
        // NIP-92's fields are one space-joined "key value" string each, and a
        // value may itself contain spaces, so a reader splits on the FIRST space
        // only. Plaza's own reader already does; this writes what that reads.
        const url_field = std.fmt.allocPrint(gpa, "url {s}", .{url}) catch break;
        const mime = imageMimeForUrl(url);
        const tag = if (mime.len == 0)
            gpa.dupe([]const u8, &.{ "imeta", url_field }) catch break
        else blk: {
            const mime_field = std.fmt.allocPrint(gpa, "m {s}", .{mime}) catch break;
            break :blk gpa.dupe([]const u8, &.{ "imeta", url_field, mime_field }) catch break;
        };
        out.appendAssumeCapacity(tag);
    }

    return out.toOwnedSlice(gpa) catch base;
}

/// The NIP-25 like tags for a note: `["e", id, relay]`, `["p", author, relay]`,
/// `["k", "1"]`. Each relay is left off, not blanked, when nothing is known:
/// NIP-25 puts the hint last in both tags, so there is nothing to hold a place
/// for. Process-lifetime (the sign paths reference them); null on OOM.
fn buildLikeTags(gpa: std.mem.Allocator, note: *const Note) ?[]const nostr.event.Tag {
    const id_hex = hexAlloc(gpa, note.event_id) orelse return null;
    var hints: HintList = .{};
    hintsFor(note.event_id, note.pubkey, &hints);
    const e = if (hints.count == 0)
        gpa.dupe([]const u8, &.{ "e", id_hex }) catch return null
    else
        gpa.dupe([]const u8, &.{ "e", id_hex, hintOrEmpty(gpa, &hints) orelse return null }) catch return null;
    const p = pTagFor(gpa, note.pubkey) orelse return null;
    const k = gpa.dupe([]const u8, &.{ "k", "1" }) catch return null;
    const tags = gpa.alloc(nostr.event.Tag, 3) catch return null;
    tags[0] = e;
    tags[1] = p;
    tags[2] = k;
    return tags;
}

/// The NIP-18 tags on a repost: `["e", id, "", author]` and `["p", author]`.
///
/// Read off Jumble (`src/lib/draft-event.ts:126` `createRepostDraftEvent`, whose
/// `buildETag(event.id, event.pubkey)` puts the author in the e-tag's fourth
/// field) and NDK (`core/src/events/repost.ts`, which tags the event and then
/// adds `k` only for a kind other than 1). Both send the e-tag and the p-tag and
/// no `k` for a kind:1, which is every note Plaza's feed holds, so there is no
/// `k` here and no kind:16.
///
/// The third field is the relay hint, where the reposted note can be found
/// (`hintsFor`). It is empty rather than absent when nothing is known because
/// the author sits in the fourth, and dropping the hint would move the pubkey
/// into the hint's place and tell every reader to dial it as a relay. Jumble's
/// `buildETag` fills the same slot from `getEventHint`, and Amethyst's
/// `RepostEvent.build` from the hint bundle's relay.
fn buildRepostTags(gpa: std.mem.Allocator, note: *const Note) ?[]const nostr.event.Tag {
    const id_hex = hexAlloc(gpa, note.event_id) orelse return null;
    const author_hex = hexAlloc(gpa, note.pubkey) orelse return null;
    var hints: HintList = .{};
    hintsFor(note.event_id, note.pubkey, &hints);
    const hint = hintOrEmpty(gpa, &hints) orelse return null;
    const e = gpa.dupe([]const u8, &.{ "e", id_hex, hint, author_hex }) catch return null;
    const p = pTagFor(gpa, note.pubkey) orelse return null;
    const tags = gpa.alloc(nostr.event.Tag, 2) catch return null;
    tags[0] = e;
    tags[1] = p;
    return tags;
}

/// The reposted note itself, as JSON, which is what NIP-18 says the content
/// should carry and what both clients above put there. A reader that has never
/// seen the note can render it from this without going and asking for it.
///
/// Empty when the note is not in the store, which is legal and is what those
/// clients fall back to as well. Plaza reads its own feed out of the store, so
/// it is normally there; a note that has been evicted still reposts, it just
/// costs the reader a fetch.
pub fn repostContent(gpa: std.mem.Allocator, note: *const Note) []const u8 {
    const store = g_store orelse return gpa.dupe(u8, "") catch "";
    var se = (store.getEvent(gpa, note.event_id) catch null) orelse return gpa.dupe(u8, "") catch "";
    defer se.deinit();
    return nostr.event.toJson(gpa, se.event) catch gpa.dupe(u8, "") catch "";
}

/// The NIP-09 deletion tags to un-like: `["e", reaction_id]`, `["k", "7"]`.
/// The tags of a NIP-09 deletion: the event it asks relays to drop, and the
/// kind that event was. This was `buildUnlikeTags` with the 7 written in, which
/// is the same builder with one number decided in advance.
///
/// The `k` tag is what lets a relay refuse a request to delete something of a
/// kind the sender should not be deleting, without fetching the target first.
fn buildDeleteTags(gpa: std.mem.Allocator, target_id: [32]u8, target_kind: u16) ?[]const nostr.event.Tag {
    const id_hex = hexAlloc(gpa, target_id) orelse return null;
    var kind_buf: [8]u8 = undefined;
    const kind_text = std.fmt.bufPrint(&kind_buf, "{d}", .{target_kind}) catch return null;
    const kind_owned = gpa.dupe(u8, kind_text) catch return null;
    const e = gpa.dupe([]const u8, &.{ "e", id_hex }) catch return null;
    const k = gpa.dupe([]const u8, &.{ "k", kind_owned }) catch return null;
    const tags = gpa.alloc(nostr.event.Tag, 2) catch return null;
    tags[0] = e;
    tags[1] = k;
    return tags;
}

/// Toggles a like on `note_id`. A guest cannot sign, so the like is remembered
/// and the join sheet opens; it completes after sign-in (`drivePendingIntent`).
fn toggleLike(model: *Model, fx: *Effects, note_id: i64) void {
    if (model.is_guest()) {
        model.pending = .{ .like = note_id };
        model.joining = true;
        return;
    }
    // A like and an un-like both move `g_my_likes` before they sign, and an
    // un-like's kind:5 is a deletion. A rejected sign there would leave the heart
    // empty and the reaction still standing on every relay.
    if (!signerReady()) return;
    if (isLiked(note_id)) unlike(fx, note_id) else like(model, fx, note_id);
}

/// Publishes a kind:7 like and fills the heart at once. The reaction id is
/// deterministic in the unsigned fields, so it is computed here (with the same
/// created/tags/content the sign path will use) and remembered, so an un-like
/// can delete exactly this reaction.
fn like(model: *const Model, fx: *Effects, note_id: i64) void {
    const note = model.noteById(note_id) orelse return;
    const gpa = std.heap.page_allocator;
    const pk = activePubkey() orelse return;
    const created = nowSeconds();
    const tags = buildLikeTags(gpa, note) orelse return;
    const content = gpa.dupe(u8, "+") catch return;
    const id = nostr.event.computeId(gpa, pk, created, 7, tags, content) catch return;
    rememberLike(note_id, id);
    signAndPublish(fx, gpa, created, 7, tags, content, false, .{ .like = note_id }, null);
}

/// Publishes a kind:6 repost, and fills the icon at once.
///
/// One way, on purpose. Jumble disables its button once you have reposted
/// (`RepostButton.tsx`, `canRepost = !hasReposted && …`) and NDK offers no undo
/// at all; a like has one here only because an un-like has a reaction id to
/// name in a kind:5, and every reader treats a deleted repost differently
/// anyway. Pressing again is a no-op rather than a second repost.
fn repost(model: *Model, fx: *Effects, note_id: i64) void {
    if (model.is_guest()) {
        model.pending = .{ .repost = note_id };
        model.joining = true;
        return;
    }
    if (!signerReady()) return;
    if (engagementFor(note_id).reposted_by_me) return;
    const note = model.noteById(note_id) orelse return;
    const gpa = std.heap.page_allocator;
    const tags = buildRepostTags(gpa, note) orelse return;
    const content = repostContent(gpa, note);
    // Filled before the signature comes back, the same way a like is. Our own
    // kind:6 arrives through the engagement subscription a moment later and sets
    // the same flag from the crowd, so this only covers the gap.
    markRepostedByMe(note_id);
    signAndPublish(fx, gpa, nowSeconds(), 6, tags, content, false, .{ .repost = note_id }, null);
}

/// Sets the "ours" flag on a note's row before the crowd confirms it.
///
/// The FLAG only. Not the count, which is the part a like has to work at: a like
/// shows an optimistic +1 and then has to retire it, which is why it remembers
/// its reaction id and why `likeCountFor` subtracts. Adding one here would be
/// added again a moment later, because our own kind:6 arrives through the same
/// engagement subscription as everybody else's and `markSeen` is keyed by event
/// id, so that fold is the first time that id has been seen and it counts.
///
/// So the icon fills at once and the number moves when the repost is really out.
/// That is the honest pair: the icon is about what you did, the number is about
/// what has been seen.
fn markRepostedByMe(note_id: i64) void {
    engagementLock();
    defer engagementUnlock();
    const row = ensureEngagement(note_id) orelse return;
    row.counts.reposted_by_me = true;
}

/// Clears it again, for a repost whose signature never came back.
///
/// The flag used to be written `true` and nothing else, so a refused repost
/// left the button dead for the rest of the process (`repost` returns early on
/// it), and, because it is not cleared on logout either, dead for the next
/// account to sign in as well.
fn clearRepostedByMe(note_id: i64) void {
    engagementLock();
    defer engagementUnlock();
    const row = ensureEngagement(note_id) orelse return;
    row.counts.reposted_by_me = false;
}

/// Publishes a kind:5 deletion of our own reaction and empties the heart at once.
fn unlike(fx: *Effects, note_id: i64) void {
    const gpa = std.heap.page_allocator;
    const reaction_id = forgetLike(note_id) orelse return;
    const tags = buildDeleteTags(gpa, reaction_id, 7) orelse return;
    const content = gpa.dupe(u8, "") catch return;
    // The id is already gone from the table by here, so the undo carries it:
    // without it a refused un-like empties the heart, leaves the kind:7 on
    // every relay, and the next press publishes a second reaction.
    signAndPublish(fx, gpa, nowSeconds(), 5, tags, content, false, .{ .unlike = .{ .note_id = note_id, .reaction_id = reaction_id } }, null);
}

/// Asks the relays to drop a note this reader wrote.
///
/// The local half needs no code: the store tombstones and removes on ingest of
/// a kind:5, scoped to the same author, the signed event reaches it through the
/// one door every write goes through, and a kind:5 landing already invalidates
/// the feed. So the note leaves the feed on the next rebuild with nothing added
/// here.
///
/// Kind 1 only, and that is a rule rather than a simplification. A replaceable
/// event is superseded, never deleted: `capturePrevious` and `keepReplaced`
/// exist so a list can be walked back, and a kind:5 aimed at one would ask
/// relays to drop the reader's follow list or their relay list with no way
/// back. Amethyst does delete lists this way. This will not.
fn deleteNote(model: *Model, fx: *Effects, note_id: i64) void {
    const target = deletableTarget(model, note_id) orelse return;
    if (!signerReady()) return;
    const gpa = std.heap.page_allocator;
    const tags = buildDeleteTags(gpa, target.event_id, target.kind) orelse return;
    const content = gpa.dupe(u8, "") catch return;
    // A thread level is a snapshot, so reading the note you just deleted would
    // leave a level showing an event the store no longer holds.
    if (model.viewing_thread == note_id) closeThread(model);
    signAndPublish(fx, gpa, nowSeconds(), 5, tags, content, false, .none, null);
}

/// What a deletion may target, or null when the answer is no.
///
/// Separated from the publish because these gates are the whole safety of the
/// feature and a test has to be able to ask them without signing anything.
fn deletableTarget(model: *Model, note_id: i64) ?struct { event_id: [32]u8, kind: u16 } {
    const note = model.noteById(note_id) orelse return null;
    const me = activePubkey() orelse return null;
    if (!std.mem.eql(u8, &note.pubkey, &me)) return null;
    // The kind comes from the STORE, not from the card. A `Note` carries no
    // kind: the feed builds one from whatever it drew, and an event of a kind
    // this app cannot render is still drawn as a note today (#268). Reading the
    // stored event is the only way to know what is actually being asked for,
    // and it is worth a disk read on the one action with no undo.
    const store = g_store orelse return null;
    var stored = (store.getEvent(std.heap.page_allocator, note.event_id) catch return null) orelse return null;
    defer stored.deinit();
    // Kind 1 only, and that is a rule rather than a simplification. A
    // replaceable event is superseded, never deleted: `capturePrevious` and
    // `keepReplaced` exist so a list can be walked back, and a kind:5 aimed at
    // one would ask relays to drop this reader's follow list or their relay
    // list with no way back. Amethyst deletes lists this way. This will not.
    if (stored.event.kind != 1) return null;
    // The card said it was theirs; the stored event has to agree. A card is
    // built by the feed and a signature is not.
    if (!std.mem.eql(u8, &stored.event.pubkey, &me)) return null;
    return .{ .event_id = note.event_id, .kind = stored.event.kind };
}

pub fn deletableTargetKindForTest(model: *Model, note_id: i64) ?u16 {
    const t = deletableTarget(model, note_id) orelse return null;
    return t.kind;
}

/// After sign-in, completes a like a guest reached for: the welcome-in moment.
/// Driven from the tick, where `fx` is in hand and the feed has just rebuilt.
fn drivePendingIntent(model: *Model, fx: *Effects) void {
    if (!model.pending.waiting() or model.is_guest()) return;
    const intent = model.pending;
    // Cleared FIRST, whatever happens next. A verb that cannot be completed (the
    // note scrolled away, the follow list has not loaded) must not be retried on
    // every tick for the rest of the session.
    model.pending = .none;
    switch (intent) {
        .none => {},
        .post => model.composing = true,
        .reply => |id| {
            // Back to the conversation they were in, with what they wrote still
            // in the box: `reply_buffer` survived the sheet.
            if (model.viewing_thread != id) openEvent(model, noteEventId(model, id) orelse return);
        },
        .like => |id| {
            if (isLiked(id)) return;
            like(model, fx, id);
            setToast(model, "Liked");
        },
        .repost => |id| {
            if (engagementFor(id).reposted_by_me) return;
            repost(model, fx, id);
            setToast(model, "Reposted");
        },
        .follow => |pk| {
            // The follow-safety gate still applies: this publishes a replaceable
            // list, and nothing may be written over a contact list that has not
            // been read back. When it is not yet safe the intent is dropped rather
            // than queued, because a write that lands minutes later, silently, is
            // exactly the shape this app refuses everywhere else.
            if (!canWriteFollows()) {
                // Every relay finished with no list: the guest's first follow is
                // asked about like any other, now that they have an account.
                if (askFreshFirst(model, .{ .action = .follow, .who = pk })) return;
                setToast(model, noListToast("follow list"));
                return;
            }
            sayFollowWrite(model, writeFollow(fx, pk, true), true);
        },
    }
}

pub fn drivePendingIntentForTest(model: *Model, fx: *Effects) void {
    drivePendingIntent(model, fx);
}

/// The full event id of a loaded note, for reopening what a guest was reading.
fn noteEventId(model: *const Model, note_id: i64) ?[32]u8 {
    if (model.noteById(note_id)) |note| return note.event_id;
    return null;
}

/// Deep-copies `tags` into process-lifetime memory so the detached publisher can
/// read them after the parse arena is freed. Returns an empty set on OOM (posts
/// are tagless, so nothing is lost there; a reaction that OOMs simply drops).
/// Copies a record's tags, or reports that it could not.
///
/// Null, never an empty slice. This is the splice base for every replaceable
/// write (kind 0, 3 and 10002), and those writes decide how much to keep by
/// counting what is in here. An empty slice says "this record had no tags",
/// which is a true statement about a record with no tags and a catastrophic one
/// about a copy that ran out of memory: the follow list's own shrink guard
/// compares against this same slice, so 0 to 1 reads as growth and passes.
///
/// A base that could not be copied whole must read as "not read". Every caller
/// already handles that safely, because it is the same path as a store miss.
fn dupeTags(gpa: std.mem.Allocator, tags: []const nostr.event.Tag) ?[]const nostr.event.Tag {
    if (tags.len == 0) return &.{};
    const out = gpa.alloc(nostr.event.Tag, tags.len) catch return null;
    for (tags, 0..) |tag, i| {
        const fields = gpa.alloc([]const u8, tag.len) catch return null;
        for (tag, 0..) |field, j| {
            fields[j] = gpa.dupe(u8, field) catch return null;
        }
        out[i] = fields;
    }
    return out;
}

/// The engine write seam: a note this process now holds, whether locally signed
/// or returned signed from the remote signer, enters the local store and is
/// published to the pool. The store is the single-writer data plane, only ever
/// written from this process. `verify` re-checks a signature we did not produce
/// ourselves and gates such a note out of both the store and the pool on
/// failure; a note we just signed skips the check and publishes even if the
/// store rejects the write (a duplicate). `ev.content` must be a
/// process-lifetime allocation, since the detached publisher reads it after
/// this returns.
fn ingestAndPublish(gpa: std.mem.Allocator, ev: nostr.event.Event, verify: ?nostr.keys.Signer, route: PlaceRoute) void {
    // A media server's upload token is a bearer credential for one file, not a
    // record. It is never stored and never published, whatever signed it.
    if (ev.kind == blossom.auth_kind) return;
    if (builtin.is_test) g_last_published = ev;
    if (g_store == null) return;
    if (verify) |signer| {
        // A note we did not produce: verification is the gate into the store
        // AND the pool, so a bad signature is dropped rather than propagated.
        _ = plazaIngest(gpa, ev, .{ .verify_with = signer }) catch return;
    } else {
        // A note we just signed: a store failure (e.g. a duplicate id) must not
        // stop it reaching the pool.
        _ = plazaIngest(gpa, ev, .{}) catch {};
    }
    // Queued BEFORE the walk, so a note that never reaches a relay is still a
    // note the app knows it owes the reader. A queue with no room says so:
    // publishing anyway would be a note nobody is tracking while the banner
    // promises that anything written is kept.
    if (isReaderNote(ev.kind)) {
        if (!enqueueOutbox(ev.id, ev.pubkey, nowSeconds(), route)) {
            g_outbox_overflow.store(true, .monotonic);
            return;
        }
    } else if (verify == null) {
        // Everything else this reader signs: a follow, a mute, a like, a relay
        // list. Tracked so that a write which acks NO relay is retried and
        // counted like a note, instead of being published once and forgotten.
        //
        // Best effort, deliberately. The refusal above is right for a note,
        // whose text the reader would otherwise lose with nothing tracking it.
        // A follow is not that: refusing to publish it because the queue is
        // full would turn a full queue into silently dropped writes, which is
        // worse than an untracked publish and is a failure this app did not
        // have before.
        _ = enqueueOutbox(ev.id, ev.pubkey, nowSeconds(), route);
    }
    // A test drives the write path, not the network. Its pool names hosts that
    // do not resolve, and a detached dial thread for one of those outlives the
    // test that started it and can take the process down on the way out, which
    // reads as a failing suite with no failing assertion. Comptime, so the
    // shipped binary has no branch here at all.
    if (builtin.is_test) return;
    const thread = std.Thread.spawn(.{}, publishWorker, .{ gpa, ev, route }) catch {
        // No thread: the note stays queued and the next drain will carry it.
        return;
    };
    thread.detach();
}

/// One publish walk for `ev`, with the queue updated around it.
fn publishWorker(gpa: std.mem.Allocator, ev: nostr.event.Event, route: PlaceRoute) void {
    markOutboxSending(ev.id, true);
    publishEvent(gpa, ev, route);
    markOutboxSending(ev.id, false);
}

fn markOutboxSending(id: [32]u8, sending: bool) void {
    outboxLock();
    defer outboxUnlock();
    const e = outboxEntryFor(id) orelse return;
    e.sending = sending;
    if (!sending) e.rounds +|= 1;
    _ = g_outbox_rev.fetchAdd(1, .monotonic);
}

// -------------------------------------------------------------------- the outbox
//
// What happens to a note between pressing Post and knowing it is somewhere else.
//
// Publishing used to be fire-and-forget: a detached thread dialled every relay,
// wrote the frame, read one message to flush it, and dropped the verdict. The
// note was in the local store, so the feed showed it, and whether it ever
// reached anyone was not a question the app could answer.
//
// Now every publish goes through a queue. Each entry names an event that is
// already in the store's own tables (we ingest what we sign) and carries one bit
// per relay: did that relay say OK. The queue is the app's answer to "is my note
// out there", the status bar reads it, and it survives a quit, because a note
// written on a train and lost on landing is the worst thing a client can do.
//
// The queue is small on purpose. It is not a retry engine for a broken network;
// it is a record of what has not been acknowledged yet, drained whenever a relay
// comes back.

/// One note on its way out.
pub const OutboxEntry = struct {
    used: bool = false,
    id: [32]u8 = [_]u8{0} ** 32,
    /// Where this note was written, kept so a retry minutes later still goes to
    /// the room it was written in and not to whichever one the reader has since
    /// walked into. Not persisted: a queue reloaded from disk has lost the room,
    /// and falls back to the reader's own relays, which is the safe direction to
    /// be wrong in.
    route: PlaceRoute = .none,
    /// Who signed the note this entry owes. A queue entry is a promise to ONE
    /// account, and the publisher, the counts and the popover all filter on it.
    ///
    /// Not persisted, and it does not need to be: `loadOutbox` already reads the
    /// event back out of the store to check it still exists, and the event
    /// carries its own author. Deriving it there keeps the on-disk format
    /// unchanged, so a queue written by an older build still loads.
    author: [32]u8 = [_]u8{0} ** 32,
    /// When it was queued, so the popover can say how long it has been waiting
    /// and the oldest entry can be dropped when the queue is full.
    queued_at: i64 = 0,
    /// One bit per pool relay: this relay answered OK.
    acked: u8 = 0,
    /// One bit per pool relay: this relay answered, and said no.
    refused: u8 = 0,
    /// How many times the publisher has walked the relays for this entry, so a
    /// note nobody will take stops asking rather than hammering forever.
    rounds: u8 = 0,
    /// Whether a publish walk is in flight for this entry right now.
    sending: bool = false,
    /// When the last walk started, so the next one waits.
    last_try_at: i64 = 0,

    /// How many relays have taken it.
    pub fn ackCount(self: OutboxEntry) usize {
        return @popCount(self.acked);
    }

    /// Where this note is, in the words the popover uses.
    pub fn state(self: OutboxEntry) OutboxState {
        if (self.acked != 0) return .sent;
        if (self.sending) return .sending;
        // A LABEL, not a verdict. The queue keeps offering this note; the word
        // only tells the reader it has been a while. It used to mean the app
        // had given up, which is the one thing a queue must not do silently.
        if (self.rounds >= rounds_before_stuck) return .stuck;
        return .queued;
    }
};

pub const OutboxState = enum { queued, sending, sent, stuck };

/// How long to wait before offering a note again, widening with each attempt so
/// a relay that is down is asked minutes apart rather than every second.
fn outboxRetryDelay(rounds: u8) i64 {
    return switch (rounds) {
        0 => 0,
        1 => 5,
        2 => 20,
        3 => 60,
        4 => 300,
        5 => 900,
        // Once an hour, forever. A relay that has been unreachable for an hour
        // may well come back tomorrow, and asking it hourly costs one dial.
        else => 3600,
    };
}

/// Set when a note could not be queued at all, so the reader is told rather than
/// left with a promise the app did not keep.
var g_outbox_overflow = std.atomic.Value(bool).init(false);

/// Room for a burst of posting without becoming a store of its own. A reader who
/// writes more than this while offline is past what a status bar can explain.
const outbox_cap = 16;
/// After how many failed rounds the popover starts calling a note stuck.
///
/// This used to be the point at which the queue GAVE UP. Six rounds on the old
/// ladder is about eleven and a half minutes, so closing a laptop lid for
/// twelve, or spending that long on a captive portal where TCP connects and TLS
/// does not, permanently abandoned every queued note. It was never offered
/// again for the life of the install, the count survived a restart, and sixteen
/// of them filled the queue so the account could never post from that install
/// again. The only escape was editing the relay list, which nobody would guess.
///
/// Now it only changes the word on the row. The note keeps being offered, on a
/// widening delay, for as long as the app is running.
const rounds_before_stuck = 6;

pub var g_outbox = [_]OutboxEntry{.{}} ** outbox_cap;
/// Bumped whenever the queue changes, so the UI thread can tell that the
/// publisher touched something without locking.
pub var g_outbox_rev = std.atomic.Value(u32).init(0);
/// The same tiny spinlock the pending-signature table uses, and for the same
/// reason: every critical section here is a handful of field writes or a
/// 16-slot scan and never touches IO, while `std.Io.Mutex` would drag a
/// per-thread `io` across threads that deliberately never share one.
var g_outbox_lock = std.atomic.Value(bool).init(false);

pub fn outboxLock() void {
    while (g_outbox_lock.cmpxchgWeak(false, true, .acquire, .monotonic) != null) std.atomic.spinLoopHint();
}
pub fn outboxUnlock() void {
    g_outbox_lock.store(false, .release);
}

/// Whether this entry belongs to whoever is signed in right now.
///
/// The three places that ACT on the reader's behalf ask this: what the publisher
/// sends, what the status bar counts, and what the popover lists. The bookkeeping
/// that runs over the whole array (`sweepOutbox`, `forgetOutboxAcks`,
/// `recordOutboxAck`, `markOutboxSending`) deliberately does not, because by the
/// time any of it runs the array holds one account's entries and nobody else's:
/// `syncOutboxOwner` hands the slots over when the account changes.
///
/// A queued note is a promise made to ONE account. Logging out does not empty
/// the queue, deliberately: `sweepOutbox` refuses to erase a note nobody has
/// taken, because that is the app destroying something the reader wrote, and a
/// logout is not a reason to break that promise. So the note stays, and stops
/// being walkable instead. Sign back in as its author and it resumes; sign in as
/// somebody else and it is not theirs to send, not theirs to be counted, and not
/// theirs to see.
///
/// Signed out, nothing is anybody's, which is why a null active key is false
/// rather than a wildcard.
fn outboxEntryIsMine(e: OutboxEntry) bool {
    const me = activePubkey() orelse return false;
    return std.mem.eql(u8, &me, &e.author);
}

/// Puts `id` in the queue, or returns the entry already there. The caller holds
/// the lock.
fn outboxEntryFor(id: [32]u8) ?*OutboxEntry {
    for (&g_outbox) |*e| {
        if (e.used and std.mem.eql(u8, &e.id, &id)) return e;
    }
    return null;
}

/// Queues a note we have just signed and stored. Returns false when the queue is
/// full of notes that have not been acknowledged, which is a state the reader can
/// see rather than one the app hides.
fn enqueueOutbox(id: [32]u8, author: [32]u8, now_s: i64, route: PlaceRoute) bool {
    outboxLock();
    defer outboxUnlock();
    if (outboxEntryFor(id) != null) return true;
    for (&g_outbox) |*e| {
        if (!e.used) {
            e.* = .{ .used = true, .id = id, .author = author, .queued_at = now_s, .route = route };
            _ = g_outbox_rev.fetchAdd(1, .monotonic);
            return true;
        }
    }
    // Full: drop the oldest note that has already reached somebody, since its
    // record is the least useful thing here.
    var victim: ?*OutboxEntry = null;
    for (&g_outbox) |*e| {
        if (e.acked == 0) continue;
        if (victim == null or e.queued_at < victim.?.queued_at) victim = e;
    }
    const slot = victim orelse return false;
    slot.* = .{ .used = true, .id = id, .author = author, .queued_at = now_s, .route = route };
    _ = g_outbox_rev.fetchAdd(1, .monotonic);
    return true;
}

/// Whether the queue could take another note right now.
///
/// Asked BEFORE the composer is emptied, which is the difference between a note
/// the reader still has and one that is gone. `ingestAndPublish` refuses to
/// publish what it cannot track, and it is right to: a note nobody is counting
/// under a banner promising that anything written is kept is the lie the queue
/// exists to stop telling. But the refusal happened after `.post` had cleared
/// the composer and deleted the draft file, so the note was simply lost, with no
/// queue row, no retry and no way back.
///
/// Sixteen slots, and eviction only takes a note that has already reached
/// somebody. Sixteen unacked notes therefore wedge the queue for as long as the
/// failure lasts, which for a pool that all requires NIP-42 AUTH, or a laptop on
/// a plane, is a real state and not a corner.
fn outboxHasRoom() bool {
    outboxLock();
    defer outboxUnlock();
    for (&g_outbox) |*e| {
        if (!e.used) return true;
        if (e.acked != 0) return true;
    }
    return false;
}

pub fn outboxHasRoomForTest() bool {
    return outboxHasRoom();
}

/// Records what one relay said about one note.
fn recordOutboxAck(id: [32]u8, relay_index: usize, accepted: bool) void {
    if (relay_index >= max_relays) return;
    outboxLock();
    defer outboxUnlock();
    const e = outboxEntryFor(id) orelse return;
    const bit = @as(u8, 1) << @intCast(relay_index);
    if (accepted) e.acked |= bit else e.refused |= bit;
    _ = g_outbox_rev.fetchAdd(1, .monotonic);
}

/// A snapshot of the queue for the view, newest first. The view never reads the
/// queue directly: the publisher writes it from its own thread.
pub fn outboxSnapshot(out: []OutboxEntry) usize {
    outboxLock();
    defer outboxUnlock();
    var n: usize = 0;
    for (&g_outbox) |*e| {
        if (!e.used or n == out.len) continue;
        // The same rule `outboxCounts` applies: the popover explains the count,
        // so it has to be a list of the same notes.
        if (!outboxEntryIsMine(e.*)) continue;
        out[n] = e.*;
        n += 1;
    }
    std.mem.sort(OutboxEntry, out[0..n], {}, struct {
        fn lt(_: void, a: OutboxEntry, b: OutboxEntry) bool {
            return a.queued_at > b.queued_at;
        }
    }.lt);
    return n;
}

/// How many notes are still trying, and how many have given up. They are
/// counted apart because they say different things: one is work in progress,
/// the other is a note the reader wrote that never left.
pub const OutboxCounts = struct { trying: usize = 0, stuck: usize = 0 };

pub fn outboxCounts() OutboxCounts {
    outboxLock();
    defer outboxUnlock();
    var counts: OutboxCounts = .{};
    for (&g_outbox) |*e| {
        if (!e.used or e.acked != 0) continue;
        // The status bar speaks for the reader who is here now. Counting a note
        // they did not write would have the app owe them something that is not
        // theirs, and offer no way to act on it.
        if (!outboxEntryIsMine(e.*)) continue;
        if (e.state() == .stuck) counts.stuck += 1 else counts.trying += 1;
    }
    return counts;
}

/// How many notes are still waiting for their first relay, trying or not.
pub fn outboxPending() usize {
    const c = outboxCounts();
    return c.trying + c.stuck;
}

/// Forgets the notes that are done: acknowledged by somebody, or refused by
/// everyone that answered after enough rounds. Called once the reader has had a
/// chance to see them, so the zone does not blink out mid-glance.
fn sweepOutbox(now_s: i64) void {
    outboxLock();
    defer outboxUnlock();
    var changed = false;
    for (&g_outbox) |*e| {
        if (!e.used or e.sending) continue;
        // A note that LANDED is let go once it has been on screen long enough to
        // read. A note that did not is KEPT: erasing it would be the app quietly
        // dropping something the reader wrote, which is the one thing this queue
        // exists to prevent. It stops asking, and it stays visible as stuck.
        if (e.acked != 0 and now_s - e.queued_at > outbox_sent_linger_s) {
            e.* = .{};
            changed = true;
        }
    }
    if (changed) _ = g_outbox_rev.fetchAdd(1, .monotonic);
}

/// How long a sent note stays in the queue so the reader can see that it landed.
const outbox_sent_linger_s: i64 = 20;
/// The revision last written to disk, so the queue is saved when it changes and
/// not on every tick.
var g_outbox_saved_rev: u32 = 0;

/// The queue's own seams, so a test drives the real state machine rather than a
/// copy of it.
pub fn resetOutboxForTest() void {
    outboxLock();
    defer outboxUnlock();
    for (&g_outbox) |*e| e.* = .{};
    relay_conn.g_outbox_woke_at.store(0, .monotonic);
    relay_conn.g_outbox_woke_ever.store(false, .monotonic);
}

pub fn outboxStateForTest(id: [32]u8) ?OutboxState {
    outboxLock();
    defer outboxUnlock();
