pub const rounds_before_stuck_for_test = rounds_before_stuck;
pub const outbox_sent_linger_for_test = outbox_sent_linger_s;

/// A fingerprint of the pool, in slot order. The outbox records which relay took
/// a note as a BIT PER SLOT, so those bits only mean anything against the list
/// they were written for: after an edit, bit 2 may be a relay that never saw the
/// note. The fingerprint travels with the queue so a changed list is noticed
/// rather than silently misread.
fn relayListFingerprint() u64 {
    var h = std.hash.Wyhash.init(0);
    for (0..relaySlots()) |i| {
        const e = relayAt(i) orelse {
            h.update("-");
            continue;
        };
        h.update(e.url());
        h.update(if (e.write) "w" else ".");
    }
    return h.final();
}

/// Forgets which relays took what, keeping the notes themselves. Called when the
/// list changes: a note that was delivered will simply be offered again, and a
/// relay that already has it will say so, which is cheaper than remembering a
/// claim that may now name the wrong relay.
pub fn forgetOutboxAcks() void {
    outboxLock();
    defer outboxUnlock();
    var changed = false;
    for (&g_outbox) |*e| {
        // EVERY owed note, including one that gave up with no verdict at all.
        // Skipping those would skip exactly the notes an edit is meant to
        // rescue: a note is stuck because `rounds` ran out, and a note whose
        // relays all went silent has `acked == 0 and refused == 0`. Adding a
        // relay for a note that never went out has to give that note its rounds
        // back, or the new relay is never asked.
        if (!e.used) continue;
        if (e.acked == 0 and e.refused == 0 and e.rounds == 0) continue;
        e.acked = 0;
        e.refused = 0;
        e.rounds = 0;
        changed = true;
    }
    if (changed) _ = g_outbox_rev.fetchAdd(1, .monotonic);
}

/// The queue's key in the store's generic table, one record PER ACCOUNT. The
/// events themselves are in the store's own event tables (we ingest what we
/// sign), so this holds only the index: which ids are owed, and what each relay
/// said.
///
/// Per account, because the sixteen slots in `g_outbox` are a scarce resource
/// and they belong to whoever is signed in. An account that logs out has its
/// queue written to its own record and its slots handed back; signing in reads
/// that record and nothing else. The alternative, leaving another account's
/// entries sitting in the array where they can never be sent, never acked and
/// therefore never reclaimed, wedges the queue: sixteen of them and the person
/// at the keyboard cannot publish at all, in silence.
const outbox_key_prefix = "outbox:";

/// The pre-account record, kept readable so a queue written by an older build is
/// not stranded. Each account claims its own share of it the first time it signs
/// in; whatever is left belongs to somebody else and stays put.
const legacy_outbox_key = "outbox";

fn outboxKeyFor(out: *[outbox_key_prefix.len + 64]u8, owner: [32]u8) []const u8 {
    @memcpy(out[0..outbox_key_prefix.len], outbox_key_prefix);
    var hex: [64]u8 = undefined;
    writeHexId(&hex, owner);
    @memcpy(out[outbox_key_prefix.len..][0..64], &hex);
    return out[0 .. outbox_key_prefix.len + 64];
}

/// Whose entries are in `g_outbox` right now. Null while signed out, when the
/// array is empty.
var g_outbox_owner: ?[32]u8 = null;

/// Writes the queue where a restart can find it. A note written on a train and
/// lost on landing is the worst thing a client can do, so this runs on every
/// change rather than at exit, which may never come.
fn saveOutbox() void {
    const store = g_store orelse return;
    // Nobody signed in means nothing of anybody's in the array, so there is no
    // record to write and nowhere to write it.
    const owner = g_outbox_owner orelse return;
    // Snapshotted under the lock, written outside it. `store.put` opens a write
    // transaction and commits it, which fsyncs and waits on LMDB's writer mutex
    // that the ingest threads hold: holding a SPINLOCK across that would burn a
    // core in every publisher and stall the frame that reads the queue. The lock
    // is only justified while it is what it claims to be, a few field writes.
    var entries: [outbox_cap]OutboxEntry = undefined;
    var n: usize = 0;
    outboxLock();
    for (&g_outbox) |*e| {
        if (!e.used) continue;
        entries[n] = e.*;
        n += 1;
    }
    outboxUnlock();

    // Room for every entry at its longest: 64 hex, four separators, a ten-digit
    // second, three small numbers and a newline. Sized at the worst case rather
    // than the typical one, because a short buffer would drop the LAST entries,
    // which is exactly when the queue matters most.
    var buf: [outbox_cap * 100 + 32]u8 = undefined;
    var w = std.Io.Writer.fixed(&buf);
    // The list those ack bits were recorded against, first.
    w.print("pool {d}\n", .{relayListFingerprint()}) catch return;
    for (entries[0..n]) |e| {
        var hex: [64]u8 = undefined;
        writeHexId(&hex, e.id);
        // A short write means the buffer was mis-sized, so nothing is written at
        // all: a truncated index would silently lose notes on the next start.
        w.print("{s}:{d}:{d}:{d}:{d}\n", .{ hex[0..], e.queued_at, e.acked, e.refused, e.rounds }) catch return;
    }
    var key_buf: [outbox_key_prefix.len + 64]u8 = undefined;
    store.put(outboxKeyFor(&key_buf, owner), w.buffered()) catch {};
}

fn writeHexId(out: *[64]u8, id: [32]u8) void {
    const hexdigits = "0123456789abcdef";
    for (id, 0..) |b, i| {
        out[i * 2] = hexdigits[b >> 4];
        out[i * 2 + 1] = hexdigits[b & 0x0f];
    }
}

/// Reads `owner`'s queue into the array, replacing whatever was there.
///
/// Anything whose event is no longer in the store is dropped: the index points
/// at events, and an index without its event is not something the reader can be
/// shown or the app can publish. Anything signed by somebody else is dropped
/// too, which only matters for the legacy record, and is the whole point of
/// reading it: each account takes its own share and leaves the rest.
fn loadOutbox(owner: [32]u8) void {
    const store = g_store orelse return;
    var key_buf: [outbox_key_prefix.len + 64]u8 = undefined;
    const raw = blk: {
        if (store.get(std.heap.page_allocator, outboxKeyFor(&key_buf, owner)) catch null) |own| break :blk own;
        if (store.get(std.heap.page_allocator, legacy_outbox_key) catch null) |legacy| break :blk legacy;
        // No record at all is an ANSWER, not a reason to leave the array alone:
        // this account's queue is empty, and whatever is in the slots belongs to
        // somebody else. Returning here without clearing is how the previous
        // account's notes stay in the next account's queue.
        clearOutboxSlots();
        return;
    };
    defer std.heap.page_allocator.free(raw);
    // Parsed and resolved first, installed second: every `getEvent` below opens a
    // read transaction, and the lock may not span IO.
    var parsed: [outbox_cap]OutboxEntry = undefined;
    var lines = std.mem.tokenizeScalar(u8, raw, '\n');
    // Whether the ack bits still refer to the relays they were written for.
    var same_pool = false;
    var n: usize = 0;
    while (lines.next()) |line| {
        if (std.mem.startsWith(u8, line, "pool ")) {
            const saved = std.fmt.parseInt(u64, line["pool ".len..], 10) catch 0;
            same_pool = saved == relayListFingerprint();
            continue;
        }
        if (n == parsed.len) break;
        var parts = std.mem.splitScalar(u8, line, ':');
        const hex = parts.next() orelse continue;
        if (hex.len != 64) continue;
        var id: [32]u8 = undefined;
        _ = std.fmt.hexToBytes(&id, hex) catch continue;
        const queued_at = std.fmt.parseInt(i64, parts.next() orelse "0", 10) catch continue;
        const acked = std.fmt.parseInt(u8, parts.next() orelse "0", 10) catch 0;
        const refused = std.fmt.parseInt(u8, parts.next() orelse "0", 10) catch 0;
        const rounds = std.fmt.parseInt(u8, parts.next() orelse "0", 10) catch 0;
        // The event has to still be there, or there is nothing to publish.
        const se = (store.getEvent(std.heap.page_allocator, id) catch continue) orelse continue;
        var owned = se;
        // The author comes from the event, which is why it is not in the file.
        const author = owned.event.pubkey;
        owned.deinit();
        // Somebody else's, which the legacy record can hold. Theirs to keep, so
        // it is left in that record rather than taken or dropped.
        if (!std.mem.eql(u8, &author, &owner)) continue;
        // A note is kept whatever the list did; only the CLAIMS about who has it
        // are dropped, so it is offered again rather than assumed delivered.
        parsed[n] = if (same_pool)
            .{ .used = true, .id = id, .author = author, .queued_at = queued_at, .acked = acked, .refused = refused, .rounds = rounds }
        else
            .{ .used = true, .id = id, .author = author, .queued_at = queued_at };
        n += 1;
    }
    outboxLock();
    defer outboxUnlock();
    // The WHOLE array, not the first n. This replaces one account's queue with
    // another's, so anything past the new entries has to go, or the tail of the
    // previous account's queue survives in the slots nobody overwrote.
    g_outbox = [_]OutboxEntry{.{}} ** outbox_cap;
    for (parsed[0..n], g_outbox[0..n]) |src, *dst| dst.* = src;
    _ = g_outbox_rev.fetchAdd(1, .monotonic);
}

/// Empties the sixteen slots. The notes themselves are events in the store and
/// their index is in a per-account record, so this hands slots back rather than
/// destroying anything.
fn clearOutboxSlots() void {
    outboxLock();
    g_outbox = [_]OutboxEntry{.{}} ** outbox_cap;
    outboxUnlock();
    _ = g_outbox_rev.fetchAdd(1, .monotonic);
}

/// Which queued notes the next drain will actually send, stamping each one's
/// attempt as it goes.
///
/// Split out of `drainOutbox` so the choice can be tested without a store and
/// without spawning publishers. The choice IS the safety property: the drain
/// itself is a loop that reads events and hands them to threads, and every
/// question worth asking about who may publish what is answered here.
fn collectOutboxDue(ids: *[outbox_cap][32]u8, now_s: i64) usize {
    var n: usize = 0;
    outboxLock();
    defer outboxUnlock();
    for (&g_outbox) |*e| {
        if (!e.used or e.sending or e.acked != 0) continue;
        // Somebody else's note. This is the line that stops the previous
        // account's unsent writing going out over the next account's relays,
        // and signed out it stops everything, because a queued note is a promise
        // to one account and there is nobody here to keep it for.
        if (!outboxEntryIsMine(e.*)) continue;
        // Spaced out, and widening: the drain runs every tick, so without this a
        // transient failure (a captive portal, a TLS error, a relay that takes
        // the socket and refuses the publish) would burn every round in seconds
        // and leave the note stuck a moment after it was written.
        if (e.last_try_at != 0 and now_s - e.last_try_at < outboxRetryDelay(e.rounds)) continue;
        if (n == ids.len) break;
        e.last_try_at = now_s;
        ids[n] = e.id;
        n += 1;
    }
    return n;
}

pub fn collectOutboxDueForTest(ids: *[outbox_cap][32]u8, now_s: i64) usize {
    return collectOutboxDue(ids, now_s);
}

pub fn syncOutboxOwnerForTest() void {
    syncOutboxOwner();
}

pub fn loadOutboxForTest(owner: [32]u8) void {
    loadOutbox(owner);
}

pub fn saveOutboxForTest() void {
    saveOutbox();
}

pub fn outboxOwnerForTest() ?[32]u8 {
    return g_outbox_owner;
}

pub fn clearOutboxOwnerForTest() void {
    g_outbox_owner = null;
}

pub fn outboxAuthorAtForTest(i: usize) ?[32]u8 {
    outboxLock();
    defer outboxUnlock();
    if (!g_outbox[i].used) return null;
    return g_outbox[i].author;
}

pub fn outboxUsedSlotsForTest() usize {
    outboxLock();
    defer outboxUnlock();
    var n: usize = 0;
    for (&g_outbox) |*e| {
        if (e.used) n += 1;
    }
    return n;
}

pub const outbox_cap_for_test = outbox_cap;

/// Hands the sixteen slots to whoever is signed in, whenever that changes.
///
/// ONE place, called from the tick before anything reads the queue, because
/// getting it wrong in two places is how the previous account's notes end up in
/// the next account's queue. The leaving account's entries are written to their
/// own record first and only then cleared, so nothing is dropped: they are
/// parked, not deleted, and reading them back is what signing in again does.
///
/// This is what keeps `outboxEntryIsMine` an invariant rather than a load-
/// bearing filter. Leaving foreign entries in the array and merely refusing to
/// send them looks safe and is not: nothing can ever ack them, so nothing can
/// ever sweep or evict them either, and sixteen of them stop the person at the
/// keyboard publishing anything at all, with no counter, no popover row and no
/// banner to say why.
fn syncOutboxOwner() void {
    const now_owner = activePubkey();
    if (g_outbox_owner) |had| {
        if (now_owner) |now| if (std.mem.eql(u8, &had, &now)) return;
    } else if (now_owner == null) return;

    // Park the leaving account's queue before the slots are handed over.
    if (g_outbox_owner != null) {
        saveOutbox();
        clearOutboxSlots();
    }
    g_outbox_owner = now_owner;
    if (now_owner) |owner| loadOutbox(owner) else clearOutboxSlots();
    // The queue on disk is already current for both accounts, so the tick's
    // save-on-change is told not to write the freshly loaded one straight back.
    g_outbox_saved_rev = g_outbox_rev.load(.monotonic);
}

/// Offers every note that nobody has taken to the relays again. Called when a
/// Where a queued note was written, for the retry that carries it.
fn outboxRouteFor(id: [32]u8) PlaceRoute {
    outboxLock();
    defer outboxUnlock();
    const e = outboxEntryFor(id) orelse return .none;
    return e.route;
}

/// relay comes back, which is the moment the answer might have changed.
fn drainOutbox(gpa: std.mem.Allocator) void {
    const store = g_store orelse return;
    var ids: [outbox_cap][32]u8 = undefined;
    const n = collectOutboxDue(&ids, nowSeconds());
    for (ids[0..n]) |id| {
        const route = outboxRouteFor(id);
        var se = (store.getEvent(gpa, id) catch continue) orelse continue;
        defer se.deinit();
        // COPIED, not borrowed. `StoredEvent.deinit` tears down the arena that
        // backs the content and the tags, and it would fire at the end of this
        // iteration, while the detached publisher is still serialising them.
        // `ingestAndPublish` states the same rule for its own path: what the
        // publisher reads has to outlive the call that spawned it.
        const owned = dupeEventForPublish(se.event) orelse continue;
        const thread = std.Thread.spawn(.{}, publishOwnedWorker, .{ gpa, owned, route }) catch {
            freePublishedEvent(owned);
            continue;
        };
        thread.detach();
    }
}

/// A process-lifetime copy of an event, for handing to a detached publisher.
/// Returns null when the copy cannot be made, in which case nothing is spawned.
fn dupeEventForPublish(ev: nostr.event.Event) ?nostr.event.Event {
    const gpa = std.heap.page_allocator;
    var out = ev;
    out.content = gpa.dupe(u8, ev.content) catch return null;
    const tags = gpa.alloc(nostr.event.Tag, ev.tags.len) catch {
        gpa.free(out.content);
        return null;
    };
    var filled: usize = 0;
    errdefer {
        for (tags[0..filled]) |t| {
            for (t) |field| gpa.free(field);
            gpa.free(t);
        }
        gpa.free(tags);
        gpa.free(out.content);
    }
    for (ev.tags, tags) |src, *dst| {
        const fields = gpa.alloc([]const u8, src.len) catch return null;
        var wrote: usize = 0;
        for (src, fields) |field, *slot| {
            slot.* = gpa.dupe(u8, field) catch {
                for (fields[0..wrote]) |f| gpa.free(f);
                gpa.free(fields);
                return null;
            };
            wrote += 1;
        }
        dst.* = fields;
        filled += 1;
    }
    out.tags = tags;
    return out;
}

/// Frees what `dupeEventForPublish` allocated.
fn freePublishedEvent(ev: nostr.event.Event) void {
    const gpa = std.heap.page_allocator;
    for (ev.tags) |t| {
        for (t) |field| gpa.free(field);
        gpa.free(t);
    }
    gpa.free(ev.tags);
    gpa.free(ev.content);
}

/// The drain's worker: publishes a copy it owns, and frees it when the walk is
/// over rather than leaving it to a caller that has already moved on.
fn publishOwnedWorker(gpa: std.mem.Allocator, ev: nostr.event.Event, route: PlaceRoute) void {
    defer freePublishedEvent(ev);
    publishWorker(gpa, ev, route);
}

/// Publishes `ev` to every relay in the pool, each on a throwaway connection,
/// best-effort. Posting is a rare, human-paced action, so a fresh dial per post
/// keeps the ingest loops untouched; the note is already in the local store, so
/// the feed shows it regardless of publish latency. Runs on a detached thread
/// with its own io backend, never the UI thread's.
/// At most this many of one recipient's read relays are added for a publish.
///
/// Jumble takes five, welshman's default scenario limit is three. Three is the
/// smaller of the two and still means a person has to have lost three relays at
/// once to miss a reply.
const inbox_relays_per_recipient = 3;
/// A ceiling on the whole extra set, so a note naming a dozen people does not
/// turn one Post into thirty dials.
const max_extra_inbox_relays = 8;

/// Publishes `ev` to the relays the people it names actually READ from.
///
/// Plaza sent every note to the reader's own write relays and nowhere else. If
/// the person being replied to does not read those relays, their client never
/// sees the reply and never tells them: a thread started from Plaza reads
/// one-sided to everybody else in it. Plaza's own inbox subscription is the
/// mirror of this and is correct, so the app was receiving what others routed
/// to it and not reciprocating.
///
/// Best effort, and deliberately not recorded in the outbox. An acknowledgement
/// there is a bit in a per-slot bitmap and these relays hold no slot; more to
/// the point, "did my note go out" is a question about the reader's own relays,
/// and a stranger's inbox relay refusing an unknown pubkey is normal rather
/// than a delivery failure worth alarming them about.
fn publishToRecipientInboxes(gpa: std.mem.Allocator, io: std.Io, ev: nostr.event.Event) void {
    const store = g_store orelse return;

    // Who the note names. The author is skipped: a reply to yourself does not
    // need routing, and the pool already carries it.
    var recipients: [max_extra_inbox_relays * 2][32]u8 = undefined;
    var n: usize = 0;
    for (ev.tags) |tag| {
        if (n == recipients.len) break;
        if (tag.len < 2 or !std.mem.eql(u8, tag[0], "p") or tag[1].len != 64) continue;
        var pk: [32]u8 = undefined;
        _ = std.fmt.hexToBytes(&pk, tag[1]) catch continue;
        if (std.mem.eql(u8, &pk, &ev.pubkey)) continue;
        var dupe = false;
        for (recipients[0..n]) |seen| {
            if (std.mem.eql(u8, &seen, &pk)) dupe = true;
        }
        if (dupe) continue;
        recipients[n] = pk;
        n += 1;
    }
    if (n == 0) return;

    const kinds = [_]u16{relay_list_kind};
    var result = store.query(gpa, .{ .authors = recipients[0..n], .kinds = &kinds, .limit = @intCast(n) }) catch return;
    defer result.deinit();

    var urls: [max_extra_inbox_relays][96]u8 = undefined;
    var url_len: [max_extra_inbox_relays]usize = undefined;
    var urls_n: usize = 0;

    for (result.events) |list_ev| {
        var parsed = nostr.nip65.parseRelayList(gpa, list_ev) catch continue;
        defer parsed.deinit();
        var taken: usize = 0;
        for (parsed.list.entries) |entry| {
            if (taken == inbox_relays_per_recipient or urls_n == urls.len) break;
            // Where they READ. A relay they only write to will never show them
            // anything, so a reply left there is a reply nobody receives.
            if (!entry.read) continue;
            const trimmed = std.mem.trim(u8, entry.url, " \t\r\n");
            if (trimmed.len == 0 or trimmed.len > 96) continue;
            // Already covered by the pool walk, so dialling it again would only
            // publish the same note twice to the same host.
            if (poolHasRelay(trimmed)) continue;
            var already = false;
            for (0..urls_n) |i| {
                if (std.mem.eql(u8, urls[i][0..url_len[i]], trimmed)) already = true;
            }
            if (already) continue;
            @memcpy(urls[urls_n][0..trimmed.len], trimmed);
            url_len[urls_n] = trimmed.len;
            urls_n += 1;
            taken += 1;
        }
    }

    for (0..urls_n) |i| {
        const url = urls[i][0..url_len[i]];
        var relay = nostr.relay.dial(gpa, io, url) catch continue;
        // Declared AFTER deinit so it runs BEFORE it: the keeper must have
        // let go of this pointer before the connection is freed.
        defer relay.deinit();
        const watched = watchOneShot(io, relay, one_shot_budget_ms);
        defer releaseOneShot(watched);
        relay.publish(ev) catch continue;
        // One read, to give the frame somewhere to flush to. The verdict is not
        // recorded, so there is nothing to wait around for.
        var msg = (relay.receive() catch continue) orelse continue;
        msg.deinit();
    }
}

/// Whether `url` is already one of the reader's own relays.
pub fn poolHasRelayForTest(url: []const u8) bool {
    return poolHasRelay(url);
}

fn poolHasRelay(url: []const u8) bool {
    for (0..relaySlots()) |i| {
        var buf: [96]u8 = undefined;
        const entry = relaySnapshot(i, &buf) orelse continue;
        // The pool's own comparison, which knows that a trailing slash and a
        // difference of case are the same relay. Two spellings here would mean
        // publishing the same note to the same host twice.
        if (relayUrlEql(entry.url, url)) return true;
    }
    return false;
}

/// Where a write goes, decided when the reader asked for it.
///
/// A VALUE, and copied, for two reasons. `activePlace()` hands back a pointer
/// into a global the UI thread assigns a whole new `Place` over, and this is
/// read on a detached publish thread across a dial: one walk could see half of
/// one room's relay list and half of another's. And the room is read LATE
/// otherwise. A note held for the undo pause, a note waiting on a remote
/// signer's approval, and a note the outbox retries minutes later are all
/// published long after the reader pressed Post, so asking then answers about
/// whichever room they have since walked into, not the one they wrote in.
const PlaceRoute = struct {
    urls: [place_relays_cap][place_relay_cap]u8 = @splat(@splat(0)),
    lens: [place_relays_cap]u8 = @splat(0),
    len: u8 = 0,
    /// The place said "only these". Honoured only when it named some, because a
    /// place claiming exclusivity and naming none would silence the reader.
    exclusive: bool = false,

    /// No room: the reader's own relays, and nothing else.
    const none: PlaceRoute = .{};

    fn url(self: *const PlaceRoute, i: usize) []const u8 {
        return self.urls[i][0..self.lens[i]];
    }
};

/// What the route a held note is carrying names, for the test: the relay list a
/// publish walk would actually dial, taken from the value and not from whatever
/// room happens to be open when it is read.
pub fn heldRouteRelaysForTest(out: [][]const u8) usize {
    var n: usize = 0;
    while (n < g_held_route.len and n < out.len) : (n += 1) out[n] = g_held_route.url(n);
    return n;
}

pub fn routeForOpenPlaceRelaysForTest(out: [][]const u8) usize {
    const r = routeForOpenPlace();
    g_route_probe = r;
    var n: usize = 0;
    while (n < g_route_probe.len and n < out.len) : (n += 1) out[n] = g_route_probe.url(n);
    return n;
}
var g_route_probe: PlaceRoute = .none;

/// The room open right now, as something that can be carried away from it.
fn routeForOpenPlace() PlaceRoute {
    var out: PlaceRoute = .{};
    // `activePlace`, not `visitingPlace`. The second one means a place being
    // looked at and NOT yet entered, so this would go quiet the moment somebody
    // actually joined the community: exactly backwards.
    const place = activePlace() orelse return out;
    for (0..place.write_relays_len) |i| {
        if (out.len == out.urls.len) break;
        const u = place.writeRelay(i);
        out.lens[out.len] = @intCast(copyBounded(&out.urls[out.len], u));
        out.len += 1;
    }
    out.exclusive = place.write_exclusive;
    return out;
}

fn publishEvent(gpa: std.mem.Allocator, ev: nostr.event.Event, route: PlaceRoute) void {
    var threaded = std.Io.Threaded.init(gpa, .{});
    defer threaded.deinit();
    const io = threaded.io();

    // The place being read, if any, sent to FIRST and separately from the
    // reader's own pool.
    //
    // `activePlace`, not `visitingPlace`. The second one means a place being
    // looked at and NOT yet entered, so every one of these would have gone
    // quiet the moment somebody actually joined the community: exactly
    // backwards.
    //
    // A note written inside a community used to walk only the reader's write
    // slots, so it went everywhere except the community it was written in. The
    // place names where it lives; this is that promise kept.
    //
    // Not recorded in the outbox: a slot index is what an acknowledgement is
    // filed against, and these relays hold no slot. So they are a best effort
    // in the same sense the room itself is, and the note is still tracked
    // against the reader's own relays below.
    for (0..route.len) |i| {
        var relay = nostr.relay.dial(gpa, io, route.url(i)) catch continue;
        defer relay.deinit();
        const watched = watchOneShot(io, relay, one_shot_budget_ms);
        defer releaseOneShot(watched);
        relay.publish(ev) catch continue;
    }
    if (route.exclusive and route.len > 0) return;

    for (0..relaySlots()) |i| {
        var url_buf: [96]u8 = undefined;
        const entry = relaySnapshot(i, &url_buf) orelse continue;
        // Only where the reader asked to be published. The slot index is what
        // the outbox records an acknowledgement against, which is why a slot is
        // never reused for a different relay while the process lives.
        if (!entry.write) continue;
        var relay = nostr.relay.dial(gpa, io, entry.url) catch continue;
        // Declared AFTER deinit so it runs BEFORE it: the keeper must have
        // let go of this pointer before the connection is freed.
        defer relay.deinit();
        const watched = watchOneShot(io, relay, one_shot_budget_ms);
        defer releaseOneShot(watched);
        relay.publish(ev) catch continue;
        // The relay's OK is the answer to "is my note out there", so it is READ
        // rather than merely waited for: which relay took it, and which refused,
        // is the whole content of the outbox. A relay may say other things
        // first (a NOTICE, an EVENT for an open subscription), so this reads
        // until it sees a verdict for THIS id or runs out of patience.
        var seen: usize = 0;
        while (seen < max_publish_messages) : (seen += 1) {
            var msg = (relay.receive() catch break) orelse break;
            defer msg.deinit();
            switch (msg.value) {
                .ok => |ok| {
                    if (!std.mem.eql(u8, &ok.event_id, &ev.id)) continue;
                    // An ack is recorded against a SLOT, and this walk has been
                    // blocked on a socket long enough for the reader to have
                    // removed the relay or put another one in its seat. Record
                    // it only if the seat still holds the relay that answered,
                    // or the note would be reported as delivered to a relay that
                    // never saw it.
                    var still_buf: [96]u8 = undefined;
                    const still = relaySnapshot(i, &still_buf) orelse break;
                    if (!relayUrlEql(still.url, entry.url)) break;
                    recordOutboxAck(ev.id, i, ok.accepted);
                    break;
                },
                else => continue,
            }
        }
    }

    // And where the people it names actually read, which the reader's own
    // relays say nothing about.
    publishToRecipientInboxes(gpa, io, ev);
}

/// How many frames to read from one relay while waiting for its verdict. A relay
/// with a busy subscription can have several in front of the OK; past this it is
/// not answering about this note.
const max_publish_messages = 8;

// ------------------------------------------------------------------------ threads
//
// A thread is the focused note plus the kind:1 replies that e-tag it. It is
// layered OVER the feed, which stays mounted so its scroll offset survives.
// Opening one snapshots the root, reads any replies already in the store, and
// fires a one-shot fetch of the rest (with their engagement) into the store; the
// replies are cached in the model so they are pressable (open as a sub-thread)
// and get their pictures fetched, the same local-first path the feed uses.

/// Opens `note_id` as a thread. The target may live in the feed or the current
/// thread; it is snapshotted as the new root so it survives store rebuilds. When
/// a thread is already open, the current root is pushed so Back returns to it.
fn openThread(model: *Model, note_id: i64) void {
    const target = model.noteById(note_id) orelse return;
    // A note pressed on the feed itself has no sheet to go back to, whatever an
    // earlier visit to Notifications left behind.
    if (!model.levelOpen()) model.notifications_return = false;
    enterThread(model, target.*);
}

/// Focuses `root` as the open thread: pushes the current thread (if any) onto
/// the back-stack, snapshots the new root, and fires its reply fetch. Shared by
/// open-a-feed-note, open-a-reply, and open-a-quoted-note.
fn enterThread(model: *Model, root: Note) void {
    parkReplyDraft(model);
    pushCurrentScreen(model);
    // Here and not in `setThreadRoot`: a newer copy of the article being read
    // swaps the root in place, and the reply being typed under it stays put.
    takeReplyDraft(model, root.event_id);
    setThreadRoot(model, root);
}

/// Makes `root` the open thread without touching the back-stack. `enterThread`
/// is a push and this; a newer copy of an article the reader is already reading
/// is this alone, so Back still goes where it went before.
fn setThreadRoot(model: *Model, root: Note) void {
    // A topic or the bookmark list outranks a thread when the view is built,
    // so left set, either one hid the thread: pressing a note on those pages
    // opened nothing. The level being left is already on the stack.
    model.topic_len = 0;
    model.viewing_bookmarks = false;
    model.viewing_profile = null;
    model.viewing_thread = root.id;
    model.thread_root = root;
    model.thread_notes_len = 0;
    // The level being opened starts at its first page with its held section
    // closed. Only this level: the ones underneath keep what the reader left
    // them holding. The arrival table needs no reset either, since it is keyed
    // by the level's root and discards itself when it finds another thread.
    model.thread_page[model.currentLevel()] = 1;
    model.thread_outside_open[model.currentLevel()] = false;
    wantProfile(root.pubkey);
    // The fetch is claimed BEFORE the first build, because that build asks
    // whether this level's fetch has settled: against the previous level's
    // sequence it would answer yes, mark the table settled before a single
    // reply had landed, and put the whole opening read back into relay-answer
    // order, which is the thing arrival batching exists to prevent.
    const now = nowSeconds();
    const seq = g_thread_seq.fetchAdd(1, .monotonic) + 1;
    model.thread_seq = seq;
    model.thread_open_at = now;
    model.refreshThreadNotes(now);
    model.thread_loading = model.thread_notes_len == 0;
    fetchThreadReplies(root.event_id, seq);
}

/// The level bookkeeping, for a test that walks a stack up and down. Both take
/// the same paths the app does, so what they assert is what a reader gets.
pub fn enterThreadForTest(model: *Model, root: Note) void {
    enterThread(model, root);
}

/// Replaces the open level's root in place, keeping the back-stack.
fn swapThreadRoot(model: *Model, root: Note) void {
    setThreadRoot(model, root);
}

pub fn closeThreadForTest(model: *Model) void {
    closeThread(model);
}

// Unsent replies, kept for the threads the reader stepped out of. The reply box
// holds one reply, and it belongs to the open thread, so every move to another
// level used to empty it: a sentence half written was gone after a Back, where
// a half written note survives a restart. A draft lives here from the moment its
// thread is left until the reader returns to it, which takes it back out, so a
// slot only ever holds a thread that is not open. Session only, a few at a
// time, and the oldest is dropped when they run out.
const reply_draft_slots = 8;
const ReplyDraft = struct {
    used: bool = false,
    event_id: [32]u8 = @splat(0),
    /// When it was kept, so the one dropped when the slots run out is the oldest.
    kept: u64 = 0,
    len: usize = 0,
    text: [compose_capacity]u8 = undefined,
};
var g_reply_drafts: [reply_draft_slots]ReplyDraft = [_]ReplyDraft{.{}} ** reply_draft_slots;
var g_reply_draft_clock: u64 = 0;

/// Keeps what is in the reply box under the thread it belongs to, then empties
/// the box. The box only ever holds the open thread's reply, and every move to
/// another level passes through here, so `thread_root` is whose it is. An empty
/// box keeps nothing and leaves any other thread's draft alone.
///
/// A reply held under its Undo pause is the box's text too, so it stops here
/// and is kept with the rest. Left armed it would fire into whatever thread is
/// open when the pause ran out, with whatever draft that thread put back in the
/// box, and nobody would have pressed Reply on it.
fn parkReplyDraft(model: *Model) void {
    defer model.reply_buffer.clear();
    const held = g_reply_due_s != 0;
    g_reply_due_s = 0;
    const text = model.reply_buffer.text();
    if (std.mem.trim(u8, text, " \t\r\n").len == 0) return;
    keepReplyDraft(model.thread_root.event_id, text, true);
    if (held) setToast(model, "Reply not sent. It is kept in its thread.");
}

/// Files `text` as the kept reply for the thread rooted at `event_id`. A thread
/// that already has one keeps it unless `replace`, so a reply coming back from
/// a refused signature never writes over one typed since.
fn keepReplyDraft(event_id: [32]u8, text: []const u8, replace: bool) void {
    var slot: ?usize = null;
    for (&g_reply_drafts, 0..) |*d, i| {
        if (d.used and std.mem.eql(u8, &d.event_id, &event_id)) slot = i;
    }
    if (slot != null and !replace) return;
    if (slot == null) {
        for (&g_reply_drafts, 0..) |*d, i| {
            if (!d.used) {
                slot = i;
                break;
            }
        }
    }
    // Full: the one kept longest ago makes room. Not a rotating index, which
    // would pick whichever slot it reached next, and that can be the draft kept
    // a moment ago into a slot a return had just freed.
    const i = slot orelse blk: {
        var oldest: usize = 0;
        for (&g_reply_drafts, 0..) |*d, j| {
            if (d.kept < g_reply_drafts[oldest].kept) oldest = j;
        }
        break :blk oldest;
    };
    const n = @min(text.len, compose_capacity);
    g_reply_draft_clock += 1;
    g_reply_drafts[i].used = true;
    g_reply_drafts[i].event_id = event_id;
    g_reply_drafts[i].kept = g_reply_draft_clock;
    g_reply_drafts[i].len = n;
    @memcpy(g_reply_drafts[i].text[0..n], text[0..n]);
}

/// Puts back the reply the reader left in this thread, or leaves the box empty.
fn takeReplyDraft(model: *Model, event_id: [32]u8) void {
    model.reply_buffer.clear();
    for (&g_reply_drafts) |*d| {
        if (!d.used or !std.mem.eql(u8, &d.event_id, &event_id)) continue;
        model.reply_buffer.set(d.text[0..d.len]);
        d.used = false;
        return;
    }
}

/// Forgets every kept reply, for a session that is ending. The text is wiped as
/// well as released: it is the leaving account's private thinking.
fn forgetReplyDrafts() void {
    for (&g_reply_drafts) |*d| {
        @memset(&d.text, 0);
        d.used = false;
        d.event_id = @splat(0);
        d.kept = 0;
        d.len = 0;
    }
}

/// The thread a kept reply is filed under, for a test of where a reply went.
pub fn keptReplyDraftForTest(event_id: [32]u8) ?[]const u8 {
    for (&g_reply_drafts) |*d| {
        if (d.used and std.mem.eql(u8, &d.event_id, &event_id)) return d.text[0..d.len];
    }
    return null;
}

/// Pushes whatever level is open, so Back returns to it. A no-op at the feed,
/// and a no-op at the depth cap, which is the same rule threads always had.
fn pushCurrentScreen(model: *Model) void {
    if (model.thread_stack_len >= model.thread_stack.len) return;
    if (model.viewing_bookmarks) {
        model.thread_stack[model.thread_stack_len] = .{ .bookmarks = true };
        model.thread_stack_len += 1;
        return;
    }
    if (model.viewingTopic()) |topic| {
        var level = Screen{ .topic_len = @intCast(topic.len) };
        @memcpy(level.topic_buf[0..topic.len], topic);
        model.thread_stack[model.thread_stack_len] = level;
        model.thread_stack_len += 1;
        return;
    }
    if (model.viewing_profile) |pk| {
        model.thread_stack[model.thread_stack_len] = .{ .profile = pk, .profile_limit = model.profile_limit };
        model.thread_stack_len += 1;
        return;
    }
    if (model.viewing_thread != 0) {
        model.thread_stack[model.thread_stack_len] = .{ .note = model.thread_root };
        model.thread_stack_len += 1;
    }
}

/// The filters that ask for notes older than `until`.
///
/// Chunked exactly like the live subscription, and for the same reason: a relay
/// refuses a filter whose field items exceed its size cap. Separate from
/// `buildFeedFilters` because this asks for notes and nothing else: profiles
/// and relay lists are replaceable, so there is no older copy to page back to.
pub fn buildOlderFilters(
    authors: []const [32]u8,
    until: i64,
    out: []nostr.filter.Filter,
) []nostr.filter.Filter {
    var len: usize = 0;
    var start: usize = 0;
    while (start < authors.len and len < out.len) : (start += follow_chunk) {
        const chunk = authors[start..@min(start + follow_chunk, authors.len)];
        out[len] = .{
            .authors = chunk,
            .kinds = &feed_filter_kinds,
            .until = until,
            .limit = feed_page,
        };
        len += 1;
    }
    return out[0..len];
}

/// Whether an older-notes fetch is already in flight, so a reader who keeps
/// scrolling does not stack one request per frame.
var g_older_busy = std.atomic.Value(bool).init(false);
/// Set when a network round for older notes came back with nothing new, which
/// is the only honest way to know the feed has an end.
var g_feed_end_reached = std.atomic.Value(bool).init(false);

pub fn feedEndReached() bool {
    return g_feed_end_reached.load(.monotonic);
}

/// The end of history is an answer about a QUESTION: is there anything older
/// than this, from these authors, on these relays. Change the question and the
/// answer stops being about anything.
///
/// This existed only as a test helper with no callers anywhere, so the latch
/// was write-once for the life of the process: sign in as somebody else, follow
/// three hundred new people, add a relay that holds a decade of history, and
/// the feed still refused to ask.
pub fn resetFeedEnd() void {
    g_feed_end_reached.store(false, .monotonic);
}

/// The latch's condition, lifted out so it can be asserted without standing up
/// a relay. The worker calls this with what its round actually saw.
fn feedEndLatches(asked: usize, answered: usize, added: usize) bool {
    return asked > 0 and answered > 0 and added == 0;
}

pub fn feedEndLatchesForTest(asked: usize, answered: usize, added: usize) bool {
    return feedEndLatches(asked, answered, added);
}
pub fn setFeedEndForTest() void {
    g_feed_end_reached.store(true, .monotonic);
}

pub fn resetFeedEndForTest() void {
    resetFeedEnd();
    g_older_busy.store(false, .monotonic);
}

/// Asks the relays for notes older than `until`.
///
/// Reaching the end of the loaded feed used to raise the store's query limit
/// and nothing else. The store answers with what it has, so once the initial
/// backfill was exhausted the list simply stopped growing: no older history, no
/// end-of-feed state, and no way to reach anything from before the app was
/// opened. A reader coming back after a week saw the last few hundred notes and
/// could not scroll past them. Grepping this file for `.until` returned nothing
/// at all, which is the whole bug: no filter Plaza ever sent carried one.
///
/// Store first, network second, which is Jumble's ordering: `_loadMoreTimeline`
/// serves from its cached list and only then asks with `{ ...filter, until }`.
fn fetchOlderNotes(until: i64) void {
    if (!relayFetchAllowed()) return;
    // One at a time. Sitting at the bottom of the list fires this on every
    // frame, and each round is a dial per relay.
    if (g_older_busy.swap(true, .acq_rel)) return;
    const thread = std.Thread.spawn(.{}, fetchOlderWorker, .{until}) catch {
        g_older_busy.store(false, .release);
        return;
    };
    thread.detach();
}

fn fetchOlderWorker(until: i64) void {
    const gpa = std.heap.page_allocator;
    defer g_older_busy.store(false, .release);
    var threaded = std.Io.Threaded.init(gpa, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var signer = nostr.keys.Signer.init();
    defer signer.deinit();

    var authors: [max_follows + 1][32]u8 = undefined;
    var authors_len: usize = 0;
    if (activePubkey()) |pk| {
        authors[authors_len] = pk;
        authors_len += 1;
    }
    for (followSet()) |pk| {
        if (authors_len == authors.len) break;
        authors[authors_len] = pk;
        authors_len += 1;
    }
    if (authors_len == 0) return;

    var filters: [max_feed_filters]nostr.filter.Filter = undefined;
    const built = buildOlderFilters(authors[0..authors_len], until, &filters);
    const flen = built.len;

    var added: usize = 0;
    // How many relays took the subscription and answered it. Both, because an
    // end of history is a thing relays TELL you and the two ways of not being
    // told look identical from `added` alone.
    var asked: usize = 0;
    var answered: usize = 0;
    for (0..relaySlots()) |ri| {
        var url_buf: [96]u8 = undefined;
        const entry = relaySnapshot(ri, &url_buf) orelse continue;
        if (!entry.read) continue;
        var relay = nostr.relay.dial(gpa, io, entry.url) catch continue;
        // Declared AFTER deinit so it runs BEFORE it: the keeper must have
        // let go of this pointer before the connection is freed.
        defer relay.deinit();
        const watched = watchOneShot(io, relay, one_shot_budget_ms);
        defer releaseOneShot(watched);
        relay.subscribe("plaza-older", filters[0..flen]) catch continue;
        asked += 1;
        var seen: usize = 0;
        // Bounded: `receive` has no deadline, and a relay that takes the
        // subscription and then goes quiet would hold this thread forever.
        while (seen < profile_fetch_messages) : (seen += 1) {
            var msg = (relay.receive() catch break) orelse break;
            defer msg.deinit();
            switch (msg.value) {
                .event => |e| {
                    const result = plazaIngestFrom(gpa, e.event, .{ .verify_with = signer }, entry.url) catch continue;
                    if (result == .added) added += 1;
                },
                .eose => {
                    // "I have looked and that is all of it." The only message
                    // that licenses the latch below.
                    answered += 1;
                    break;
                },
                .closed => break,
                else => {},
            }
        }
        relay.unsubscribe("plaza-older") catch {};
    }

    // Nothing anywhere had anything older, AND somebody was actually there to
    // say so. Both halves matter, and only the first was checked.
    //
    // `added` counts events that were new to the store, and every failure in
    // the loop above is a `catch continue`: a dial that could not connect, a
    // subscribe that was refused. So an offline round and a round where every
    // relay answered "nothing older" produced the same zero, and this latched
    // on the first paging attempt made on a train. It is write-once for the
    // life of the process, so the feed then dead-ended until the app restarted.
    //
    // A round that reached nobody now says nothing at all, and the next attempt
    // asks again.
    if (feedEndLatches(asked, answered, added)) g_feed_end_reached.store(true, .monotonic);
}

/// Opens a person as a level of their own.
/// Opens a topic as a level of its own: what this reader already holds carrying
/// that `t` tag, on the back stack, with the feed left where it was.
///
/// Local store first and rendered immediately, then a bounded ask to the read
/// relays behind it. A topic has no author, so the outbox model has nothing to
/// say about where to ask: the reader's own read relays are the honest answer,
/// rather than a search relay nobody chose.
fn openTopic(model: *Model, topic_in: []const u8) void {
    if (topic_in.len == 0 or topic_in.len > max_topic_bytes) return;
    // NIP-24: `t` values are lowercase, and a relay matches them exactly, so
    // `#Nostr` asked for as written finds nothing that `contentTags` published.
    var folded: [max_topic_bytes]u8 = undefined;
    for (topic_in, 0..) |c, i| folded[i] = std.ascii.toLower(c);
    const topic = folded[0..topic_in.len];
    // Already here: pressing `#zig` inside the `#zig` topic would otherwise push
    // a second copy of it and cost a Back to undo.
    if (model.viewingTopic()) |current| {
        if (std.mem.eql(u8, current, topic)) return;
    }
    leaveNotifications(model);
    pushCurrentScreen(model);
    model.viewing_bookmarks = false;
    model.viewing_profile = null;
    model.viewing_thread = 0;
    model.thread_notes_len = 0;
    parkReplyDraft(model);
    @memcpy(model.topic_buf[0..topic.len], topic);
    model.topic_len = @intCast(topic.len);
    const now = nowSeconds();
    const seq = g_thread_seq.fetchAdd(1, .monotonic) + 1;
    model.thread_seq = seq;
    model.thread_open_at = now;
    model.refreshTopicNotes(now);
    model.thread_loading = model.thread_notes_len == 0;
    fetchTopicNotes(topic, seq);
}

pub fn openTopicForTest(model: *Model, topic: []const u8) void {
    openTopic(model, topic);
}

/// Opens the bookmark list as a level of its own.
///
/// The answer to "a bookmark I cannot find again is a button, not a feature".
fn openBookmarks(model: *Model) void {
    if (model.viewing_bookmarks) return;
    leaveNotifications(model);
    pushCurrentScreen(model);
    model.viewing_profile = null;
    model.viewing_thread = 0;
    model.topic_len = 0;
    model.thread_notes_len = 0;
    parkReplyDraft(model);
    model.viewing_bookmarks = true;
    model.thread_seq = g_thread_seq.fetchAdd(1, .monotonic) + 1;
    model.thread_open_at = nowSeconds();
    // Read from this machine and nothing else. Every bookmarked note was in the
    // feed when it was saved, so it is already here; there is no relay round
    // trip to wait on and no skeleton to show.
    model.refreshBookmarkNotes(nowSeconds());
    model.thread_loading = false;
}

pub fn openBookmarksForTest(model: *Model) void {
    openBookmarks(model);
}

fn enterProfile(model: *Model, pubkey: [32]u8) void {
    // Already here. Pressing a face on somebody's own page would otherwise push
    // a second copy of the same person and cost a Back to undo.
    if (model.viewing_profile) |current| {
        if (std.mem.eql(u8, &current, &pubkey)) return;
    }
    pushCurrentScreen(model);
    model.topic_len = 0;
    model.viewing_bookmarks = false;
    model.viewing_profile = pubkey;
    model.viewing_thread = 0;
    model.thread_notes_len = 0;
    parkReplyDraft(model);
    wantProfile(pubkey);
    model.profile_tab = .notes;
    model.profile_limit = profile_page;
    model.profile_autofill = 0;
    model.profile_asked_until = 0;
    g_profile_bottom_in_view = false;
    armProfileReach(pubkey, true);
    const now = nowSeconds();
    const seq = g_thread_seq.fetchAdd(1, .monotonic) + 1;
    model.thread_seq = seq;
    model.thread_open_at = now;
    model.refreshProfileNotes(now);
    model.thread_loading = model.thread_notes_len == 0;
    fetchProfileNotes(pubkey, seq);
}

pub fn enterProfileForTest(model: *Model, pubkey: [32]u8) void {
    enterProfile(model, pubkey);
}

/// Opens an event (by its full id) as a thread, reading it straight from the
/// store. `openThread` cannot: it resolves the render key through the feed and
/// the open thread, and a quoted note or an ANCESTOR is in neither. Both press
/// this instead, and both only ever fire for an event already ingested (an
/// unresolved quote card is not pressable, and an ancestor row exists because
/// the walk found the event).
/// Puts the address field away and forgets what was in it.
fn closeAddress(model: *Model) void {
    model.address_open = false;
    model.address_buffer.clear();
    model.address_error = .none;
    g_nip05_ask = null;
    searchReset();
}

/// Reads what is in the address field and goes where it points.
///
/// The field closes BEFORE the navigation, never after it. Every destination
/// here has an early return in front of it, and closing on arrival leaves the
/// sheet up in exactly the cases where the reader has least idea why nothing
/// moved. This is the same rule `.open_event` already follows for the
/// notifications sheet.
///
/// A refusal does the opposite and leaves the field open with what was typed
/// still in it, because the reader is about to fix a character.
fn openAddress(model: *Model, fx: *Effects) void {
    // A NIP-19 entity is a few hundred bytes at the outside, and the decode
    // allocates the relay list and a place's identifier out of this too.
    var scratch: [4096]u8 = undefined;
    var fba = std.heap.FixedBufferAllocator.init(&scratch);
    const parsed = parseAddress(fba.allocator(), model.address_buffer.text());
    const hit = switch (parsed) {
        .unreadable => {
            model.address_error = .unreadable;
            return;
        },
        .wrong_kind => {
            model.address_error = .wrong_kind;
            return;
        },
        .ok => |ok| ok,
    };

    closeAddress(model);
    // The address can be opened over Settings, and the destination is drawn
    // under it. Leave Settings first, or the reader presses Open and sees
    // nothing happen.
    if (model.stage == .settings) leaveSettings(model);
    switch (hit.target) {
        // The hints go in FIRST, so that if the note is not held the fetch
        // `openEvent` starts already knows where to look. `wantQuote` inside
        // `openEvent` then finds this entry and leaves it alone.
        .event => |id| {
            wantQuoteHinted(id, hit.hints);
            openEvent(model, id);
        },
        .person => |pk| {
            wantProfileHinted(pk, hit.hints);
            openPerson(model, pk);
        },
        .place => |pl| {
            var want: @TypeOf(places.g_place_want.?) = .{ .pubkey = pl.pubkey, .ident_buf = @splat(0), .ident_len = 0 };
            want.ident_len = @intCast(copyBounded(&want.ident_buf, pl.identifier));
            places.g_place_want = want;
            askPlace(fx, hit.hints);
            // A copy already in the store opens the room now. Otherwise say
            // that the address was heard: the fetch ends with a toast of its
            // own, and the seconds between are not silence.
            // Not when the address is the room already on screen: there is
            // nothing to look for, and the window only watches for a newer copy.
            refreshPlaceFetch(model);
            if (places.g_place_want) |w| {
                if (!w.applied and !samePlace(w)) setToast(model, place_looking_toast);
            }
        },
        .article => |art| {
            // Cannot fail: `parseAddress` only returns this for an address that
            // `Address.make` accepted.
            const addr = Address.make(art.kind, art.pubkey, art.identifier) orelse return;
            openAddressedArticle(model, addr, hit.hints);
        },
    }
}

/// Goes to a stored event the reader asked for by id. A note opens as a thread
/// and a published article opens as the article, which `feedView` draws as a
/// reader instead of a thread because its root is a kind:30023.
///
/// A draft (kind:30024) opens nothing. It is the author's unfinished copy, it is
/// not addressed to a reader, and putting it on screen with the same title and
/// body as the published one is how a draft gets read as the real thing.
fn enterEvent(model: *Model, ev: nostr.event.Event) void {
    if (ev.kind == article.draft_kind) {
        setToast(model, "That is an unpublished draft.");
        return;
    }
    enterThread(model, noteFrom(ev, nowSeconds()));
}

// ------------------------------------------------------- finding a person
//
// The field that opens an address finds people by name as well, because it is
// the one place somebody goes to say who they mean. Two sources answer it, and
// they are not mixed up: every profile already on this machine, instantly and
// with the network off, then NIP-50 search relays, whose results are folded in
// as they land and each marked with the relay that gave it.

/// Most rows the results list holds, and how many of those can be people the
/// store already knew. This is a node budget as much as a taste: the sheet is
/// stacked over the feed, and a row costs about a dozen of the 1024 nodes a view
/// may have.
pub const search_rows_max = 20;
const search_local_max = 12;
/// How many kind:0 events one page of the index build reads, and the most it
/// reads in all. The store keeps one kind:0 per author, so this is a ceiling on
/// people. Newest first, so a store larger than this loses its oldest profiles
/// from the instant half, not its recent ones.
const search_scan_page = 1024;
const search_scan_max = 32 * 1024;
/// How many contact lists name the reader, at most, when working out who follows
/// them.
const search_followers_max = 4096;
/// Seconds an index may be old before opening the field builds a new one.
const search_index_ttl_s: i64 = 30;
/// Quiet time after the last keystroke before a name goes to the relays. A name
/// is put to three strangers, so it waits until the reader has stopped typing.
const search_settle_ms: i64 = 600;
/// Shortest term that goes to relays on its own. Enter sends anything.
const search_auto_min = 2;
/// Frames one relay may spend on a search before it is let go.
const search_frames_max = 200;

/// One line of the results.
const SearchRow = struct {
    pubkey: [32]u8,
    /// The store already had this person.
    local: bool,
    /// Bit `i` set: search relay `i` returned them.
    relays: u8,
};

var g_search_rows: [search_rows_max]SearchRow = undefined;
var g_search_len: usize = 0;
/// The term the rows answer, in the form that was searched.
var g_search_term: [search.term_max]u8 = undefined;
var g_search_term_len: usize = 0;
/// Moves every time the term changes, so an answer to an earlier term that
/// arrives late is recognised and dropped.
var g_search_gen = std.atomic.Value(u32).init(0);
/// The generation already put to the relays.
var g_search_asked: u32 = 0;
/// When the term last changed, on the awake clock.
var g_search_typed_ms: i64 = 0;
/// Where each search relay stands, as a packed `search.Status`.
var g_search_status: [search.relays_max]std.atomic.Value(u64) = @splat(std.atomic.Value(u64).init(0));

/// A person a relay returned, on its way from the thread that read it to the one
/// that draws it.
const SearchArrival = struct { gen: u32, relay: u8, pubkey: [32]u8 };
/// Room for every relay's full answer between two ticks. The tick drains once a
/// second and three relays can each send `relay_limit` people well inside that,
/// so a smaller inbox dropped the later relays' answers: their people never
/// appeared, and people already listed lost the mark naming them.
const search_inbox_cap = search.relays_max * search.relay_limit;
var g_search_inbox: [search_inbox_cap]SearchArrival = undefined;
var g_search_inbox_len: usize = 0;
var g_search_inbox_lock = std.atomic.Value(bool).init(false);

fn lockSearchInbox() void {
    while (g_search_inbox_lock.cmpxchgWeak(false, true, .acquire, .monotonic) != null) {}
}
fn unlockSearchInbox() void {
    g_search_inbox_lock.store(false, .release);
}

/// Every profile on this machine with something to match on. Replaced whole by
/// a worker; held under `g_search_index_lock` by anything that reads it.
var g_search_index: search.Index = .{};
var g_search_index_ready = false;
var g_search_index_built_s: i64 = 0;
var g_search_index_lock = std.atomic.Value(bool).init(false);
var g_search_index_building = std.atomic.Value(bool).init(false);

fn lockSearchIndex() void {
    while (g_search_index_lock.cmpxchgWeak(false, true, .acquire, .monotonic) != null) {}
}
fn unlockSearchIndex() void {
    g_search_index_lock.store(false, .release);
}

/// The relays a name is put to, by slot.
fn searchRelays() []const []const u8 {
    return &search.default_relays;
}

fn awakeMs() i64 {
    const io = g_io orelse return 0;
    return std.Io.Timestamp.now(io, .awake).toMilliseconds();
}

/// The term on screen, cleaned, or null when the field holds no name.
fn searchTermOf(model: *const Model, out: *[search.term_max]u8) ?[]const u8 {
    return switch (classifySearch(model.address_buffer.text())) {
        .blank, .address, .key => null,
        .nip05, .term => search.cleanTerm(out, model.address_buffer.text()),
    };
}

/// Forgets the results and cancels whatever was still on its way.
fn searchReset() void {
    _ = g_search_gen.fetchAdd(1, .acq_rel);
    g_search_len = 0;
    g_search_term_len = 0;
    lockSearchInbox();
    g_search_inbox_len = 0;
    unlockSearchInbox();
    for (&g_search_status) |*s| s.store(0, .release);
}

/// The field has opened: nothing to show yet, and a fresh index on its way so
/// the first letters typed are matched against everything held.
fn searchOpen() void {
    searchReset();
    searchIndexEnsure();
}

/// The field's text changed. The instant half answers now, synchronously; the
/// relays are asked once typing settles, from the tick.
fn searchOnEdit(model: *const Model) void {
    searchReset();
    var buf: [search.term_max]u8 = undefined;
    const term = searchTermOf(model, &buf) orelse return;
    @memcpy(g_search_term[0..term.len], term);
    g_search_term_len = term.len;
    g_search_typed_ms = awakeMs();
    searchRunLocal(term);
}

/// Matches `term` against every profile held and fills the list with the best.
fn searchRunLocal(term: []const u8) void {
    var picked: [search_local_max][32]u8 = undefined;
    var n: usize = 0;
    var hits: [search_local_max * 2]search.Hit = undefined;

    lockSearchIndex();
    const have_index = g_search_index_ready;
    if (have_index) {
        const found = g_search_index.find(term, &hits);
        for (hits[0..found]) |hit| {
            if (n == picked.len) break;
            const pk = g_search_index.entries[hit.entry].pubkey;
            if (isMuted(pk)) continue;
            picked[n] = pk;
            n += 1;
        }
    }
    unlockSearchIndex();

    // Before the index has been built (the first moments after a launch, or no
    // store at all) the profiles the app already holds in memory answer, which
    // is what the mention picker has always done.
    if (!have_index) n = searchCachePick(term, &picked);

    g_search_len = 0;
    for (picked[0..n]) |pk| {
        g_search_rows[g_search_len] = .{ .pubkey = pk, .local = true, .relays = 0 };
        g_search_len += 1;
    }
    hydrateProfiles(picked[0..n]);
}

/// The cache-only answer: the in-memory profiles, ranked the same way.
fn searchCachePick(term: []const u8, out: *[search_local_max][32]u8) usize {
    const gpa = std.heap.page_allocator;
    var builder = search.Builder.init(gpa);
    defer builder.deinit();
    for (&g_profiles) |*pr| {
        if (!pr.used) continue;
        const tier: search.Tier = if (inFollowGraph(pr.pubkey)) .follows else .seen;
        builder.add(pr.pubkey, tier, 0, pr.name(), pr.username(), pr.nip05()) catch return 0;
    }
    var index = builder.finish() catch return 0;
    defer index.deinit(gpa);
    var hits: [search_local_max * 2]search.Hit = undefined;
    const found = index.find(term, &hits);
    var n: usize = 0;
    for (hits[0..found]) |hit| {
        if (n == out.len) break;
        const pk = index.entries[hit.entry].pubkey;
        if (isMuted(pk)) continue;
        out[n] = pk;
        n += 1;
    }
    return n;
}

/// Reads the kind:0 of each person from the store into the profile cache, so a
/// row can draw a name rather than a key. Disk first and exact, as the wanted
/// profiles pass has always done: the store has an author+kind index.
fn hydrateProfiles(pubkeys: []const [32]u8) void {
    if (pubkeys.len == 0) return;
    const store = g_store orelse return;
    const kinds = [_]u16{0};
    var result = store.query(std.heap.page_allocator, .{ .authors = pubkeys, .kinds = &kinds, .limit = @intCast(pubkeys.len) }) catch return;
    defer result.deinit();
    for (result.events) |ev| {
        const prof = upsertProfile(ev.pubkey) orelse continue;
        if (std.mem.eql(u8, &prof.meta_id, &ev.id)) continue;
        parseMetadataInto(prof, ev.content);
        prof.meta_id = ev.id;
        g_names_generation +%= 1;
    }
}

// --- the index

/// Builds a fresh index on a worker if the one held is missing or old.
fn searchIndexEnsure() void {
    if (comptime builtin.is_test) return;
    if (g_store == null) return;
    // Under the lock: the worker writes both of these from its own thread.
    const now = nowSeconds();
    lockSearchIndex();
    const fresh = g_search_index_ready and now - g_search_index_built_s < search_index_ttl_s;
    unlockSearchIndex();
    if (fresh) return;
    if (g_search_index_building.swap(true, .acq_rel)) return;
    const thread = std.Thread.spawn(.{}, searchIndexWorker, .{}) catch {
        g_search_index_building.store(false, .release);
        return;
    };
    thread.detach();
}

fn searchIndexWorker() void {
    defer g_search_index_building.store(false, .release);
    searchIndexRefresh();
}

/// The accounts whose contact lists name the reader. The store can only say who
/// follows the reader among the lists it holds, which is the honest meaning of
/// "people who follow me" here: nothing local can know about a list never read.
fn searchFollowers(gpa: std.mem.Allocator, store: *nostr.store.Store) std.AutoHashMapUnmanaged([32]u8, void) {
    var set: std.AutoHashMapUnmanaged([32]u8, void) = .empty;
    const me = activePubkey() orelse return set;
    var hex: [64]u8 = undefined;
    hexLower(&hex, me);
    const kinds = [_]u16{contact_list_kind};
    const values = [_][]const u8{&hex};
    const tags = [_]nostr.filter.TagFilter{.{ .letter = 'p', .values = &values }};
    var result = store.query(gpa, .{ .kinds = &kinds, .tags = &tags, .limit = search_followers_max }) catch return set;
    defer result.deinit();
    for (result.events) |ev| set.put(gpa, ev.pubkey, {}) catch break;
    return set;
}

/// Reads every kind:0 in the store into a new index and swaps it in.
fn searchIndexRefresh() void {
    const store = g_store orelse return;
    const gpa = std.heap.page_allocator;
    var builder = search.Builder.init(gpa);
    defer builder.deinit();
    var followers = searchFollowers(gpa, store);
    defer followers.deinit(gpa);
    var added: std.AutoHashMapUnmanaged([32]u8, void) = .empty;
    defer added.deinit(gpa);
    var scratch = std.heap.ArenaAllocator.init(gpa);
    defer scratch.deinit();

    const Meta = struct {
        name: ?[]const u8 = null,
        display_name: ?[]const u8 = null,
        displayName: ?[]const u8 = null,
        nip05: ?[]const u8 = null,
    };

    var until: ?i64 = null;
    var scanned: usize = 0;
    while (scanned < search_scan_max) {
        const kinds = [_]u16{0};
        var page = store.query(gpa, .{ .kinds = &kinds, .until = until, .limit = search_scan_page }) catch break;
        defer page.deinit();
        if (page.events.len == 0) break;
        var fresh: usize = 0;
        for (page.events) |ev| {
            scanned += 1;
            if (added.contains(ev.pubkey)) continue;
            _ = scratch.reset(.retain_capacity);
            const meta = std.json.parseFromSliceLeaky(Meta, scratch.allocator(), ev.content, .{ .ignore_unknown_fields = true }) catch continue;
            // The same choice `parseMetadataInto` makes, so the row that is
            // drawn is named by the string that was matched.
            var shown: []const u8 = "";
            for ([_]?[]const u8{ meta.displayName, meta.display_name, meta.name }) |candidate| {
                const trimmed = std.mem.trim(u8, candidate orelse continue, " \t\r\n");
                if (trimmed.len == 0) continue;
                shown = trimmed;
                break;
            }
            const user = std.mem.trim(u8, meta.name orelse "", " \t\r\n");
            var address = std.mem.trim(u8, meta.nip05 orelse "", " \t\r\n");
            if (std.mem.indexOfScalar(u8, address, '@') == null) address = "";
            const tier: search.Tier = if (inFollowGraph(ev.pubkey)) .follows else if (followers.contains(ev.pubkey)) .follows_me else .seen;
            builder.add(ev.pubkey, tier, ev.created_at, shown, user, address) catch break;
            added.put(gpa, ev.pubkey, {}) catch break;
            fresh += 1;
        }
        if (page.events.len < search_scan_page) break;
        const oldest = page.events[page.events.len - 1].created_at;
        // A whole page inside one second that brought nothing new will bring
        // nothing new again.
        if (until != null and until.? == oldest and fresh == 0) break;
        until = oldest;
    }

    var fresh_index = builder.finish() catch return;
    const built_s = nowSeconds();
    lockSearchIndex();
    std.mem.swap(search.Index, &g_search_index, &fresh_index);
    g_search_index_ready = true;
    g_search_index_built_s = built_s;
    unlockSearchIndex();
    fresh_index.deinit(gpa);
}

// --- the relays

/// What one relay thread is told.
const SearchJob = struct {
    gen: u32,
    relay: u8,
    url: []const u8,
    term: [search.term_max]u8,
    term_len: u8,
};

/// Puts the term on screen to the search relays, once per term.
fn searchAskRelays() void {
    const gen = g_search_gen.load(.acquire);
    if (g_search_term_len == 0 or g_search_asked == gen) return;
    g_search_asked = gen;
    if (!relayFetchAllowed()) return;
    const urls = searchRelays();
    for (urls, 0..) |url, i| {
        if (i >= search.relays_max) break;
        if (relaysPaused()) {
            g_search_status[i].store((search.Status{ .gen = gen, .state = .paused, .count = 0 }).pack(), .release);
            continue;
        }
        g_search_status[i].store((search.Status{ .gen = gen, .state = .asking, .count = 0 }).pack(), .release);
        var job = SearchJob{ .gen = gen, .relay = @intCast(i), .url = url, .term = undefined, .term_len = @intCast(g_search_term_len) };
        @memcpy(job.term[0..g_search_term_len], g_search_term[0..g_search_term_len]);
        const thread = std.Thread.spawn(.{}, searchRelayWorker, .{job}) catch {
            g_search_status[i].store((search.Status{ .gen = gen, .state = .unreachable_, .count = 0 }).pack(), .release);
            continue;
        };
        thread.detach();
    }
}

/// Publishes a relay's outcome, unless the term has moved on.
fn searchPublish(job: SearchJob, state: search.RelayState, count: u16) void {
    if (g_search_gen.load(.acquire) != job.gen) return;
    g_search_status[job.relay].store((search.Status{ .gen = job.gen, .state = state, .count = count }).pack(), .release);
}

/// Keeps one person a relay returned: verified, stored, and queued for the list.
/// False when the event is not a profile or does not verify.
fn searchAccept(gpa: std.mem.Allocator, signer: nostr.keys.Signer, job: SearchJob, ev: nostr.event.Event) bool {
    if (ev.kind != 0) return false;
    const result = plazaIngest(gpa, ev, .{ .verify_with = signer }) catch return false;
    if (result == .invalid) return false;
    searchArrived(job.gen, job.relay, ev.pubkey);
    return true;
}

fn searchArrived(gen: u32, relay: u8, pubkey: [32]u8) void {
    lockSearchInbox();
    defer unlockSearchInbox();
    // A full inbox drops the newest: the list is as full as it will get long
    // before this many people have been named.
    if (g_search_inbox_len == g_search_inbox.len) return;
    g_search_inbox[g_search_inbox_len] = .{ .gen = gen, .relay = relay, .pubkey = pubkey };
    g_search_inbox_len += 1;
}

/// Asks one search relay for profiles matching the term, on its own thread.
fn searchRelayWorker(job: SearchJob) void {
    const gpa = std.heap.page_allocator;
    var threaded = std.Io.Threaded.init(gpa, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var signer = nostr.keys.Signer.init();
    defer signer.deinit();

    var state: search.RelayState = .unreachable_;
    var found: u16 = 0;
    // Who this relay has named, so two versions of one profile count once.
    var seen: search.Seen = .{};
    defer searchPublish(job, state, found);

    var relay = nostr.relay.dial(gpa, io, job.url) catch return;
    defer relay.deinit();
    // Bounded by the keeper like every other one-shot read: a relay that takes
    // the request and goes quiet must not hold this thread for the life of the
    // process.
    const watched = watchOneShot(io, relay, one_shot_budget_ms);
    defer releaseOneShot(watched);
    const request = search.requestText(gpa, job.term[0..job.term_len]) catch return;
    defer gpa.free(request);
    search.sendText(relay, request) catch return;
    // Asked. From here a relay that never says anything is a quiet one, not one
    // that could not be reached.
    state = .silent;

    // Read in slices of a second rather than parked in `receive`. A thread
    // blocked there cannot see that the term has moved on, and kept a socket
    // and a keeper slot for a search nobody was looking at until the relay next
    // spoke. The deadline is its own as well as the keeper's, so the thread ends
    // even when the keeper's table was full and nothing is watching it.
    const deadline = std.Io.Timestamp.now(io, .awake).toMilliseconds() + one_shot_budget_ms;
    var frames: usize = 0;
    while (frames < search_frames_max) {
        if (g_search_gen.load(.acquire) != job.gen) return;
        if (std.Io.Timestamp.now(io, .awake).toMilliseconds() >= deadline) break;
        var msg = (relay.receiveTimeout(ingest_wake) catch |err| switch (err) {
            error.Timeout => continue,
            else => break,
        }) orelse break;
        defer msg.deinit();
        frames += 1;
        const reply: search.Reply = switch (msg.value) {
            .event => |e| blk: {
                if (searchAccept(gpa, signer, job, e.event) and seen.add(e.event.pubkey)) found +|= 1;
                break :blk .event;
            },
            .eose => .eose,
            .closed => .closed,
            .notice => .notice,
            .auth => .auth,
            else => .other,
        };
        if (search.settle(reply, found)) |done| {
            state = done;
            return;
        }
    }
    // The connection ended, or the budget did, with people already in hand.
    if (found > 0) state = .answered;
}

/// Moves what the relay threads found into the list, on the UI thread.
fn searchDrain() void {
    var batch: [search_inbox_cap]SearchArrival = undefined;
    lockSearchInbox();
    const n = g_search_inbox_len;
    @memcpy(batch[0..n], g_search_inbox[0..n]);
    g_search_inbox_len = 0;
    unlockSearchInbox();
    if (n == 0) return;

    const gen = g_search_gen.load(.acquire);
    var fresh: [search_inbox_cap][32]u8 = undefined;
    var fresh_len: usize = 0;
    for (batch[0..n]) |arrival| {
        if (arrival.gen != gen) continue;
        const bit: u8 = @as(u8, 1) << @intCast(arrival.relay);
        var known = false;
        for (g_search_rows[0..g_search_len]) |*row| {
            if (!std.mem.eql(u8, &row.pubkey, &arrival.pubkey)) continue;
            row.relays |= bit;
            known = true;
            break;
        }
        if (known or g_search_len == search_rows_max or isMuted(arrival.pubkey)) continue;
        g_search_rows[g_search_len] = .{ .pubkey = arrival.pubkey, .local = false, .relays = bit };
        g_search_len += 1;
        fresh[fresh_len] = arrival.pubkey;
        fresh_len += 1;
    }
    hydrateProfiles(fresh[0..fresh_len]);
}

/// The tick's share: ask the relays once typing has settled, and take in what
/// they have sent. Only while the field is open.
fn searchTick(model: *const Model, now_ms: i64) void {
    if (!model.address_open) return;
    // A NIP-05 address is asked of its domain, so only a name is put to relays.
    const is_name = classifySearch(model.address_buffer.text()) == .term;
    if (is_name and g_search_term_len >= search_auto_min and now_ms - g_search_typed_ms >= search_settle_ms) searchAskRelays();
    searchDrain();
}

/// How one relay stands for the term on screen. A status left over from an
/// earlier term reads as not asked.
fn searchRelayStatus(i: usize) search.Status {
    const s = search.Status.unpack(g_search_status[i].load(.acquire));
    if (s.gen != g_search_gen.load(.acquire)) return .{ .gen = 0, .state = .idle, .count = 0 };
    return s;
}

// --- NIP-05

/// The address being looked up, and whether the answer is awaited.
var g_nip05_ask: ?Nip05Address = null;
/// The key that lookup went out under. An answer under any other key is to an
/// earlier lookup, possibly for another domain, and is not this one's answer.
var g_nip05_ask_key: u64 = 0;
var g_nip05_seq: u64 = 0;

fn sameNip05(a: *const Nip05Address, b: *const Nip05Address) bool {
    return std.mem.eql(u8, a.name(), b.name()) and std.mem.eql(u8, a.domain(), b.domain());
}

/// Whether the address in the field is the one whose answer is awaited.
fn nip05Pending(text: []const u8) bool {
    const ask = g_nip05_ask orelse return false;
    const current = nip05Address(text) orelse return false;
    return sameNip05(&ask, &current);
}

/// Sends the lookup for `name@domain`. The domain is a stranger's, from the
/// reader's own address, which is why this waits for an explicit press instead
/// of running as they type.
fn lookupNip05(model: *Model, fx: *Effects) void {
    const addr = nip05Address(model.address_buffer.text()) orelse return;
    var url_buf: [320]u8 = undefined;
    const url = nip05LookupUrl(&url_buf, &addr) orelse {
        model.address_error = .unreadable;
        return;
    };
    g_nip05_seq +%= 1;
    g_nip05_ask_key = nip05_lookup_key_base + g_nip05_seq % nip05_lookup_keys;
    g_nip05_ask = addr;
    model.address_error = .none;
    if (!networkAllowed()) return;
    fx.fetch(.{
        .key = g_nip05_ask_key,
        .url = url,
        .on_response = Effects.responseMsg(.nip05_found),
    });
}

/// The well-known document came back. Goes to the person it names, if the
/// reader is still looking at the address they asked about.
fn handleNip05Found(model: *Model, response: native_sdk.EffectResponse) void {
    // An answer to an earlier lookup. It may be from another domain, and the
    // field may hold that same name at a new one: read as this lookup's answer,
    // the old domain would get to say who the new address is.
    if (response.key != g_nip05_ask_key) return;
    const ask = g_nip05_ask orelse return;
    g_nip05_ask = null;
    // The reader typed on, or left. The answer is to a question nobody is
    // asking any more.
    const current = nip05Address(model.address_buffer.text()) orelse return;
    if (!model.address_open) return;
    if (!sameNip05(&current, &ask)) return;

    if (response.outcome != .ok or response.status != 200 or response.truncated or response.body.len == 0) {
        model.address_error = .lookup_failed;
        return;
    }
    var arena_state = std.heap.ArenaAllocator.init(std.heap.page_allocator);
    defer arena_state.deinit();
    const hit = nip05Resolve(arena_state.allocator(), ask.name(), response.body) orelse {
        model.address_error = .not_found;
        return;
    };
    closeAddress(model);
    // The page is drawn under Settings, as an opened address is.
    if (model.stage == .settings) leaveSettings(model);
    wantProfileHinted(hit.pubkey, hit.relays);
    openPerson(model, hit.pubkey);
}

/// Pressing a result.
fn searchPick(model: *Model, pubkey: [32]u8) void {
    closeAddress(model);
    if (model.stage == .settings) leaveSettings(model);
    openPerson(model, pubkey);
}

/// What Enter does with what is in the field.
fn submitAddress(model: *Model, fx: *Effects) void {
    switch (classifySearch(model.address_buffer.text())) {
        // Nothing is done with a key, on purpose. See `SearchInput.key`.
        .blank, .key => {},
        .address => openAddress(model, fx),
        .nip05 => lookupNip05(model, fx),
        // Straight to the relays: pressing Enter is asking now, not after the
        // pause that typing waits for.
        .term => searchAskRelays(),
    }
}

// --- test seams

/// Back to a fresh start: no index, no rows, no relay state.
pub fn searchResetForTest() void {
    searchReset();
    lockSearchIndex();
    g_search_index.deinit(std.heap.page_allocator);
    g_search_index_ready = false;
    unlockSearchIndex();
    g_search_asked = 0;
    g_search_typed_ms = 0;
    g_nip05_ask = null;
}

/// Builds the index now, on this thread, from the store.
pub fn searchIndexRefreshForTest() void {
    searchIndexRefresh();
}

pub fn searchIndexLenForTest() usize {
    lockSearchIndex();
    defer unlockSearchIndex();
    return g_search_index.entries.len;
}

pub fn searchRowCountForTest() usize {
    return g_search_len;
}

pub fn searchRowPubkeyForTest(i: usize) [32]u8 {
