}

pub fn searchTickForTest(model: *const Model, now_ms: i64) void {
    searchTick(model, now_ms);
}

/// Whether the term on screen has been put to the relays.
pub fn searchAskedForTest() bool {
    return g_search_term_len > 0 and g_search_asked == g_search_gen.load(.acquire);
}

pub fn searchGenForTest() u32 {
    return g_search_gen.load(.acquire);
}

/// A relay thread's hand-off, without the thread.
pub const search_inbox_cap_for_test = search_inbox_cap;

pub fn searchArrivedForTest(gen: u32, relay: u8, pubkey: [32]u8) void {
    searchArrived(gen, relay, pubkey);
}

/// What a relay thread does with one event.
pub fn searchAcceptForTest(gen: u32, relay: u8, signer: nostr.keys.Signer, ev: nostr.event.Event) bool {
    const job = SearchJob{ .gen = gen, .relay = relay, .url = "", .term = undefined, .term_len = 0 };
    return searchAccept(std.heap.page_allocator, signer, job, ev);
}

pub fn searchSetStatusForTest(relay: usize, state: search.RelayState, count: u16) void {
    g_search_status[relay].store((search.Status{ .gen = g_search_gen.load(.acquire), .state = state, .count = count }).pack(), .release);
}

pub fn searchRelayCountForTest() usize {
    return searchRelays().len;
}

pub fn searchRelayUrlForTest(i: usize) []const u8 {
    return searchRelays()[i];
}

pub fn nip05AskedForTest() bool {
    return g_nip05_ask != null;
}

pub fn handleNip05FoundForTest(model: *Model, response: native_sdk.EffectResponse) void {
    handleNip05Found(model, response);
}

/// The key the lookup now awaited went out under.
pub fn nip05AskKeyForTest() u64 {
    return g_nip05_ask_key;
}
pub const search_scan_page_for_test = search_scan_page;

fn openEvent(model: *Model, id: [32]u8) void {
    // A quote card or pill for an `naddr` carries the address's stand-in key
    // where an id would be, and opens the newest copy of the coordinate.
    if (addressFor(id)) |slot| {
        const addr = slot.addr;
        var hints: [RelayHints.cap][]const u8 = undefined;
        for (0..slot.hints.count) |i| hints[i] = slot.hints.at(@intCast(i));
        const n = slot.hints.count;
        openAddressedArticle(model, addr, hints[0..n]);
        return;
    }
    if (g_store) |store| {
        if (store.getEvent(std.heap.page_allocator, id) catch null) |found| {
            var se = found;
            defer se.deinit();
            enterEvent(model, se.event);
            return;
        }
    }
    // Not held. This is reachable from a notification, whose target is whatever
    // note the thing was about, and that note is often one nobody asked any relay
    // for: a stranger's parent in a thread the reader was named in, or the
    // reader's own note from before this install. Silence here is the worst
    // answer, because the row looks alive and is not. So ask for it, and say so.
    wantQuote(id);
    // And WAIT for it. Asking was all this did, and the fetch works: the id goes
    // into the quote cache, the relays the address named get dialled, and the
    // note lands in the store seconds later. Nothing recorded that the reader
    // was trying to GO somewhere, so there was nobody waiting on it when it
    // landed. The toast expired, the feed stayed the feed, and pasting the same
    // address a second time opened the thread instantly off the local copy.
    g_event_want = .{ .id = id, .from = standingNow(model) };
    setToast(model, "Fetching that note");
}

/// Where the reader is standing, in just enough detail to tell "still here"
/// from "gone somewhere else".
///
/// One snapshot compared on the tick, rather than a cancel written into each
/// door out of the feed. A cancel in `enterThread` would cover `enterThread`
/// and nothing else, and a note can arrive while the reader has opened a
/// profile, walked into a room, or gone into Settings just as easily.
const Standing = struct {
    stage: Stage = .ready,
    /// The open thread, zero at the feed.
    thread: i64 = 0,
    profile: ?[32]u8 = null,
    /// The open room: host plus `d`, the pair that is a place's identity, and
    /// null in the reader's own plaza. A title is not an identity, and two
    /// communities may share one.
    place: ?struct { pubkey: [32]u8, ident_buf: [64]u8, ident_len: u8 } = null,

    fn eql(a: Standing, b: Standing) bool {
        if (a.stage != b.stage or a.thread != b.thread) return false;
        if ((a.profile == null) != (b.profile == null)) return false;
        if (a.profile) |ap| {
            if (!std.mem.eql(u8, &ap, &b.profile.?)) return false;
        }
        if ((a.place == null) != (b.place == null)) return false;
        if (a.place) |ap| {
            const bp = b.place.?;
            if (!std.mem.eql(u8, &ap.pubkey, &bp.pubkey)) return false;
            if (!std.mem.eql(u8, ap.ident_buf[0..ap.ident_len], bp.ident_buf[0..bp.ident_len])) return false;
        }
        return true;
    }
};

fn standingNow(model: *const Model) Standing {
    var s = Standing{
        .stage = model.stage,
        .thread = model.viewing_thread,
        .profile = model.viewing_profile,
    };
    if (places.g_place) |*p| {
        var here: @TypeOf(s.place.?) = .{ .pubkey = p.author, .ident_buf = @splat(0), .ident_len = 0 };
        here.ident_len = @intCast(copyBounded(&here.ident_buf, p.ident()));
        s.place = here;
    }
    return s;
}

/// The note the reader asked to open, while it is being fetched.
///
/// The same three parts the place fetch has: what was asked for, a tick that
/// applies it when it arrives, and a bounded give-up.
var g_event_want: ?struct {
    id: [32]u8,
    /// Ticks the fetch has been outstanding, so it can give up and say so.
    waited: u16 = 0,
    /// Where the reader was standing when they asked.
    from: Standing,
} = null;

/// Looks for the note being waited on, once the store has grown. Called from
/// the tick, beside the place fetch this is modelled on, which is where every
/// other "did it arrive yet" check in this app lives.
fn refreshEventFetch(model: *Model) void {
    const want = g_event_want orelse return;
    // Gone somewhere else since asking. The window closes rather than pulling
    // the reader out of whatever they picked up instead, the same rule the
    // place fetch follows when the reader steps sideways out of a linked room.
    if (!want.from.eql(standingNow(model))) {
        g_event_want = null;
        return;
    }
    const store = g_store orelse return;
    if (store.getEvent(std.heap.page_allocator, want.id) catch null) |found| {
        var se = found;
        defer se.deinit();
        // Closed BEFORE the navigation. `enterThread` moves the reader, so a
        // window still open here would read its own arrival as a walk away on
        // the next tick: right by accident, and only while that stays the last
        // thing this function does.
        g_event_want = null;
        enterEvent(model, se.event);
        return;
    }
    // Give up eventually rather than watching a store read forever, and say so
    // out loud. A reader told "Fetching that note" and then left on the feed
    // with no second word cannot tell a slow relay from a note nobody has.
    g_event_want.?.waited +|= 1;
    if (g_event_want.?.waited > event_fetch_ticks) {
        g_event_want = null;
        setToast(model, "That note did not turn up.");
    }
}

/// How many ticks a note fetch may go unanswered. The same window a place gets,
/// for the same reason: the tick is a second, and a relay that has not answered
/// in fifteen is one that does not have it.
const event_fetch_ticks = 15;

/// Drives the REAL entry path, so what the test asserts is what a reader gets.
pub fn openEventForTest(model: *Model, id: [32]u8) void {
    openEvent(model, id);
}

/// One tick of the store-side half of that fetch.
pub fn refreshEventFetchForTest(model: *Model) void {
    refreshEventFetch(model);
}

/// Whether the window is still watching. Closed is what both walking away and
/// arriving must produce: an open window keeps reading the store every tick.
pub fn eventFetchArmedForTest() bool {
    return g_event_want != null;
}

pub fn forgetEventFetchForTest() void {
    g_event_want = null;
}

/// Back to the feed from wherever the reader has got to, in one press.
///
/// Not a Back: it drops the whole stack rather than one level, because the mark
/// in the corner of the rail is a destination and not a step. Settings is left,
/// any open person or thread is closed, and the overlays that live above the
/// feed go with them, since landing on the feed behind a panel is not landing
/// on the feed.
///
/// The sheets that ask the reader something (signing in, naming a fresh key)
/// are deliberately NOT touched here. They are questions with an answer owed,
/// and dismissing one as a side effect of navigating is how a remembered intent
/// gets dropped.
fn goHome(model: *Model) void {
    model.thread_stack_len = 0;
    model.notifications_return = false;
    model.viewing_profile = null;
    model.viewing_thread = 0;
    // Every kind of level, not the two that were written first. A topic and the
    // bookmark list were left set, so `levelOpen` stayed true and the mark did
    // nothing from either page.
    model.topic_len = 0;
    model.viewing_bookmarks = false;
    model.thread_loading = false;
    model.thread_notes_len = 0;
    parkReplyDraft(model);
    model.menu = .none;
    model.notifications_open = false;
    model.stage = .ready;
    // Home is YOUR feed, so the mark closes the room. Not the same verb as
    // Leave: the place stays in the list with its ids intact, one press away on
    // the rail, which is deliberately left exactly as it was. Hiding it here is
    // what made coming back cost two presses.
    goToOwnPlaza();
}

pub fn goHomeForTest(model: *Model) void {
    goHome(model);
}

/// Closes the open thread: pops the back-stack to the thread it was opened from,
/// or returns to the feed (which kept its scroll offset) when the stack is empty.
fn closeThread(model: *Model) void {
    // The level being left is the one that resets: the level underneath keeps
    // its pages, its held section and its arrival order, which is what makes the
    // walk back land where the reader left it.
    model.thread_page[model.currentLevel()] = 1;
    model.thread_outside_open[model.currentLevel()] = false;
    parkReplyDraft(model);
    model.thread_notes_len = 0;
    if (model.thread_stack_len > 0) {
        model.thread_stack_len -= 1;
        const prev = model.thread_stack[model.thread_stack_len];
        // Same ordering as `enterThread`, and for the same reason.
        const now = nowSeconds();
        const seq = g_thread_seq.fetchAdd(1, .monotonic) + 1;
        model.thread_seq = seq;
        model.thread_open_at = now;
        if (prev.bookmarks) {
            model.viewing_profile = null;
            model.viewing_thread = 0;
            model.topic_len = 0;
            model.viewing_bookmarks = true;
            model.refreshBookmarkNotes(now);
            model.thread_loading = false;
        } else if (prev.topic()) |topic| {
            model.viewing_bookmarks = false;
            model.viewing_profile = null;
            model.viewing_thread = 0;
            @memcpy(model.topic_buf[0..topic.len], topic);
            model.topic_len = @intCast(topic.len);
            model.refreshTopicNotes(now);
            model.thread_loading = model.thread_notes_len == 0;
            fetchTopicNotes(topic, seq);
        } else if (prev.profile) |pk| {
            model.viewing_bookmarks = false;
            model.topic_len = 0;
            model.viewing_profile = pk;
            model.viewing_thread = 0;
            model.profile_limit = prev.profile_limit;
            model.profile_autofill = 0;
            model.profile_asked_until = 0;
            g_profile_bottom_in_view = false;
            armProfileReach(pk, false);
            model.refreshProfileNotes(now);
            model.thread_loading = model.thread_notes_len == 0;
            fetchProfileNotes(pk, seq);
        } else {
            model.viewing_bookmarks = false;
            model.topic_len = 0;
            model.viewing_profile = null;
            model.viewing_thread = prev.note.id;
            model.thread_root = prev.note;
            takeReplyDraft(model, prev.note.event_id);
            model.refreshThreadNotes(now);
            model.thread_loading = model.thread_notes_len == 0;
            fetchThreadReplies(prev.note.event_id, seq);
        }
    } else {
        model.viewing_bookmarks = false;
        model.topic_len = 0;
        model.viewing_profile = null;
        model.viewing_thread = 0;
        model.thread_loading = false;
        // Back to where the reader actually came from. The list is rebuilt from
        // the same inbox and the window keeps its offset on the list's own id,
        // so this lands on the row they pressed rather than at the top.
        if (model.notifications_return) {
            model.notifications_return = false;
            model.notifications_open = true;
        }
    }
}

// The open-thread generation, so a reply fetch can report completion for the
// thread it was launched for and not a later one. `g_thread_seq` is bumped on
// each open; the worker copies its seq and, when it has asked every relay,
// stores it into `g_thread_done_seq`. The UI thread clears the loading skeletons
// only when the CURRENT thread's fetch is the one that finished (so a genuinely
// empty thread stops loading, but a stale late worker never clears a new thread).
var g_thread_seq = std.atomic.Value(u64).init(0);
var g_thread_done_seq = std.atomic.Value(u64).init(0);

const topic_kinds = [_]u16{1};

/// The filter for a topic: kind:1 notes carrying a `t` tag with this value,
/// newest `thread_reply_cap`. One definition for the store read and the relay
/// ask, so the two cannot drift into answering different questions.
///
/// Jumble sends `{"#t":[tag]}` to its default relays with the tag lowercased
/// (src/pages/secondary/NoteListPage/index.tsx:49, src/lib/link.ts:29), and
/// Amethyst keys the subscription on the lowercased tag and asks for kind 1
/// among others (HashtagFeedFilterSubAssembler.kt, FilterPostsByHashtags.kt:81-95).
/// NIP-24 says `t` values are lowercase, which `openTopic` guarantees.
fn topicFilter(values: *const [1][]const u8, tags: *[1]nostr.filter.TagFilter) nostr.filter.Filter {
    tags.* = .{.{ .letter = 't', .values = values }};
    return .{ .kinds = &topic_kinds, .tags = tags, .limit = thread_reply_cap };
}

/// The REQ a topic sends, as the relay receives it.
pub fn topicReqForTest(gpa: std.mem.Allocator, topic: []const u8) ![]u8 {
    const values = [_][]const u8{topic};
    var tags: [1]nostr.filter.TagFilter = undefined;
    const filters = [_]nostr.filter.Filter{topicFilter(&values, &tags)};
    return nostr.message.encodeReq(gpa, "plaza-topic", &filters);
}

/// Asks this reader's read relays for a topic, once. A topic has no author, so
/// there is no outbox question to answer: the relays this reader already reads
/// are the honest set, rather than a search relay nobody chose.
fn fetchTopicNotes(topic: []const u8, seq: u64) void {
    if (!relayFetchAllowed() or topic.len == 0 or topic.len > max_topic_bytes) {
        g_thread_done_seq.store(seq, .release);
        return;
    }
    var owned: [max_topic_bytes]u8 = undefined;
    @memcpy(owned[0..topic.len], topic);
    const thread = std.Thread.spawn(.{}, fetchTopicWorker, .{ owned, @as(u8, @intCast(topic.len)), seq }) catch {
        g_thread_done_seq.store(seq, .release);
        return;
    };
    thread.detach();
}

fn fetchTopicWorker(topic_buf: [max_topic_bytes]u8, topic_len: u8, seq: u64) void {
    const gpa = std.heap.page_allocator;
    var threaded = std.Io.Threaded.init(gpa, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var signer = nostr.keys.Signer.init();
    defer signer.deinit();
    defer g_thread_done_seq.store(seq, .release);

    const topic = topic_buf[0..topic_len];
    const values = [_][]const u8{topic};
    var tags: [1]nostr.filter.TagFilter = undefined;
    const filters = [_]nostr.filter.Filter{topicFilter(&values, &tags)};

    for (0..relaySlots()) |ri| {
        var url_buf: [96]u8 = undefined;
        const entry = relaySnapshot(ri, &url_buf) orelse continue;
        if (!entry.read) continue;
        var relay = nostr.relay.dial(gpa, io, entry.url) catch continue;
        // Declared AFTER deinit so it runs BEFORE it: the keeper must have let
        // go of this pointer before the connection is freed.
        defer relay.deinit();
        const watched = watchOneShot(io, relay, one_shot_budget_ms);
        defer releaseOneShot(watched);
        relay.subscribe("plaza-topic", &filters) catch continue;
        var seen: usize = 0;
        // Bounded, for the reason the profile fetch is: `receive` has no
        // deadline, and a relay that accepts a subscription and then goes quiet
        // would hold this thread for the life of the process.
        while (seen < profile_fetch_messages) : (seen += 1) {
            var msg = (relay.receive() catch break) orelse break;
            defer msg.deinit();
            switch (msg.value) {
                .event => |e| {
                    if (e.event.kind != 1) continue;
                    const result = plazaIngestFrom(gpa, e.event, .{ .verify_with = signer }, entry.url) catch continue;
                    if (result == .invalid) continue;
                },
                .eose => break,
                // A CLOSED ends this relay's part, and no EOSE is coming after it.
                .closed => break,
                else => {},
            }
        }
        relay.unsubscribe("plaza-topic") catch {};
    }
}

/// Fetches a person's recent notes (and their engagement) into the store, on a
/// detached thread. Mirrors the thread's two-phase backfill exactly: one dial per
/// read relay, their kind:1s, then on EOSE a second subscription for what those
/// notes collected, folding into the same engagement table the feed and threads
/// use. Without the second phase every row on a profile shows zero counts.
fn fetchProfileNotes(pubkey: [32]u8, seq: u64) void {
    // Opening a page is asking again, so the end of its history is forgotten:
    // the relays may hold more than they did, and the relay set may be another.
    resetProfileEnd();
    if (!relayFetchAllowed()) {
        g_thread_done_seq.store(seq, .release);
        return;
    }
    const thread = std.Thread.spawn(.{}, fetchProfileWorker, .{ pubkey, seq }) catch {
        g_thread_done_seq.store(seq, .release);
        return;
    };
    thread.detach();
}

fn fetchProfileWorker(pubkey: [32]u8, seq: u64) void {
    defer g_thread_done_seq.store(seq, .release);
    _ = profileRound(pubkey, null);
}

/// What one pass over the relays learned, for deciding whether history ended.
const ProfileRound = struct {
    /// Relays that took the subscription.
    asked: usize = 0,
    /// Relays that answered it to the end.
    answered: usize = 0,
    /// Notes that were new to the store.
    added: usize = 0,
    /// Notes the relays returned that are strictly older than the cursor asked
    /// from. This, not `added`, is what says whether there was anything to find:
    /// a note can be a duplicate because another fetch stored it a moment
    /// earlier, which says nothing about whether history has ended.
    older: usize = 0,
    /// How far back this round brought their notes without leaving a hole (see
    /// `roundReach`). Null when it brought none.
    reach: ?i64 = null,
};

/// One note a round brought: when it was written, and which one it is.
pub const ProfileSeen = struct { at: i64, key: i64 };

/// Where a round's notes stop being complete. Each relay sent its newest page
/// below the cursor, and below the oldest note of the shortest page another
/// relay may hold notes that nobody has sent yet. So the cut is the
/// `profile_relay_page`-th newest distinct note across them all, and every note
/// above it is in hand from every relay asked. When there were fewer than a page,
/// every relay sent all it had, and the oldest is the cut.
///
/// Jumble cuts its merged page the same way: it sorts what the relays sent and
/// keeps `limit` of it before taking the oldest as the next cursor
/// (services/client.service.ts:749-755).
fn roundReach(seen: []ProfileSeen) ?i64 {
    if (seen.len == 0) return null;
    std.mem.sort(ProfileSeen, seen, {}, struct {
        fn newer(_: void, a: ProfileSeen, b: ProfileSeen) bool {
            if (a.at != b.at) return a.at > b.at;
            return a.key < b.key;
        }
    }.newer);
    var distinct: usize = 0;
    var cut = seen[0].at;
    for (seen, 0..) |note, i| {
        if (i > 0 and note.key == seen[i - 1].key and note.at == seen[i - 1].at) continue;
        distinct += 1;
        cut = note.at;
        if (distinct == profile_relay_page) break;
    }
    return cut;
}

pub fn roundReachForTest(seen: []ProfileSeen) ?i64 {
    return roundReach(seen);
}

/// The most connections one older-notes round makes: the author's own write
/// relays, then the reader's read relays.
const profile_round_targets = outbox_relays_per_author + max_relays;

/// The write relays a relay list names, as owned strings, in the order the list
/// gives them. The same selection the feed's routing makes, from the same
/// function, so the two cannot disagree about where somebody publishes.
fn writeRelaysOf(ev: nostr.event.Event, out: *[outbox_relays_per_author][96]u8, lens: *[outbox_relays_per_author]u8) usize {
    var raw: [32][]const u8 = undefined;
    var selected: [outbox_relays_per_author][]const u8 = undefined;
    const chosen = selectWriteRelays(raw[0..writeTagUrls(ev, &raw)], &selected);
    for (selected[0..chosen], 0..) |url, i| {
        @memcpy(out[i][0..url.len], url);
        lens[i] = @intCast(url.len);
    }
    return chosen;
}

pub fn writeRelaysOfForTest(ev: nostr.event.Event, out: *[outbox_relays_per_author][96]u8, lens: *[outbox_relays_per_author]u8) usize {
    return writeRelaysOf(ev, out, lens);
}

/// Where to ask for somebody's older notes: the relays they publish to, which
/// is where the outbox model says their notes are, then the reader's own read
/// relays. Jumble does the same, `relayList.write` followed by its defaults
/// (Profile/ProfileFeed.tsx:140).
///
/// The author's list is read from the store, so it is whatever the routing has
/// already fetched, and a person whose list has not arrived is asked of the
/// reader's relays alone, which is also what the first page does.
fn profileTargets(pubkey: [32]u8, out: *[profile_round_targets][96]u8, lens: *[profile_round_targets]u8) usize {
    var n: usize = 0;
    if (g_store) |store| {
        const kinds = [_]u16{relay_list_kind};
        const authors = [_][32]u8{pubkey};
        if (store.query(std.heap.page_allocator, .{ .authors = &authors, .kinds = &kinds, .limit = 1 })) |res| {
            var result = res;
            defer result.deinit();
            if (result.events.len > 0) {
                var own: [outbox_relays_per_author][96]u8 = undefined;
                var own_lens: [outbox_relays_per_author]u8 = undefined;
                const got = writeRelaysOf(result.events[0], &own, &own_lens);
                for (0..got) |i| {
                    @memcpy(out[n][0..own_lens[i]], own[i][0..own_lens[i]]);
                    lens[n] = own_lens[i];
                    n += 1;
                }
            }
        } else |_| {}
    }
    for (0..relaySlots()) |ri| {
        if (n >= out.len) break;
        var url_buf: [96]u8 = undefined;
        const entry = relaySnapshot(ri, &url_buf) orelse continue;
        if (!entry.read) continue;
        var seen = false;
        for (0..n) |i| {
            if (relayUrlEql(out[i][0..lens[i]], entry.url)) {
                seen = true;
                break;
            }
        }
        if (seen) continue;
        @memcpy(out[n][0..entry.url.len], entry.url);
        lens[n] = @intCast(entry.url.len);
        n += 1;
    }
    return n;
}

pub fn profileTargetsForTest(pubkey: [32]u8, out: *[profile_round_targets][96]u8, lens: *[profile_round_targets]u8) usize {
    return profileTargets(pubkey, out, lens);
}

/// The filter that asks for a person's notes older than `until`. `until` is
/// inclusive in NIP-01, so the note it was taken from comes back once and the
/// store drops it as a duplicate; asking for `until - 1` instead would lose
/// every other note written in that same second.
pub fn buildProfileOlderFilter(authors: []const [32]u8, until: i64) nostr.filter.Filter {
    return .{
        .authors = authors,
        .kinds = &profile_note_kinds,
        .until = until,
        .limit = profile_relay_page,
    };
}

const profile_note_kinds = [_]u16{ 1, comment_kind };

/// The filter for a person's newest notes, the page their profile opens with.
/// Comments as well as notes, the same kinds an older page asks for: the next
/// page starts where this one reached, so a kind left out here is a kind
/// nothing ever asks for in the newest stretch of somebody's history.
pub fn buildProfileNewestFilter(authors: []const [32]u8) nostr.filter.Filter {
    return .{ .authors = authors, .kinds = &profile_note_kinds, .limit = profile_relay_page };
}

/// One pass over the relays for a person's notes. With no `until` it is the
/// page a profile opens with: the newest notes, their profile and contact list,
/// from the reader's read relays. With one it is the next page back, from the
/// relays the person publishes to as well.
///
/// Either way a second subscription then collects the reactions on what came
/// back, into the table every row reads its counts from.
fn profileRound(pubkey: [32]u8, until: ?i64) ProfileRound {
    const gpa = std.heap.page_allocator;
    var threaded = std.Io.Threaded.init(gpa, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var signer = nostr.keys.Signer.init();
    defer signer.deinit();

    var round = ProfileRound{};
    const authors = [_][32]u8{pubkey};
    // Their profile too: the screen needs an about, a banner and a lud16, none
    // of which the name-and-face cache models.
    const meta_kinds = [_]u16{ 0, contact_list_kind };
    const first_filters = [_]nostr.filter.Filter{
        buildProfileNewestFilter(&authors),
        .{ .authors = &authors, .kinds = &meta_kinds, .limit = 2 },
    };
    // Every note the round brought, for where it reached. A relay that sends more
    // than it was asked for has the rest left out, which only makes the cut newer.
    var brought: [profile_round_targets * profile_relay_page]ProfileSeen = undefined;
    var brought_len: usize = 0;
    const older_filters = [_]nostr.filter.Filter{buildProfileOlderFilter(&authors, until orelse 0)};
    const filters: []const nostr.filter.Filter = if (until != null) &older_filters else &first_filters;

    var targets: [profile_round_targets][96]u8 = undefined;
    var target_lens: [profile_round_targets]u8 = undefined;
    var target_count: usize = 0;
    if (until != null) {
        target_count = profileTargets(pubkey, &targets, &target_lens);
    } else {
        for (0..relaySlots()) |ri| {
            var url_buf: [96]u8 = undefined;
            const entry = relaySnapshot(ri, &url_buf) orelse continue;
            if (!entry.read or target_count >= targets.len) continue;
            @memcpy(targets[target_count][0..entry.url.len], entry.url);
            target_lens[target_count] = @intCast(entry.url.len);
            target_count += 1;
        }
    }

    for (0..target_count) |ti| {
        const target_url = targets[ti][0..target_lens[ti]];
        var relay = nostr.relay.dial(gpa, io, target_url) catch continue;
        // Declared AFTER deinit so it runs BEFORE it: the keeper must have
        // let go of this pointer before the connection is freed.
        defer relay.deinit();
        const watched = watchOneShot(io, relay, one_shot_budget_ms);
        defer releaseOneShot(watched);
        relay.subscribe(if (until != null) "plaza-person-older" else "plaza-person", filters) catch continue;
        round.asked += 1;
        var relay_older: usize = 0;

        var ids: [engagement_watch_cap][64]u8 = undefined;
        var watch: [engagement_watch_cap]i64 = undefined;
        var watch_len: usize = 0;
        var id_count: usize = 0;
        var engagement_open = false;
        var seen: usize = 0;
        // Bounded, because `relay.receive()` has no deadline and a relay that
        // accepts a subscription and then goes quiet would hold this thread for
        // the life of the process.
        while (seen < profile_fetch_messages) : (seen += 1) {
            var msg = (relay.receive() catch break) orelse break;
            defer msg.deinit();
            switch (msg.value) {
                .event => |e| {
                    // Phase 2's answers are REACTIONS, and a reaction that is
                    // only stored changes no count on any row: the table the
                    // rows read is filled by `countEngagement`, which is the
                    // whole reason phase 2 exists.
                    if (engagement_open) {
                        if (nostr.event.verify(gpa, signer, e.event) catch false)
                            countEngagement(e.event, watch[0..watch_len]);
                        continue;
                    }
                    const result = plazaIngestFrom(gpa, e.event, .{ .verify_with = signer }, target_url) catch continue;
                    if (result == .invalid) continue;
                    // Theirs, and a note: a relay can send anything down any
                    // subscription, and somebody else's note says nothing about
                    // how far back this person's history goes.
                    const theirs = std.mem.eql(u8, &e.event.pubkey, &pubkey);
                    if (theirs and (e.event.kind == 1 or e.event.kind == comment_kind)) {
                        if (result == .added) round.added += 1;
                        // `until` is inclusive, so the note the cursor came from
                        // comes back. It is not news, and counting it would let
                        // a page that found nothing older read as progress.
                        const below = if (until) |cursor| e.event.created_at < cursor else true;
                        if (below) {
                            if (until != null) {
                                round.older += 1;
                                relay_older += 1;
                            }
                            if (brought_len < brought.len) {
                                brought[brought_len] = .{ .at = e.event.created_at, .key = noteIdOf(e.event) };
                                brought_len += 1;
                            }
                        }
                    }
                    if (e.event.kind == 1 and id_count < ids.len) {
                        hexLower(&ids[id_count], e.event.id);
                        watch[watch_len] = noteIdOf(e.event);
                        watch_len += 1;
                        id_count += 1;
                    }
                },
                .eose => {
                    // "I have looked and that is all of it", which is the only
                    // message that lets an empty page mean the end.
                    if (!engagement_open) round.answered += 1;
                    if (engagement_open or id_count == 0) break;
                    engagement_open = true;
                    var evals: [engagement_watch_cap][]const u8 = undefined;
                    for (0..id_count) |i| evals[i] = &ids[i];
                    const eng_tags = [_]nostr.filter.TagFilter{.{ .letter = 'e', .values = evals[0..id_count] }};
                    const eng_filters = [_]nostr.filter.Filter{engagementFilter(&eng_tags)};
                    relay.subscribe("plaza-person-engagement", &eng_filters) catch break;
                },
                .closed => break,
                else => continue,
            }
        }
        // A full page from one relay is the page, whether or not the store had
        // those notes already. The rest of the list is for the next time the
        // reader reaches the end. Counting only what was new to the store made a
        // page of notes the store already held dial every relay in the list.
        if (until != null and relay_older >= profile_relay_page) break;
    }
    round.reach = roundReach(brought[0..brought_len]);
    if (round.reach) |at| noteProfileReach(pubkey, at);
    return round;
}

// ---------------------------------------------------- a person's older notes
//
// The same shape as the feed's paging above, and for the same reasons: the
// store first, the relays only once the store has nothing older, one round at a
// time, and an end of history that only a relay answering "nothing older" can
// declare.

/// Whether an older-notes round is out, so a reader who keeps scrolling does not
/// stack one dial per relay per frame.
var g_profile_older_busy = std.atomic.Value(bool).init(false);
/// Whose history a round found the end of. A key rather than a flag, because a
/// round for one person can land after the reader has walked to another, and
/// "that is all of it" is only true of the person it was asked about.
var g_profile_end = std.atomic.Value(u64).init(0);
/// The last older-notes ask, recorded before the network is consulted so a test
/// (which never opens a socket) can see what would have been sent.
var g_profile_older_ask: ?ProfileOlderAsk = null;

pub const ProfileOlderAsk = struct { pubkey: [32]u8, until: i64 };

fn profileEndKey(pubkey: [32]u8) u64 {
    return std.mem.readInt(u64, pubkey[0..8], .big) | 1;
}

fn profileEndReached(pubkey: [32]u8) bool {
    return g_profile_end.load(.monotonic) == profileEndKey(pubkey);
}

fn resetProfileEnd() void {
    g_profile_end.store(0, .monotonic);
}

pub fn profileEndReachedForTest(pubkey: [32]u8) bool {
    return profileEndReached(pubkey);
}

pub fn setProfileEndForTest(pubkey: [32]u8) void {
    g_profile_end.store(profileEndKey(pubkey), .monotonic);
}

pub fn resetProfileEndForTest() void {
    resetProfileEnd();
    g_profile_older_busy.store(false, .monotonic);
    g_profile_older_ask = null;
}

pub fn profileOlderAskForTest() ?ProfileOlderAsk {
    return g_profile_older_ask;
}

/// How far back the relays have brought the open person's notes on this visit:
/// the oldest cut any round has made (`roundReach`), the first page included.
///
/// The next page is asked from here, never from the oldest note in hand. The
/// store holds whatever any surface ever fetched, so beyond the run the relays
/// paged through it can hold one old note of theirs from a thread or a quote,
/// with a year of their history missing in between. Paging from that note
/// skipped the year, and since it was still the oldest note in hand on the next
/// visit, skipped it every time. Jumble pages from the refs its relays sent and
/// not from its cache (NoteList/index.tsx:519-523).
///
/// Written by the round's thread, read by the tick, so it is guarded. Only the
/// person the page is open on is recorded: a round for somebody the reader has
/// walked away from lands here as a no-op.
var g_profile_reach: struct { key: u64 = 0, at: i64 = no_profile_reach } = .{};
var g_profile_reach_lock = std.atomic.Value(bool).init(false);
const no_profile_reach = std.math.maxInt(i64);

fn lockProfileReach() void {
    while (g_profile_reach_lock.cmpxchgWeak(false, true, .acquire, .monotonic) != null) {}
}

fn unlockProfileReach() void {
    g_profile_reach_lock.store(false, .release);
}

/// Starts recording for `pubkey`. A fresh visit forgets how far an earlier one
/// got, because the person may have written since; Back to the same person keeps
/// it, along with the depth the list was paged to.
fn armProfileReach(pubkey: [32]u8, fresh: bool) void {
    const key = profileEndKey(pubkey);
    lockProfileReach();
    defer unlockProfileReach();
    if (!fresh and g_profile_reach.key == key) return;
    g_profile_reach = .{ .key = key };
}

fn noteProfileReach(pubkey: [32]u8, at: i64) void {
    const key = profileEndKey(pubkey);
    lockProfileReach();
    defer unlockProfileReach();
    if (g_profile_reach.key != key) return;
    g_profile_reach.at = @min(g_profile_reach.at, at);
}

fn profileReach(pubkey: [32]u8) ?i64 {
    const key = profileEndKey(pubkey);
    lockProfileReach();
    defer unlockProfileReach();
    if (g_profile_reach.key != key or g_profile_reach.at == no_profile_reach) return null;
    return g_profile_reach.at;
}

/// Records that a round for `pubkey` reached back to `at`, the way a relay
/// answer does, for a test that has no relay.
pub fn noteProfileReachForTest(pubkey: [32]u8, at: i64) void {
    noteProfileReach(pubkey, at);
}

pub fn profileReachForTest(pubkey: [32]u8) ?i64 {
    return profileReach(pubkey);
}

/// Where the next relay page for the open person starts. Before any round has
/// brought a note there is no run to continue, so the page asks for their
/// newest, from the moment the page opened: the first page only asked the
/// reader's own relays, and the next one also asks theirs.
fn profileOlderCursor(model: *const Model, pubkey: [32]u8) i64 {
    return profileReach(pubkey) orelse model.thread_open_at;
}

fn fetchOlderProfile(pubkey: [32]u8, until: i64) void {
    g_profile_older_ask = .{ .pubkey = pubkey, .until = until };
    if (!relayFetchAllowed()) return;
    if (g_profile_older_busy.swap(true, .acq_rel)) return;
    const thread = std.Thread.spawn(.{}, fetchProfileOlderWorker, .{ pubkey, until }) catch {
        g_profile_older_busy.store(false, .release);
        return;
    };
    thread.detach();
}

fn fetchProfileOlderWorker(pubkey: [32]u8, until: i64) void {
    defer g_profile_older_busy.store(false, .release);
    const round = profileRound(pubkey, until);
    if (profileRoundEnded(round)) g_profile_end.store(profileEndKey(pubkey), .monotonic);
}

/// Nothing anywhere had anything older, AND somebody was there to say so. The
/// same two-part rule as the feed: a round that reached nobody says nothing, and
/// the next scroll asks again.
fn profileRoundEnded(round: ProfileRound) bool {
    return feedEndLatches(round.asked, round.answered, round.older);
}

pub fn profileRoundEndedForTest(asked: usize, answered: usize, added: usize, older: usize) bool {
    return profileRoundEnded(.{ .asked = asked, .answered = answered, .added = added, .older = older });
}

/// Puts the page's first fetch back in flight, or lands it, for a test that has
/// no socket to do either.
pub fn setFirstProfileFetchOutForTest(model: *Model, out: bool) void {
    const done = g_thread_done_seq.load(.acquire);
    if (out) {
        model.thread_seq = done + 1;
    } else {
        g_thread_done_seq.store(model.thread_seq, .release);
    }
}

/// The reader reached the end of a person's list: one more page of their notes.
///
/// Store first. A read that came back full may have more behind it, so the limit
/// goes up a page and the list is read again; that is a disk read and the screen
/// grows at once. Only when the store had nothing more to give are the relays
/// asked, for what comes before where they have reached (`g_profile_reach`).
/// Jumble's order:
/// `_loadMoreTimeline` serves from its cached refs and only then queries with
/// `{ ...filter, until, limit }` (services/client.service.ts:731-751).
fn loadOlderProfile(model: *Model) void {
    const pk = model.viewing_profile orelse return;
    const held = model.thread_notes_len;
    if (held >= model.profile_limit and model.profile_limit < profile_notes_max) {
        model.profile_limit = @min(model.profile_limit + profile_page, profile_notes_max);
        model.refreshProfileNotes(nowSeconds());
        if (model.thread_notes_len > held) return;
    }
    if (held == 0 or held >= profile_notes_max) return;
    if (profileEndReached(pk)) return;
    // The page's own first fetch is still out. A short list reaches its end the
    // moment it opens, and paging from the one note the store had then would ask
    // for history the first fetch is already bringing, and find the end of it
    // by being second.
    if (g_thread_done_seq.load(.acquire) < model.thread_seq) return;
    const cursor = profileOlderCursor(model, pk);
    model.profile_asked_until = cursor;
    fetchOlderProfile(pk, cursor);
}

pub fn loadOlderProfileForTest(model: *Model) void {
    loadOlderProfile(model);
}

/// How many rows the open person's current tab holds.
fn profileTabCount(model: *const Model, pubkey: [32]u8) usize {
    var n: usize = 0;
    for (model.thread_notes[0..model.thread_notes_len]) |note| {
        if (!std.mem.eql(u8, &note.pubkey, &pubkey)) continue;
        if ((model.profile_tab == .replies) != note.has_reply_parent) continue;
        n += 1;
    }
    return n;
}

/// Whether the last row of the open person's list is built, which is to say on
/// screen or within the overscan beside it. Written by the view, read by the
/// tick, one frame stale like the other visible sets.
var g_profile_bottom_in_view: bool = false;

/// The list's bottom edge, watched rather than waited for.
///
/// `on_reach_end` fires once per approach and re-arms only after the reader has
/// scrolled well away, which is right for a long list and wrong for two cases.
/// A tab too short to scroll has no end to reach, and a list that has just
/// grown by less than a screen is still at its end with the trigger spent. Both
/// leave the reader at the bottom with nothing coming and no way to ask. This is
/// Jumble's bottom sentinel (an IntersectionObserver on the element
/// under the list, hooks/useInfiniteScroll.tsx:113-118 and NoteList/index.tsx:582):
/// while the bottom is in view and there may be more, ask.
///
/// Stops where asking again would be asking the same question. A round that
/// brought nothing older leaves the cursor where it was, and the next manual
/// reach-end is the reader's way of trying again.
fn loadAtProfileBottom(model: *Model) void {
    const pk = model.viewing_profile orelse return;
    if (!g_profile_bottom_in_view) return;
    if (model.thread_notes_len == 0) return;
    // The page's own first fetch is still out. Asking for older notes before the
    // newest have landed would page from a cursor that is about to move.
    if (g_thread_done_seq.load(.acquire) < model.thread_seq) return;
    if (g_profile_older_busy.load(.monotonic) or profileEndReached(pk)) return;
    // The store has nothing more and the relays were already asked from here.
    if (model.thread_notes_len < model.profile_limit and profileOlderCursor(model, pk) == model.profile_asked_until) return;
    // A short tab is the case a reader cannot scroll out of, so it is bounded:
    // an account with no replies at all would otherwise walk its whole history
    // for a tab that stays empty.
    if (profileTabCount(model, pk) < profile_fill_rows) {
        if (model.profile_autofill >= profile_autofill_max) return;
        model.profile_autofill += 1;
    }
    loadOlderProfile(model);
}

pub fn loadAtProfileBottomForTest(model: *Model, bottom_in_view: bool) void {
    g_profile_bottom_in_view = bottom_in_view;
    loadAtProfileBottom(model);
}

/// How many frames one relay gets to answer a profile's backfill before this
/// thread moves on. See the comment in `fetchProfileWorker`.
const profile_fetch_messages = 400;

/// One engagement query over prepared `#e` values.
///
/// Three screens ask this same question, and each used to write it out again.
/// They drifted: the thread and the profile capped the answer, and the feed's,
/// which is the one re-issued on every reconnect, carried no cap at all, so a
/// busy relay decided how much of four kinds across 128 note ids to send back.
/// One function now, so there is nothing left to drift.
pub fn engagementFilter(tags: []const nostr.filter.TagFilter) nostr.filter.Filter {
    return .{ .kinds = engagementKinds(), .tags = tags, .limit = engagement_request_limit };
}

/// Fetches a note's replies (and their engagement) into the store, on a detached
/// thread. One dial per relay: opening a thread is a rare, human-paced action, so
// --------------------------------------------------------- the relay-list sweep
//
// Who to ask about the people nobody in the pool can answer for.
//
// Every author whose kind:10002 Plaza does not hold is asked of the indexers,
// once per run. Eager over the whole follow list rather than lazily on a miss,
// because the routing table has to be warm BEFORE the first feed REQ or the
// feed goes to the wrong relays and the round trip is paid twice: three of the
// four clients read do the eager sweep for exactly that reason, and welshman,
// the one that does not, is also the one with no negative caching and an
// unbounded retry.
//
// DEFERRED, and named rather than quietly skipped: the answer is not written
// down across launches, so an author who has genuinely never published a
// relay list is asked again next time Plaza starts. Within a run they are
// asked once. Jumble is the only client of the five that persists a negative
// result, and doing it properly means a `checked_at` per pubkey in the store
// with a staleness rule, which is its own change.

pub fn sweepRelayListsForTest() void {
    sweepRelayLists();
}
pub fn collectUnroutedForTest(out: [][32]u8) usize {
    return collectUnrouted(out);
}
pub fn indexerRelaysForTest() []const []const u8 {
    return &indexer_relays;
}
pub fn indexerChunkForTest() usize {
    return indexer_chunk;
}
pub fn resetIndexerAskedForTest() void {
    routing.g_indexer_asked_len = 0;
    routing.g_indexed.store(0, .monotonic);
}
pub fn markIndexerAskedForTest(pk: [32]u8) void {
    if (routing.g_indexer_asked_len >= routing.g_indexer_asked.len) return;
    routing.g_indexer_asked[routing.g_indexer_asked_len] = pk;
    routing.g_indexer_asked_len += 1;
}
pub fn indexerAskedLenForTest() usize {
    return routing.g_indexer_asked_len;
}

pub fn relayFetchAllowedForTest() bool {
    return relayFetchAllowed();
}

fn fetchThreadReplies(root_id: [32]u8, seq: u64) void {
    if (!relayFetchAllowed()) {
        g_thread_done_seq.store(seq, .release);
        return;
    }
    const thread = std.Thread.spawn(.{}, fetchRepliesWorker, .{ root_id, seq }) catch {
        g_thread_done_seq.store(seq, .release);
        return;
    };
    thread.detach();
}

fn fetchRepliesWorker(root_id: [32]u8, seq: u64) void {
    const gpa = std.heap.page_allocator;
    var threaded = std.Io.Threaded.init(gpa, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var signer = nostr.keys.Signer.init();
    defer signer.deinit();

    // The note the reader pressed, and the ROOT of the conversation it sits in.
    //
    // Usually the same note, and when they are not, asking only about the note
    // pressed asks a question almost nothing answers. NIP-10 says a reply
    // carries an `e` tag for the ROOT and one for its immediate parent, so a
    // grandchild of the note in the reader's hand names its own parent and the
    // root, and never the note in between. Opening a reply from the feed
    // therefore fetched that note's direct children and nothing else: no
    // siblings, no parent, no root post, and nothing under those children. The
    // ancestors then trickled in one hop at a time through the quote fetcher,
    // which is why an old conversation took several seconds to assemble.
    //
    // Both ids go into ONE filter. Keeping the pressed note in it is what makes
    // this safe when a root tag is missing, wrong, or points somewhere else:
    // that note's own children still match.
    var thread_ids: [2][32]u8 = undefined;
    var thread_count: usize = 1;
    thread_ids[0] = root_id;
    if (g_store) |store| {
        if (store.getEvent(gpa, root_id) catch null) |se| {
            var owned = se;
            defer owned.deinit();
            thread_count = threadQueryIds(root_id, owned.event.kind, owned.event.tags, &thread_ids);
        }
    }
    var thread_hex: [2][64]u8 = undefined;
    var thread_evals: [2][]const u8 = undefined;
    var thread_watch: [2]i64 = undefined;
    for (0..thread_count) |i| {
        hexLower(&thread_hex[i], thread_ids[i]);
        thread_evals[i] = &thread_hex[i];
        thread_watch[i] = @intCast(std.mem.readInt(u64, thread_ids[i][0..8], .big) & std.math.maxInt(i64));
    }

    for (0..relaySlots()) |ri| {
        var url_buf: [96]u8 = undefined;
        const entry = relaySnapshot(ri, &url_buf) orelse continue;
        // A read-only or read-write relay. Asking a write-only relay to answer
        // a filter is asking the wrong question of it.
        if (!entry.read) continue;
        var relay = nostr.relay.dial(gpa, io, entry.url) catch continue;
        // Declared AFTER deinit so it runs BEFORE it: the keeper must have
        // let go of this pointer before the connection is freed.
        defer relay.deinit();
        const watched = watchOneShot(io, relay, one_shot_budget_ms);
        defer releaseOneShot(watched);

        // Phase 1: the replies themselves (kind:1 e-tagging the root). Collect
        // their ids as they arrive so phase 2 can watch their engagement too.
        var id_hex: [thread_reply_cap][64]u8 = undefined;
        var watch_ids: [thread_reply_cap + 2]i64 = undefined;
        var id_count: usize = 0;
        // The note pressed, and the conversation's root when that is a
        // different note, are both watched from the start so their own counts
        // refresh alongside the replies'.
        var watch_len: usize = 0;
        while (watch_len < thread_count) : (watch_len += 1) watch_ids[watch_len] = thread_watch[watch_len];

        // Comments too, or a thread never FETCHES the half of itself written
        // in the other vocabulary. The walk that assembles a thread admits them
        // now, but it reads the local store, and nothing was putting them
        // there: the conversation stayed exactly as holed as before.
        //
        // The `#e` filter finds them without a second one. NIP-22 has a
        // top-level comment repeat its uppercase scope in the lowercase tags,
        // so a comment on the root carries `e` = the root, and a nested one
        // carries `e` = the comment it answers, which is a thread member by
        // the time it matters.
        const reply_kinds = [_]u16{ 1, comment_kind };
        const reply_tags = [_]nostr.filter.TagFilter{.{ .letter = 'e', .values = thread_evals[0..thread_count] }};
        const reply_filters = [_]nostr.filter.Filter{.{ .kinds = &reply_kinds, .tags = &reply_tags, .limit = thread_reply_cap }};
        relay.subscribe("plaza-thread", &reply_filters) catch continue;
        while (true) {
            var msg = (relay.receive() catch break) orelse break;
            defer msg.deinit();
            switch (msg.value) {
                .event => |e| {
                    _ = plazaIngestFrom(gpa, e.event, .{ .verify_with = signer }, entry.url) catch {};
                    // Queue the replier's profile so a name and face resolve.
                    wantProfile(e.event.pubkey);
                    if (id_count < thread_reply_cap) {
                        hexLower(&id_hex[id_count], e.event.id);
                        id_count += 1;
                        watch_ids[watch_len] = noteIdOf(e.event);
                        watch_len += 1;
                    }
                },
                .eose => break,
                // A CLOSED ends this relay's part, and no EOSE is coming after it.
                .closed => break,
                else => {},
            }
        }

        // Phase 2: engagement on the root and every reply (replies, reposts,
        // likes, zaps), folded into the shared table so the thread shows real
        // metrics on each row, the same counts the feed shows.
        var evals: [thread_reply_cap + 2][]const u8 = undefined;
        var eval_len: usize = 0;
        while (eval_len < thread_count) : (eval_len += 1) evals[eval_len] = thread_evals[eval_len];
        for (0..id_count) |i| {
            evals[eval_len] = &id_hex[i];
            eval_len += 1;
        }
        const eng_tags = [_]nostr.filter.TagFilter{.{ .letter = 'e', .values = evals[0..eval_len] }};
        const eng_filters = [_]nostr.filter.Filter{engagementFilter(&eng_tags)};
        relay.subscribe("plaza-thread-eng", &eng_filters) catch continue;
        while (true) {
            var msg = (relay.receive() catch break) orelse break;
            defer msg.deinit();
            switch (msg.value) {
                .event => |e| {
                    if (nostr.event.verify(gpa, signer, e.event) catch false)
                        countEngagement(e.event, watch_ids[0..watch_len]);
                },
                .eose => break,
                // A CLOSED ends this relay's part, and no EOSE is coming after it.
                .closed => break,
                else => {},
            }
        }
    }
    // Every relay has been asked: the reply set is as complete as it will get, so
    // the UI can stop showing loading skeletons even if nothing came back.
    g_thread_done_seq.store(seq, .release);
}

// ------------------------------------------------------- remote signer (NIP-46)
//
// Signing can be routed to an external signer (Notary) over NIP-46 so the user's
// secret key never enters Plaza. Plaza is the CLIENT: it holds an ephemeral
// transport keypair, and the user's identity is the bunker's own pubkey. The
// wire is kind:24133 events whose content is a NIP-44-encrypted request/response
// `p`-tagged to the recipient. A persistent listener thread holds the bunker
// relay and processes responses; each request (connect, then one per post) goes
// out on its own short-lived connection, so a blocked receive never stalls a
// send. A signed note returns as a response `result`, stored and published to
// the feed pool exactly like a locally signed one.

/// Pairs with an external signer from a `bunker://` URL: parses it, mints an
/// ephemeral client key, starts the response listener, and sends the connect
/// request. Returns false (and marks the status failed) on a bad URL. Returning
/// true means the request is out, not that anyone is signed in: that happens
/// when the signer answers it (see `driveBunkerConnect`).
fn connectRemoteSigner(url_raw: []const u8) bool {
    const url = std.mem.trim(u8, url_raw, " \t\r\n");
    const io = g_io orelse return false;
    const gpa = std.heap.page_allocator;

    var parsed = nostr.nip46.parseBunkerUri(gpa, url) catch {
        g_remote_status.store(3, .release);
        return false;
    };
    defer parsed.deinit();
    const bunker = parsed.value;
    if (bunker.relays.len == 0 or bunker.relays[0].len > g_remote_relay_buf.len) {
        g_remote_status.store(3, .release);
        return false;
    }
    const relay_url = bunker.relays[0];

    // Mint the ephemeral transport key (never the user's key).
    var signer = nostr.keys.Signer.init();
    const client_kp = signer.generateKeyPair(io) catch {
        signer.deinit();
        g_remote_status.store(3, .release);
        return false;
    };
    signer.deinit();

    // Stash the connection details for the worker threads.
    g_remote_pubkey = bunker.remote_signer_pubkey;
    @memcpy(g_remote_relay_buf[0..relay_url.len], relay_url);
    g_remote_relay_len = relay_url.len;
    if (bunker.secret) |s| {
        const n = @min(s.len, g_remote_secret_buf.len);
        @memcpy(g_remote_secret_buf[0..n], s[0..n]);
        g_remote_secret_len = n;
    } else g_remote_secret_len = 0;
    g_remote_client_kp = client_kp;

    // The user's identity is the bunker's pubkey.
    const npub = abbreviateNpub(&g_identity_npub_buf, g_remote_pubkey);
    g_identity_npub_len = npub.len;
    g_signer_kind = .remote;
    g_remote_status.store(1, .release);
    g_remote_sign_notice.store(false, .release);
    // Nobody is signed in by this until the signer answers (see
    // `driveBunkerConnect`).
    g_remote_confirming.store(true, .release);

    // A fresh generation: any prior listener (a reconnect to a second bunker)
    // stops processing, and every request registered from here carries it.
    const generation = newRemoteGeneration();

    // The listener is a network thread, so a test build does not start one
    // (see `networkAllowed`).
    if (networkAllowed()) {
        const thread = std.Thread.spawn(.{}, nip46ReceiveLoop, .{ gpa, generation }) catch {
            abandonRemoteSigner(.signer_silent);
            return false;
        };
        thread.detach();
    }

    sendConnect(gpa);
    return true;
}

/// Request ids a unit test hands out, which has no io to draw them from.
var g_test_request_seq: u32 = 0;

/// Whether this generation's `connect` is neither waiting for its answer nor
/// answered: it never went out, so there is nothing left to wait for.
fn connectWentQuiet() bool {
    const generation = g_remote_generation.load(.acquire);
    pendingLock();
    defer pendingUnlock();
    for (&g_pending) |*slot| {
        if (slot.active and slot.method == .connect and slot.generation == generation and !slot.failed) return false;
    }
    // Read under the same lock the listener takes an answer under (see
    // `takeAnswered`), so a slot that is gone because it was ANSWERED is never
    // mistaken for one that never went out.
    return g_remote_status.load(.acquire) == 1;
}

/// Takes down a bunker connection that is not going to be anybody's sign-in:
/// the listener stops, every request in flight is dropped, and the pairing
/// secret and the client key are wiped rather than left in memory. Who is
/// signed in is not touched here (see `abandonRemoteSigner`).
fn dropRemoteConnection() void {
    // Bumped first, so the detached listener stops processing before the state
    // it reads is taken away.
    _ = g_remote_generation.fetchAdd(1, .monotonic);
    clearPending();
    g_remote_confirming.store(false, .release);
    g_remote_sign_notice.store(false, .release);
    std.crypto.secureZero(u8, &g_remote_secret_buf);
    g_remote_secret_len = 0;
    if (g_remote_client_kp) |*kp| std.crypto.secureZero(u8, &kp.secret_key);
    g_remote_client_kp = null;
    g_remote_relay_len = 0;
    g_remote_status.store(0, .release);
}

/// Takes back a bunker connection that never became a sign-in: the connection
/// is dropped, and the reader is a guest again with the reason on the sheet
/// they are still looking at.
fn abandonRemoteSigner(why: LoginError) void {
    dropRemoteConnection();
    g_identity_npub_len = 0;
    g_signer_kind = .helper;
    login.g_login_error.store(@intFromEnum(why), .release);
}

/// Whether a pasted bunker link is still waiting on its signer.
pub fn bunkerConnecting() bool {
    return g_remote_confirming.load(.acquire);
}

/// The tick's half of connecting a pasted bunker link: signs the reader in once
/// the signer has answered, and gives the sheet an error when it has not.
///
/// The link used to sign the reader in the moment it parsed. A link to a relay
/// that was down then produced an account, a green dot, and a repost that sat
/// on "Reposted" for thirty seconds before failing, with the reason only in a
/// log. The answer to `connect` is the proof that the signer exists, is
/// reachable and took this client, so it is what the sign-in waits for.
fn driveBunkerConnect(model: *Model) void {
    if (!g_remote_confirming.load(.acquire)) return;
    // Something else took the seat (a keyholder key adopted while waiting).
    // The pairing is not theirs, so it goes: left up, its listener would hold
    // the bunker relay for the rest of the run with the link's secret in
    // memory, and a late answer would mark a signer nobody uses "connected".
    if (g_signer_kind != .remote) {
        dropRemoteConnection();
        return;
    }
    switch (g_remote_status.load(.acquire)) {
        2 => {
            g_remote_confirming.store(false, .release);
            login.g_login_error.store(@intFromEnum(LoginError.none), .release);
            persistSession();
            model.joining = false;
            model.bunker_mode = false;
            model.login_buffer.clear();
            enterFeed(model);
            replayPending(model);
        },
        // The request failed or ran out its thirty seconds.
        3 => abandonRemoteSigner(.signer_silent),
        // Connecting. If nothing is in flight any more there is nothing to wait
        // for: the request never went out.
        else => if (connectWentQuiet()) abandonRemoteSigner(.signer_silent),
    }
}

/// A request id nobody watching the relay can guess.
///
/// These were `req-0`, `req-1`, and so on, from a counter that starts at zero
/// on every launch. Our client pubkey is not a secret: it is the `p` tag on
/// every request we publish. Anyone reading the bunker's relay could therefore
/// address an answer to us and guess which request was in flight. They still
/// cannot read the request, and after the sender check above they cannot be
/// heard at all, but a request id should not be a countdown either.
///
/// Sixteen hex characters from the system CSPRNG, the same source the ephemeral
/// client key comes from.
fn newRequestId(out: *[24]u8) ?[]const u8 {
    const io = g_io orelse {
        // No io in a unit test, so ids come from a counter there. Never in the app.
        if (!builtin.is_test) return null;
        g_test_request_seq +%= 1;
        return std.fmt.bufPrint(out, "test{x}", .{g_test_request_seq}) catch null;
    };
    var raw: [8]u8 = undefined;
    io.randomSecure(&raw) catch return null;
    return std.fmt.bufPrint(out, "{x}", .{raw}) catch null;
}

/// Sends the NIP-46 `connect` request (remote pubkey + optional secret).
fn sendConnect(gpa: std.mem.Allocator) void {
    var hexbuf: [64]u8 = undefined;
    hexLower(&hexbuf, g_remote_pubkey);
    var idbuf: [24]u8 = undefined;
    const req_id = newRequestId(&idbuf) orelse return;
    if (!registerPending(req_id, .connect, null, false, .none, 0, no_half_id, .{})) return;
    const params = [_][]const u8{ &hexbuf, g_remote_secret_buf[0..g_remote_secret_len] };
    sendRequest(gpa, .{ .id = req_id, .method = "connect", .params = &params });
}

/// Remote path: build the unsigned event of `kind` (with `tags`, stamped
/// `created_at`) and send a `sign_event` request. The signed event returns to
/// the listener, which stores and publishes it. `restorable` is true only for a
/// composer draft, so a failed reaction never lands "+"-text in the composer.
fn requestRemoteSign(gpa: std.mem.Allocator, created_at: i64, kind: u16, tags: []const nostr.event.Tag, content_owned: []const u8, restorable: bool, route: PlaceRoute) void {
    requestRemoteSignAs(.sign_event, gpa, created_at, kind, tags, content_owned, restorable, route);
}

/// The same request, tracked as `method`: an upload token is signed the same way
/// and answered to a different place.
fn requestRemoteSignAs(method: RemoteMethod, gpa: std.mem.Allocator, created_at: i64, kind: u16, tags: []const nostr.event.Tag, content_owned: []const u8, restorable: bool, route: PlaceRoute) void {
    // `content_owned` is handed to the pending slot (so a timeout can restore
    // it to the composer); it is freed here only on an early return.
    // A canonical unsigned event (the bunker fills in the signature). The id is
    // computed against the user's pubkey so the bunker's result matches it.
    const id = nostr.event.computeId(gpa, g_remote_pubkey, created_at, kind, tags, content_owned) catch {
        gpa.free(content_owned);
        return;
    };
    const unsigned = nostr.event.Event{
        .id = id,
        .pubkey = g_remote_pubkey,
        .created_at = created_at,
        .kind = kind,
        .tags = tags,
        .content = content_owned,
        .sig = [_]u8{0} ** 64,
    };
    const unsigned_json = nostr.event.toJson(gpa, unsigned) catch {
        gpa.free(content_owned);
        return;
    };
    defer gpa.free(unsigned_json);

    var idbuf: [24]u8 = undefined;
    const req_id = newRequestId(&idbuf) orelse {
        gpa.free(content_owned);
        return;
    };
    // Track before sending: the response can arrive on the listener thread the
    // instant the send lands, and it must find the pending slot already there.
    if (!registerPending(req_id, method, content_owned, restorable, route, 0, no_half_id, WarnCarry.fromTags(tags))) {
        gpa.free(content_owned);
        return;
    }
    const params = [_][]const u8{unsigned_json};
    sendRequest(gpa, .{ .id = req_id, .method = "sign_event", .params = &params });
}

/// Which NIP-46 method opens this private half.
///
/// NIP-51 lets the private half be NIP-04 or NIP-44, and the two are told apart
/// by shape: a NIP-04 payload is `base64?iv=base64` and a NIP-44 one is bare
/// base64, which can never contain a `?`. Jumble and Amethyst both choose on
/// that marker. A legacy list sent to `nip44_decrypt` comes back as an error,
/// which reads as a refusal and leaves the reader with a list they can never
/// write.
fn isNip04Payload(payload: []const u8) bool {
    return std.mem.indexOf(u8, payload, "?iv=") != null;
}

fn remoteDecryptMethod(payload: []const u8) RemoteMethod {
    return if (isNip04Payload(payload)) .nip04_decrypt else .nip44_decrypt;
}

pub fn remoteDecryptMethodNameForTest(payload: []const u8) []const u8 {
    return @tagName(remoteDecryptMethod(payload));
}

/// Remote path for a private half: ask the bunker to open it.
///
/// Without this a reader signed in through an external signer could never read
/// their own encrypted list. `scanPrivateHalves` only knew how to ask the LOCAL
/// keyholder over HTTP, so on a bunker the ask went to a daemon that either is
/// not running or does not hold the key, came back not-ok, and the half was
/// marked refused forever. `writeMute` then refused every mute write, because
/// a private half that is present and unreadable is exactly the case it will
/// not publish over. So the safety guard was firing correctly on a question
/// that was never actually asked of the right signer.
///
/// The peer is the reader's own pubkey: NIP-51 encrypts a private half to
/// yourself, so both sides of the conversation key are this account's.
fn requestRemoteDecrypt(gpa: std.mem.Allocator, half_index: usize, ciphertext: []const u8) bool {
    var hexbuf: [64]u8 = undefined;
    hexLower(&hexbuf, g_remote_pubkey);
    var idbuf: [24]u8 = undefined;
    const req_id = newRequestId(&idbuf) orelse return false;
    const method = remoteDecryptMethod(ciphertext);
    if (!registerPending(req_id, method, null, false, .none, @intCast(half_index), privateHalfId(ciphertext), .{})) return false;
    const params = [_][]const u8{ &hexbuf, ciphertext };
    sendRequest(gpa, .{ .id = req_id, .method = @tagName(method), .params = &params });
    return true;
}

/// Remote path for a seal: ask the bunker to encrypt a private half to this
/// reader's own key. The answer completes the bookmark write.
fn requestRemoteEncrypt(gpa: std.mem.Allocator, plaintext: []const u8) bool {
    var hexbuf: [64]u8 = undefined;
    hexLower(&hexbuf, g_remote_pubkey);
    var idbuf: [24]u8 = undefined;
    const req_id = newRequestId(&idbuf) orelse return false;
    if (!registerPending(req_id, .nip44_encrypt, null, false, .none, 0, no_half_id, .{})) return false;
    const params = [_][]const u8{ &hexbuf, plaintext };
    sendRequest(gpa, .{ .id = req_id, .method = "nip44_encrypt", .params = &params });
    return true;
}

/// Serializes `request` and spawns a one-shot thread to seal and publish it.
fn sendRequest(gpa: std.mem.Allocator, request: nostr.nip46.Request) void {
    // `networkAllowed` and not `relayFetchAllowed`: the two say different
    // things. This one asks only "may I touch the network", which is the whole
    // of the concern here. Signing does not read the store and must not start
    // depending on one existing.
    if (!networkAllowed()) return;
    const req_json = request.toJson(gpa) catch return;
    var id_buf: [24]u8 = undefined;
    const id_len = @min(request.id.len, id_buf.len);
    @memcpy(id_buf[0..id_len], request.id[0..id_len]);
    const thread = std.Thread.spawn(.{}, nip46Send, .{ gpa, req_json, id_buf, id_len }) catch {
        gpa.free(req_json);
        return;
    };
    thread.detach();
}

/// Seals `req_json` to the remote signer and publishes it on a throwaway
/// connection to the bunker relay. Owns `req_json`. Its own io and signer.
fn nip46Send(gpa: std.mem.Allocator, req_json: []const u8, req_id: [24]u8, req_id_len: usize) void {
    defer gpa.free(req_json);
    const client_kp = g_remote_client_kp orelse return;
    sendNip46(gpa, req_json, client_kp) catch {
        // A request that could not even be put on the wire has no answer
        // coming, so its slot is flagged failed now rather than left to run out
        // its thirty seconds. The tick retires it the same way it retires a
        // refusal.
        _ = failPending(req_id[0..req_id_len]);
    };
}

fn sendNip46(gpa: std.mem.Allocator, req_json: []const u8, client_kp: nostr.keys.KeyPair) !void {
    var threaded = std.Io.Threaded.init(gpa, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var signer = nostr.keys.Signer.init();
    defer signer.deinit();

    const created_at = std.Io.Timestamp.now(io, .real).toSeconds();
    var sealed = try nostr.nip46.seal(gpa, io, signer, client_kp, g_remote_pubkey, req_json, created_at);
    defer sealed.deinit();

    var relay = try nostr.relay.dial(gpa, io, g_remote_relay_buf[0..g_remote_relay_len]);
    defer relay.deinit();
    // The read below waits for the relay's OK. Without a deadline a bunker
    // relay that accepts the publish and says nothing holds this thread, and
    // this is the signing path: one wedged request would be one thread gone for
    // the life of the process, every time the reader signed anything.
    const watched = watchOneShot(io, relay, one_shot_budget_ms);
    defer releaseOneShot(watched);
    try relay.publish(sealed.event);
    // Read the relay's OK so the frame flushes before we close; best-effort.
    var msg = (relay.receive() catch return) orelse return;
    msg.deinit();
}

/// The response listener: holds the bunker relay and processes responses,
/// reconnecting until its `generation` is superseded (a logout or a reconnect
/// bumps `g_remote_generation`). Its own io backend and signer, never the UI
/// thread's.
fn nip46ReceiveLoop(gpa: std.mem.Allocator, generation: u64) void {
    var threaded = std.Io.Threaded.init(gpa, .{});
    defer threaded.deinit();
    const io = threaded.io();
    var signer = nostr.keys.Signer.init();
    defer signer.deinit();
    const client_kp = g_remote_client_kp orelse return;

    while (generation == g_remote_generation.load(.acquire)) {
        nip46ReceiveOnce(gpa, io, signer, client_kp, generation) catch |err| {
            std.debug.print("plaza: [signer] {s}\n", .{@errorName(err)});
        };
        if (generation != g_remote_generation.load(.acquire)) break;
        io.sleep(std.Io.Duration.fromSeconds(3), .awake) catch {};
    }
}

/// Dials the bunker relay, subscribes for responses addressed to our client key
/// (`#p` = the ephemeral pubkey, which only our bunker knows), and handles each
/// until the connection drops or this listener's `generation` is superseded.
fn nip46ReceiveOnce(gpa: std.mem.Allocator, io: std.Io, signer: nostr.keys.Signer, client_kp: nostr.keys.KeyPair, generation: u64) !void {
    var relay = try nostr.relay.dial(gpa, io, g_remote_relay_buf[0..g_remote_relay_len]);
    // Withdrawn before the connection is freed: declared after `deinit`, so it
    // runs before it.
    defer relay.deinit();
    offerLiveRelay(bunker_watch_slot, relay);
    defer offerLiveRelay(bunker_watch_slot, null);

    var client_hex: [64]u8 = undefined;
    hexLower(&client_hex, client_kp.public_key);
    const pvals = [_][]const u8{&client_hex};
    const tag_filters = [_]nostr.filter.TagFilter{.{ .letter = 'p', .values = &pvals }};
    const kinds = [_]u16{nostr.nip46.kind};
    // FROM THE SIGNER, addressed to us. The `p` tag alone is not a restriction:
    // our client pubkey is on every request we publish, so anyone reading the
    // relay can address an event to it. Naming the author is what makes this
    // subscription about a conversation with one party.
    //
    // `limit = 0` asks for nothing stored. Kind 24133 is ephemeral and a relay
    // should not be keeping it, but one that does would otherwise replay a
    // previous session's answers into this one.
    const authors = [_][32]u8{g_remote_pubkey};
    const filters = [_]nostr.filter.Filter{.{
        .authors = &authors,
        .kinds = &kinds,
        .tags = &tag_filters,
        .limit = 0,
    }};
    try relay.subscribe("plaza-nip46", &filters);

    while (generation == g_remote_generation.load(.acquire)) {
        var msg = (try relay.receive()) orelse break;
        defer msg.deinit();
        switch (msg.value) {
            .event => |e| handleNip46Response(gpa, signer, client_kp, e.event, generation),
            else => {},
        }
    }
}

/// Decrypts, parses, and correlates a NIP-46 response to the request that asked
/// for it. An error response flags its request so the UI restores the draft; a
/// `sign_event` result is verified, stored, and published to the feed pool (the
/// remote equivalent of the local post path); a `connect` ack marks connected.
/// An unknown or already-handled id is dropped, so a duplicate never publishes
/// twice and a stale session's response never lands.
fn handleNip46Response(gpa: std.mem.Allocator, signer: nostr.keys.Signer, client_kp: nostr.keys.KeyPair, ev: nostr.event.Event, generation: u64) void {
    if (generation != g_remote_generation.load(.acquire)) return;
    // Only the signer this session connected to.
    //
    // A relay filter is a request, not a guarantee, and this one has to hold on
    // its own because of how NIP-44 works: the conversation key is derived from
    // the SENDER's key, so an event from anybody decrypts successfully as long
    // as they encrypted it to our client key. That key is public. Without this
    // line, a stranger who guesses the id of a request in flight can answer it,
    // and the answer is either an event we then publish from the reader's
    // machine to the reader's relays, or a failure that discards their note.
    if (!std.mem.eql(u8, &ev.pubkey, &g_remote_pubkey)) return;
    const plaintext = nostr.nip46.open(gpa, signer, client_kp.secret_key, ev) catch return;
    defer gpa.free(plaintext);
    var resp = nostr.nip46.parseResponse(gpa, plaintext) catch return;
    defer resp.deinit();

    if (resp.value.err.len != 0) {
        std.debug.print("plaza: [signer] {s}\n", .{resp.value.err});
        // Leave the slot in the table, flagged: the UI tick owns the composer,
        // so it restores the draft (sign) or fails the status (connect).
        _ = failPending(resp.value.id);
        return;
    }

    // Correlate to the request that asked. A missing slot means an unknown id
    // or one already handled: drop it (no double publish, no stray "connected").
    // Taking it also marks the connection up (see `takeAnswered`).
    const pending = takeAnswered(resp.value.id) orelse return;
    defer if (pending.content) |c| gpa.free(c);

    g_remote_sign_notice.store(false, .release);

    switch (pending.method) {
        // The connect ack is a plain "ack" string; the status above is the point.
        .connect => {},
        // The plaintext of a private half. Parked for the UI tick rather than
        // written straight into `g_private_halves`, which the view reads every
        // frame and `scanPrivateHalves` writes on the other thread.
        .nip44_encrypt => {
            pendingLock();
            defer pendingUnlock();
            const n = @min(resp.value.result.len, g_seal_inbox.buf.len);
            @memcpy(g_seal_inbox.buf[0..n], resp.value.result[0..n]);
            g_seal_inbox.len = @intCast(n);
            g_seal_inbox.used = true;
            g_seal_inbox.ok = n > 0;
        },
        .nip44_decrypt, .nip04_decrypt => {
            pendingLock();
            defer pendingUnlock();
            for (&g_half_inbox) |*box| {
                if (box.used) continue;
                const n = @min(resp.value.result.len, box.plain_buf.len);
                box.* = .{ .used = true, .index = pending.half_index, .half_id = pending.half_id, .ok = true, .plain_len = @intCast(n) };
                @memcpy(box.plain_buf[0..n], resp.value.result[0..n]);
                break;
            }
        },
        // A relay's NIP-42 challenge, signed. Never published and never stored:
        // it goes to the one relay that asked, by way of the slot that is
        // waiting for it, and `authDeliverSigned` checks it before it can.
        .sign_auth => {
            var parsed = nostr.event.fromJson(gpa, resp.value.result) catch {
                authFailSigning(pending.half_index);
                return;
            };
            defer parsed.deinit();
            authDeliverSigned(gpa, signer, pending.half_index, parsed.value);
        },
        // An upload token: checked here, parked for the tick, never stored.
        .sign_upload_auth => {
            var parsed = nostr.event.fromJson(gpa, resp.value.result) catch {
                parkUploadSign(null);
                return;
            };
            defer parsed.deinit();
            const sound = std.mem.eql(u8, &parsed.value.pubkey, &g_remote_pubkey) and
                (nostr.event.verify(gpa, signer, parsed.value) catch false);
            if (!sound) {
                parkUploadSign(null);
                return;
            }
            const json = nostr.event.toJson(gpa, parsed.value) catch {
                parkUploadSign(null);
                return;
            };
            defer gpa.free(json);
            parkUploadSign(json);
        },
        .sign_event => {
            var parsed = nostr.event.fromJson(gpa, resp.value.result) catch return;
            defer parsed.deinit();
            // Signed as the account we asked it to sign as. The verify further
            // down the write path checks that an event's signature matches its
            // OWN pubkey, which a stranger's event also satisfies, so this is
            // the check that says the note is this reader's.
            if (!std.mem.eql(u8, &parsed.value.pubkey, &g_remote_pubkey)) return;
            // A process-lifetime copy of the content: `parsed` is freed on
            // return, but the detached publisher reads it afterwards. Our
            // composer produces tagless kind:1 notes, so an empty tag set still
            // matches the signed id, and the write seam verifies that before
            // trusting it into the feed.
            const owned = gpa.dupe(u8, parsed.value.content) catch return;
            var out = parsed.value;
            out.content = owned;
            // Preserve the signed tags (a reaction carries e/p/k); forcing them
            // empty would make the id not match, and the verify below would drop
            // it. Deep-copied because `parsed` is freed on return.
            // Whole, or not published: the id is computed over these tags, so
            // a partial copy is an event the verify below would drop anyway.
            out.tags = dupeTags(gpa, parsed.value.tags) orelse return;
            // Signed, so there is nothing to take back. Same reasoning as the
            // built-in signer's: released on the signature, not on the ingest.
            releaseUndo();
            ingestAndPublish(gpa, out, signer, pending.route);
        },
    }
}

/// UI-thread sweep of the pending table (called each tick): a request that
/// failed or ran past its deadline is retired here, where the composer can be
/// touched. A timed-out or refused `sign_event` restores its draft (only into
/// an empty composer, so a newer draft is never clobbered) and shows a notice;
/// a `connect` that never returned fails the connection status. A slot from a
/// superseded generation (logout/reconnect) is dropped silently.
fn scanPendingRemote(model: *Model, fx_for_seal: *Effects) void {
    const now = nowSeconds();
    const gpa = std.heap.page_allocator;
    const generation = g_remote_generation.load(.acquire);
    var restore: ?[]const u8 = null;
    var restore_warn: WarnCarry = .{};
    var sign_failed = false;
    var any_sign_failed = false;
    var connect_failed = false;
    var seal_failed = false;
    var upload_sign_failed = false;

    pendingLock();
    for (&g_pending) |*slot| {
        if (!slot.active) continue;
        const stale = slot.generation != generation;
        const due = slot.failed or now >= slot.deadline_s;
        if (!stale and !due) continue;
        const method = slot.method;
        const content = slot.content;
        const slot_half = slot.half_index;
        const slot_half_id = slot.half_id;
        const slot_explicit = slot.failed;
        const slot_restorable = slot.restorable;
        const slot_warn = slot.warn;
        slot.* = .{};
        if (stale) {
            if (content) |c| gpa.free(c);
            // An ask that died with its session leaves the half "asking"
            // forever, and nothing would ask again: the reader's list would
            // stay read-only until a restart. Back to idle, so the next tick
            // asks. Only the half that ask was about: the slot may belong to
            // another list by now.
            if (method == .nip44_decrypt or method == .nip04_decrypt) {
                if (halfAwaiting(slot_half, slot_half_id)) |h| h.state = .idle;
            }
            continue;
        }
        switch (method) {
            .sign_event => {
                // The composer holds one draft: keep the first restorable one,
                // free the rest. A reaction's content is not restorable, so it
                // is freed and its failure stays silent.
                if (content) |c| {
                    if (slot_restorable and restore == null) {
                        restore = c;
                        restore_warn = slot_warn;
                    } else gpa.free(c);
                }
                if (slot_restorable) sign_failed = true;
                // Any failed signature, restorable or not, may have been a
                // follow press whose list already moved.
                any_sign_failed = true;
            },
            .connect => {
                if (content) |c| gpa.free(c);
                connect_failed = true;
            },
            // A token the bunker refused or never answered. The upload card says
            // so; there is no draft to give back.
            .sign_upload_auth => {
                if (content) |c| gpa.free(c);
                upload_sign_failed = true;
            },
            // Refused or never answered. NOT "the half is empty": that
            // distinction is the whole reason this cache exists, and collapsing
            // the two is what publishes an empty content over somebody's
            // private list.
            //
            // An error from the bunker is a "no" and waits for a press. A
            // deadline that passed is a silence: the prompt may be sitting
            // unseen on a phone, or the answer lost on the way, so the half
            // is asked again once `private_half_retry_s` has passed.
            .nip44_decrypt, .nip04_decrypt => {
                if (content) |c| gpa.free(c);
                if (halfAwaiting(slot_half, slot_half_id)) |h| {
                    h.state = .refused;
                    h.retry_at_s = if (slot_explicit) 0 else now + private_half_retry_s;
                }
            },
            // A seal the bunker refused or never answered. The list is left
            // exactly as it was, which is the only safe outcome: the reader
            // still has every private bookmark they had.
            .nip44_encrypt => {
                if (content) |c| gpa.free(c);
                seal_failed = true;
            },
            // The relay's challenge goes unanswered and the row says so.
            .sign_auth => {
                if (content) |c| gpa.free(c);
                authFailSigning(slot_half);
            },
        }
    }
    // Answers that came back while the listener held them. Applied here so
    // every write to `g_private_halves` happens on this thread.
    var opened = false;
    for (&g_half_inbox) |*box| {
        if (!box.used) continue;
        // Only into the half that was asked: a slot freed by a sign-out and
        // taken by another list is not this answer's home.
        if (halfAwaiting(box.index, box.half_id)) |h| {
            if (box.ok and box.plain_len > 0) {
                const n = @min(box.plain_len, h.plain_buf.len);
                @memcpy(h.plain_buf[0..n], box.plain_buf[0..n]);
                h.plain_len = @intCast(n);
                h.state = .open;
                opened = true;
            } else {
                h.state = .refused;
            }
        }
        std.crypto.secureZero(u8, &box.plain_buf);
        box.* = .{};
    }
    // The bunker's ciphertext, if one arrived. Applied here so the splice and
    // the publish happen on this thread, like every other write.
    var sealed: ?[]const u8 = null;
    var sealed_buf: [4096]u8 = undefined;
    if (g_seal_inbox.used) {
        if (g_seal_inbox.ok and g_seal_inbox.len > 0) {
            @memcpy(sealed_buf[0..g_seal_inbox.len], g_seal_inbox.buf[0..g_seal_inbox.len]);
            sealed = sealed_buf[0..g_seal_inbox.len];
        } else seal_failed = true;
        g_seal_inbox = .{};
    }
    pendingUnlock();
    if (sealed) |ciphertext| finishPrivateBookmark(model, fx_for_seal, ciphertext);
    if (seal_failed) {
        g_private_seal = .{};
        setToast(model, "Your signer did not seal that. Nothing was sent.");
    }
    if (opened) {
        // The set was read with this half closed, so it is short by whatever
        // was in it. Read it again now that it can be.
        loadMutesFromStore();
        loadBookmarksFromStore();
        invalidateFeed();
    }

    if (restore) |c| {
        if (model.draft_empty()) {
            setPlain(compose_capacity, &model.draft_buffer, c);
            restore_warn.restoreInto(model);
        }
        gpa.free(c);
    }
    if (sign_failed) g_remote_sign_notice.store(true, .release);
    if (any_sign_failed) applyUndo(model);
    if (upload_sign_failed) uploadSignFailed();
    if (connect_failed and g_remote_status.load(.acquire) == 1) g_remote_status.store(3, .release);
}

/// Lowercase-hex-encodes a 32-byte key into `out`.
pub fn hexLower(out: *[64]u8, bytes: [32]u8) void {
    const digits = "0123456789abcdef";
    for (bytes, 0..) |b, i| {
        out[i * 2] = digits[b >> 4];
        out[i * 2 + 1] = digits[b & 0x0f];
    }
}

// -------------------------------------------------------------------- app run

// CoreText/CoreGraphics, for registering the bundled faces process-wide by
// PostScript name. Already linked: the SDK's AppKit host uses CTFontManager.
const ct = if (builtin.os.tag == .macos) struct {
    const CGDataProviderRef = ?*anyopaque;
    const CGFontRef = ?*anyopaque;
    const CFTypeRef = ?*anyopaque;
    extern "c" fn CGDataProviderCreateWithData(info: ?*anyopaque, data: [*]const u8, size: usize, release: ?*anyopaque) CGDataProviderRef;
    extern "c" fn CGDataProviderRelease(provider: CGDataProviderRef) void;
    extern "c" fn CGFontCreateWithDataProvider(provider: CGDataProviderRef) CGFontRef;
    extern "c" fn CGFontRelease(font: CGFontRef) void;
    extern "c" fn CTFontManagerRegisterGraphicsFont(font: CGFontRef, err: ?*CFTypeRef) bool;
    extern "c" fn CFRelease(ref: CFTypeRef) void;
} else struct {};

/// Installs Plaza's own vector icons (plaza_icons.zig) so `ui.appIcon` names
/// resolve like built-ins. Idempotent: it just publishes a static table. The
/// tests call it too, so a view built in a test draws the real glyphs instead of
/// the missing-icon fallback (and an icon regression can actually fail a test).
pub fn registerIcons() void {
    canvas.icons.registerAppIcons(&plaza_icons.app_icons);
}

/// Registers the bundled Geist faces (theme.zig) with CoreText from the
/// binary's own bytes, process scope, so the host's by-name resolution of the
/// default sans/mono ids (and the reserved medium/bold span ids) finds them
/// on EVERY launch path: the live window, a dev run from any working
/// directory, and headless session replay. Best-effort per face: a face that
/// is already registered (a system-installed Geist, a second call) fails
/// quietly, and by-name lookup still resolves; either copy is the same OFL
/// family.
fn registerFontFaces() void {
    if (comptime builtin.os.tag != .macos) return;
    const faces = [_][]const u8{ theme.geist_ttf, theme.geist_medium_ttf, theme.geist_bold_ttf, theme.geist_mono_ttf };
    for (faces) |ttf| {
        const provider = ct.CGDataProviderCreateWithData(null, ttf.ptr, ttf.len, null) orelse continue;
        defer ct.CGDataProviderRelease(provider);
        const font = ct.CGFontCreateWithDataProvider(provider) orelse continue;
        defer ct.CGFontRelease(font);
        var err: ct.CFTypeRef = null;
        _ = ct.CTFontManagerRegisterGraphicsFont(font, &err);
        if (err) |e| ct.CFRelease(e);
    }
}

/// The faces registered off macOS, and none on it. A slice rather than an
/// optional because that is the shape `Options.fonts` takes.
///
/// The emoji face is for the renderer's colour fallback; nothing asks to be
/// drawn in its id. The two weights are the opposite: the toolkit maps a span's
/// weight onto reserved ids of its own and bundles no face for any of them, so
/// off macOS medium and bold ink REGULAR outlines and the app has no
/// typographic hierarchy at all. Filling those ids is the only way to get the
/// weights, and it is the same two files CoreText is handed on macOS, already
/// embedded, so it costs no binary.
const registered_fonts: []const PlazaApp.FontRegistration = if (builtin.os.tag == .macos)
    &.{}
else
    &.{
        // Twemoji FIRST. The renderer's fallback walks these in order, so a
        // codepoint two faces both carry goes to the one registered earlier,
        // and an emoji should be drawn as a picture rather than as whichever
        // text face happens to have a monochrome glyph for it.
        .{ .id = theme.emoji_font_id, .name = "Twemoji.ttf", .ttf = theme.emoji_ttf },
        .{ .id = canvas.default_sans_medium_font_id, .name = "Geist-Medium.ttf", .ttf = theme.geist_medium_ttf },
        .{ .id = canvas.default_sans_bold_font_id, .name = "Geist-Bold.ttf", .ttf = theme.geist_bold_ttf },
        // The scripts Geist does not carry. Nothing is ever drawn IN these ids;
        // they are here so the faces exist for the fallback to find. See
        // `theme.noto_ttf`.
        .{ .id = theme.noto_font_id, .name = "NotoSans-Regular.ttf", .ttf = theme.noto_ttf },
        .{ .id = theme.noto_sc_font_id, .name = "NotoSansSC-Regular.ttf", .ttf = theme.noto_sc_ttf },
        .{ .id = theme.noto_kr_font_id, .name = "NotoSansKR-Hangul.ttf", .ttf = theme.noto_kr_ttf },
    };

pub fn main(init: std.process.Init) !void {
    g_io = init.io;
    g_environ = init.environ_map;
    // Before anything else reads it: a link is why this process exists when the
    // reader followed one, and the ceremony below can take a while.
    captureArgvLink(init.minimal.args);

    // The bundled Geist faces, registered with CoreText before the platform
    // host exists, so every later font lookup resolves them (see theme.zig).
    registerFontFaces();

    // The glyphs the built-in set does not carry. Registered before the first
    // view build.
    registerIcons();

    // A returning user has a persisted session: restore it (load the local key,
    // or silently reconnect the bunker) so they are signed straight back in.
    // Best-effort: on failure the app still runs, as a guest.
    loadSettings(init.io, init.environ_map);
    _ = restoreSession(init.io, init.environ_map);
    // Resolve the keyholder daemon (its path and a fresh bearer token); boot
    // spawns it. Non-fatal, but not free either: Plaza has not minted a key in
    // this process since the key moved out of it, so an install that arrived
    // without the daemon cannot make one, and `keyholderMissing` is how the join
    // screens say so instead of offering a button that swallows the press.
    resolveHelper(init);
    resolveNotaryWindow(init);

    const app_state = try PlazaApp.create(std.heap.page_allocator, .{
        .name = "plaza",
        .scene = shell_scene,
        .canvas_label = canvas_label,
        .init_fx = boot,
        .update_fx = update,
        .view = appView,
        .on_command = onCommand,
        .on_key = onKey,
        // On macOS: none. The typography tokens sit on the BUILT-IN ids (the
        // toolkit's default sans IS Geist), which is the only routing that
        // gives span weights real medium and bold faces, and `registerFontFaces`
        // hands the faces to CoreText, which then cascades to the system for
        // anything Geist lacks.
        //
        // Everywhere else: the colour emoji face and the two Geist weights,
        // because none of that exists there. See `registered_fonts`.
        .fonts = registered_fonts,
        // The dark, cool-grey, white-accent look (see theme.zig).
        .tokens_fn = theme.tokens(Model),
    });
    defer app_state.destroy();
    g_app = app_state;
    app_state.model = initialModel();
    // Guest-first: the app opens INTO the feed, never a welcome wall. A
    // restored session is signed straight back in; a newcomer browses as a
    // guest (the feed reads fine without an identity) and is asked for one at
    // first intent, not at launch. Either way the store and the pool start
    // before the window appears, so the first frame renders from disk.
    app_state.model.stage = .ready;
    startFeed(init.io, init.environ_map);

    try runner.runWithOptions(app_state.app(), .{
        .app_name = "plaza",
        .window_title = "Plaza",
        .bundle_id = "com.zig-nostr.plaza",
        .icon_path = "assets/icon.png",
        .default_frame = geometry.RectF.init(0, 0, window_width, window_height),
        .restore_state = false,
        .js_window_api = false,
        .security = .{
            .permissions = &app_permissions,
            .navigation = .{
                .allowed_origins = &.{ "zero://inline", "zero://app" },
                // The toolkit refuses `openUrl` unless the policy says a link
                // may reach the system browser, so this has to be anything but
                // the default `.deny`.
                //
                // `*` and not `"https://*"`, which is what this said until a
                // reader reported that no link opened anywhere. The toolkit's
                // pattern language cannot express a scheme-wide wildcard:
                // `security.externalWildcardPrefixValid` requires a host AND a
                // path slash after the scheme, so `"https://*"` leaves an empty
                // rest, finds no `/`, and is discarded as malformed. A policy
                // of two discarded patterns matches nothing and denies
                // everything, silently, because the refusal is an error nobody
                // surfaces.
                //
                // So the real gate is `isSafeExternalUrl`, which runs FIRST and
                // already refuses anything that is not http(s) with no control
                // characters. This one is the toolkit's own, and the honest
                // way to say "whatever the first gate passed" is `*`.
                .external_links = external_link_policy,
            },
        },
    }, init);
}

/// Opens the local-first store and spawns the background ingest thread. The
/// store is heap-allocated and the thread detached, both living for the whole
/// process: LMDB commits each event durably, and the ingest thread can be
/// blocked in a relay read at quit, so we deliberately never tear them down,
/// process exit reclaims them without racing the detached thread. A failure
/// here is non-fatal: the app runs with an empty feed that reads "offline".
fn startFeed(io: std.Io, environ: *const std.process.Environ.Map) void {
    if (g_store != null) return; // already running
    const gpa = std.heap.page_allocator;
    const store = gpa.create(nostr.store.Store) catch return;
    store.* = openFeedStore(io, environ) catch |err| {
        std.debug.print("plaza: local store unavailable: {s}\n", .{@errorName(err)});
        gpa.destroy(store);
        return;
    };
    g_store = store;
    seedFeedNewest(store);
    // The reader's own follow list is already on disk from last session. Read it
    // before the first frame, so a local-first app opens on THEIR feed rather
    // than on nine strangers while it waits for a relay.
    loadFollowsFromStore();
    loadMutesFromStore();
    loadBookmarksFromStore();
    loadBlossomFromStore();
    loadInbox();

    // The reader's own list, or the one the app was born with. Read before the
    // threads start, so the first dial goes where they asked.
    loadRelays(io, environ);
    loadAuthChoices(io, environ);

    // One ingest thread per SLOT, not per relay: a slot's thread outlives the
    // relay in it, so adding one later is a slot claim rather than a thread
    // spawn from the UI, and removing one leaves a thread that finds the slot
    // dormant and waits. Each dials independently, so a slow or down relay never
    // holds up the others, and all write into the one shared store (LMDB
    // serialises the concurrent writers).
    for (0..max_relays) |i| {
        const thread = std.Thread.spawn(.{}, ingestRelay, .{ gpa, i }) catch |err| {
            std.debug.print("plaza: [{s}] could not start: {s}\n", .{ relayUrlAt(i), @errorName(err) });
            setRelayStatus(i, .offline);
            continue;
        };
        thread.detach();
    }

    // And one per discovered relay: where the reader's follows turned out to
    // be, which the pool would never ask because it only knows the reader's own
    // list. Spawned even before the table has anything in it, because these are
    // slot threads like the pool's: they park until a slot is filled.
    for (0..max_discovered_relays) |i| {
        if (std.Thread.spawn(.{}, discoveredRelayThread, .{ gpa, i })) |t| {
            t.detach();
        } else |err| {
            std.debug.print("plaza: discovered relay {d} did not start: {s}\n", .{ i, @errorName(err) });
        }
    }

    // One more, watching all of them. It has to be a separate thread and not
    // work folded into the eight: each of those is blocked inside `receive`
    // exactly when there is something to notice, and a thread waiting on a dead
    // peer is the last thing that can tell it has stopped answering.
    if (std.Thread.spawn(.{}, relayKeeper, .{gpa})) |keeper| {
        keeper.detach();
    } else |err| {
        // Not fatal. Without it the pool behaves the way it did before: a
        // half-open socket sits there. Said out loud rather than swallowed,
        // because "the feed silently stopped updating" is the symptom and it
        // looks nothing like its cause.
        std.debug.print("plaza: relay keepalive did not start ({s}); a dropped connection will not be noticed\n", .{@errorName(err)});
    }
}

/// How much address space the store may grow into.
///
/// LMDB never grows past its map size, and the library's default is 1 GiB. There
/// is no pruning here and no retention window: the store only grows, at a
/// measured 2.4 MB a day on a development machine with a modest follow set and
/// the app not even running continuously. A reader on eight relays all day with
/// a real follow list, taking kind:6 and kind:7 engagement as well, gets there
/// materially faster.
///
/// Arriving is silent and it is the reader's own notes that pay. `plazaIngest`
/// is `catch {}` at the write of a note this app just signed, deliberately, so a
/// duplicate id cannot stop it reaching the pool, and a full map takes the same
/// branch. `saveOutbox` fails the same way, so the queue index never lands, and
/// `loadOutbox` drops on the next launch every entry whose event is not in the
/// store. The banner goes on saying the app is posting them.
///
/// A map size is address space, not a file: LMDB reserves it and the file stays
/// sparse. So the cheapest honest answer is to reserve far more of it than this
/// app can plausibly use, which moves the wall from a few years out to further
/// away than the format. Detecting MDB_MAP_FULL properly needs the library to
/// tell it apart from every other LMDB error, and pruning is a feature; both are
/// worth having and neither is a reason to leave the wall where it is.
const feed_store_map_size: usize = 32 << 30;

/// Opens (creating if needed) the feed store at `$HOME/.plaza/feed.mdb`.
fn openFeedStore(io: std.Io, environ: *const std.process.Environ.Map) !nostr.store.Store {
    const home = environ.get("HOME") orelse ".";
    var dir_buf: [512]u8 = undefined;
    const dir_path = try std.fmt.bufPrint(&dir_buf, "{s}/.plaza", .{home});
    // mkdir -p (idempotent); an absolute sub-path ignores the cwd handle.
    var dir = try std.Io.Dir.cwd().createDirPathOpen(io, dir_path, .{});
    dir.close(io);

    var path_buf: [512]u8 = undefined;
    const db_path = try std.fmt.bufPrintZ(&path_buf, "{s}/feed.mdb", .{dir_path});
    return nostr.store.Store.open(db_path, .{ .map_size = feed_store_map_size });
}

// ----------------------------------------------------------------- identity
//
// Plaza's local signing identity lives beside the feed store, at
// `$HOME/.plaza/identity.key` (the raw 32-byte secret, mode 0600). It is created
// on the user's onboarding action, not silently: a first run with no key file
// opens the welcome screen, and "Create your identity" generates and persists
// it. This is the zero-config local signer; connecting an external signer
// (Notary, over NIP-46) so the key never touches the client is the next
// onboarding option, and swaps in at `signAndPublish`.

/// Opens (creating if needed) `$HOME/.plaza`, returning the directory handle.
pub fn plazaDir(io: std.Io, environ: *const std.process.Environ.Map) !std.Io.Dir {
    const home = environ.get("HOME") orelse ".";
    var dir_buf: [512]u8 = undefined;
    const dir_path = try std.fmt.bufPrint(&dir_buf, "{s}/.plaza", .{home});
    // mkdir -p (idempotent); an absolute sub-path ignores the cwd handle.
    return std.Io.Dir.cwd().createDirPathOpen(io, dir_path, .{});
}

/// Whether a key from an older Plaza is still sitting on this disk.
///
/// Plaza used to keep the raw secret at `$HOME/.plaza/identity.key`, mode 0600.
/// It does not read it any more, and it does not move it either: importing it
/// would mean this process holding a secret key, which is the whole thing that
/// stopped.
///
/// So the file is LEFT ALONE and the reader is told it is there. Deleting
/// somebody's only copy of an identity because an app was rewritten is not a
/// migration, and silently orphaning it is worse: they would land on the
/// welcome screen as a guest with their account still on the disk and nothing
/// on screen connecting the two.
var g_legacy_key_found = false;

pub fn legacyKeyOnDisk() bool {
    return g_legacy_key_found;
}

fn noticeLegacyKey(io: std.Io, environ: *const std.process.Environ.Map) void {
    var dir = plazaDir(io, environ) catch return;
    defer dir.close(io);
    const st = dir.statFile(io, "identity.key", .{}) catch return;
    g_legacy_key_found = st.size == 32;
}

// ------------------------------------------------------------------- session
//
// The active identity is persisted as a small session file at
// `$HOME/.plaza/session` (mode 0600), a line-based `key=value` record, so a
// returning user is signed straight back in without re-entering anything. A
// local session points at `identity.key` (the raw secret already on disk); a
// remote session carries everything needed to silently reconnect the NIP-46
// bunker (the signer's pubkey, its relay, our ephemeral transport secret, and
// the connect secret), never the user's own key, which lives only in the signer.

/// Writes the session file for the current identity kind. Best-effort: a failure
/// to persist just means this identity will not auto-restore next launch.
fn persistSession() void {
    const io = g_io orelse return;
    const environ = g_environ orelse return;
    var dir = plazaDir(io, environ) catch return;
    defer dir.close(io);

    var buf: [1024]u8 = undefined;
    const data = switch (g_signer_kind) {
        .helper => blk: {
            if (!g_helper_has_identity) return;
            var pk_hex: [64]u8 = undefined;
            hexLower(&pk_hex, g_helper_identity_pk);
            break :blk std.fmt.bufPrint(&buf, "kind=helper\npubkey={s}\nminted={d}\n", .{ &pk_hex, @intFromBool(g_identity_minted_here) }) catch return;
        },
        .remote => blk: {
            const kp = g_remote_client_kp orelse return;
            var pk_hex: [64]u8 = undefined;
            hexLower(&pk_hex, g_remote_pubkey);
            var cs_hex: [64]u8 = undefined;
            hexLower(&cs_hex, kp.secret_key);
            break :blk std.fmt.bufPrint(&buf, "kind=remote\nremote_pubkey={s}\nrelay={s}\nclient_secret={s}\nsecret={s}\n", .{
                &pk_hex,
                g_remote_relay_buf[0..g_remote_relay_len],
                &cs_hex,
                g_remote_secret_buf[0..g_remote_secret_len],
            }) catch return;
        },
    };
    dir.writeFile(io, .{
        .sub_path = "session",
        .data = data,
        .flags = .{ .permissions = secret_file_permissions },
    }) catch |err| std.debug.print("plaza: could not persist session: {s}\n", .{@errorName(err)});
}

/// Restores the persisted identity at boot. Returns whether a session was
/// restored (so the feed should start). Reads `$HOME/.plaza/session`; falls back
/// to migrating a legacy `identity.key` (pre-session installs) into a local
/// session. Any missing or malformed data returns false, landing on onboarding.
fn restoreSession(io: std.Io, environ: *const std.process.Environ.Map) bool {
    var dir = plazaDir(io, environ) catch return false;
    defer dir.close(io);
    const gpa = std.heap.page_allocator;

    const raw = dir.readFileAlloc(io, "session", gpa, std.Io.Limit.limited(2048)) catch {
        // No session file. An older Plaza kept its key here; it is not read
        // and not moved, only noticed, so the reader can be told where it is.
        noticeLegacyKey(io, environ);
        return false;
    };
    defer gpa.free(raw);

    var kind: []const u8 = "";
    var f_pubkey: []const u8 = "";
    var f_relay: []const u8 = "";
    var f_client_secret: []const u8 = "";
    var f_secret: []const u8 = "";
    var lines = std.mem.splitScalar(u8, raw, '\n');
    while (lines.next()) |line| {
        const eq = std.mem.indexOfScalar(u8, line, '=') orelse continue;
        const key = line[0..eq];
        const val = line[eq + 1 ..];
        if (std.mem.eql(u8, key, "kind")) kind = val;
        // Whether this key was minted here. Absent means an older session file,
        // and absent has to read as "imported": assuming a key is ours when we
        // do not know is exactly the assumption that loses a contact list.
        if (std.mem.eql(u8, key, "minted")) g_identity_minted_here = std.mem.eql(u8, val, "1");
        if (std.mem.eql(u8, key, "remote_pubkey")) f_pubkey = val;
        if (std.mem.eql(u8, key, "pubkey")) f_pubkey = val;
        if (std.mem.eql(u8, key, "relay")) f_relay = val;
        if (std.mem.eql(u8, key, "client_secret")) f_client_secret = val;
        if (std.mem.eql(u8, key, "secret")) f_secret = val;
    }

    if (std.mem.eql(u8, kind, "helper")) return restoreHelperIdentity(f_pubkey);
    // A session written by a Plaza that held its own key. There is no such
    // identity any more, so this lands on the welcome screen; the notice says
    // where the key it was pointing at still is.
    if (std.mem.eql(u8, kind, "local")) {
        noticeLegacyKey(io, environ);
        return false;
    }
    if (std.mem.eql(u8, kind, "remote")) return restoreRemoteSigner(gpa, f_pubkey, f_relay, f_client_secret, f_secret);
    return false;
}

/// Rebuilds the remote-signer connection from a persisted session and reconnects
/// silently: adopts the bunker pubkey as the identity, reconstructs the ephemeral
/// transport key, starts the response listener, and re-sends `connect`.
fn restoreRemoteSigner(gpa: std.mem.Allocator, pubkey_hex: []const u8, relay: []const u8, client_secret_hex: []const u8, secret: []const u8) bool {
    if (pubkey_hex.len != 64 or client_secret_hex.len != 64) return false;
    if (relay.len == 0 or relay.len > g_remote_relay_buf.len) return false;
    if (secret.len > g_remote_secret_buf.len) return false;

    var pubkey: [32]u8 = undefined;
    _ = std.fmt.hexToBytes(&pubkey, pubkey_hex) catch return false;
    var client_secret: [32]u8 = undefined;
    _ = std.fmt.hexToBytes(&client_secret, client_secret_hex) catch return false;

    var signer = nostr.keys.Signer.init();
    const client_kp = signer.keyPairFromSecretKey(client_secret) catch {
        signer.deinit();
        return false;
    };
    signer.deinit();

    g_remote_pubkey = pubkey;
    @memcpy(g_remote_relay_buf[0..relay.len], relay);
    g_remote_relay_len = relay.len;
    @memcpy(g_remote_secret_buf[0..secret.len], secret);
    g_remote_secret_len = secret.len;
    g_remote_client_kp = client_kp;

    const npub = abbreviateNpub(&g_identity_npub_buf, pubkey);
    g_identity_npub_len = npub.len;
    g_signer_kind = .remote;
    g_remote_status.store(1, .release);
    g_remote_sign_notice.store(false, .release);

    // A fresh generation for this reconnected session (see `connectRemoteSigner`).
    const generation = newRemoteGeneration();
    const thread = std.Thread.spawn(.{}, nip46ReceiveLoop, .{ gpa, generation }) catch return false;
    thread.detach();
    sendConnect(gpa);
    return true;
}

/// The document one place writes, for the round-trip test.
pub fn writePlaceDocumentForTest(gpa: std.mem.Allocator, out: *std.ArrayList(u8), m: *const Place) !void {
    return writePlaceDocument(gpa, out, m);
}

pub fn settingsWritesForTest() usize {
    return prefs.g_settings_writes;
}

/// Where an unsent draft waits between launches. One slot, because the composer
/// is one sheet: a list of drafts is a different feature and the plan says so.
const draft_file = "draft";
const draft_warning_file = "draft_warning";
/// Set by an edit, cleared by the tick that writes it: a keystroke must not
/// carry a file write, and a file write must not wait for the sheet to close.
var g_draft_dirty = false;

/// The content warning that goes with the draft, when one is switched on.
fn applyStashedDraft(model: *Model, stashed: StashedDraft) void {
    if (stashed.text.len == 0) return;
    setPlain(compose_capacity, &model.draft_buffer, stashed.text);
    if (stashed.warn) |reason| {
        model.warn_on = true;
        model.warn_buffer.set(reason);
    }
}

fn draftWarningOf(model: *const Model) ?[]const u8 {
    return if (model.warn_on) model.warn_buffer.text() else null;
}

/// Keeps what was written but not sent. The composer already survives being
/// closed within a session; this is what makes it survive the app quitting,
/// which is the case that actually loses words: a machine that sleeps, an
/// update, a crash.
///
/// Written with the same restrictive permissions as the rest of ~/.plaza,
/// because an unsent note is as private as a sent one and rather more likely
/// to be unfinished thinking.
///
/// The warning rides along as a sibling file whose existence is the switch and
/// whose content is the reason, written and deleted in the same breath as the
/// draft: a note that was going to be covered must not come back from a quit
/// one press from going out uncovered.
fn saveDraft(text: []const u8, warn: ?[]const u8) void {
    const io = g_io orelse return;
    const environ = g_environ orelse return;
    var dir = plazaDir(io, environ) catch return;
    defer dir.close(io);
    writeDraft(io, &dir, text, warn);
}

fn writeDraft(io: std.Io, dir: *std.Io.Dir, text: []const u8, warn: ?[]const u8) void {
    if (text.len == 0) {
        // Nothing to keep: the slot is removed rather than left holding a stale
        // draft that would reappear over the next empty composer.
        dir.deleteFile(io, draft_file) catch {};
        dir.deleteFile(io, draft_warning_file) catch {};
        return;
    }
    dir.writeFile(io, .{
        .sub_path = draft_file,
        .data = text,
        .flags = .{ .permissions = secret_file_permissions },
    }) catch {};
    if (warn) |reason| {
        dir.writeFile(io, .{
            .sub_path = draft_warning_file,
            .data = reason,
            .flags = .{ .permissions = secret_file_permissions },
        }) catch {};
    } else {
        dir.deleteFile(io, draft_warning_file) catch {};
    }
}

const StashedDraft = struct {
    text: []const u8 = "",
    /// The reason, when the draft was saved with a warning switched on (an empty
    /// reason is still a warning).
    warn: ?[]const u8 = null,
};

/// Reads the stashed draft back, or an empty one when there is none.
fn loadDraft(out: []u8, warn_out: []u8) StashedDraft {
    const io = g_io orelse return .{};
    const environ = g_environ orelse return .{};
    var dir = plazaDir(io, environ) catch return .{};
    defer dir.close(io);
    return readDraft(io, &dir, out, warn_out);
}

fn readDraft(io: std.Io, dir: *std.Io.Dir, out: []u8, warn_out: []u8) StashedDraft {
    const n = dir.readFile(io, draft_file, out) catch return .{};
    if (n.len == 0) return .{};
    const w = dir.readFile(io, draft_warning_file, warn_out) catch return .{ .text = out[0..n.len] };
    return .{ .text = out[0..n.len], .warn = warn_out[0..w.len] };
}

pub fn writeDraftForTest(io: std.Io, dir: *std.Io.Dir, text: []const u8, warn: ?[]const u8) void {
    writeDraft(io, dir, text, warn);
}

pub fn draftWarningForModelForTest(model: *const Model) ?[]const u8 {
    return draftWarningOf(model);
}

/// Restores a launch's composer from `dir`, the way startup does.
pub fn loadDraftIntoForTest(io: std.Io, dir: *std.Io.Dir, model: *Model) void {
    var draft_buf: [note_content_cap]u8 = undefined;
    var warn_buf: [warning_input_capacity]u8 = undefined;
    const stashed = readDraft(io, dir, &draft_buf, &warn_buf);
    applyStashedDraft(model, stashed);
}

/// Logs out: deletes the session (and, for a local key, the key file itself),
/// resets the identity globals, and returns to onboarding. The feed store and
/// its ingest threads keep running (they serve the starter pack regardless of
/// who is signed in); a subsequent sign-in reuses them. The user is never locked
/// in, a local key can always be copied from Settings first, and a remote
/// signer keeps the user's key throughout.
/// Drives the whole sign-out, so a test can assert what does NOT survive it. The
/// list of things it clears is the interesting part, and every one of them was
/// added after something of the previous account's turned up under the next
/// account's key.
pub fn performLogoutForTest(model: *Model, fx: *Effects) void {
    performLogout(model, fx);
}

pub fn loggedOutPubkeyForTest() ?[32]u8 {
    return g_logged_out_pk;
}

fn performLogout(model: *Model, fx: *Effects) void {
    // Notary is NOT touched. Signing out of a client is not the same act as
    // taking your key off the machine, and conflating them means one press in
    // one app destroys an identity every other app was using. The key stays
    // where it lives; this app stops using it.
    //
    // Which makes the latch below the whole mechanism rather than a backstop.
    // The keyholder still holds the key and will keep saying so on every
    // health check, so "signed out" is a fact Plaza has to remember for itself.
    _ = fx;
    g_logged_out = true;
    // WHICH key left, so the health-check can refuse to hand it back even after
    // an explicit sign-in drops the latch above.
    g_logged_out_pk = activePubkey();
    if (g_io) |io| if (g_environ) |environ| {
        if (plazaDir(io, environ)) |dir_const| {
            var dir = dir_const;
            defer dir.close(io);
            // The session, and nothing else. No key file is removed, by
            // either name: `identity.key` belongs to a Plaza that held its own
            // key and is left where its owner can find it, and the keyholder's
            // file is the keyholder's.
            dir.deleteFile(io, "session") catch {};
        } else |_| {}
    };

    // Tear down the NIP-46 session: bumping the generation stops the detached
    // listener from processing into the next session, and the pending table is
    // emptied so no in-flight request survives the logout.
    _ = g_remote_generation.fetchAdd(1, .monotonic);
    clearPending();
    g_remote_sign_notice.store(false, .release);
    // And the built-in signer's slot, for the same reason: it holds the leaving
    // account's writing, and the confirmation said what that costs.
    releaseHelperSign();
    g_helper_sign_notice.store(false, .release);

    g_identity_npub_len = 0;
    g_helper_has_identity = false;
    g_signer_kind = .helper;
    g_remote_client_kp = null;
    g_remote_relay_len = 0;
    g_remote_secret_len = 0;
    g_remote_status.store(0, .release);
    login.g_login_error.store(@intFromEnum(LoginError.none), .release);
    invalidateFeed();

    // The relay list belongs to the ACCOUNT, not the machine: it came from their
    // kind:10002 and it names where they read and write. Carrying it into the
    // next account would route a stranger's notes through the previous reader's
    // relays, and hand the new account a list they never chose. Back to the
    // relays the app was born with, ready to adopt the next account's own.
    resetRelaysToBootstrap();
    // And what was concluded about the leaving account's own records. Carrying
    // any of it would let the next account be judged without being asked, and a
    // write would then go out over a list nobody has read.
    forgetOwnRecordAnswers();
    // And who the leaving account followed, so the next reader is not shown a
    // feed built from a stranger's list.
    forgetFollows();
    forgetMutes();
    forgetBookmarks();
    forgetPrivateHalves();
    dropUpload();
    forgetBlossom();
    resetInbox();
    forgetPlaces();
    // And a note this account was about to sign. It is held on the near side of
    // the signature precisely so it can still be taken back, and a session
    // ending is the clearest possible instance of taking it back.
    g_post_due_s = 0;
    g_reply_due_s = 0;
    model.notifications_open = false;
    model.editing_profile = false;
    model.profile_seeded = false;
    model.profile_confirm_new = false;
    model.fresh_ask = null;

    // And this key was not made here, whoever comes next. The flag is the ONE
    // piece of evidence that authorizes building a contact list, a relay list or
    // a profile from nothing, and it is persisted to the session file, so left
    // set it outlived the account it was true about: mint here, log out, and an
    // identity imported afterwards inherited permission to publish nine
    // starter-pack names over a real eight-hundred-follow list.
    g_identity_minted_here = false;
    // And Home reads follows again. The pack is where a key MADE here starts,
    // which is a fact about that account and not about this app: left set, the
    // next reader signed in with eight hundred follows and got nine strangers.
    g_home_scope = .following;

    model.login_buffer.clear();
    model.draft_buffer.clear();
    model.draft_dropped = 0;
    model.warn_on = false;
    model.warn_buffer.clear();
    // Every other thing the previous reader typed, for the same reason the draft
    // is cleared: it is their private thinking, and it is one press from being
    // published under the NEXT account's key.
    //
    // The reply box survived because logout performs no navigation, so the next
    // account landed inside the previous reader's open thread with their unsent
    // sentence still in the composer. The name field survived Skip as well as
    // logout, so a freshly minted key could be given a permanent kind:0 carrying
    // the previous person's typed name.
    model.reply_buffer.clear();
    forgetReplyDrafts();
    model.name_buffer.clear();
    model.viewing_thread = 0;
    model.thread_stack_len = 0;
    model.notifications_return = false;
    model.viewing_profile = null;
    model.topic_len = 0;
    model.viewing_bookmarks = false;
    // And off the disk. An unfinished note is the previous account's private
    // thinking; leaving it would hand it to whoever signs in next, in their
    // composer, one keystroke from being published under THEIR key.
    saveDraft("", null);
    // The OUTBOX is deliberately left alone, and that is not an oversight.
    //
    // A queued note is one the reader wrote and the app has not managed to
    // deliver yet. Emptying the queue here would destroy it, and `sweepOutbox`
    // already refuses to do that for exactly this reason. So it stays, and
    // `syncOutboxOwner` is what makes staying safe: on the next tick the slots
    // are handed to whoever is signed in, and these entries are parked in this
    // account's own record. Sign back in as its author and it is read back and
    // goes out. For a LOCAL key that is only possible if the reader kept a copy,
    // because this function deletes the key file; the note is still theirs, and
    // still here, which is the most an app can honestly promise at that point.
    //
    // Getting this wrong is how the previous account's unsent note would ride
    // out over the next account's relays, counted in their status bar as
    // something the app owed THEM.
    model.logout_pending = false;
    model.notes_len = 0;
    // Never a locked door: signing out lands on the guest feed, reading
    // uninterrupted (the pool and store keep running), not a welcome wall.
    model.stage = .ready;
}

// ----------------------------------------------------------- background ingest
//
// Each relay's ingest loop runs on its own thread with its own `std.Io.Threaded`
// and its own secp256k1 context, the io backend and the signer are not shared
// across threads, the exact shape the Notary daemon uses per relay. It dials,
// subscribes for recent kind:1, verifies each event, and writes it into the
// shared store; the UI thread reads it back through `Model.refresh`.

/// The first wait before redialling a relay whose connection ended, and the
/// ceiling that wait grows to.
///
/// This used to be a flat three seconds, forever, with no counter. A relay that
/// is down, that has stopped taking this reader, or that accepts the handshake
/// and then drops the socket was dialled twelve hundred times an hour for as
/// long as the app stayed open, from eight threads with no jitter between them,
/// and every one of those dials re-asked for the whole backlog.
const reconnect_base_ms: u64 = 3_000;
const reconnect_max_ms: u64 = 300_000;

/// How long a connection has to last before it counts as having worked.
///
/// The reason for the rule is not obvious: a successful handshake is NOT
/// evidence that a relay is healthy. A relay that accepts the socket and
/// immediately closes it would reset the ladder on every open, and the widening
/// delay would never widen. Only a connection that stayed up clears the count.
const stable_connection_ms: i64 = 60_000;

/// The wait before redialling, after `attempts` connections in a row that did
/// not last. Doubling, capped.
pub fn reconnectDelayMs(attempts: u6) u64 {
    const shift: u6 = @min(attempts, 7);
    return @min(reconnect_base_ms << shift, reconnect_max_ms);
}

/// The attempt count after a connection that stayed up for `lasted_ms`.
///
/// Separate from the loop so the rule can be asserted rather than described: a
/// connection only clears the ladder by LASTING, never by opening.
pub fn nextReconnectAttempts(attempts: u6, lasted_ms: i64) u6 {
    return if (lasted_ms >= stable_connection_ms) 0 else attempts +| 1;
}

/// Extra delay for slot `index`, so the pool does not redial in lockstep.
///
/// Spread rather than randomness, because the thing being avoided is specific:
/// eight threads that dropped together on one network blip coming back together,
/// and then staying in step for the rest of the session. Walking the offset by
/// the attempt as well as the slot separates two relays that happened to start
/// aligned. Never more than a quarter of the wait, and it is a function, so what
/// it promises can be asserted.
pub fn reconnectJitterMs(wait: u64, index: usize, attempts: u6) u64 {
    const slice = wait / 64;
    const step = (index *% 5 +% @as(usize, attempts) *% 3) % 16;
    return slice * step;
}

/// Opens, or replaces, the engagement subscription over the first `count`
/// watched notes.
///
/// A REQ under an existing id IS a replacement, so widening the watched set
/// costs one message and no CLOSE.
/// Records a feed note's id so its engagement can be watched, deduped and
/// bounded.
///
/// Shared by the pool threads and the routed ones, because they had drifted:
/// the pool watched engagement and the routed relays did not, and after the
/// outbox landed the routed relays are the ones carrying most of the feed. One
/// function is what stops that happening again.
///
/// The cap keeps the `#e` filter a size relays actually accept.
pub const engagementWatchCapForTest = engagement_watch_cap;

pub fn rememberFeedIdForTest(
    ids: *[engagement_watch_cap]i64,
    hex: *[engagement_watch_cap][64]u8,
    len: *usize,
    ev: nostr.event.Event,
) void {
    rememberFeedId(ids, hex, len, ev);
}

fn rememberFeedId(
    ids: *[engagement_watch_cap]i64,
    hex: *[engagement_watch_cap][64]u8,
    len: *usize,
    ev: nostr.event.Event,
) void {
    if (len.* >= engagement_watch_cap) return;
    const nid = noteIdOf(ev);
    for (ids[0..len.*]) |seen| {
        if (seen == nid) return;
    }
    ids[len.*] = nid;
    hexLower(&hex[len.*], ev.id);
    len.* += 1;
}

// -- What the feed is SHOWING, rather than what happened to arrive -----------
//
// The watch list was built only from events that came down the wire this
// session, while the feed's own REQ carries a `since` off the newest stored
// note. So on any store that is not cold, the feed draws notes nobody has asked
// a relay about, and every one of them reads zero replies, zero reposts, zero
// likes and zero sats for the whole session. A guest sees it worst, because a
// starter-pack feed is nearly all store after the first launch, and it looked
// like guests simply do not get counts.
//
// It also explains the shape of it: opening a note fetches THAT note's
// engagement on its own socket, so a count would appear for exactly the note
// somebody had looked at, stay when they went back, and nowhere else.
//
// So the view publishes what it is drawing, and each relay worker folds that in
// before it asks. Written by the view thread, read by every relay thread, under
// a lock of its own: the engagement table has one already and taking it here
// would mean holding two in an order nothing else in the app agrees on.
var g_feed_watch_lock = std.atomic.Value(bool).init(false);
var g_feed_watch_ids: [engagement_watch_cap]i64 = undefined;
var g_feed_watch_hex: [engagement_watch_cap][64]u8 = undefined;
var g_feed_watch_len: usize = 0;
/// Moves whenever the published set CHANGES, so a worker can tell "the feed grew
/// while I was reading" from "the same feed, redrawn". A redraw happens on every
/// tick; re-asking every relay four times a second is a different bug.
var g_feed_watch_gen = std.atomic.Value(u32).init(0);

fn lockFeedWatch() void {
    while (g_feed_watch_lock.cmpxchgWeak(false, true, .acquire, .monotonic) != null) std.atomic.spinLoopHint();
}

fn unlockFeedWatch() void {
    g_feed_watch_lock.store(false, .release);
}

/// The view thread, after a feed rebuild. Newest first and bounded, which is
/// the order the feed is already in: what a reader is looking at is what its
/// counts are wanted for.
fn publishFeedWatch(notes: []const Note) void {
    lockFeedWatch();
    defer unlockFeedWatch();
    const n = @min(notes.len, engagement_watch_cap);
    var changed = n != g_feed_watch_len;
    for (notes[0..n], 0..) |note, i| {
        if (!changed and g_feed_watch_ids[i] != note.id) changed = true;
        g_feed_watch_ids[i] = note.id;
        hexLower(&g_feed_watch_hex[i], note.event_id);
    }
    g_feed_watch_len = n;
    if (changed) _ = g_feed_watch_gen.fetchAdd(1, .monotonic);
}

fn feedWatchGeneration() u32 {
    return g_feed_watch_gen.load(.monotonic);
}

/// Folds the published set into one worker's watch list, keeping what that
/// socket already knew. Returns the new length.
fn mergeFeedWatch(
    ids: *[engagement_watch_cap]i64,
    hex: *[engagement_watch_cap][64]u8,
    len: usize,
) usize {
    lockFeedWatch();
    defer unlockFeedWatch();
    var n = len;
    outer: for (0..g_feed_watch_len) |i| {
        if (n >= engagement_watch_cap) break;
        for (ids[0..n]) |seen| {
            if (seen == g_feed_watch_ids[i]) continue :outer;
        }
        ids[n] = g_feed_watch_ids[i];
        hex[n] = g_feed_watch_hex[i];
        n += 1;
    }
    return n;
}

pub fn publishFeedWatchForTest(notes: []const Note) void {
    publishFeedWatch(notes);
}

pub fn mergeFeedWatchForTest(
    ids: *[engagement_watch_cap]i64,
    hex: *[engagement_watch_cap][64]u8,
    len: usize,
) usize {
    return mergeFeedWatch(ids, hex, len);
}

pub fn feedWatchGenerationForTest() u32 {
    return feedWatchGeneration();
}

fn subscribeEngagement(relay: *nostr.relay.Relay, hex: *const [engagement_watch_cap][64]u8, count: usize) void {
    if (count == 0) return;
    var evals: [engagement_watch_cap][]const u8 = undefined;
    for (0..count) |i| evals[i] = &hex[i];
    const eng_tags = [_]nostr.filter.TagFilter{.{ .letter = 'e', .values = evals[0..count] }};
    const eng_filters = [_]nostr.filter.Filter{engagementFilter(&eng_tags)};
    relay.subscribe("plaza-engagement", &eng_filters) catch {};
}

// -- Every socket asks only about the people it can answer for ---------------
//
// The pool used to ask all eight of its relays about every followed author, and
// the routed relays asked about theirs. That is a hybrid: the routing bought
// reach, and none of it bought the pool relays a smaller question. Jumble and
// Amethyst both route the WHOLE feed, and this is that.
//
// Each pool relay is asked about the follows who write THERE, plus the
// residual: everyone no relay in either set is going to be asked about. The
// residual is what makes the change safe, and defining it correctly is the
// whole risk. It is NOT "authors with no relay list". It is every author not
// covered by any chosen relay, list or no list, because an author who publishes
// only to a relay that did not make the cut is otherwise asked of nobody at all
// and simply vanishes from the feed. No error, no empty state, which is the
// exact failure the outbox model exists to fix and the easiest one to
// reintroduce while fixing it.
//
// So the invariant, and there is a test for it by name: every followed author
// appears in at least one relay's filters.

pub fn poolAuthorsForTest(index: usize, out: *[max_follows + 1][32]u8) usize {
    return poolAuthors(index, out);
}
pub fn poolAuthorsOrAllForTest(index: usize, out: *[max_follows + 1][32]u8) usize {
    return poolAuthorsOrAll(index, out);
}
pub fn discoveredAuthorsForTest(index: usize, out: *[discovered_authors_cap][32]u8) usize {
    lockDiscovered();
    defer unlockDiscovered();
    if (index >= routing.g_discovered.len) return 0;
    const d = &routing.g_discovered[index];
    @memcpy(out[0..d.authors_len], d.authors[0..d.authors_len]);
    return d.authors_len;
}
pub fn clearRoutesForTest() void {
    lockDiscovered();
    defer unlockDiscovered();
    for (&routing.g_pool_routed) |*p| {
        p.url_len = 0;
        p.authors_len = 0;
    }
    routing.g_residual_len = 0;
}

pub fn forgetDiscoveredForTest() void {
    forgetDiscovered();
}

pub const outboxSubIdForTest = outbox_sub_id;

pub fn routeFollowUpForTest(live_url: []const u8, live_gen: u32, slot_url: []const u8, slot_gen: u32) RouteFollowUp {
    return routeFollowUp(live_url, live_gen, slot_url, slot_gen);
}

pub fn residualCountForTest() usize {
    lockDiscovered();
    defer unlockDiscovered();
    return routing.g_residual_len;
}

/// One discovered relay's loop: dial, ask about the people who write there,
/// ingest, and redial when the connection drops or the table moves under it.
///
/// Deliberately thinner than the pool's loop. No publish, no latency probe, no
/// engagement subscription, no inbox: this connection exists to close one gap,
/// which is that a follow writing somewhere the reader is not would otherwise
/// never arrive at all.
fn discoveredRelayThread(gpa: std.mem.Allocator, index: usize) void {
    var threaded = std.Io.Threaded.init(gpa, .{});
    defer threaded.deinit();
    const io = threaded.io();

    var signer = nostr.keys.Signer.init();
    defer signer.deinit();

    var attempts: u6 = 0;
    var url_buf: [96]u8 = undefined;
    var authors: [discovered_authors_cap][32]u8 = undefined;
    while (true) {
        const gen = routing.g_discovered_gen[index].load(.acquire);
        const snap = discoveredSnapshot(index, gen, &url_buf, &authors);
        if (snap == null or relaysPaused()) {
            attempts = 0;
            io.sleep(std.Io.Duration.fromSeconds(2), .awake) catch {};
            continue;
        }
        const opened_at = std.Io.Timestamp.now(io, .awake).toMilliseconds();
        const url = url_buf[0..snap.?.url_len];
        discoveredOnce(gpa, io, signer, index, url, authors[0..snap.?.authors_len], gen) catch {};
        const lasted = std.Io.Timestamp.now(io, .awake).toMilliseconds() - opened_at;
        // The pool's ladder, and its guard: a relay that accepts the handshake
        // and drops the socket would otherwise reset the backoff on every
        // connection and redial in a tight loop forever.
        attempts = nextReconnectAttempts(attempts, lasted);
        // Unlike the pool, this slot can be spent elsewhere. A connection that
        // held is a relay that will have us; a run of short ones is a relay that
        // will not, and the slot is worth more on the next relay down.
        if (attempts == 0) {
            clearRelayRefusal(url);
        } else if (noteRelayRefusal(url)) {
            // Ask for a rethink rather than waiting for somebody's relay list
            // to land, which on a settled account may be never.
            routing.g_relay_ranks_dirty.store(true, .release);
        }
        const base = reconnectDelayMs(attempts);
        io.sleep(std.Io.Duration.fromMilliseconds(@intCast(base + reconnectJitterMs(base, index, attempts))), .awake) catch {};
    }
}

fn discoveredOnce(
    gpa: std.mem.Allocator,
    io: std.Io,
    signer: nostr.keys.Signer,
    index: usize,
    url: []const u8,
    authors: []const [32]u8,
    gen_in: u32,
) !void {
    const authors_len_in = authors.len;
    var relay = try nostr.relay.dial(gpa, io, url);
    // Declared after `deinit` so it runs before it: the keeper must have let go
    // of the pointer before the connection is freed.
    defer relay.deinit();
    offerLiveRelay(discovered_watch_base + index, relay);
    defer offerLiveRelay(discovered_watch_base + index, null);

    var filter_buf: [max_feed_filters]nostr.filter.Filter = undefined;
    try relay.subscribe(outbox_sub_id, buildRoutedFilters(authors[0..authors_len_in], &filter_buf));

    // The notes this relay carries, so their engagement can be watched HERE.
    //
    // The pool threads have done this since counts existed, and these have not,
    // and after the outbox landed these are the relays that carry most of the
    // feed. So a note routed here showed no replies, no likes and no zaps for as
    // long as it was on screen: the numbers only appeared once the note was
    // opened, because a thread fetches engagement on its own path, and then they
    // were in the table and the feed looked fine. That is why this reads as
    // "counts load late" rather than as "counts are missing".
    var feed_ids: [engagement_watch_cap]i64 = undefined;
    var feed_id_hex: [engagement_watch_cap][64]u8 = undefined;
    var feed_ids_len: usize = 0;
    var engagement_watching: usize = 0;
    var engagement_at: i64 = 0;
    var engagement_gen: u32 = 0;
    // Published only now, so the keeper never replaces a question that has not
    // been asked yet. Cleared on the way out, before the connection is freed.
    setRoutedLive(index, url, gen_in);
    defer clearRoutedLive(index);

    while (true) {
        if (relaysPaused()) return;
        // Widen as more of this relay's feed arrives, on the same rule the pool
        // threads use: a subscription opened once at EOSE leaves every note that
        // arrives afterwards reading zero forever.
        const now_ms = std.Io.Timestamp.now(io, .awake).toMilliseconds();
        // Two things can put a note in front of a reader without a count: one
        // arriving here, and one the view read out of the store. Both are asked
        // about, and the second is why this no longer waits for `watching > 0`:
        // a connection whose first EOSE found nothing had no way back to
        // watching anything at all, for the rest of its life.
        const watch_gen = feedWatchGeneration();
        if (now_ms - engagement_at > engagement_widen_ms and
            (watch_gen != engagement_gen or feed_ids_len > engagement_watching))
        {
            feed_ids_len = mergeFeedWatch(&feed_ids, &feed_id_hex, feed_ids_len);
            engagement_gen = watch_gen;
            if (feed_ids_len > 0) {
                subscribeEngagement(relay, &feed_id_hex, feed_ids_len);
                engagement_watching = feed_ids_len;
                engagement_at = now_ms;
            }
        }
        // The slot was pointed at a DIFFERENT relay. Nothing here is worth
        // keeping, so drop it and let the loop dial whatever the slot holds now.
        //
        // A change of WHO is not checked here and must not be: this thread only
        // reaches this line when the relay says something, and a relay with
        // nothing to say says nothing. The keeper replaces the question on the
        // live socket instead.
        if (!routedSlotStillNames(index, url)) return;
        var msg = (relay.receive() catch return) orelse return;
        defer msg.deinit();
        switch (msg.value) {
            .event => |e| {
                if (std.mem.eql(u8, e.subscription_id, outbox_sub_id)) {
                    // Verified before it is stored. This is a relay the reader
                    // never chose, reached because a follow named it, so it gets
                    // less trust than the pool rather than more.
                    const result = plazaIngestFrom(gpa, e.event, .{ .verify_with = signer }, url) catch continue;
                    if (result == .invalid) continue;
                    if (e.event.kind == 1) {
                        noteFeedNewest(e.event.created_at);
                        rememberFeedId(&feed_ids, &feed_id_hex, &feed_ids_len, e.event);
                    }
                } else {
                    // The engagement subscription. Verified too, so a forged
                    // reaction cannot inflate a tally.
                    if (nostr.event.verify(gpa, signer, e.event) catch false) {
                        countEngagement(e.event, feed_ids[0..feed_ids_len]);
                    }
                }
            },
            .eose => |eo| {
                // What this relay had, drained: now watch those notes.
                if (engagement_watching == 0 and std.mem.eql(u8, eo.subscription_id, outbox_sub_id)) {
                    feed_ids_len = mergeFeedWatch(&feed_ids, &feed_id_hex, feed_ids_len);
                    engagement_gen = feedWatchGeneration();
                    if (feed_ids_len > 0) {
                        subscribeEngagement(relay, &feed_id_hex, feed_ids_len);
                        engagement_watching = feed_ids_len;
                        engagement_at = std.Io.Timestamp.now(io, .awake).toMilliseconds();
                    }
                }
            },
            .closed => return,
            else => {},
        }
    }
}

/// One relay's ingest loop: dial, serve, and reconnect after a widening delay,
/// forever.
fn ingestRelay(gpa: std.mem.Allocator, index: usize) void {
    var threaded = std.Io.Threaded.init(gpa, .{});
    defer threaded.deinit();
    const io = threaded.io();

    var signer = nostr.keys.Signer.init();
    defer signer.deinit();

    // Connections in a row that did not last `stable_connection_ms`.
    var attempts: u6 = 0;
    // The address last dialled, so re-pointing a slot starts a clean ladder
    // instead of inheriting the previous relay's failures. Fixing a typo in a
    // relay URL should take effect now, not in five minutes.
    var tried_buf: [96]u8 = undefined;
    var tried_len: usize = 0;

    while (true) {
        // An empty slot is not an error: it is a seat kept for a relay the
        // reader may add. It costs a sleeping thread and nothing else.
        if (relayAt(index) == null) {
            setRelayStatus(index, .offline);
            attempts = 0;
            tried_len = 0;
            io.sleep(std.Io.Duration.fromSeconds(1), .awake) catch {};
            continue;
        }
        // A paused pool never dials. The reader still has the whole store, so
        // pausing costs them nothing but the live tail.
        if (relaysPaused()) {
            setRelayStatus(index, .offline);
            attempts = 0;
            io.sleep(std.Io.Duration.fromSeconds(1), .awake) catch {};
            continue;
        }
        var url_buf: [96]u8 = undefined;
        if (relaySnapshot(index, &url_buf)) |now| {
            if (!relayUrlEql(now.url, tried_buf[0..tried_len])) {
                attempts = 0;
                tried_len = now.url.len;
                @memcpy(tried_buf[0..tried_len], now.url);
            }
        }
        setRelayStatus(index, .connecting);
        const opened_at = std.Io.Timestamp.now(io, .awake).toMilliseconds();
        ingestOnce(gpa, io, signer, index) catch |err| {
            std.debug.print("plaza: [{s}] {s}\n", .{ relayUrlAt(index), @errorName(err) });
        };
        setRelayStatus(index, .offline);
        clearRelayRtt(index);
        const lasted = std.Io.Timestamp.now(io, .awake).toMilliseconds() - opened_at;
        attempts = nextReconnectAttempts(attempts, lasted);
        const wait = reconnectDelayMs(attempts);
        const spread = reconnectJitterMs(wait, index, attempts);
        io.sleep(std.Io.Duration.fromMilliseconds(@intCast(wait + spread)), .awake) catch {};
    }
}

// -- Being asked who you are (NIP-42) ----------------------------------------
//
// A relay may send `["AUTH", <challenge>]`. Answering means signing a kind:22242
// event that names the relay and echoes the challenge, with the reader's key.
// That tells the relay whose connection this is, so it is never done without the
// reader's say: the first time a relay refuses us for want of it, a notice names
// the relay and the reader chooses Allow or Don't allow. The answer is kept per account and relay, so a
// second account on the same machine is asked for itself, and it can be changed
// in the relay's row.
//
// Nothing here happens because a relay greeted us. Plenty of public relays send
// a challenge on every connection and gate nothing, and answering those would
// both ask the reader about relays that do not care and tell those relays who
// they are. So a challenge is only kept, quietly, as the latest one that relay
// sent. The reader's choice is consulted when the relay actually refuses
// something with an `auth-required:` reason: allow answers and re-sends what was
// refused, don't allow does nothing, and ask raises the notice. A relay that
// never refuses anything is never asked about and never sent an AUTH.
//
// Three parties are involved and none of them may wait on another. The relay's
// reader thread hears the AUTH and the CLOSED and later sends the reply. The UI
// thread gets the signature, because the signer is reached through effects
// (Notary's loopback door, or a bunker over NIP-46) and a person may take a
// while to approve. So they meet in a per-relay slot under a spin lock, and each
// only reads the slot or moves it one step. The reader never blocks on a
// signature: it keeps reading, and the feed on every other relay is untouched.
//
// What is copied, and from where:
//   - A challenge is stored and an `auth-required:` CLOSED reuses it, because a
//     relay does not re-issue one (Amethyst RelayAuthenticator.kt:176-178,
//     :231-237, :273-290).
//   - Authentication is started by the refusal and not by the challenge: Jumble
//     calls its authenticator only from the `auth-required` branch of a REQ's
//     close handler (relay-subscription.ts:86-89), never when the challenge
//     arrives.
//   - The AUTH's OK is what re-sends the refused subscriptions, once, so a
//     refusal cannot loop (Amethyst RelayAuthenticator.kt:293-305; Jumble
//     relay-subscription.ts:86-100 restarts the REQ only after `authenticate`
//     resolves and only if it has not authed before).
//   - Whether to identify is the reader's decision per relay, asked once and
//     remembered (Amethyst AuthCoordinator.kt:117-149, :193-226). A CLOSED
//     that stays refused is a finished subscription, counted as settled and
//     not as data (Jumble relay-subscription.ts:107-110).

/// The longest challenge Plaza will sign. NIP-42 leaves it an arbitrary string;
/// real relays send a few dozen bytes. One past this is not a challenge worth
/// putting inside a signed event.
const auth_challenge_cap = 256;
/// The signed event as JSON: id, pubkey and sig (256 hex), the relay address
/// (96), the challenge (256, doubled if every byte needs escaping), and the keys.
const auth_event_cap = 1536;
/// How long a signature may be out before it is given up on.
const auth_sign_timeout_s: i64 = 30;
/// A relay that refused a subscription for want of AUTH and then never sent a
/// challenge is not going to. Past this the connection is dropped and re-dialed,
/// which is what a refused feed did before AUTH was understood at all.
const auth_gate_wait_ms: i64 = 20_000;

/// What the reader has said about identifying themselves to one relay.
pub const AuthChoice = enum(u8) { ask, allow, deny };

const max_auth_choices = 128;
/// `$HOME/.plaza/relay-auth`: one `allow <pubkey> <url>` or `deny <pubkey> <url>`
/// per line, the pubkey in hex naming the account the answer was given for.
/// Beside the relay list and the other local settings, and nowhere near a key.
const auth_choices_file = "relay-auth";
/// Written here first and renamed over the real one, so a crash mid-write
/// leaves the old file whole rather than a last line cut short. A cut line
/// could still be a relay address, just a different relay's.
const auth_choices_tmp = "relay-auth.tmp";
/// A line is the word, 64 hex, the address (96 at most) and three separators.
const auth_choices_file_cap = max_auth_choices * 176 + 64;

const AuthChoiceEntry = struct {
    used: bool = false,
    allow: bool = false,
    /// Whose answer it is. Saying yes as one account says nothing about
    /// another: the relay learns a different person.
    account: [32]u8 = [_]u8{0} ** 32,
    url_len: u8 = 0,
    url_buf: [96]u8 = [_]u8{0} ** 96,

    fn url(self: *const AuthChoiceEntry) []const u8 {
        return self.url_buf[0..self.url_len];
    }
};

/// Where one relay's challenge has got to.
const AuthPhase = enum(u8) {
    /// Nothing has been asked of us on this connection. A challenge may be held
    /// in the slot, but no relay has refused anything for want of it yet.
    idle,
    /// Waiting for the reader to say yes or no.
    asking,
    /// Allowed. The UI tick has to get it signed.
    want_sign,
    /// A signer has the request.
    signing,
    /// `event` holds the signed reply, for the reader thread to send.
    signed,
    /// On the wire, waiting for the relay's OK.
    sent,
    /// The reader said no, now or earlier.
    declined,
    /// There is no key to identify with: a guest.
    no_key,
    /// The signer failed, or the relay refused the reply.
    failed,
    /// The relay accepted it.
    done,
};

const AuthSlot = struct {
    phase: AuthPhase = .idle,
    /// The relay has refused something for want of AUTH. This is what turns a
    /// held challenge into a question for the reader: a relay that merely greets
    /// with a challenge is never asked about and never answered.
    gated: bool = false,
    deadline_s: i64 = 0,
    /// The account the signer was asked to sign as.
    signing_as: [32]u8 = [_]u8{0} ** 32,
    challenge_len: u16 = 0,
    challenge: [auth_challenge_cap]u8 = [_]u8{0} ** auth_challenge_cap,
    event_len: u16 = 0,
    event: [auth_event_cap]u8 = [_]u8{0} ** auth_event_cap,
};

var g_auth_lock = std.atomic.Value(bool).init(false);
var g_auth_choices: [max_auth_choices]AuthChoiceEntry = @splat(.{});
var g_auth_slots: [max_relays]AuthSlot = @splat(.{});

fn authLock() void {
    while (g_auth_lock.cmpxchgWeak(false, true, .acquire, .monotonic) != null) std.atomic.spinLoopHint();
}
fn authUnlock() void {
    g_auth_lock.store(false, .release);
}

fn authChoiceLocked(account: [32]u8, url: []const u8) AuthChoice {
    for (&g_auth_choices) |*e| {
        if (!e.used or !std.mem.eql(u8, &e.account, &account)) continue;
        if (relayUrlEql(e.url(), url)) return if (e.allow) .allow else .deny;
    }
    return .ask;
}

/// What `account` has said about `url`, or `.ask` when it has not.
fn authChoiceOf(account: [32]u8, url: []const u8) AuthChoice {
    authLock();
    defer authUnlock();
    return authChoiceLocked(account, url);
}

/// What the signed-in reader has said about `url`. `.ask` for a guest, who has
/// nothing to say yes with.
pub fn authChoiceFor(url: []const u8) AuthChoice {
    const me = activePubkey() orelse return .ask;
    return authChoiceOf(me, url);
}

/// Records `account`'s choice for `url`. `.ask` forgets it. False when there is
/// no room, in which case nothing was recorded and the next challenge asks
/// again, which is the safe way to fail.
fn setAuthChoice(account: [32]u8, url: []const u8, choice: AuthChoice) bool {
    const trimmed = std.mem.trimEnd(u8, url, "/");
    if (trimmed.len == 0 or trimmed.len > 96) return false;
    authLock();
    defer authUnlock();
    for (&g_auth_choices) |*e| {
        if (!e.used or !std.mem.eql(u8, &e.account, &account)) continue;
        if (!relayUrlEql(e.url(), trimmed)) continue;
        if (choice == .ask) e.* = .{} else e.allow = choice == .allow;
        return true;
    }
    if (choice == .ask) return true;
    for (&g_auth_choices) |*e| {
        if (e.used) continue;
        e.* = .{ .used = true, .allow = choice == .allow, .account = account, .url_len = @intCast(trimmed.len) };
        @memcpy(e.url_buf[0..trimmed.len], trimmed);
        return true;
    }
    return false;
}

/// Reads the file's TEXT into the table. Split from the io so the format has a
/// test, the same as the relay list's.
fn applyAuthChoicesFile(raw: []const u8) void {
    var lines = std.mem.tokenizeAny(u8, raw, "\r\n");
    while (lines.next()) |line| {
        const trimmed = std.mem.trim(u8, line, " \t");
        if (trimmed.len == 0 or trimmed[0] == '#') continue;
        var parts = std.mem.tokenizeScalar(u8, trimmed, ' ');
        const word = parts.next() orelse continue;
        // A line with no account on it (`allow <url>`, the shape before answers
        // were per account) says nothing about whom it was said for, so it is
        // skipped and that relay is asked about again.
        const hex = parts.next() orelse continue;
        const url = parts.next() orelse continue;
        if (parts.next() != null) continue;
        if (hex.len != 64) continue;
        var account: [32]u8 = undefined;
        _ = std.fmt.hexToBytes(&account, hex) catch continue;
        // Only an address this app would dial. A hand-edited line naming
        // anything else is not a decision about a relay.
        if (!isRelayUrl(url)) continue;
        if (std.mem.eql(u8, word, "allow")) {
            _ = setAuthChoice(account, url, .allow);
        } else if (std.mem.eql(u8, word, "deny")) {
            _ = setAuthChoice(account, url, .deny);
        }
    }
}

fn formatAuthChoicesFile(buf: []u8) ?[]const u8 {
    var w = std.Io.Writer.fixed(buf);
    authLock();
    defer authUnlock();
    for (&g_auth_choices) |*e| {
        if (!e.used) continue;
        var hex: [64]u8 = undefined;
        hexLower(&hex, e.account);
        w.print("{s} {s} {s}\n", .{ if (e.allow) "allow" else "deny", hex[0..], e.url() }) catch return null;
    }
    return w.buffered();
}

fn loadAuthChoices(io: std.Io, environ: *const std.process.Environ.Map) void {
    var dir = plazaDir(io, environ) catch return;
    defer dir.close(io);
    var buf: [auth_choices_file_cap]u8 = undefined;
    const raw = dir.readFile(io, auth_choices_file, &buf) catch return;
    applyAuthChoicesFile(raw);
}

fn saveAuthChoices() void {
    const io = g_io orelse return;
    const environ = g_environ orelse return;
    var dir = plazaDir(io, environ) catch return;
    defer dir.close(io);
    var buf: [auth_choices_file_cap]u8 = undefined;
    const text = formatAuthChoicesFile(&buf) orelse return;
    dir.writeFile(io, .{
        .sub_path = auth_choices_tmp,
        .data = text,
        .flags = .{ .permissions = secret_file_permissions },
    }) catch return;
    dir.rename(auth_choices_tmp, dir, auth_choices_file, io) catch {};
}

/// What to do about a challenge, given who the reader is and what they said.
/// Called with the lock held; `account` is read before it is taken.
fn authDecideLocked(account: ?[32]u8, url: []const u8) AuthPhase {
    const me = account orelse return .no_key;
    return switch (authChoiceLocked(me, url)) {
        .allow => .want_sign,
        .deny => .declined,
        .ask => .asking,
    };
}

/// A fresh connection on `index`, or one that has just ended: nothing from the
/// last one applies to the next.
fn authSlotReset(index: usize) void {
    if (index >= max_relays) return;
    authLock();
    defer authUnlock();
    g_auth_slots[index] = .{};
}

/// The relay on `index` sent a challenge. It is kept as the latest one and
/// nothing else happens, unless the relay has already refused something for want
/// of it, in which case this is the challenge that was being waited for.
/// Returns where that leaves the slot.
fn authSlotChallenge(index: usize, url: []const u8, challenge: []const u8) AuthPhase {
    if (index >= max_relays) return .idle;
    const me = activePubkey();
    authLock();
    defer authUnlock();
    const s = &g_auth_slots[index];
    s.event_len = 0;
    if (challenge.len == 0 or challenge.len > auth_challenge_cap) {
        s.challenge_len = 0;
        if (s.gated) s.phase = .failed;
        return s.phase;
    }
    @memcpy(s.challenge[0..challenge.len], challenge);
    s.challenge_len = @intCast(challenge.len);
    s.phase = if (s.gated) authDecideLocked(me, url) else .idle;
    return s.phase;
}

/// Looks again at a challenge that is waiting on something the reader can
/// change: signing in, switching account, or answering from the relay's row.
///
/// `pressed` is true when the reader has just answered. Only then does a failed
/// exchange get another go: a signer that timed out while a person was away
/// otherwise left the relay refusing for the life of the socket. Never on the
/// reader thread's own wake, or a signer that keeps refusing would be asked
/// again every thirty seconds.
fn authSlotReevaluate(index: usize, url: []const u8, pressed: bool) void {
    if (index >= max_relays) return;
    const me = activePubkey();
    authLock();
    defer authUnlock();
    const s = &g_auth_slots[index];
    if (s.challenge_len == 0) return;
    switch (s.phase) {
        // `want_sign` is in the list so that changing the badge from identify to
        // anonymous before the tick has asked for a signature takes effect. Once
        // a signer has the request it is too late to recall, and the send checks
        // the choice again.
        .asking, .declined, .no_key, .want_sign => s.phase = authDecideLocked(me, url),
        .failed => if (pressed) {
            s.phase = authDecideLocked(me, url);
        },
        else => {},
    }
}

/// A composed reply that may not go out after all: the reader said no while it
/// was on its way, or is now a different account than the one it names. The
/// slot is decided again for whoever is signed in now, so a yes from the new
/// account gets its own signature and a no sends nothing.
fn authSlotDiscardSigned(index: usize, url: []const u8) void {
    if (index >= max_relays) return;
    const me = activePubkey();
    authLock();
    defer authUnlock();
    const s = &g_auth_slots[index];
    s.event_len = 0;
    s.phase = authDecideLocked(me, url);
}

/// The relay on `index` refused something for want of AUTH. This is the moment
/// the reader's choice is consulted, with the challenge the relay last sent. With
/// none held yet the slot waits for one.
fn authSlotGate(index: usize, url: []const u8) void {
    if (index >= max_relays) return;
    const me = activePubkey();
    authLock();
    defer authUnlock();
    const s = &g_auth_slots[index];
    s.gated = true;
    if (s.challenge_len != 0 and s.phase == .idle) s.phase = authDecideLocked(me, url);
}

fn authSlotPhase(index: usize) AuthPhase {
    if (index >= max_relays) return .idle;
    authLock();
    defer authUnlock();
    return g_auth_slots[index].phase;
}

fn authSlotGated(index: usize) bool {
    if (index >= max_relays) return false;
    authLock();
    defer authUnlock();
    return g_auth_slots[index].gated;
}

const AuthAsking = struct {
    /// The first relay waiting on the reader's answer, the one the notice names.
    first: usize,
    /// How many are waiting, that one included.
    count: usize,
};

/// Who is waiting on the reader, in ONE pass under the lock. The notice needs
/// both halves, and taking them in two passes let a reader thread clear the
/// slot in between: a first relay and a count of zero, and `count - 1` below
/// zero.
fn authAskingSummary() ?AuthAsking {
    authLock();
    defer authUnlock();
    var out: ?AuthAsking = null;
    for (&g_auth_slots, 0..) |*s, i| {
        // A relay that has left the list cannot be asked about, and must not
        // stand in front of one that still can.
        if (s.phase != .asking or relayAt(i) == null) continue;
        if (out) |*o| o.count += 1 else out = .{ .first = i, .count = 1 };
    }
    return out;
}

/// The first relay waiting on the reader's answer, for the notice.
pub fn authAsking() ?usize {
    const a = authAskingSummary() orelse return null;
    return a.first;
}

/// How many relays are waiting on the reader, so the notice can say there are
/// more behind the one it names.
pub fn authAskingCount() usize {
    const a = authAskingSummary() orelse return 0;
    return a.count;
}

/// Claims an allowed challenge for signing. Returns its length, with the bytes
/// in `out`, or null when this slot has nothing to sign.
///
/// Decided again here, for the account signed in at this moment. `want_sign`
/// was decided for whoever was signed in when the challenge came or when the
/// reader thread last woke, and a switch of account in between must not turn
/// one account's yes into a signature from another.
fn authBeginSigning(index: usize, url: []const u8, out: *[auth_challenge_cap]u8) ?usize {
    if (index >= max_relays) return null;
    const me = activePubkey();
    authLock();
    defer authUnlock();
    const s = &g_auth_slots[index];
    if (s.phase != .want_sign) return null;
    s.phase = authDecideLocked(me, url);
    if (s.phase != .want_sign) return null;
    const n: usize = s.challenge_len;
    @memcpy(out[0..n], s.challenge[0..n]);
    s.signing_as = me.?;
    s.phase = .signing;
    s.deadline_s = nowSeconds() + auth_sign_timeout_s;
    return n;
}

/// A signature that did not come: the signer refused, timed out, or answered
/// with something unusable. Only moves a slot that is actually waiting on one.
fn authFailSigning(index: usize) void {
    if (index >= max_relays) return;
    authLock();
    defer authUnlock();
    const s = &g_auth_slots[index];
    if (s.phase == .signing) s.phase = .failed;
}

/// Retires signatures that have been out too long.
fn authSweep(now_s: i64) void {
    authLock();
    defer authUnlock();
    for (&g_auth_slots) |*s| {
        if (s.phase == .signing and now_s >= s.deadline_s) s.phase = .failed;
    }
}

/// A signed event has come back for `index`. It is checked against the slot
/// before it can be sent: it must be a kind:22242 signed by the account that is
/// signed in, naming this relay by the address it was dialed at and echoing the
/// challenge it is currently holding. A signer is a separate program, and what
/// it returns is data.
fn authDeliverSigned(gpa: std.mem.Allocator, signer: nostr.keys.Signer, index: usize, ev: nostr.event.Event) void {
    if (index >= max_relays) return;
    var url_buf: [96]u8 = undefined;
    const entry = relaySnapshot(index, &url_buf) orelse {
        authFailSigning(index);
        return;
    };
    const mine = activePubkey();
    var relay_tag: ?[]const u8 = null;
    var challenge_tag: ?[]const u8 = null;
    for (ev.tags) |tag| {
        if (tag.len < 2) continue;
        if (relay_tag == null and std.mem.eql(u8, tag[0], "relay")) relay_tag = tag[1];
        if (challenge_tag == null and std.mem.eql(u8, tag[0], "challenge")) challenge_tag = tag[1];
    }
    var sound = ev.kind == nostr.nip42.kind and ev.content.len == 0;
    sound = sound and mine != null and std.mem.eql(u8, &ev.pubkey, &mine.?);
    sound = sound and relay_tag != null and std.mem.eql(u8, relay_tag.?, entry.url) and challenge_tag != null;
    if (sound) sound = nostr.event.verify(gpa, signer, ev) catch false;
    const json: ?[]u8 = if (sound) (nostr.event.toJson(gpa, ev) catch null) else null;
    defer if (json) |j| gpa.free(j);

    authLock();
    defer authUnlock();
    const s = &g_auth_slots[index];
    // Superseded: the connection ended or the slot moved on while this was out.
    if (s.phase != .signing) return;
    // The reader signed out, or in as someone else, while this was out. It
    // answers for an account that is not here, so it is dropped, and the
    // challenge is decided again for whoever is: their own yes is signed by
    // them, and with no yes the notice asks. Failing it instead left the relay
    // refusing the new account for the life of the socket.
    const still_same = mine != null and std.mem.eql(u8, &mine.?, &s.signing_as);
    if (!still_same) {
        s.phase = authDecideLocked(mine, entry.url);
        return;
    }
    const j = json orelse {
        s.phase = .failed;
        return;
    };
    if (j.len > auth_event_cap) {
        s.phase = .failed;
        return;
    }
    // The relay sent a newer challenge while the signer worked. This signature
    // answers the old one, so it is thrown away and the new one is signed.
    if (!std.mem.eql(u8, challenge_tag.?, s.challenge[0..s.challenge_len])) {
        s.phase = .want_sign;
        return;
    }
    @memcpy(s.event[0..j.len], j);
    s.event_len = @intCast(j.len);
    s.phase = .signed;
}

/// Takes the signed reply, for the reader thread to send.
fn authTakeSigned(index: usize, out: *[auth_event_cap]u8) ?usize {
    if (index >= max_relays) return null;
    authLock();
    defer authUnlock();
    const s = &g_auth_slots[index];
    if (s.phase != .signed) return null;
    const n: usize = s.event_len;
    @memcpy(out[0..n], s.event[0..n]);
    s.phase = .sent;
    return n;
}

/// The relay's OK for our reply.
fn authOutcome(index: usize, accepted: bool) void {
    if (index >= max_relays) return;
    authLock();
    defer authUnlock();
    const s = &g_auth_slots[index];
    if (s.phase == .sent) s.phase = if (accepted) .done else .failed;
}

/// Which subscriptions a relay refused for want of AUTH, so they can be asked
/// again once it has been given.
const OwedSubs = struct {
    feed: bool = false,
    inbox: bool = false,
    engagement: bool = false,

    fn mark(self: *OwedSubs, sub_id: []const u8) void {
        // The feed under any generation of its id: it is re-issued as
        // `plaza-feed-<n>` whenever its question changes, sign-in included.
        if (isFeedSub(sub_id)) {
            self.feed = true;
        } else if (std.mem.eql(u8, sub_id, "plaza-inbox")) {
            self.inbox = true;
        } else if (std.mem.eql(u8, sub_id, "plaza-engagement")) {
            self.engagement = true;
        }
    }

    pub fn any(self: OwedSubs) bool {
        return self.feed or self.inbox or self.engagement;
    }
};

/// One connection's side of the exchange. Lives on the reader thread's stack.
const AuthSession = struct {
    index: usize,
    owed: OwedSubs = .{},
    /// The id of the reply we sent and are waiting on an OK for.
    sent_id: ?[32]u8 = null,
    /// A challenge arrived on this connection.
    challenged: bool = false,
    /// The relay accepted our reply. After this an `auth-required:` is final:
    /// identifying again would not change the answer, and asking would loop.
    authed: bool = false,
    /// When the first auth-required CLOSED arrived, in the awake clock.
    gated_at_ms: i64 = 0,
    /// Whose connection it was when the reply went out. See `AuthPoll.redial`.
    sent_gen: u32 = 0,
};

const AuthReaction = struct {
    /// The message was about authentication and the caller is done with it.
    handled: bool = false,
    /// Subscriptions to ask again, because the relay has accepted us.
    resend: OwedSubs = .{},
};

fn isAuthRequired(reason: []const u8) bool {
    // NIP-01's machine-readable prefix, matched the way both reference clients
    // match it: by the start of the reason, nothing after the colon.
    return std.mem.startsWith(u8, reason, "auth-required");
}

/// What a relay's message means for authentication. Everything else comes back
/// unhandled and goes on to the loop's own switch.
fn authReact(sess: *AuthSession, url: []const u8, msg: nostr.message.RelayMessage, now_ms: i64) AuthReaction {
    switch (msg) {
        .auth => |a| {
            // A new challenge starts the exchange over. Nothing sent for an
            // earlier one counts for this one.
            sess.sent_id = null;
            sess.authed = false;
            sess.challenged = true;
            sess.gated_at_ms = 0;
            const phase = authSlotChallenge(sess.index, url, a.challenge);
            if (phase == .failed) std.debug.print("plaza: [{s}] sent a challenge that cannot be answered\n", .{url});
            return .{ .handled = true };
        },
        .closed => |c| {
            if (!isAuthRequired(c.message)) return .{};
            if (sess.authed) return .{};
            authGated(sess, url, now_ms);
            sess.owed.mark(c.subscription_id);
            return .{ .handled = true };
        },
        .ok => |o| {
            const sent = sess.sent_id orelse return authRefusedEvent(sess, url, o, now_ms);
            if (!std.mem.eql(u8, &o.event_id, &sent)) return authRefusedEvent(sess, url, o, now_ms);
            sess.sent_id = null;
            authOutcome(sess.index, o.accepted);
            if (!o.accepted) {
                std.debug.print("plaza: [{s}] refused our NIP-42 reply: {s}\n", .{ url, o.message });
                return .{ .handled = true };
            }
            sess.authed = true;
            const owed = sess.owed;
            sess.owed = .{};
            return .{ .handled = true, .resend = owed };
        },
        else => return .{},
    }
}

/// The relay has refused something for want of AUTH: this is what makes it a
/// question for the reader.
fn authGated(sess: *AuthSession, url: []const u8, now_ms: i64) void {
    authSlotGate(sess.index, url);
    if (sess.gated_at_ms == 0) sess.gated_at_ms = now_ms;
}

/// An OK that said no to an event with an `auth-required:` reason. The same
/// refusal as a CLOSED for a REQ. Nothing is owed back to the relay for it: the
/// reader thread sends no events of its own, so there is nothing to re-send, but
/// the relay has still said it wants to know who the reader is.
fn authRefusedEvent(sess: *AuthSession, url: []const u8, o: anytype, now_ms: i64) AuthReaction {
    if (o.accepted or !isAuthRequired(o.message) or sess.authed) return .{};
    authGated(sess, url, now_ms);
    return .{ .handled = true };
}

const AuthPoll = enum {
    quiet,
    /// Drop this connection and dial again. Either the relay refused a
    /// subscription for want of a challenge it never sent, or the reader is no
    /// longer the person this socket was identified as.
    redial,
};

/// The reader's half of the exchange that is not a reaction to a message: send
/// a signature that has arrived, and notice that the reader changed their mind
/// or signed in. Called once a wake, so a quiet relay is served as well.
fn authPoll(sess: *AuthSession, url: []const u8, relay: anytype, now_ms: i64, identity_gen: u32) AuthPoll {
    // A relay remembers who a socket was identified as for as long as the socket
    // lives. Signing out, or in as someone else, does not change that, so the
    // only way to stop being known to the relay as the previous account is to
    // leave the connection.
    if (sess.authed and identity_gen != sess.sent_gen) return .redial;
    authSlotReevaluate(sess.index, url, false);
    var buf: [auth_event_cap]u8 = undefined;
    if (authTakeSigned(sess.index, &buf)) |n| {
        const gpa = std.heap.page_allocator;
        if (nostr.event.fromJson(gpa, buf[0..n])) |parsed_const| {
            var parsed = parsed_const;
            defer parsed.deinit();
            // Checked again here, at the last moment before it leaves: the
            // reader can press "anonymous" while a bunker is still waiting for a
            // person, or switch account, and a reply signed as the previous one
            // would identify this socket as somebody who is no longer here.
            // Only a yes from the account the reply names lets it go.
            const me = activePubkey();
            const still_mine = me != null and std.mem.eql(u8, &me.?, &parsed.value.pubkey);
            if (!still_mine or authChoiceOf(parsed.value.pubkey, url) != .allow) {
                authSlotDiscardSigned(sess.index, url);
                return .quiet;
            }
            if (relay.authenticate(parsed.value)) |_| {
                sess.sent_id = parsed.value.id;
                sess.sent_gen = identity_gen;
            } else |_| {
                authOutcome(sess.index, false);
            }
        } else |_| {
            authOutcome(sess.index, false);
        }
    }
    if (sess.gated_at_ms != 0 and !sess.challenged and now_ms - sess.gated_at_ms > auth_gate_wait_ms) return .redial;
    return .quiet;
}

// The UI half. Everything below runs on the UI thread, which is the only one
// that may reach a signer.

/// One signature at a time through Notary's door, as with a note. A bunker has
/// a table of its own.
var g_helper_auth_active = false;
var g_helper_auth_index: usize = 0;
const helper_auth_key: u64 = 45;

fn authSignerReady() bool {
    return switch (g_signer_kind) {
        .helper => !g_helper_auth_active and (g_helper_port != 0 or builtin.is_test),
        .remote => true,
    };
}

/// Builds the unsigned kind:22242 for `url` and `challenge` and asks the active
/// signer for a signature. False when nothing could be asked.
fn requestAuthSign(fx: *Effects, index: usize, url: []const u8, challenge: []const u8) bool {
    const pk = activePubkey() orelse return false;
    var arena_state = std.heap.ArenaAllocator.init(std.heap.page_allocator);
    defer arena_state.deinit();
    const a = arena_state.allocator();
    const created = nowSeconds();
    const relay_tag = a.dupe([]const u8, &.{ "relay", url }) catch return false;
    const challenge_tag = a.dupe([]const u8, &.{ "challenge", challenge }) catch return false;
    const tags = a.dupe(nostr.event.Tag, &.{ relay_tag, challenge_tag }) catch return false;
    const id = nostr.event.computeId(a, pk, created, nostr.nip42.kind, tags, "") catch return false;
    const unsigned = nostr.event.Event{
        .id = id,
        .pubkey = pk,
        .created_at = created,
        .kind = nostr.nip42.kind,
        .tags = tags,
        .content = "",
        .sig = [_]u8{0} ** 64,
    };
    const unsigned_json = nostr.event.toJson(a, unsigned) catch return false;
    switch (g_signer_kind) {
        .helper => {
            const body = (nostr.signer_ipc.SignEvent{ .event = unsigned_json }).toJson(a) catch return false;
            g_helper_auth_active = true;
            g_helper_auth_index = index;
            // A test cannot drive the loopback, so a stand-in keyholder answers
            // the way the real one does and the response handler runs for real.
            if (builtin.is_test) {
                if (!g_test_signer_silent) answerHelperAuthForTest(a, unsigned_json);
                return true;
            }
            helperFetch(fx, helper_auth_key, "/sign", body, Effects.responseMsg(.helper_auth_signed));
            return true;
        },
        .remote => {
            var idbuf: [24]u8 = undefined;
            const req_id = newRequestId(&idbuf) orelse return false;
            // Tracked before it is sent: the answer can land on the listener
            // thread the instant the send does.
            if (!registerPending(req_id, .sign_auth, null, false, .none, @intCast(index), no_half_id, .{})) return false;
            const params = [_][]const u8{unsigned_json};
            sendRequest(std.heap.page_allocator, .{ .id = req_id, .method = "sign_event", .params = &params });
            return true;
        },
    }
}

fn answerHelperAuthForTest(a: std.mem.Allocator, unsigned_json: []const u8) void {
    const secret = feed_state.g_test_secret orelse return;
    var signer = nostr.keys.Signer.init();
    defer signer.deinit();
    const kp = signer.keyPairFromSecretKey(secret) catch return;
    var parsed = nostr.event.fromJson(a, unsigned_json) catch return;
    defer parsed.deinit();
    const ev = parsed.value;
    const signed = nostr.event.create(a, signer, kp, ev.created_at, ev.kind, ev.tags, ev.content, null) catch return;
    const signed_json = nostr.event.toJson(a, signed) catch return;
    const body = (nostr.signer_ipc.SignEvent{ .event = signed_json }).toJson(a) catch return;
    handleHelperAuthSigned(.{ .key = helper_auth_key, .outcome = .ok, .status = 200, .body = body });
}

fn handleHelperAuthSigned(response: native_sdk.EffectResponse) void {
    const index = g_helper_auth_index;
    g_helper_auth_active = false;
    if (response.outcome != .ok or response.status != 200) {
        authFailSigning(index);
        return;
    }
    const gpa = std.heap.page_allocator;
    var wrapped = nostr.signer_ipc.parse(nostr.signer_ipc.SignEvent, gpa, response.body) catch {
        authFailSigning(index);
        return;
    };
    defer wrapped.deinit();
    var parsed = nostr.event.fromJson(gpa, wrapped.value.event) catch {
        authFailSigning(index);
        return;
    };
    defer parsed.deinit();
    var verifier = nostr.keys.Signer.init();
    defer verifier.deinit();
    authDeliverSigned(gpa, verifier, index, parsed.value);
}

/// The tick's share: retire stale signatures, and get the allowed challenges
/// signed.
fn driveRelayAuth(fx: *Effects) void {
    authSweep(nowSeconds());
    for (0..max_relays) |i| {
        if (authSlotPhase(i) != .want_sign) continue;
        if (!authSignerReady()) return;
        var url_buf: [96]u8 = undefined;
        const entry = relaySnapshot(i, &url_buf) orelse {
            authSlotReset(i);
            continue;
        };
        var challenge: [auth_challenge_cap]u8 = undefined;
        const n = authBeginSigning(i, entry.url, &challenge) orelse continue;
        if (!requestAuthSign(fx, i, entry.url, challenge[0..n])) {
            if (g_signer_kind == .helper) g_helper_auth_active = false;
            authFailSigning(i);
        }
    }
}

/// The reader's answer to the notice.
fn authAnswer(index: usize, allow: bool) void {
    const me = activePubkey() orelse return;
    var url_buf: [96]u8 = undefined;
    const entry = relaySnapshot(index, &url_buf) orelse return;
    _ = setAuthChoice(me, entry.url, if (allow) .allow else .deny);
    saveAuthChoices();
    authSlotReevaluate(index, entry.url, true);
}

/// The relay row's badge: ask first, then identify, then anonymous.
fn authCycle(index: usize) void {
    const me = activePubkey() orelse return;
    var url_buf: [96]u8 = undefined;
    const entry = relaySnapshot(index, &url_buf) orelse return;
    const next: AuthChoice = switch (authChoiceOf(me, entry.url)) {
        .ask => .allow,
        .allow => .deny,
        .deny => .ask,
    };
    _ = setAuthChoice(me, entry.url, next);
    saveAuthChoices();
    authSlotReevaluate(index, entry.url, true);
}

/// What the badge on a relay row says, or null when there is nothing to say
/// yet: no choice made and no refusal for want of AUTH. Null for a guest too, who has no
/// identity to give and so nothing for the badge to change.
fn authBadgeText(index: usize, url: []const u8) ?[]const u8 {
    if (activePubkey() == null) return null;
    const choice = authChoiceFor(url);
    if (choice == .ask and authSlotPhase(index) == .idle) return null;
    return switch (choice) {
        .ask => "ask first",
        .allow => "identify",
        .deny => "anonymous",
    };
}

/// Why a relay is not giving this reader what they asked for, in the row, when
/// the reason is authentication. Null for a relay that has not refused.
fn authRowNote(index: usize) ?[]const u8 {
    if (!authSlotGated(index)) return null;
    return switch (authSlotPhase(index)) {
        .asking => "Wants to know who you are. Waiting for your answer.",
        .want_sign, .signing, .signed, .sent => "Identifying you to it.",
        .declined => "Wants to know who you are. You chose not to tell it.",
        .no_key => "Wants to know who you are. Sign in to answer it.",
        .failed => "Wants to know who you are, and would not accept the answer.",
        .idle, .done => null,
    };
}

pub fn resetRelayAuthForTest() void {
    authLock();
    g_auth_choices = @splat(.{});
    g_auth_slots = @splat(.{});
    authUnlock();
    g_helper_auth_active = false;
    g_helper_auth_index = 0;
}

pub fn authChoiceForTest(url: []const u8) AuthChoice {
    return authChoiceFor(url);
}
pub fn authChoiceOfForTest(account: [32]u8, url: []const u8) AuthChoice {
    return authChoiceOf(account, url);
}
pub fn setAuthChoiceForTest(account: [32]u8, url: []const u8, choice: AuthChoice) bool {
    return setAuthChoice(account, url, choice);
}
pub fn authFileForTest(buf: []u8) ?[]const u8 {
    return formatAuthChoicesFile(buf);
}
pub fn applyAuthFileForTest(raw: []const u8) void {
    applyAuthChoicesFile(raw);
}
pub fn authPhaseNameForTest(index: usize) []const u8 {
    return @tagName(authSlotPhase(index));
}
pub fn authRowNoteForTest(index: usize) ?[]const u8 {
    return authRowNote(index);
}
pub fn authBadgeTextForTest(index: usize, url: []const u8) ?[]const u8 {
    return authBadgeText(index, url);
}
pub fn driveRelayAuthForTest(fx: *Effects) void {
    driveRelayAuth(fx);
}
pub fn authAnswerForTest(index: usize, allow: bool) void {
    authAnswer(index, allow);
}
pub fn authCycleForTest(index: usize) void {
    authCycle(index);
}
pub fn authSweepForTest(now_s: i64) void {
    authSweep(now_s);
}
pub fn authHelperBusyForTest() bool {
    return g_helper_auth_active;
}
/// The keyholder's answer to the request that was out has arrived and been
/// dropped, as `handleHelperAuthSigned` does, leaving it free for the next.
pub fn authHelperFreeForTest() void {
    g_helper_auth_active = false;
}
/// The connection on `index` has ended.
pub fn authSlotResetForTest(index: usize) void {
    authSlotReset(index);
}
pub fn authDeliverSignedForTest(index: usize, ev: nostr.event.Event) void {
    var verifier = nostr.keys.Signer.init();
    defer verifier.deinit();
    authDeliverSigned(std.heap.page_allocator, verifier, index, ev);
}

/// The reader thread's reaction, driven by a test with a stand-in relay.
pub const AuthSessionForTest = AuthSession;
pub const AuthReactionForTest = AuthReaction;
pub fn authReactForTest(sess: *AuthSession, url: []const u8, msg: nostr.message.RelayMessage, now_ms: i64) AuthReaction {
    return authReact(sess, url, msg, now_ms);
}
pub fn authPollForTest(sess: *AuthSession, url: []const u8, relay: anytype, now_ms: i64) []const u8 {
    return @tagName(authPoll(sess, url, relay, now_ms, identityGeneration()));
}
pub const auth_gate_wait_ms_for_test = auth_gate_wait_ms;

/// Dials relay `index`, subscribes for recent kind:1, and ingests each event
/// into the shared store until the connection closes.
fn ingestOnce(gpa: std.mem.Allocator, io: std.Io, signer: nostr.keys.Signer, index: usize) !void {
    // Read fresh each time round: the reader may have changed this slot's URL,
    // or emptied it, since the last dial.
    var url_buf: [96]u8 = undefined;
    const entry = relaySnapshot(index, &url_buf) orelse return error.RelayRemoved;
    const url = entry.url;
    const reads = entry.read;
    var relay = try nostr.relay.dial(gpa, io, url);
    // Withdrawn BEFORE the connection is freed, and the defers unwind in
    // reverse, so this one is declared second and runs first. The other order
    // hands the keeper a pointer to a `Relay` that is already gone.
    defer relay.deinit();
    offerLiveRelay(index, relay);
    defer offerLiveRelay(index, null);
    setRelayStatus(index, .connected);

    // NIP-42, for this connection. The slot is wiped on the way in and on the
    // way out: a challenge belongs to the socket that heard it, and a notice
    // left standing for a socket that is gone would be asking about nothing.
    var auth = AuthSession{ .index = index };
    authSlotReset(index);
    defer authSlotReset(index);

    // Follow-scoped: the starter pack's recent notes for the feed, plus their
    // kind:0 metadata (and the user's own) so the feed can show real names and
    // avatars. Two filters share one subscription.
    var authors: [max_follows + 1][32]u8 = undefined;
    // Snapshotted, not borrowed: `followSet` hands back a slice of a table the
    // UI thread rewrites when a follow lands, and this filter outlives the frame.
    // Not every follow: the ones who write HERE, plus everyone no relay in
    // either set is being asked about. See `fillPoolRoutes`.
    //
    // Before the routing existed this was the whole follow list on all eight
    // relays, which asked every relay about two thousand strangers and told
    // each of them the reader's entire social graph.
    var authors_len: usize = poolAuthorsOrAll(index, &authors);
    // The generation this subscription was built for. When it moves, this
    // connection is asking the wrong question and re-asks below.
    var subscribed_gen = followGeneration();
    // Set to the generation already served by `subscribeInbox` at dial below,
    // so the loop does not immediately re-issue what was just sent.
    var inbox_gen = identityGeneration();
    // WHO this subscription asked about, if anyone. A connection dialed while
    // signed out did not ask about the reader, and its EOSE is not an answer
    // about them. Read once, so the filter and the record of what it asked
    // cannot name two different accounts across a sign-in.
    var asked_about: ?[32]u8 = activePubkey();
    if (asked_about) |pk| {
        authors[authors_len] = pk;
        authors_len += 1;
    }
    // Two filters per chunk of authors, all in ONE REQ.
    //
    // `authors_len` INCLUDES the reader. An earlier version took the snapshot
    // BEFORE appending the reader's own key, so a note written anywhere but this
    // install was never fetched from any relay: the feed reads your own notes
    // from the store and the store never had them. Signing in with an existing
    // key showed a feed with none of your own writing in it, and every
    // notification about those notes pressed into nothing, because the note it
    // pointed at was not held.
    //
    // The chunking is a payload split and nothing more. A relay answers every
    // filter in a REQ, so five filters of five hundred authors ask the same
    // question as one filter of two and a half thousand, in an envelope relays
    // actually accept. The per-chunk limit stays whole for the same reason:
    // dividing it would starve whoever landed in the last chunk.
    var filter_buf: [max_feed_filters]nostr.filter.Filter = undefined;
    // The reader's key for their own filters, owned by this connection.
    var self_author: [1][32]u8 = undefined;
    if (asked_about) |pk| self_author[0] = pk;
    const filters = buildFeedFilters(authors[0..authors_len], if (asked_about != null) &self_author else null, feedSince(), &filter_buf);
    // What other people aimed at this reader. Its own subscription, never folded
    // into the feed's: a relay that is handed two differently-scoped filters in
    // one REQ may answer the stored query and then go quiet, which is the worst
    // failure mode to notice.
    if (reads) subscribeInbox(relay);

    // A relay marked write-only is not asked anything. It keeps its socket, so a
    // note goes out the moment it is written, but no filter of this reader's
    // ever reaches it: that is the whole difference the badge promises.
    // The feed's id carries the generation it was asked under. A REQ re-issued
    // under the SAME id cannot be told apart from the one it replaced, and the
    // one it replaced may still be answering: the subscription sent as a guest
    // at launch is usually still in flight when the account signs in, and its
    // end-of-stored-events would then be read as this relay having finished with
    // the reader's own lists before it had sent them. See `isFeedSub`.
    var feed_sub_buf: [32]u8 = undefined;
    var feed_sub: []const u8 = feed_sub_base;
    if (reads) try relay.subscribe(feed_sub, filters);

    // Latency is measured with a PROBE, never with the subscriptions above: the
    // feed REQ asks for a 300-note backlog plus profiles, so timing it measures
    // how much this relay had to send, not how fast it answers. The probe asks
    // for an id that cannot exist, so the answer is an empty EOSE and the number
    // is the round trip and nothing else. Re-sent periodically so it stays live,
    // and CLOSED as soon as it answers. The AWAKE clock, so a system clock step
    // cannot swing a reading.
    var probe_at: i64 = 0;
    var probed_at: i64 = 0;

    // The loaded notes' ids (and their hex), collected from the feed as it
    // arrives. On the feed's EOSE a second subscription opens for their
    // engagement, so counts fold in alongside the feed on the same connection,
    // and it is widened as more notes load.
    var feed_ids: [engagement_watch_cap]i64 = undefined;
    var feed_id_hex: [engagement_watch_cap][64]u8 = undefined;
    var feed_ids_len: usize = 0;
    // How many of those ids the engagement subscription currently names, and
    // when it was last (re)issued.
    var engagement_watching: usize = 0;
    var engagement_at: i64 = 0;
    var engagement_gen: u32 = 0;

    while (true) {
        // A pause takes effect within a wake: the thread returns, `defer
        // relay.deinit()` closes the socket, and the reconnect loop parks. The
        // chip still says "pausing" until every thread has actually left rather
        // than claiming a pause it has not achieved, because a thread mid-frame
        // finishes the frame first.
        if (relaysPaused()) return;
        // The same for an edit. Removing a relay, or clearing its read marker,
        // must end THIS connection: leaving the socket up until the next
        // reconnect would keep a relay the reader dropped feeding the store, and
        // keep a relay they set write-only answering their filters. Checked
        // against the address dialed, so a slot that changed hands also drops.
        var now_buf: [96]u8 = undefined;
        const now_entry = relaySnapshot(index, &now_buf) orelse return;
        if (!relayUrlEql(now_entry.url, url)) return;
        if (now_entry.read != reads) return;
        // Following someone changes what this connection should be asking for.
        // NIP-01 makes a REQ under an existing id a replacement, so the same
        // subscription is simply re-issued: without this a follow shows nothing
        // new until the socket happens to drop, which reads as a broken button.
        // A follow OR an identity change: `forgetFollows` bumps the same
        // counter on sign-out and sign-in, because a connection built for a
        // guest never asks for the account's own records and would otherwise
        // leave following disabled for the whole session.
        if (reads and followGeneration() != subscribed_gen) {
            subscribed_gen = followGeneration();
            authors_len = poolAuthorsOrAll(index, &authors);
            var next_authors_len = authors_len;
            const next_self = activePubkey();
            asked_about = null;
            if (next_self) |pk| {
                if (next_authors_len < authors.len) {
                    authors[next_authors_len] = pk;
                    next_authors_len += 1;
                    asked_about = pk;
                }
            }
            // Built by the SAME function the dial-time subscription uses.
            //
            // This path used to hand-roll its own pair of filters, and both of
            // the things `buildFeedFilters` exists to prevent came back with it:
            // every author named in ONE filter, which is past the size several
            // relays accept once a real follow list is loaded, and a metadata
            // limit taken from `profile_cap`, which is the size of a screen
            // cache and has nothing to do with how many records to ask for.
            //
            // It mattered more here than anywhere, because this is the path
            // every reader takes: Plaza dials before anyone has signed in, so
            // the subscription that carries the actual account is always the
            // re-issued one, never the one built at dial.
            if (next_self) |pk| self_author[0] = pk;
            const next_filters = buildFeedFilters(authors[0..next_authors_len], if (next_self != null) &self_author else null, feedSince(), &filter_buf);
            // Closed and asked again under a new id, rather than replaced in
            // place, so the old question's answers stay its own.
            relay.unsubscribe(feed_sub) catch {};
            feed_sub = std.fmt.bufPrint(&feed_sub_buf, feed_sub_base ++ "-{d}", .{subscribed_gen}) catch feed_sub_base;
            relay.subscribe(feed_sub, next_filters) catch {};
            // The inbox rides the SAME signal, and for a reason the feed's own
            // comment above already explains: this counter moves on sign-in.
            // Asking only at dial was the whole feature's undoing, because Plaza
            // opens as a guest and dials every relay BEFORE anyone has signed in.
            // The bell then read zero for the entire session, on a healthy
            // connection, no matter who replied. Re-issuing here is also what
            // heals a REQ that failed to send, and what stops a socket carrying
            // the previous account's filter after a switch.
        }
        // The inbox rides its own generation: its filter names ONE pubkey, the
        // reader's, so a contact-list change has nothing to do with it.
        if (reads and identityGeneration() != inbox_gen) {
            inbox_gen = identityGeneration();
            subscribeInbox(relay);
        }
        // A signature that has come back is sent from here and nowhere else:
        // this thread owns the socket's conversation, and the UI thread that got
        // the signature never touches it. A relay set write-only is not asked
        // anything, so it has nothing an identity would unlock.
        if (reads) {
            const awake_ms = std.Io.Timestamp.now(io, .awake).toMilliseconds();
            if (authPoll(&auth, url, relay, awake_ms, identityGeneration()) == .redial) return error.FeedSubscriptionClosed;
        }
        // With a deadline, so the checks above actually run on a quiet relay.
        //
        // Without one this loop only advances when the relay speaks, so a relay
        // the reader removed, repointed or set write-only kept its socket and
        // kept feeding the store until it happened to say something. A relay
        // that says nothing for an hour held one for an hour. `nostr#64`.
        //
        // A timeout consumes nothing, so `continue` here resumes on the same
        // connection rather than resynchronising: the wait is a readiness check
        // on the socket, not a read. Cutting the socket to achieve the same
        // thing would not do: `shutdown` over TLS poisons the session, and this
        // one is also carrying the inbox and engagement subscriptions.
        var msg = (relay.receiveTimeout(ingest_wake) catch |err| switch (err) {
            error.Timeout => continue,
            else => |e| return e,
        }) orelse break;
        defer msg.deinit();

        // Time to re-probe? The probe rides the next message rather than a
        // timer; a relay too quiet to carry one is also a relay whose latency
        // nobody is waiting on.
        //
        // A write-only relay is probed too: a question about one id that does
        // not exist, which says nothing about who this reader follows or reads,
        // and its answer is the latency shown beside a relay they do use.
        const now_ms = std.Io.Timestamp.now(io, .awake).toMilliseconds();
        // A challenge, a refusal for want of one, or the verdict on our reply.
        // None of these is the end of a subscription: a CLOSED for auth is the
        // relay saying "not yet", and the feed it refused is asked again once
        // the relay has accepted us. Without this arm the refused feed ended the
        // connection and the reconnect ladder went round again, forever, without
        // ever answering the challenge that was the reason.
        if (reads) {
            const react = authReact(&auth, url, msg.value, now_ms);
            if (react.handled) {
                switch (msg.value) {
                    .closed => |c| {
                        std.debug.print("plaza: [{s}] closed {s}: {s}\n", .{ url, c.subscription_id, c.message });
                        if (std.mem.eql(u8, c.subscription_id, probe_sub)) probe_at = 0;
                    },
                    else => {},
                }
                // Moving the generation is how this loop already re-asks a
                // subscription, so the refused ones are re-sent by the same
                // code that built them rather than by a copy of it.
                if (react.resend.feed) subscribed_gen -%= 1;
                if (react.resend.inbox) inbox_gen -%= 1;
                if (react.resend.engagement) {
                    engagement_watching = 0;
                    engagement_at = 0;
                }
                continue;
            }
        }
        if (probe_at == 0 and (probed_at == 0 or now_ms - probed_at > probe_interval_ms)) {
            const probe_filters = probeFilters();
            if (relay.subscribe(probe_sub, &probe_filters)) |_| {
                probe_at = now_ms;
                probed_at = now_ms;
            } else |_| {}
        }
        // Widen the engagement subscription as more of the feed loads. It used
        // to be opened once per connection over whatever had arrived by the
        // feed's EOSE and never touched again, so every note past that point
        // read zero likes, zero replies and zero zaps for the whole session, and
        // so did every note that arrived live.
        //
        // And it asked only about arrivals, which left every note the view read
        // out of the store unwatched. That is most of the feed on any launch but
        // the first. Both sources are folded in here now, and the "already
        // watching" guard is gone with them: a connection whose first EOSE found
        // nothing had no way back to watching anything for the rest of its life.
        const watch_gen = feedWatchGeneration();
        if (now_ms - engagement_at > engagement_widen_ms and
            (watch_gen != engagement_gen or feed_ids_len > engagement_watching))
        {
            feed_ids_len = mergeFeedWatch(&feed_ids, &feed_id_hex, feed_ids_len);
            engagement_gen = watch_gen;
            if (feed_ids_len > 0) {
                subscribeEngagement(relay, &feed_id_hex, feed_ids_len);
                engagement_watching = feed_ids_len;
                engagement_at = now_ms;
            }
        }
        switch (msg.value) {
            .event => |e| {
                if (std.mem.eql(u8, e.subscription_id, "plaza-inbox")) {
                    // Verified before it counts: a relay can send anything down
                    // any subscription, and an inbox is the one surface where a
                    // stranger chooses what the reader sees.
                    const result = plazaIngestFrom(gpa, e.event, .{ .verify_with = signer }, url) catch continue;
                    if (result == .invalid) continue;
                    if (inboxAdd(e.event, nowSeconds())) markInboxDirty();
                    continue;
                }
                if (isFeedSub(e.subscription_id)) {
                    // Verify (secp256k1) before storing; silently drop a bad event.
                    // `.invalid` is a RETURNED VALUE here, not an error: a
                    // forged event does not throw, it comes back saying it did
                    // not verify. Reading only the error channel let a relay
                    // hand this reader a relay list signed by nobody.
                    const result = plazaIngestFrom(gpa, e.event, .{ .verify_with = signer }, url) catch continue;
                    if (result == .invalid) continue;
                    // Note which relay carried it, so a thread can say how widely
                    // a note is held rather than guess.
                    if (e.event.kind == 1) {
                        markRelaySeen(noteIdOf(e.event), index);
                        // What the next subscription will start from.
                        noteFeedNewest(e.event.created_at);
                    }
                    if (e.event.kind == relay_list_kind) ingestRelayList(e.event);
                    if (e.event.kind == contact_list_kind) ingestContactList(e.event);
                    // Note this feed post so its engagement can be watched. Bounded
                    // to keep the `#e` filter a size relays accept.
                    if (e.event.kind == 1) rememberFeedId(&feed_ids, &feed_id_hex, &feed_ids_len, e.event);
                } else if (isOneShotSub(e.subscription_id)) {
                    // Somebody else's question, answered on this socket. It goes
                    // to the store like everything else and nothing is routed
                    // back, which is exactly why the socket can be shared: there
                    // is no caller waiting on a reply.
                    //
                    // This branch has to exist before anything uses `askPool`.
                    // Without it a one-shot's events fall into the engagement
                    // arm below and every profile fetched gets counted as
                    // somebody reacting to a note.
                    const result = plazaIngestFrom(gpa, e.event, .{ .verify_with = signer }, url) catch continue;
                    if (result == .invalid) continue;
                    if (e.event.kind == 1) noteFeedNewest(e.event.created_at);
                } else {
                    // The engagement subscription: fold into the counts, verified
                    // so a forged reaction cannot inflate a tally.
                    if (nostr.event.verify(gpa, signer, e.event) catch false) countEngagement(e.event, feed_ids[0..feed_ids_len]);
                }
            },
            .eose => |eo| {
                if (std.mem.eql(u8, eo.subscription_id, probe_sub) and probe_at != 0) {
                    const elapsed = std.Io.Timestamp.now(io, .awake).toMilliseconds() - probe_at;
                    if (elapsed >= 0) recordRelayRtt(index, @intCast(@min(elapsed, std.math.maxInt(u16))));
                    probe_at = 0;
                    // Answered, so close it. A REQ stays live past EOSE, and the
                    // question has been answered: leaving it open is how the
                    // probe became a standing subscription on every relay.
                    relay.unsubscribe(probe_sub) catch {};
                }
                // A one-shot has been answered. Close it: a REQ stays live past
                // EOSE, and leaving them open is how the latency probe became a
                // standing subscription on every relay in the pool.
                //
                // Closed HERE, on the thread that owns the socket, and never
                // before EOSE: relays dislike a CLOSE for a subscription they
                // are still answering, which NDK's source says in as many words.
                if (isOneShotSub(eo.subscription_id)) relay.unsubscribe(eo.subscription_id) catch {};
                if (isFeedSub(eo.subscription_id)) {
                    // Only when THIS subscription actually asked about the
                    // reader. A guest-era filter names nine strangers, and its
                    // EOSE says nothing at all about the account that signed in
                    // afterwards. Nor is the EOSE of a generation this one
                    // replaced, and nor is an answer about an account that is
                    // no longer the one signed in: the identity can change
                    // between the check at the top of this loop and here.
                    if (asked_about) |asked| {
                        if (activePubkey()) |me| {
                            // Who they follow, recorded against THIS relay.
                            // EOSE means "that is all I have", never "you have
                            // none": one relay that does not carry this list
                            // must not be able to authorize replacing it.
                            if (std.mem.eql(u8, &asked, &me) and std.mem.eql(u8, eo.subscription_id, feed_sub)) {
                                noteContactsAnsweredBy(index, url, me);
                            }
                        }
                    }
                }
                // Stored feed drained: now watch those notes' engagement, plus
                // whatever the view is drawing out of the store.
                if (engagement_watching == 0 and isFeedSub(eo.subscription_id)) {
                    feed_ids_len = mergeFeedWatch(&feed_ids, &feed_id_hex, feed_ids_len);
                    engagement_gen = feedWatchGeneration();
                    if (feed_ids_len > 0) {
                        subscribeEngagement(relay, &feed_id_hex, feed_ids_len);
                        engagement_watching = feed_ids_len;
                        engagement_at = now_ms;
                    }
                }
            },
            .closed => |c| {
                // A relay saying no. NIP-01's CLOSED carries a reason, and
                // dropping it on the floor is what made a refused subscription
                // indistinguishable from a quiet one: a green chip, "Live", and
                // nothing arriving, for the rest of the connection, with no
                // retry and nothing written down.
                std.debug.print("plaza: [{s}] closed {s}: {s}\n", .{ url, c.subscription_id, c.message });
                if (std.mem.eql(u8, c.subscription_id, probe_sub)) {
                    // Only the latency reading is lost. Clear the pending sample
                    // so the next message asks again rather than waiting forever
                    // for an EOSE that is not coming.
                    probe_at = 0;
                } else if (std.mem.eql(u8, c.subscription_id, feed_sub)) {
                    // The feed is what this connection is FOR, so end it and let
                    // the reconnect ladder decide when to ask again. A relay that
                    // refuses this filter now will usually refuse it in three
                    // seconds too, which is exactly why that delay widens.
                    return error.FeedSubscriptionClosed;
                }
                // The inbox and the engagement subscription are refused on their
                // own terms. Either one is worth reporting and neither is worth
                // tearing down a working feed for.
            },
            else => {},
        }
    }
}

